--
-- Name: _inventory_reverse_item(uuid, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._inventory_reverse_item(p_order_item_id uuid, p_reason text DEFAULT 'void'::text, p_performed_by uuid DEFAULT NULL::uuid, p_correlation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_order RECORD;
  v_r     RECORD;
  v_corr  uuid := COALESCE(p_correlation_id, gen_random_uuid());
  v_reversed INT := 0;
  v_id   uuid;
BEGIN
  IF p_performed_by IS NOT NULL THEN
    PERFORM public.validate_actor(p_performed_by);
  END IF;

  SELECT o.* INTO v_order
    FROM public.orders o
    JOIN public.order_items oi ON oi.order_id = o.id
   WHERE oi.id = p_order_item_id
   LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', true, 'result', 'no_order', 'reversed', 0);
  END IF;

  -- B2: for each ingredient, reverse only the consumption NOT already
  -- reversed. net_to_reverse = consumption - existing_reversals (> 0).
  FOR v_r IN
    SELECT l.ingredient_id,
           ( SUM(l.quantity)
             - COALESCE( (SELECT SUM(r.quantity)
                            FROM public.inventory_logs r
                           WHERE r.order_item_id = p_order_item_id
                             AND r.ingredient_id = l.ingredient_id
                             AND r.type = 'reversal'), 0 )
           ) AS net_to_reverse,
           COALESCE(MAX(l.unit), COALESCE((SELECT unit FROM public.ingredients WHERE id = l.ingredient_id), 'gram')) AS unit
      FROM public.inventory_logs l
     WHERE l.order_item_id = p_order_item_id
       AND l.type = 'order_consumption'
     GROUP BY l.ingredient_id
  LOOP
    IF v_r.net_to_reverse IS NULL OR v_r.net_to_reverse <= 0 THEN
      CONTINUE;  -- already fully reversed (by a prior refund or reversal)
    END IF;

    INSERT INTO public.inventory_logs
      (ingredient_id, type, quantity, unit, order_id, order_item_id,
       reference_type, reference_id, correlation_id, idempotency_key, performed_by,
       reason, location_id, organization_id, created_at)
    VALUES
      (v_r.ingredient_id, 'reversal', v_r.net_to_reverse, v_r.unit,
       v_order.id, p_order_item_id, 'order', v_order.id,
       v_corr, 'reversal:' || p_order_item_id::text || ':' || v_r.ingredient_id::text || ':' || v_corr::text,
       p_performed_by, COALESCE(p_reason, 'void'), v_order.location_id, v_order.organization_id, now())
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      v_reversed := v_reversed + 1;
      PERFORM public.emit_outbox_event('inventory', v_r.ingredient_id, 'inventory.transaction.created',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_r.ingredient_id, 'quantity', v_r.net_to_reverse, 'type', 'reversal'),
        jsonb_build_object('correlation_id', v_corr));
      PERFORM public.emit_outbox_event('inventory', v_r.ingredient_id, 'inventory.stock_changed',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_r.ingredient_id, 'quantity', v_r.net_to_reverse),
        jsonb_build_object('correlation_id', v_corr));
      PERFORM public.emit_outbox_event('inventory', v_r.ingredient_id, 'inventory.reversal.requested',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_r.ingredient_id, 'quantity', v_r.net_to_reverse, 'reason', p_reason),
        jsonb_build_object('correlation_id', v_corr));
    END IF;
  END LOOP;

  IF v_reversed = 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'no_consumption', 'reversed', 0);
  END IF;

  RETURN jsonb_build_object('success', true, 'result', 'reversed', 'reversed', v_reversed, 'correlation_id', v_corr);
END;
$$;


--
-- Name: _inventory_reverse_item_qty(uuid, integer, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._inventory_reverse_item_qty(p_order_item_id uuid, p_qty integer, p_reason text DEFAULT 'correction'::text, p_performed_by uuid DEFAULT NULL::uuid, p_correlation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_r RECORD;
  v_corr uuid := COALESCE(p_correlation_id, gen_random_uuid());
  v_units numeric := 0;
  v_target integer := 0;
  v_reversed INT := 0;
  v_id uuid;
BEGIN
  IF p_performed_by IS NOT NULL THEN
    PERFORM public.validate_actor(p_performed_by);
  END IF;

  IF p_qty IS NULL OR p_qty <= 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'no_qty', 'reversed', 0);
  END IF;

  SELECT o.* INTO v_order
  FROM public.orders o
  JOIN public.order_items oi ON oi.order_id = o.id
  WHERE oi.id = p_order_item_id
  LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', true, 'result', 'no_order', 'reversed', 0);
  END IF;

  SELECT COALESCE(MIN(item_quantity), 0)::integer INTO v_units
  FROM public.inventory_logs l
  WHERE l.order_item_id = p_order_item_id AND l.type = 'order_consumption';

  IF v_units <= 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'no_consumption', 'reversed', 0);
  END IF;

  v_target := LEAST(p_qty, v_units::integer);

  FOR v_r IN
    SELECT l.ingredient_id,
           SUM(l.quantity) AS qty,
           COALESCE(MAX(l.unit), COALESCE((SELECT unit FROM public.ingredients WHERE id = l.ingredient_id), 'gram')) AS unit
    FROM public.inventory_logs l
    WHERE l.order_item_id = p_order_item_id
      AND l.type = 'order_consumption'
    GROUP BY l.ingredient_id
  LOOP
    IF v_r.qty <= 0 THEN
      CONTINUE;
    END IF;

    INSERT INTO public.inventory_logs
      (ingredient_id, type, quantity, unit, order_id, order_item_id,
       item_quantity, reference_type, reference_id, correlation_id, idempotency_key, performed_by,
       reason, location_id, organization_id, created_at)
    VALUES
      (v_r.ingredient_id, 'reversal', ROUND((v_r.qty * v_target / v_units)::numeric, 4), v_r.unit,
       v_order.id, p_order_item_id, v_target, 'order', v_order.id,
       v_corr, 'reversal_qty:' || p_order_item_id::text || ':' || v_r.ingredient_id::text || ':' || v_corr::text,
       p_performed_by, COALESCE(p_reason, 'correction'), v_order.location_id, v_order.organization_id, now())
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      v_reversed := v_reversed + 1;
      PERFORM public.emit_outbox_event('inventory', v_r.ingredient_id, 'inventory.transaction.created',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_r.ingredient_id, 'quantity', ROUND((v_r.qty * v_target / v_units)::numeric, 4), 'type', 'reversal'),
        jsonb_build_object('correlation_id', v_corr));
      PERFORM public.emit_outbox_event('inventory', v_r.ingredient_id, 'inventory.stock_changed',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_r.ingredient_id, 'quantity', ROUND((v_r.qty * v_target / v_units)::numeric, 4)),
        jsonb_build_object('correlation_id', v_corr));
      PERFORM public.emit_outbox_event('inventory', v_r.ingredient_id, 'inventory.reversal.requested',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_r.ingredient_id, 'quantity', ROUND((v_r.qty * v_target / v_units)::numeric, 4), 'reason', p_reason),
        jsonb_build_object('correlation_id', v_corr));
    END IF;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'result', CASE WHEN v_reversed > 0 THEN 'reversed' ELSE 'no_consumption' END,
    'reversed', v_reversed, 'correlation_id', v_corr, 'reversed_units', v_target);
END;
$$;


--
-- Name: _loyalty_post(uuid, text, integer, text, uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._loyalty_post(p_account_id uuid, p_type text, p_points integer, p_reference_type text, p_reference_id uuid, p_reason text, p_performed_by uuid, p_correlation_id uuid, p_idempotency_key text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_acct      RECORD;
  v_newbal    integer;
  v_corr      uuid := COALESCE(p_correlation_id, gen_random_uuid());
  v_existing  uuid;
BEGIN
  IF p_account_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'no_account');
  END IF;
  IF p_points = 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'zero');
  END IF;

  SELECT * INTO v_acct FROM public.loyalty_accounts WHERE id = p_account_id FOR UPDATE;
  IF NOT FOUND OR COALESCE(v_acct.is_active, true) = false THEN
    RETURN jsonb_build_object('success', false, 'error', 'ACCOUNT_NOT_FOUND_OR_INACTIVE');
  END IF;

  -- Idempotency: same key → return prior row.
  SELECT id INTO v_existing FROM public.loyalty_transactions
   WHERE idempotency_key = p_idempotency_key LIMIT 1;
  IF v_existing IS NOT NULL THEN
    RETURN jsonb_build_object('success', true, 'result', 'idempotent_replay', 'transaction_id', v_existing);
  END IF;

  v_newbal := COALESCE(v_acct.points_balance, 0) + p_points;
  IF v_newbal < 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'NEGATIVE_BALANCE', 'attempted', v_newbal);
  END IF;

  INSERT INTO public.loyalty_transactions
    (account_id, type, points, balance_after, reference_type, reference_id,
     reason, performed_by, correlation_id, idempotency_key)
  VALUES (p_account_id, p_type, p_points, v_newbal, p_reference_type, p_reference_id,
          p_reason, p_performed_by, v_corr, p_idempotency_key);

  UPDATE public.loyalty_accounts SET
    points_balance = v_newbal,
    total_earned   = COALESCE(total_earned, 0)   + GREATEST(p_points, 0),
    total_redeemed = COALESCE(total_redeemed, 0) + GREATEST(-p_points, 0),
    updated_at     = NOW()
  WHERE id = p_account_id;

  PERFORM public.log_audit(
    'loyalty_' || p_type, 'loyalty_account', p_account_id::text,
    p_performed_by, NULL,
    jsonb_build_object('balance', v_acct.points_balance),
    jsonb_build_object('points', p_points, 'new_balance', v_newbal, 'reference_id', p_reference_id),
    jsonb_build_object('idempotency_key', p_idempotency_key, 'correlation_id', v_corr),
    NULL
  );

  PERFORM public.emit_outbox_event('loyalty', p_account_id, 'loyalty.points_changed',
    jsonb_build_object('account_id', p_account_id, 'type', p_type, 'points', p_points,
                       'balance_after', v_newbal, 'reference_type', p_reference_type, 'reference_id', p_reference_id),
    jsonb_build_object('correlation_id', v_corr));

  RETURN jsonb_build_object('success', true, 'result', 'posted',
                            'points', p_points, 'balance_after', v_newbal, 'correlation_id', v_corr);
END;
$$;


--
-- Name: _price_replacement_snapshot(uuid, integer, jsonb, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._price_replacement_snapshot(p_product_id uuid, p_quantity integer, p_modifiers jsonb, p_tax_rate numeric) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_product RECORD;
  v_mod RECORD;
  v_mod_rec jsonb;
  v_mod_json jsonb := '[]'::jsonb;
  v_mod_total numeric := 0;
  v_unit numeric;
  v_total numeric;
  v_tax numeric;
  v_snapshot jsonb;
BEGIN
  SELECT * INTO v_product FROM products WHERE id = p_product_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'PRODUCT_NOT_FOUND: %', p_product_id USING ERRCODE = 'P0001'; END IF;

  v_unit := CASE WHEN v_product.discount_price IS NOT NULL AND v_product.discount_price > 0
                 THEN v_product.discount_price ELSE v_product.price END;

  FOR v_mod_rec IN SELECT * FROM jsonb_array_elements(COALESCE(p_modifiers, '[]'::jsonb))
  LOOP
    SELECT * INTO v_mod FROM product_modifiers
    WHERE id = COALESCE((v_mod_rec->>'id')::uuid, (v_mod_rec->>'modifier_id')::uuid)
      AND product_id = p_product_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_MODIFIER: % for product %',
        COALESCE((v_mod_rec->>'id'), (v_mod_rec->>'modifier_id')), p_product_id USING ERRCODE = 'P0001';
    END IF;
    v_mod_json := v_mod_json || jsonb_build_array(jsonb_build_object(
      'id', v_mod.id, 'name', COALESCE(v_mod.name_az, v_mod.name),
      'price', v_mod.price, 'quantity', COALESCE((v_mod_rec->>'quantity')::int, 1)
    ));
  END LOOP;

  SELECT COALESCE(sum((el->>'price')::numeric * (el->>'quantity')::int), 0)
    INTO v_mod_total FROM jsonb_array_elements(v_mod_json) el;

  v_unit := v_unit + v_mod_total;
  v_total := v_unit * p_quantity;
  v_tax := round(v_total * COALESCE(p_tax_rate, 0) / 100, 2);

  v_snapshot := jsonb_build_object(
    'schema', 'v1',
    'product_id', p_product_id,
    'product_name', v_product.name,
    'base_unit_price', v_product.price,
    'discount_price', NULLIF(v_product.discount_price, 0),
    'applied_discount', ROUND((v_product.price - CASE WHEN v_product.discount_price > 0
                 THEN v_product.discount_price ELSE v_product.price END)::numeric, 2),
    'unit_price', v_unit,
    'modifiers', v_mod_json,
    'modifier_total', v_mod_total,
    'tax_rate', COALESCE(p_tax_rate, 0),
    'tax_amount', v_tax,
    'currency', 'AZN',
    'total_price', v_total,
    'snapshot_at', now(),
    'correction', true
  );

  RETURN jsonb_build_object(
    'product_name', v_product.name,
    'station_id', v_product.station_id,
    'unit_price', v_unit,
    'modifier_total', v_mod_total,
    'total_price', v_total,
    'tax_amount', v_tax,
    'modifiers', v_mod_json,
    'snapshot', v_snapshot
  );
END;
$$;


--
-- Name: _trg_order_loyalty_spine(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public._trg_order_loyalty_spine() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_res jsonb;
BEGIN
  IF NEW.id IS DISTINCT FROM OLD.id THEN RETURN NEW; END IF;

  -- EARN on first paid (idempotent inside loyalty_earn via
  -- orders.loyalty_points_earned anchor).
  IF NEW.status = 'paid' AND OLD.status IS DISTINCT FROM 'paid' THEN
    BEGIN
      v_res := public.loyalty_earn(NEW.id, NULL);
      RAISE NOTICE 'loyalty_spine earn(%): %', NEW.id, COALESCE(v_res->>'result', v_res->>'error');
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'loyalty_spine earn failed for %: %', NEW.id, SQLERRM;
    END;

    BEGIN
      IF NEW.customer_id IS NOT NULL THEN
        UPDATE public.customers SET
          total_visits  = COALESCE(total_visits, 0) + 1,
          total_spent   = COALESCE(total_spent, 0) + COALESCE(NEW.paid_amount, 0) - COALESCE(NEW.discount_amount, 0),
          last_order_at = NOW()
        WHERE id = NEW.customer_id;
      END IF;
    EXCEPTION WHEN OTHERS THEN
      RAISE NOTICE 'loyalty_spine customer stats failed: %', SQLERRM;
    END;
  END IF;

  -- REVERSAL is intentionally NOT here: it requires the refunded
  -- order_item_id, which only the refund API call knows. The refund
  -- routes call public.loyalty_reverse(p_order_id, p_order_item_id)
  -- (idempotent per item, safe under retries).

  RETURN NEW;
END;
$$;


