-- Name: accept_item_atomic(text, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_item_atomic(p_token text, p_item_id uuid, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_correlation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT item_kitchen_step(p_token, p_item_id, 'accepted', p_reason, p_metadata, p_correlation_id)
$$;


--
-- Name: accept_kitchen_ticket_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_kitchen_ticket_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order is not pending');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'accepted',
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'accepted',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'accept_kitchen_ticket',
    jsonb_build_object('kitchen_status', 'pending'),
    jsonb_build_object('kitchen_status', 'accepted'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: accept_order_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.accept_order_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_assigned_name TEXT;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status NOT IN ('pending', 'cooking', 'preparing', 'reserved') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order cannot be accepted in current status');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_assigned_name FROM public.profiles WHERE id = p_performed_by;
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'preparing',
    assigned_to = p_performed_by,
    assigned_to_name = v_assigned_name,
    updated_at = NOW(),
    version = COALESCE(version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  UPDATE public.order_items SET
    kitchen_status = 'preparing',
    updated_at = NOW()
  WHERE order_id = p_order_id AND kitchen_status IN ('pending', 'reserved');

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'preparing',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'accept_order',
    jsonb_build_object('kitchen_status', v_order.kitchen_status, 'assigned_to', v_order.assigned_to),
    jsonb_build_object('kitchen_status', 'preparing', 'assigned_to', p_performed_by, 'assigned_to_name', v_assigned_name),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: activate_location_atomic(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_location_atomic(p_token text, p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid; v_loc RECORD; v_old jsonb; v_new jsonb; v_corr uuid;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    IF NOT has_permission('settings.admin') AND NOT is_superadmin() THEN RAISE EXCEPTION 'Permission denied'; END IF;
    SELECT * INTO v_loc FROM locations WHERE id = p_location_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Location not found'; END IF;
    IF NOT has_org_access(v_loc.organization_id) THEN RAISE EXCEPTION 'Cannot activate location in another org'; END IF;
    IF v_loc.status = 'ACTIVE' THEN RAISE EXCEPTION 'Already ACTIVE'; END IF;
    IF v_loc.status = 'ARCHIVED' THEN RAISE EXCEPTION 'ARCHIVED locations cannot be reactivated'; END IF;
    v_old := row_to_json(v_loc)::jsonb; v_corr := gen_random_uuid();
    UPDATE locations SET status='ACTIVE' WHERE id=p_location_id RETURNING row_to_json(locations.*)::jsonb INTO v_new;
    INSERT INTO operation_logs (entity_type, entity_id, operation, before_state, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('location', p_location_id, 'location.activated', v_old, v_new, v_staff_id, v_corr, p_location_id, v_loc.organization_id);
    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, metadata, status)
    VALUES ('location', p_location_id, 'location.activated', v_new,
            jsonb_build_object('organization_id', v_loc.organization_id, 'actor_staff_id', v_staff_id, 'correlation_id', v_corr), 'pending');
    RETURN v_new;
END;
$$;


--
-- Name: activate_table_atomic(text, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.activate_table_atomic(p_token text, p_table_id uuid, p_guest_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table RECORD;
  v_reservation RECORD;
  v_order_id UUID;
  v_total NUMERIC;
BEGIN
  PERFORM public.set_session_staff(p_token);
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'orders.create'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  SELECT * INTO v_table FROM public.table_floors WHERE id = p_table_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;

  IF v_table.status != 'reserved' THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_RESERVED');
  END IF;
  IF NOT has_location_access(v_table.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;

  SELECT * INTO v_reservation FROM public.reservations
    WHERE id = v_table.reservation_id AND status = 'confirmed'
    FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'RESERVATION_NOT_FOUND');
  END IF;

  SELECT COALESCE(SUM(rpi.unit_price * rpi.quantity), 0) INTO v_total
  FROM public.reservation_preorder_items rpi
  WHERE rpi.reservation_id = v_reservation.id;

  INSERT INTO public.orders (
    table_number, status, guest_count, reservation_id, customer_id, customer_name,
    customer_phone, kitchen_status, is_draft, total_amount, location_id, organization_id,
    created_at, updated_at, version
  ) VALUES (
    v_table.table_number, 'confirmed', COALESCE(p_guest_count, v_reservation.guests),
    v_reservation.id, v_reservation.customer_id, v_reservation.name, v_reservation.phone,
    'pending', false, v_total, v_table.location_id, v_table.organization_id,
    NOW(), NOW(), 1
  ) RETURNING id INTO v_order_id;

  INSERT INTO public.order_items (
    order_id, product_id, product_name, quantity, unit_price, total_price,
    kitchen_status, price_snapshot, created_at
  )
  SELECT
    v_order_id, rpi.product_id, rpi.product_name, rpi.quantity, rpi.unit_price,
    rpi.unit_price * rpi.quantity, 'pending',
    jsonb_build_object(
      'unit_price', rpi.unit_price, 'quantity', rpi.quantity,
      'total_price', rpi.unit_price * rpi.quantity, 'snapshot_at', NOW()
    ), NOW()
  FROM public.reservation_preorder_items rpi
  WHERE rpi.reservation_id = v_reservation.id;

  UPDATE public.table_floors SET
    status = 'occupied',
    current_order_id = v_order_id,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    updated_at = NOW()
  WHERE id = p_table_id;

  INSERT INTO public.operation_logs (
    operation, order_id, source_table_number, old_state, new_state, performed_by
  ) VALUES (
    'activate_table', v_order_id, v_table.table_number,
    jsonb_build_object('status', v_table.status, 'reservation_id', v_table.reservation_id),
    jsonb_build_object('status', 'occupied', 'order_id', v_order_id),
    NULL
  );

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('table', v_table.id, 'table.order_opened',
    jsonb_build_object('table_number', v_table.table_number,
      'order_id', v_order_id,
      'reservation_id', v_reservation.id,
      'location_id', v_table.location_id),
    'pending');

  RETURN jsonb_build_object('success', true, 'order_id', v_order_id, 'table_number', v_table.table_number);
END;
$$;


--
-- Name: add_customer_address(uuid, text, text, text, text, text, text, numeric, numeric, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_customer_address(p_customer_id uuid, p_address_line text, p_address_line2 text DEFAULT NULL::text, p_city text DEFAULT 'Bakı'::text, p_district text DEFAULT NULL::text, p_landmark text DEFAULT NULL::text, p_delivery_notes text DEFAULT NULL::text, p_lat numeric DEFAULT NULL::numeric, p_lng numeric DEFAULT NULL::numeric, p_is_default boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  -- If setting as default, unset others
  IF p_is_default THEN
    UPDATE customer_addresses SET is_default = false WHERE customer_id = p_customer_id;
  END IF;

  INSERT INTO customer_addresses (
    customer_id, address_line, address_line2, city, district,
    landmark, delivery_notes, lat, lng, is_default
  ) VALUES (
    p_customer_id, p_address_line, p_address_line2, p_city, p_district,
    p_landmark, p_delivery_notes, p_lat, p_lng, p_is_default
  )
  RETURNING id INTO v_id;

  RETURN jsonb_build_object('success', true, 'address_id', v_id);
END;
$$;


--
-- Name: add_item_atomic(text, uuid, uuid, integer, jsonb, text, integer, text, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_item_atomic(p_token text, p_order_id uuid, p_product_id uuid, p_quantity integer DEFAULT 1, p_modifiers jsonb DEFAULT '[]'::jsonb, p_course text DEFAULT 'main'::text, p_seat_number integer DEFAULT NULL::integer, p_special_notes text DEFAULT NULL::text, p_tax_rate numeric DEFAULT 0, p_idempotency_key text DEFAULT NULL::text, p_correlation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_order RECORD;
  v_product RECORD;
  v_mod RECORD;
  v_mod_rec jsonb;
  v_mod_total numeric := 0;
  v_unit numeric;
  v_total numeric;
  v_tax numeric;
  v_snapshot jsonb;
  v_mod_json jsonb := '[]'::jsonb;
  v_allowed jsonb;
  v_item_id uuid;
  prev_item RECORD;
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  IF p_quantity <= 0 THEN
    RAISE EXCEPTION 'INVALID_QTY: quantity must be > 0' USING ERRCODE = 'P0001';
  END IF;

  -- serialized on the order row
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001'; END IF;
  IF v_order.status IN ('paid','closed','cancelled') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED' USING ERRCODE = 'P0001';
  END IF;

  v_allowed := authorize(p_token, 'orders.create', v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: orders.create at % (reason: %)',
      v_order.location_id, v_allowed->>'reason' USING ERRCODE = 'P0001';
  END IF;

  -- idempotency dedupe
  IF p_idempotency_key IS NOT NULL THEN
    SELECT * INTO prev_item FROM order_items WHERE idempotency_key = p_idempotency_key;
    IF FOUND THEN
      RETURN jsonb_build_object('success', true, 'duplicate', true,
        'order_item_id', prev_item.id, 'item_added', false);
    END IF;
  END IF;

  -- server-sourced product price
  SELECT * INTO v_product FROM products WHERE id = p_product_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'PRODUCT_NOT_FOUND: %', p_product_id USING ERRCODE = 'P0001';
  END IF;

  v_unit := CASE WHEN v_product.discount_price IS NOT NULL AND v_product.discount_price > 0
                 THEN v_product.discount_price ELSE v_product.price END;

  -- modifier validation + server prices
  FOR v_mod_rec IN SELECT * FROM jsonb_array_elements(COALESCE(p_modifiers,'[]'::jsonb))
  LOOP
    SELECT * INTO v_mod FROM product_modifiers
    WHERE id = COALESCE((v_mod_rec->>'id')::uuid, (v_mod_rec->>'modifier_id')::uuid)
      AND product_id = p_product_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'INVALID_MODIFIER: % for product %',
        COALESCE((v_mod_rec->>'id'), (v_mod_rec->>'modifier_id')), p_product_id USING ERRCODE = 'P0001';
    END IF;
    v_mod_json := v_mod_json || jsonb_build_array(jsonb_build_object(
      'id', v_mod.id, 'name', COALESCE(v_mod.name_az, v_mod.name),
      'price', v_mod.price,
      'quantity', COALESCE((v_mod_rec->>'quantity')::int, 1)
    ));
  END LOOP;

  SELECT COALESCE(sum((el->>'price')::numeric * (el->>'quantity')::int), 0)
    INTO v_mod_total FROM jsonb_array_elements(v_mod_json) el;

  v_unit := v_unit + v_mod_total;
  v_total := v_unit * p_quantity;
  v_tax := round(v_total * COALESCE(p_tax_rate, 0) / 100, 2);

  v_snapshot := jsonb_build_object(
    'schema', 'v1',
    'product_id', p_product_id,
    'product_name', v_product.name,
    'base_unit_price', v_product.price,
    'discount_price', NULLIF(v_product.discount_price, 0),
    'applied_discount', ROUND((v_product.price - CASE WHEN v_product.discount_price > 0 THEN v_product.discount_price ELSE v_product.price END)::numeric, 2),
    'unit_price', v_unit,
    'modifiers', v_mod_json,
    'modifier_total', v_mod_total,
    'tax_rate', COALESCE(p_tax_rate, 0),
    'tax_amount', v_tax,
    'currency', 'AZN',
    'total_price', v_total,
    'snapshot_at', now()
  );

  INSERT INTO order_items (
    order_id, product_id, product_name, quantity, unit_price, total_price,
    modifiers, course, seat_number, special_notes,
    kitchen_status, tax_rate, tax_amount, price_snapshot,
    station_id, idempotency_key, correlation_id
  ) VALUES (
    p_order_id, p_product_id, v_product.name, p_quantity, v_unit, v_total,
    v_mod_json, COALESCE(p_course, 'main'), p_seat_number, p_special_notes,
    'pending', COALESCE(p_tax_rate, 0), v_tax, v_snapshot,
    v_product.station_id,
    p_idempotency_key,
    COALESCE(p_correlation_id, gen_random_uuid())
  )
  RETURNING id INTO v_item_id;

  UPDATE orders SET
    total_amount = COALESCE(total_amount, 0) + v_total,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  PERFORM log_order_event(p_order_id, 'item_added',
    NULL,
    jsonb_build_object('order_item_id', v_item_id, 'product_name', v_product.name,
      'quantity', p_quantity, 'unit_price', v_unit, 'total_price', v_total,
      'tax_amount', v_tax),
    jsonb_build_object('idempotency_key', p_idempotency_key,
      'correlation_id', COALESCE(p_correlation_id, gen_random_uuid())),
    v_staff_id, NULL, NULL, NULL);

  INSERT INTO operation_logs (operation, order_id, performed_by, reason, old_state, new_state,
                              location_id, organization_id, metadata)
  VALUES ('order_item.add', p_order_id, v_staff_id, p_special_notes, '{}'::jsonb,
          jsonb_build_object('item', v_item_id, 'product', p_product_id, 'qty', p_quantity, 'total', v_total),
          v_order.location_id, v_order.organization_id,
          jsonb_build_object('idempotency_key', p_idempotency_key, 'correlation_id', COALESCE(p_correlation_id, gen_random_uuid())));

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', v_item_id, 'order_item.added',
    jsonb_build_object('order_id', p_order_id, 'product_id', p_product_id,
      'quantity', p_quantity, 'unit_price', v_unit, 'total_price', v_total,
      'tax_amount', v_tax, 'performed_by', v_staff_id),
    'pending');

  RETURN jsonb_build_object('success', true, 'order_item_id', v_item_id,
    'unit_price', v_unit, 'total_price', v_total, 'tax_amount', v_tax,
    'modifier_total', v_mod_total, 'price_snapshot', v_snapshot);
END;
$$;


--
-- Name: add_items_to_order(uuid, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_items_to_order(p_order_id uuid, p_items jsonb, p_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_item JSONB;
  v_new_total NUMERIC;
  v_new_version INTEGER;
BEGIN
  -- Lock the order row FOR UPDATE to prevent concurrent modification
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  -- Insert items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    INSERT INTO order_items (
      order_id, product_id, product_name, variant_id, quantity,
      unit_price, total_price, modifiers, special_notes,
      kitchen_status, seat_number, updated_by_terminal_id, price_snapshot, created_at
    ) VALUES (
      p_order_id,
      (v_item->>'product_id')::UUID,
      v_item->>'product_name',
      v_item->>'variant_id',
      COALESCE((v_item->>'quantity')::INTEGER, 1),
      COALESCE((v_item->>'unit_price')::NUMERIC, 0),
      COALESCE((v_item->>'unit_price')::NUMERIC, 0) * COALESCE((v_item->>'quantity')::INTEGER, 1),
      COALESCE(v_item->'modifiers', '[]'::JSONB),
      v_item->>'special_notes',
      'pending',
      (v_item->>'seat_number')::INTEGER,
      p_terminal_id,
      jsonb_build_object(
        'unit_price', COALESCE((v_item->>'unit_price')::NUMERIC, 0),
        'discount_price', GREATEST(0, COALESCE((v_item->>'original_unit_price')::NUMERIC, 0) - COALESCE((v_item->>'unit_price')::NUMERIC, 0)),
        'campaign_id', v_item->>'campaign_id',
        'campaign_discount', COALESCE((v_item->>'campaign_discount_amount')::NUMERIC, 0),
        'total_price', COALESCE((v_item->>'unit_price')::NUMERIC, 0) * COALESCE((v_item->>'quantity')::INTEGER, 1),
        'snapshot_at', now()::TEXT
      ),
      now()
    );
  END LOOP;

  -- Recalculate total from all non-cancelled items
  SELECT COALESCE(SUM(total_price), 0)
  INTO v_new_total
  FROM order_items
  WHERE order_id = p_order_id AND kitchen_status != 'cancelled';

  -- Increment version
  v_new_version := v_order.version + 1;

  -- Update order atomically
  UPDATE orders SET
    total_amount = v_new_total,
    version = v_new_version,
    is_draft = false,
    status = 'confirmed',
    updated_at = now(),
    updated_by_terminal_id = COALESCE(p_terminal_id, updated_by_terminal_id),
    -- Only reset kitchen_status to 'pending' if it wasn't already 'pending'
    kitchen_status = CASE
      WHEN v_order.kitchen_status IS NULL OR v_order.kitchen_status = '' THEN 'pending'
      ELSE v_order.kitchen_status
    END
  WHERE id = p_order_id;

  -- Update table_floors total_amount
  IF v_order.table_number IS NOT NULL THEN
    UPDATE table_floors SET
      total_amount = v_new_total,
      status = CASE WHEN v_new_total > 0 THEN 'occupied' ELSE status END,
      last_activity_at = now()
    WHERE table_number = v_order.table_number;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'total_amount', v_new_total,
    'version', v_new_version
  );
END;
$$;


--
-- Name: add_items_to_order(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_items_to_order(p_order_id uuid, p_items jsonb, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_item JSONB;
  v_added INTEGER := 0;
  v_total_add NUMERIC := 0;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status IN ('paid', 'closed', 'cancelled') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED' USING ERRCODE = 'P0001';
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO order_items (
      order_id, product_id, product_name, quantity, unit_price, total_price,
      modifiers, special_notes, kitchen_status
    ) VALUES (
      p_order_id,
      (v_item->>'product_id')::UUID,
      v_item->>'product_name',
      COALESCE((v_item->>'quantity')::INTEGER, 1),
      (v_item->>'unit_price')::NUMERIC,
      (v_item->>'unit_price')::NUMERIC * COALESCE((v_item->>'quantity')::INTEGER, 1),
      COALESCE(v_item->'modifiers', '[]'::JSONB),
      v_item->>'special_notes',
      'pending'
    );

    v_total_add := v_total_add + (v_item->>'unit_price')::NUMERIC * COALESCE((v_item->>'quantity')::INTEGER, 1);
    v_added := v_added + 1;

    PERFORM log_order_event(
      p_order_id, 'item_added',
      NULL,
      jsonb_build_object('product_name', v_item->>'product_name', 'quantity', (v_item->>'quantity')::INTEGER),
      NULL, p_performed_by, NULL, NULL, NULL
    );
  END LOOP;

  UPDATE orders SET
    total_amount = COALESCE(total_amount, 0) + v_total_add,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'items_added', v_added,
    'total_increase', v_total_add,
    'new_total', COALESCE(v_order.total_amount, 0) + v_total_add
  );
END;
$$;


--
-- Name: add_order_items(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.add_order_items(p_order_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_item JSONB;
  v_item_total NUMERIC;
  v_inserted INTEGER := 0;
BEGIN
  -- Lock order
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status IN ('paid', 'cancelled', 'closed') THEN
    RAISE EXCEPTION 'ORDER_CLOSED' USING ERRCODE = 'P0001';
  END IF;

  -- Insert each item
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_item_total := COALESCE((v_item->>'total_price')::NUMERIC,
                             (v_item->>'unit_price')::NUMERIC * (v_item->>'quantity')::NUMERIC);

    INSERT INTO order_items (
      order_id, product_id, product_name, quantity, unit_price, total_price,
      modifiers, special_notes, combo_group_id, parent_order_item_id, variant_id,
      kitchen_status
    ) VALUES (
      p_order_id,
      (v_item->>'product_id')::UUID,
      v_item->>'product_name',
      (v_item->>'quantity')::INTEGER,
      (v_item->>'unit_price')::NUMERIC,
      v_item_total,
      v_item->>'modifiers',
      v_item->>'special_notes',
      (v_item->>'combo_group_id')::UUID,
      (v_item->>'parent_order_item_id')::UUID,
      (v_item->>'variant_id')::UUID,
      'pending'
    );

    v_inserted := v_inserted + 1;
  END LOOP;

  -- Update order total
  UPDATE orders
  SET total_amount = COALESCE(total_amount, 0) + (
    SELECT COALESCE(SUM(total_price), 0) FROM order_items WHERE order_id = p_order_id AND id IN (
      SELECT id FROM order_items WHERE order_id = p_order_id ORDER BY created_at DESC LIMIT v_inserted
    )
  ),
  version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id, 'inserted', v_inserted);
END;
$$;


--
-- Name: apply_service_charge(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_service_charge(p_order_id uuid, p_pct numeric, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_sc_amount NUMERIC;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status = 'paid' THEN
    RAISE EXCEPTION 'ORDER_ALREADY_PAID' USING ERRCODE = 'P0001';
  END IF;
  IF p_pct < 0 OR p_pct > 50 THEN
    RAISE EXCEPTION 'INVALID_SERVICE_CHARGE_PCT' USING ERRCODE = 'P0001';
  END IF;

  v_sc_amount := round(COALESCE(v_order.total_amount, 0) * p_pct / 100, 2);

  UPDATE orders SET
    service_charge_pct = p_pct,
    service_charge_amount = v_sc_amount,
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  PERFORM log_order_event(
    p_order_id, 'service_charge_applied',
    jsonb_build_object('old_pct', v_order.service_charge_pct, 'old_amount', v_order.service_charge_amount),
    jsonb_build_object('pct', p_pct, 'amount', v_sc_amount),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'service_charge_pct', p_pct,
    'service_charge_amount', v_sc_amount,
    'new_total', COALESCE(v_order.total_amount, 0) + v_sc_amount
  );
END;
$$;


--
-- Name: apply_stock_count(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_stock_count(p_count_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count RECORD;
  v_item  RECORD;
  v_total NUMERIC(12,2) := 0;
  v_pct   NUMERIC;
  v_loc   UUID;
  v_org   UUID;
  v_corr  UUID := gen_random_uuid();
  v_key   TEXT;
  v_id    UUID;
  v_live  NUMERIC;
  v_items INT := 0;
BEGIN
  IF p_performed_by IS NOT NULL THEN
    PERFORM public.validate_actor(p_performed_by);
    SELECT s.active_location_id, s.organization_id
      INTO v_loc, v_org
      FROM public.sessions s
     WHERE s.user_id = p_performed_by
       AND s.revoked_at IS NULL
       AND s.expires_at > now()
     ORDER BY s.last_activity_at DESC
     LIMIT 1;
  END IF;

  SELECT * INTO v_count FROM public.stock_counts WHERE id = p_count_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'COUNT_NOT_FOUND' USING ERRCODE = 'P0001'; END IF;
  IF v_count.status = 'cancelled' THEN RAISE EXCEPTION 'COUNT_CANCELLED' USING ERRCODE = 'P0001'; END IF;
  IF v_count.status != 'completed' THEN RAISE EXCEPTION 'COUNT_NOT_COMPLETED' USING ERRCODE = 'P0001'; END IF;
  IF v_count.applied_at IS NOT NULL THEN RAISE EXCEPTION 'COUNT_ALREADY_APPLIED' USING ERRCODE = 'P0001'; END IF;

  FOR v_item IN
    SELECT sci.*, i.name AS ingredient_name, i.current_stock, i.average_cost_per_unit
    FROM public.stock_count_items sci
    JOIN public.ingredients i ON i.id = sci.ingredient_id
    WHERE sci.stock_count_id = p_count_id
    FOR UPDATE OF i
  LOOP
    -- LIVE recompute: reconcile against the stock NOW, not the stale snapshot.
    v_live := v_item.actual_qty - COALESCE(v_item.current_stock, 0);
    v_pct := CASE
      WHEN COALESCE(v_item.current_stock, 0) > 0 AND ABS(v_live) > 0
      THEN ABS(v_live) / v_item.current_stock * 100
      ELSE 0
    END;
    v_key := 'stock_count:' || p_count_id::text || ':' || v_item.ingredient_id::text;

    INSERT INTO public.inventory_logs (
      ingredient_id, type, quantity, cost_per_unit, reason,
      reference_type, reference_id, notes,
      correlation_id, idempotency_key, performed_by, location_id, organization_id,
      created_at
    ) VALUES (
      v_item.ingredient_id, 'adjustment', v_live, v_item.average_cost_per_unit,
      'stock_count', 'stock_count', p_count_id,
      'Stock count: counted ' || v_item.actual_qty
        || ' / snapshot ' || v_item.system_qty
        || ' / live adjustment ' || v_live,
      v_corr, v_key, p_performed_by, v_loc, v_org,
      now()
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      PERFORM public.emit_outbox_event('inventory', v_item.ingredient_id, 'inventory.transaction.created',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', v_item.ingredient_id,
                           'quantity', v_live, 'type', 'adjustment'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'stock_count',
                           'performed_by', p_performed_by, 'location_id', v_loc,
                           'organization_id', v_org, 'count_id', p_count_id));
      PERFORM public.emit_outbox_event('inventory', v_item.ingredient_id, 'inventory.stock_changed',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', v_item.ingredient_id,
                           'quantity', v_live, 'type', 'adjustment'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'stock_count',
                           'performed_by', p_performed_by, 'location_id', v_loc,
                           'organization_id', v_org, 'count_id', p_count_id));

      UPDATE public.ingredients
         SET theoretical_stock = v_item.actual_qty,
             updated_at = now()
       WHERE id = v_item.ingredient_id;

      v_total := v_total + ABS(v_live * COALESCE(v_item.average_cost_per_unit, 0));
      v_items := v_items + 1;

      IF v_pct > 10 AND ABS(v_live) > 0 THEN
        INSERT INTO public.discrepancy_alerts (
          type, severity, title, description, source_id, source_table,
          value, expected_value, variance_pct, status, created_at
        ) VALUES (
          'stock_vs_sales',
          CASE WHEN v_pct > 50 THEN 'critical' WHEN v_pct > 25 THEN 'high' ELSE 'medium' END,
          'Stock count variance: ' || v_item.ingredient_name,
          'Count ' || v_item.actual_qty || ' vs system ' || v_item.system_qty
            || ' (live ' || ROUND(v_pct, 1) || '%)',
          v_item.ingredient_id, 'ingredients', v_item.actual_qty, v_item.current_stock,
          v_pct, 'open', now());
      END IF;
    END IF;
  END LOOP;

  UPDATE public.stock_counts
     SET total_variance = v_total,
         applied_at = now(),
         updated_at = now()
   WHERE id = p_count_id;

  RETURN jsonb_build_object(
    'success', true,
    'count_id', p_count_id,
    'total_variance', v_total,
    'count_number', v_count.count_number,
    'items_applied', v_items,
    'correlation_id', v_corr
  );
END;
$$;


--
-- Name: apply_tax(uuid, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.apply_tax(p_order_id uuid, p_pct numeric, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
