--
-- Name: archive_table_atomic(text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.archive_table_atomic(p_token text, p_table_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_table table_floors;
BEGIN
  PERFORM public.set_session_staff(p_token);
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;

  SELECT * INTO v_table FROM public.table_floors
   WHERE table_number = p_table_number
     AND (v_sess_loc IS NULL OR location_id = v_sess_loc) FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  IF NOT has_location_access(v_table.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF v_table.status NOT IN ('empty','cleaning') OR v_table.current_order_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_EMPTY');
  END IF;

  UPDATE public.table_floors
   SET is_archived = true, archived_at = now(), status = 'empty'
   WHERE id = v_table.id;

  PERFORM public.log_audit(
    'table_archived', 'table_floors', v_table.table_number::text, current_staff_id(), NULL,
    jsonb_build_object('table_number', v_table.table_number, 'location_id', v_table.location_id),
    NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'table_number', v_table.table_number, 'archived_at', now());
END;
$$;


--
-- Name: assign_courier(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_courier(p_order_id uuid, p_courier_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_courier RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_courier FROM couriers WHERE id = p_courier_id AND is_active = true;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'COURIER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- Check if courier already has an order
  IF v_courier.current_order_id IS NOT NULL AND v_courier.current_order_id != p_order_id THEN
    RAISE EXCEPTION 'COURIER_BUSY' USING ERRCODE = 'P0001';
  END IF;

  -- Free previous courier
  IF v_order.courier_id IS NOT NULL AND v_order.courier_id != p_courier_id THEN
    UPDATE couriers SET current_order_id = NULL WHERE id = v_order.courier_id;
  END IF;

  -- Assign
  UPDATE couriers SET current_order_id = p_order_id WHERE id = p_courier_id;
  UPDATE orders SET
    courier_id = p_courier_id,
    courier_name = v_courier.name,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  PERFORM log_order_event(
    p_order_id, 'courier_assigned',
    NULL,
    jsonb_build_object('courier_id', p_courier_id, 'courier_name', v_courier.name),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'courier_name', v_courier.name);
END;
$$;


--
-- Name: assign_order_staff(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_order_staff(p_order_id uuid, p_staff_id uuid, p_performed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order record;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  UPDATE public.orders
  SET    assigned_to = p_staff_id,
         updated_at = now()
  WHERE  id = p_order_id;

  PERFORM public.log_audit(
    'order_assigned', 'order', p_order_id::text, p_performed_by,
    NULL, NULL, NULL,
    jsonb_build_object('assigned_to', p_staff_id),
    NULL
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: assign_reservation_tables_atomic(uuid, integer[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_reservation_tables_atomic(p_reservation_id uuid, p_table_numbers integer[], p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table RECORD;
  v_parent_table_number integer;
  v_child_table_numbers integer[];
  v_table_number integer;
  v_order_id uuid;
  v_merged_group_id text;
  v_undo jsonb;
  v_total_amount numeric := 0;
  v_total_guests integer := 0;
BEGIN
  IF array_length(p_table_numbers, 1) IS NULL OR array_length(p_table_numbers, 1) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'At least one table required');
  END IF;
  v_parent_table_number := p_table_numbers[1];
  v_child_table_numbers := p_table_numbers[2:];
  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'RESERVATION_NOT_FOUND');
  END IF;
  IF v_reservation.status NOT IN ('pending', 'confirmed', 'waiting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'CANNOT_ASSIGN_RESERVATION_STATUS');
  END IF;
  FOR v_table_number IN SELECT unnest(p_table_numbers) LOOP
    SELECT * INTO v_table FROM public.table_floors WHERE table_number = v_table_number FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND', 'table_number', v_table_number);
    END IF;
    IF v_table.status NOT IN ('empty', 'dirty') THEN
      RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_AVAILABLE', 'table_number', v_table_number, 'current_status', v_table.status);
    END IF;
  END LOOP;
  SELECT id INTO v_order_id FROM public.orders
    WHERE reservation_id = p_reservation_id
      AND status NOT IN ('paid', 'cancelled', 'closed', 'completed')
      AND merged_into IS NULL
    ORDER BY created_at ASC LIMIT 1;
  IF v_order_id IS NULL THEN
    INSERT INTO public.orders (
      table_number, status, guest_count, total_amount,
      order_source, reservation_id, created_at, updated_at,
      created_by, is_draft, kitchen_status
    ) VALUES (
      v_parent_table_number, 'new', v_reservation.guests, 0,
      'dine_in', p_reservation_id, NOW(), NOW(),
      p_performed_by, true, 'reserved'
    ) RETURNING id INTO v_order_id;
  END IF;
  IF v_child_table_numbers IS NOT NULL AND array_length(v_child_table_numbers, 1) > 0 THEN
    FOR v_table_number IN SELECT unnest(v_child_table_numbers) LOOP
      INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
      VALUES (p_reservation_id, v_table_number, NOW())
      ON CONFLICT (reservation_id, table_number) DO NOTHING;
      UPDATE public.table_floors SET
        status = 'reserved',
        reservation_id = p_reservation_id,
        reservation_name = v_reservation.name,
        reservation_phone = v_reservation.phone,
        reservation_time = v_reservation.time::text,
        guest_count = v_reservation.guests,
        current_order_id = v_order_id,
        updated_at = NOW()
      WHERE table_number = v_table_number;
    END LOOP;
  END IF;
  UPDATE public.table_floors SET
    status = 'reserved',
    reservation_id = p_reservation_id,
    reservation_name = v_reservation.name,
    reservation_phone = v_reservation.phone,
    reservation_time = v_reservation.time::text,
    guest_count = COALESCE(v_reservation.guests, guest_count),
    current_order_id = v_order_id,
    updated_at = NOW()
  WHERE table_number = v_parent_table_number;
  UPDATE public.reservations SET
    table_ids = p_table_numbers,
    updated_at = NOW()
  WHERE id = p_reservation_id;
  DELETE FROM public.reservation_tables
  WHERE reservation_id = p_reservation_id
    AND table_number = ANY(v_child_table_numbers);
  INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
  SELECT p_reservation_id, tn, NOW()
  FROM unnest(p_table_numbers) AS tn
  ON CONFLICT (reservation_id, table_number) DO NOTHING;
  v_undo := jsonb_build_object(
    'reservation_id', p_reservation_id,
    'table_numbers', p_table_numbers,
    'order_id', v_order_id
  );
  INSERT INTO public.operation_logs (
    table_number, order_id, reservation_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_parent_table_number,
    v_order_id,
    p_reservation_id,
    'assign_reservation_tables',
    jsonb_build_object('table_numbers', p_table_numbers),
    jsonb_build_object('order_id', v_order_id, 'undo', v_undo),
    p_performed_by
  );
  RETURN jsonb_build_object(
    'success', true,
    'reservation_id', p_reservation_id,
    'order_id', v_order_id,
    'undo', v_undo
  );
END;
$$;


--
-- Name: assign_staff_to_location(uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.assign_staff_to_location(p_staff_id uuid, p_location_id uuid, p_is_primary boolean DEFAULT false) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO staff_locations (staff_id, location_id, is_primary)
  VALUES (p_staff_id, p_location_id, p_is_primary)
  ON CONFLICT (staff_id, location_id)
  DO UPDATE SET is_primary = p_is_primary;

  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: atomic_apply_invoice(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.atomic_apply_invoice(p_invoice_id uuid, p_stock_updates jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_applied INT := 0;
  v_id uuid;
  v_corr uuid := gen_random_uuid();
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_stock_updates)
  LOOP
    -- Log-only: current_stock moves ONCE via trg_z_inventory_log_effect.
    INSERT INTO inventory_logs (ingredient_id, type, quantity, cost_per_unit, reason)
    VALUES (
      (v_item->>'ingredient_id')::UUID,
      'stock_in',
      (v_item->>'quantity')::NUMERIC,
      (v_item->>'cost_per_unit')::NUMERIC,
      'Invoice apply: ' || COALESCE((v_item->>'product_name')::TEXT, '')
    )
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      PERFORM public.emit_outbox_event('inventory', (v_item->>'ingredient_id')::UUID, 'inventory.transaction.created',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', (v_item->>'ingredient_id')::UUID, 'quantity', (v_item->>'quantity')::NUMERIC, 'type', 'stock_in'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'apply_invoice', 'invoice_id', p_invoice_id));
      PERFORM public.emit_outbox_event('inventory', (v_item->>'ingredient_id')::UUID, 'inventory.stock_changed',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', (v_item->>'ingredient_id')::UUID, 'quantity', (v_item->>'quantity')::NUMERIC, 'type', 'stock_in'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'apply_invoice', 'invoice_id', p_invoice_id));
    END IF;

    v_applied := v_applied + 1;
  END LOOP;

  UPDATE invoices SET status = 'applied', applied_at = NOW()
  WHERE id = p_invoice_id;

  INSERT INTO transaction_logs (operation, status, details)
  VALUES ('atomic_apply_invoice', 'completed',
    'Invoice:' || p_invoice_id || ' applied:' || v_applied || ' items');

  RETURN jsonb_build_object('success', true, 'applied', v_applied);
END;
$$;


--
-- Name: atomic_receive_goods(uuid, jsonb, jsonb, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.atomic_receive_goods(p_purchase_order_id uuid, p_stock_updates jsonb, p_reviews jsonb, p_invoice_id uuid DEFAULT NULL::uuid, p_po_status text DEFAULT 'partial'::text, p_order_number text DEFAULT ''::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_item JSONB;
  v_matched INT := 0;
  v_total INT;
  v_id uuid;
  v_corr uuid := gen_random_uuid();
BEGIN
  v_total := jsonb_array_length(p_stock_updates);

  -- Update stock for matched items
  -- H10.2 fix: no direct current_stock write here. The inventory_logs
  -- stock_in INSERT below is the single stock mutation; the effect trigger
  -- (trg_apply_inventory_effect) applies +quantity exactly once.
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_stock_updates)
  LOOP
    INSERT INTO inventory_logs (ingredient_id, type, quantity, cost_per_unit, reason, order_id)
    VALUES (
      (v_item->>'ingredient_id')::UUID,
      'stock_in',
      (v_item->>'quantity')::NUMERIC,
      (v_item->>'cost_per_unit')::NUMERIC,
      'Auto-receive from PO ' || p_order_number,
      p_purchase_order_id
    )
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      PERFORM public.emit_outbox_event('inventory', (v_item->>'ingredient_id')::UUID, 'inventory.transaction.created',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', (v_item->>'ingredient_id')::UUID, 'quantity', (v_item->>'quantity')::NUMERIC, 'type', 'stock_in'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'receive_goods', 'purchase_order_id', p_purchase_order_id));
      PERFORM public.emit_outbox_event('inventory', (v_item->>'ingredient_id')::UUID, 'inventory.stock_changed',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', (v_item->>'ingredient_id')::UUID, 'quantity', (v_item->>'quantity')::NUMERIC, 'type', 'stock_in'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'receive_goods', 'purchase_order_id', p_purchase_order_id));
    END IF;

    v_matched := v_matched + 1;
  END LOOP;

  -- Insert reviews
  IF jsonb_array_length(p_reviews) > 0 THEN
    INSERT INTO procurement_reviews (purchase_order_id, invoice_id, product_name, quantity, unit, unit_cost, suggested_ingredient_id, status, severity)
    SELECT
      p_purchase_order_id,
      p_invoice_id,
      (v_item->>'product_name')::TEXT,
      (v_item->>'quantity')::NUMERIC,
      COALESCE((v_item->>'unit')::TEXT, 'gram'),
      (v_item->>'unit_cost')::NUMERIC,
      (v_item->>'suggested_ingredient_id')::UUID,
      'pending',
      'medium'
    FROM jsonb_array_elements(p_reviews) AS v_item;
  END IF;

  -- Update PO status
  UPDATE purchase_orders
  SET status = p_po_status, received_at = NOW()
  WHERE id = p_purchase_order_id;

  -- Log transaction
  INSERT INTO transaction_logs (operation, status, details)
  VALUES ('atomic_receive_goods', 'completed',
    'PO:' || p_purchase_order_id || ' matched:' || v_matched || '/' || v_total);

  RETURN jsonb_build_object(
    'success', true,
    'matched', v_matched,
    'total', v_total,
    'reviews', jsonb_array_length(p_reviews)
  );
END;
$$;


--
-- Name: authorize(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize(p_token text, p_permission text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_session RECORD;
    v_staff RECORD;
    v_role RECORD;
    v_has_perm boolean := false;
    v_loc_access boolean := false;
    v_result jsonb;
BEGIN
    -- 1. Session valid?
    SELECT * INTO v_session FROM sessions
    WHERE token = p_token AND expires_at > now() AND status = 'ACTIVE';

    IF NOT FOUND THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'invalid_session');
    END IF;

    -- 2. Staff active?
    SELECT * INTO v_staff FROM staff WHERE id = v_session.user_id AND status = 'ACTIVE';
    IF NOT FOUND THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'staff_inactive');
    END IF;

    -- 3. Organization match?
    IF v_staff.organization_id != v_session.organization_id THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'org_mismatch');
    END IF;

    -- 4. Location access (if location_id provided)
    IF p_location_id IS NOT NULL THEN
        SELECT EXISTS(
            SELECT 1 FROM staff_locations
            WHERE staff_id = v_staff.id
            AND location_id = p_location_id
            AND active = true
        ) INTO v_loc_access;

        IF NOT v_loc_access THEN
            RETURN jsonb_build_object('allowed', false, 'reason', 'location_denied');
        END IF;
    END IF;

    -- 5. Permission check via role_permissions
    SELECT EXISTS(
        SELECT 1 FROM role_permissions rp
        WHERE rp.role_id = v_staff.role_id
        AND rp.permission_key = p_permission
    ) INTO v_has_perm;

    IF NOT v_has_perm THEN
        RETURN jsonb_build_object('allowed', false, 'reason', 'permission_denied');
    END IF;

    -- 6. All checks passed
    RETURN jsonb_build_object(
        'allowed', true,
        'staff_id', v_staff.id,
        'role_id', v_staff.role_id,
        'organization_id', v_staff.organization_id,
        'location_id', p_location_id
    );
END;
$$;


--
-- Name: authorize_with_reason(text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.authorize_with_reason(p_token text, p_permission text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    RETURN authorize(p_token, p_permission, p_location_id);
END;
$$;


--
-- Name: auto_apply_campaigns(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_apply_campaigns(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_campaign RECORD;
  v_rule RECORD;
  v_total_amount NUMERIC;
  v_item_count INTEGER;
  v_discount NUMERIC := 0;
  v_product_ids TEXT[];
  v_category_ids TEXT[];
  v_target RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'ORDER_NOT_FOUND');
  END IF;

  SELECT COALESCE(SUM(COALESCE(total_price, unit_price * quantity)), 0), COUNT(*)
  INTO v_total_amount, v_item_count
  FROM order_items WHERE order_id = p_order_id;
  IF v_item_count = 0 THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'NO_ITEMS');
  END IF;

  SELECT ARRAY_AGG(DISTINCT oi.product_id::text) FILTER (WHERE oi.product_id IS NOT NULL),
         ARRAY_AGG(DISTINCT p.category_id::text) FILTER (WHERE p.category_id IS NOT NULL)
  INTO v_product_ids, v_category_ids
  FROM order_items oi
  LEFT JOIN products p ON p.id = oi.product_id
  WHERE oi.order_id = p_order_id;

  -- Find best matching active campaign via normalized tables
  SELECT c.* INTO v_campaign
  FROM campaigns c
  WHERE c.is_active = true
    AND c.deleted_at IS NULL
    -- max_uses IS NULL or <= 0 means unlimited; only block when a positive
    -- cap has been reached.
    AND (c.max_uses IS NULL OR c.max_uses <= 0 OR c.current_uses < c.max_uses)
    AND (c.start_date IS NULL OR c.start_date <= CURRENT_DATE)
    AND (c.end_date IS NULL OR c.end_date >= CURRENT_DATE)
    AND EXISTS (
      SELECT 1 FROM campaign_targets ct
      WHERE ct.campaign_id = c.id
        AND (
          ct.target_type = 'category' AND ct.target_id::text = ANY(COALESCE(v_category_ids, ARRAY[]::TEXT[]))
          OR ct.target_type = 'product' AND ct.target_id::text = ANY(COALESCE(v_product_ids, ARRAY[]::TEXT[]))
          OR ct.target_type = 'whole_order'
        )
    )
  ORDER BY c.priority DESC NULLS LAST
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'NO_MATCHING_CAMPAIGN');
  END IF;

  -- Get the rule
  SELECT * INTO v_rule FROM campaign_rules WHERE campaign_id = v_campaign.id LIMIT 1;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('applied', false, 'reason', 'NO_RULE');
  END IF;

  -- Order/delivery-scoped rules produce no item-level discount. Do not apply a
  -- phantom 0.00 — return applied=false so usage is not recorded for them.
  IF v_rule.rule_type IN ('free_delivery', 'combo', 'whole_order') THEN
    RETURN jsonb_build_object(
      'applied', false,
      'reason', 'ORDER_SCOPED_RULE',
      'rule_type', v_rule.rule_type
    );
  END IF;

  -- Calculate discount based on rule type — aligned with the POS inline engine
  -- (src/app/api/pos/products/route.ts computeEffectivePrice).
  IF v_rule.rule_type IN ('percentage', 'happy_hour') THEN
    v_discount := ROUND(v_total_amount * (COALESCE(v_rule.percentage, 0) / 100.0) * 100) / 100;
  ELSIF v_rule.rule_type = 'fixed_amount' THEN
    v_discount := LEAST(COALESCE(v_rule.fixed_amount, 0), v_total_amount);
  ELSIF v_rule.rule_type IN ('buy_x_pay_y', 'buy_x_get_y') THEN
    -- Simplified per-campaign (order-level) approximation: the eligible free
    -- fraction of one unit's price, where buy/pay/free are taken as quantities.
    -- This mirrors the inline engine's per-item math so the value is non-zero
    -- and consistent rather than silently 0.
    DECLARE
      v_buy INTEGER := COALESCE(v_rule.buy_quantity, 2);
      v_pay INTEGER := COALESCE(v_rule.pay_quantity, 1);
      v_free INTEGER := COALESCE(v_rule.free_quantity, 1);
      v_free_per_group NUMERIC;
    BEGIN
      IF v_buy <= 0 THEN v_buy := 2; END IF;
      v_free_per_group := CASE
        WHEN v_rule.rule_type = 'buy_x_pay_y' THEN (v_buy - v_pay)
        ELSE v_free
      END;
      -- Distribute the free fraction across the whole order total proportionally.
      v_discount := ROUND(v_total_amount * (v_free_per_group / v_buy) * 100) / 100;
    END;
  END IF;

  IF v_campaign.max_discount_amount IS NOT NULL AND v_discount > v_campaign.max_discount_amount THEN
    v_discount := v_campaign.max_discount_amount;
  END IF;
  v_discount := GREATEST(0, v_discount);

  -- NOTE: no current_uses increment here. process_order_payment is the sole
  -- writer of campaign_usage + current_uses for the paid order.

  RETURN jsonb_build_object(
    'applied', true,
    'campaign_id', v_campaign.id,
    'discount_amount', v_discount,
    'discount_type', v_rule.rule_type
  );
END;
$$;


--
-- Name: auto_calculate_tip_shortfalls(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_calculate_tip_shortfalls(p_period_start date DEFAULT (CURRENT_DATE - '7 days'::interval), p_period_end date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_staff IN
    SELECT id FROM staff WHERE is_active = true
  LOOP
    PERFORM calculate_tip_shortfall_v2(v_staff.id, p_period_start, p_period_end);
    v_count := v_count + 1;
  END LOOP;

  RETURN json_build_object('success', true, 'processed_staff', v_count);
END;
$$;


--
-- Name: auto_clockout_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_clockout_staff() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_shift RECORD;
  v_count INTEGER := 0;
BEGIN
  FOR v_shift IN
    SELECT s.id, s.staff_id, s.opened_at
    FROM public.shifts s
    WHERE s.closed_at IS NULL
      AND s.auto_closed = false
      AND s.opened_at < NOW() - INTERVAL '12 hours'
  LOOP
    UPDATE public.shifts
    SET closed_at = NOW(), auto_closed = true, auto_closed_at = NOW(),
        status = 'CLOSED',          -- 045 (E/S, proven regression): 019 invariant
        updated_at = NOW()
    WHERE id = v_shift.id;
    v_count := v_count + 1;
  END LOOP;
  RETURN json_build_object('success', true, 'auto_closed_count', v_count);
END;
$$;


--
-- Name: auto_no_show(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_no_show() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_processed INTEGER := 0;
BEGIN
  UPDATE reservations
  SET status = 'no_show',
      cancelled_at = now(),
      cancelled_reason = 'auto_no_show'
  WHERE status = 'confirmed'
    AND (time + INTERVAL '15 minutes') < now()
    AND checked_in_at IS NULL
    AND reservation_type = 'reservation';

  GET DIAGNOSTICS v_processed = ROW_COUNT;
  RETURN v_processed;
END;
$$;


--
-- Name: auto_no_show_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_no_show_v2() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_count INT := 0;
BEGIN
  FOR v_reservation IN
    SELECT * FROM public.reservations
    WHERE status = 'confirmed'
      AND date < CURRENT_DATE
    FOR UPDATE
  LOOP
    UPDATE public.reservations SET
      status = 'no_show',
      no_show_at = NOW(),
      updated_at = NOW()
    WHERE id = v_reservation.id;

    IF v_reservation.table_ids IS NOT NULL AND cardinality(v_reservation.table_ids) > 0 THEN
      UPDATE public.table_floors SET
        status = 'empty',
        reservation_id = NULL,
        reservation_name = NULL,
        reservation_phone = NULL,
        reservation_time = NULL,
        updated_at = NOW()
      WHERE table_number = ANY(v_reservation.table_ids);
    END IF;

    INSERT INTO public.operation_logs (
      operation, old_state, new_state
    ) VALUES (
      'auto_no_show',
      jsonb_build_object('status', 'confirmed'),
      jsonb_build_object('status', 'no_show')
    );

    v_count := v_count + 1;
  END LOOP;

  RETURN jsonb_build_object('success', true, 'processed', v_count);
END;
$$;


--
-- Name: auto_populate_ingredients_i18n(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_populate_ingredients_i18n() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- If ingredients_i18n is null/empty but legacy ingredients exists
    IF (NEW.ingredients_i18n IS NULL OR NEW.ingredients_i18n = '{}') AND NEW.ingredients IS NOT NULL AND array_length(NEW.ingredients, 1) > 0 THEN
        NEW.ingredients_i18n = jsonb_build_object('az', NEW.ingredients);
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: auto_release_expired_holds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.auto_release_expired_holds() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
