    AS $$
DECLARE
  v_released INTEGER := 0;
BEGIN
  UPDATE order_items
  SET hold_until = NULL
  WHERE hold_until IS NOT NULL
    AND hold_until <= now()
    AND kitchen_status = 'pending';

  GET DIAGNOSTICS v_released = ROW_COUNT;
  RETURN v_released;
END;
$$;


--
-- Name: batch_mark_items_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.batch_mark_items_ready(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
