END;
$$;


--
-- Name: calculate_cart_campaign_discount(uuid, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_cart_campaign_discount(p_campaign_id uuid, p_cart_items jsonb, p_product_prices jsonb DEFAULT '{}'::jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_campaign RECORD;
  v_items JSONB;
  v_buy_qty INTEGER;
  v_get_qty INTEGER;
  v_free_items INTEGER := 0;
  v_discount_amount NUMERIC := 0;
  v_item JSONB;
  v_price NUMERIC;
  v_target_items JSONB := '[]'::jsonb;
  v_applicable_count INTEGER := 0;
  v_eligible BOOLEAN;
  v_reason TEXT;
BEGIN
  SELECT * INTO v_campaign FROM campaigns WHERE id = p_campaign_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('discount_amount', 0, 'free_items', 0, 'eligible', FALSE, 'reason', 'Campaign not found');
  END IF;

  IF v_campaign.type NOT IN ('BOGO', 'BUY2GET1') THEN
    RETURN jsonb_build_object('discount_amount', 0, 'free_items', 0, 'eligible', FALSE, 'reason', 'Not a Buy X Get Y campaign');
  END IF;

  IF v_campaign.type = 'BOGO' THEN
    v_buy_qty := 1;
    v_get_qty := 1;
  ELSIF v_campaign.type = 'BUY2GET1' THEN
    v_buy_qty := 2;
    v_get_qty := 1;
  END IF;

  IF v_campaign.buy_quantity IS NOT NULL THEN
    v_buy_qty := v_campaign.buy_quantity;
  END IF;
  IF v_campaign.get_quantity IS NOT NULL THEN
    v_get_qty := v_campaign.get_quantity;
  END IF;

  IF v_campaign.target_type = 'product' AND v_campaign.target_id IS NOT NULL THEN
    SELECT jsonb_agg(item) INTO v_target_items
    FROM jsonb_array_elements(p_cart_items) item
    WHERE item->>'product_id' = v_campaign.target_id;
  ELSIF v_campaign.target_type = 'category' AND v_campaign.target_id IS NOT NULL THEN
    SELECT jsonb_agg(item) INTO v_target_items
    FROM jsonb_array_elements(p_cart_items) item
    WHERE item->>'category_id' = v_campaign.target_id;
  ELSE
    v_target_items := p_cart_items;
  END IF;

  v_applicable_count := 0;
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_target_items)
  LOOP
    v_applicable_count := v_applicable_count + (v_item->>'quantity')::INTEGER;
  END LOOP;

  IF v_applicable_count < v_buy_qty THEN
    RETURN jsonb_build_object('discount_amount', 0, 'free_items', 0, 'eligible', FALSE, 'reason', 'Not enough items');
  END IF;

  v_free_items := (v_applicable_count / (v_buy_qty + v_get_qty)) * v_get_qty;
  IF v_free_items <= 0 THEN
    RETURN jsonb_build_object('discount_amount', 0, 'free_items', 0, 'eligible', TRUE, 'reason', NULL);
  END IF;

  v_discount_amount := 0;
  FOR v_item IN SELECT * FROM jsonb_array_elements(v_target_items) ORDER BY (v_item->>'unit_price')::NUMERIC DESC
  LOOP
    IF v_free_items <= 0 THEN EXIT; END IF;
    v_price := COALESCE((v_item->>'unit_price')::NUMERIC, 0);
    v_discount_amount := v_discount_amount + v_price;
    v_free_items := v_free_items - 1;
  END LOOP;

  RETURN jsonb_build_object(
    'discount_amount', ROUND(v_discount_amount::NUMERIC, 2),
    'free_items', v_free_items + (v_applicable_count / (v_buy_qty + v_get_qty)) * v_get_qty,
    'eligible', TRUE,
    'reason', NULL
  );
END;
$$;


--
-- Name: calculate_cart_campaign_discount(jsonb, uuid, numeric, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_cart_campaign_discount(p_cart_items jsonb, p_customer_id uuid DEFAULT NULL::uuid, p_order_amount numeric DEFAULT 0, p_dining_type text DEFAULT 'dine_in'::text, p_table_number integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_campaign RECORD;
  v_rule RECORD;
  v_target RECORD;
  v_schedule RECORD;
  v_best_campaign_id UUID := NULL;
  v_best_discount NUMERIC := 0;
  v_best_free_items INTEGER := 0;
  v_best_message TEXT := '';
  v_best_rule_type TEXT := '';
  v_calc_result JSONB;
  v_now DATE := CURRENT_DATE;
  v_now_time TEXT := TO_CHAR(NOW(), 'HH24:MI');
  v_day_of_week INTEGER := EXTRACT(DOW FROM CURRENT_TIMESTAMP)::INTEGER;
  v_applicable_items JSONB := '[]'::jsonb;
  v_usage_count INTEGER := 0;
  v_customer_usage_count INTEGER := 0;
BEGIN
  FOR v_campaign IN
    SELECT * FROM campaigns 
    WHERE is_active = TRUE 
      AND deleted_at IS NULL
      AND (start_date IS NULL OR start_date <= v_now)
      AND (end_date IS NULL OR end_date >= v_now)
    ORDER BY priority DESC, created_at DESC
  LOOP
    SELECT * INTO v_schedule FROM campaign_schedules 
    WHERE campaign_id = v_campaign.id 
      AND (start_date IS NULL OR start_date <= v_now)
      AND (end_date IS NULL OR end_date >= v_now)
      AND (is_recurring = TRUE OR (start_time IS NULL OR start_time <= v_now_time))
      AND (is_recurring = TRUE OR (end_time IS NULL OR end_time >= v_now_time))
      AND (weekdays IS NULL OR v_day_of_week = ANY(weekdays))
    LIMIT 1;

    IF v_campaign.start_date IS NULL AND v_campaign.end_date IS NULL AND NOT EXISTS (SELECT 1 FROM campaign_schedules WHERE campaign_id = v_campaign.id) THEN
      v_schedule := NULL;
    ELSIF NOT FOUND THEN
      CONTINUE;
    END IF;

    IF v_campaign.max_uses IS NOT NULL AND v_campaign.max_uses > 0 THEN
      SELECT COUNT(*) INTO v_usage_count FROM campaign_usage WHERE campaign_id = v_campaign.id;
      IF v_usage_count >= v_campaign.max_uses THEN
        CONTINUE;
      END IF;
    END IF;

    IF v_campaign.max_uses_per_customer IS NOT NULL AND p_customer_id IS NOT NULL THEN
      SELECT COUNT(*) INTO v_customer_usage_count FROM campaign_usage WHERE campaign_id = v_campaign.id AND customer_id = p_customer_id;
      IF v_customer_usage_count >= v_campaign.max_uses_per_customer THEN
        CONTINUE;
      END IF;
    END IF;

    IF v_campaign.min_order_amount IS NOT NULL AND p_order_amount < v_campaign.min_order_amount THEN
      CONTINUE;
    END IF;
    IF v_campaign.max_order_amount IS NOT NULL AND p_order_amount > v_campaign.max_order_amount THEN
      CONTINUE;
    END IF;
    IF v_campaign.dining_type IS NOT NULL AND p_dining_type != ANY(v_campaign.dining_type) THEN
      CONTINUE;
    END IF;
    IF v_campaign.table_numbers IS NOT NULL AND p_table_number IS NOT NULL AND p_table_number != ANY(v_campaign.table_numbers) THEN
      CONTINUE;
    END IF;

    SELECT jsonb_agg(item) INTO v_applicable_items
    FROM jsonb_array_elements(p_cart_items) item
    WHERE EXISTS (
      SELECT 1 FROM campaign_targets t
      WHERE t.campaign_id = v_campaign.id
        AND (
          (t.target_type = 'whole_order')
          OR (t.target_type = 'product' AND item->>'product_id' = t.target_id::text)
          OR (t.target_type = 'category' AND item->>'category_id' = t.target_id::text)
        )
    );

    IF v_applicable_items IS NULL OR jsonb_array_length(v_applicable_items) = 0 THEN
      IF EXISTS (SELECT 1 FROM campaign_targets WHERE campaign_id = v_campaign.id AND target_type = 'whole_order') THEN
        v_applicable_items := p_cart_items;
      ELSE
        CONTINUE;
      END IF;
    END IF;

    SELECT * INTO v_rule FROM campaign_rules WHERE campaign_id = v_campaign.id LIMIT 1;
    IF NOT FOUND THEN
      CONTINUE;
    END IF;

    v_calc_result := calculate_rule_discount(v_rule, v_applicable_items);
    IF (v_calc_result->>'discount_amount')::NUMERIC > v_best_discount THEN
      v_best_discount := (v_calc_result->>'discount_amount')::NUMERIC;
      v_best_free_items := (v_calc_result->>'free_items')::INTEGER;
      v_best_campaign_id := v_campaign.id;
      v_best_message := v_calc_result->>'message';
      v_best_rule_type := v_rule.rule_type;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'campaign_id', v_best_campaign_id,
    'discount_amount', ROUND(v_best_discount::NUMERIC, 2),
    'free_items', v_best_free_items,
    'message', v_best_message,
    'rule_type', v_best_rule_type
  );
END;
$$;


--
-- Name: calculate_cart_pricing(jsonb, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_cart_pricing(p_items jsonb, p_current_time timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_item JSONB;
  v_result JSONB := '[]'::JSONB;
  v_pricing JSONB;
  v_subtotal NUMERIC := 0;
  v_total_discount NUMERIC := 0;
  v_total NUMERIC := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_pricing := calculate_effective_price(
      (v_item->>'product_id')::UUID,
      COALESCE((v_item->>'quantity')::INTEGER, 1),
      (v_item->>'category_id')::UUID,
      p_current_time
    );

    v_subtotal := v_subtotal + (v_pricing->>'base_price')::NUMERIC * COALESCE((v_item->>'quantity')::INTEGER, 1);
    v_total := v_total + (v_pricing->>'effective_price')::NUMERIC * COALESCE((v_item->>'quantity')::INTEGER, 1);
    v_total_discount := v_total_discount + (v_pricing->>'discount_amount')::NUMERIC * COALESCE((v_item->>'quantity')::INTEGER, 1);

    v_result := v_result || jsonb_build_object(
      'product_id', v_pricing->>'product_id',
      'quantity', COALESCE((v_item->>'quantity')::INTEGER, 1),
      'base_price', v_pricing->>'base_price',
      'effective_price', v_pricing->>'effective_price',
      'discount_amount', v_pricing->>'discount_amount',
      'discount_type', v_pricing->>'discount_type',
      'campaign_id', v_pricing->>'campaign_id',
      'campaign_label', v_pricing->>'campaign_label',
      'campaign_badge', v_pricing->>'campaign_badge'
    );
  END LOOP;

  RETURN jsonb_build_object(
    'items', v_result,
    'subtotal', v_subtotal,
    'total_discount', v_total_discount,
    'total', v_total
  );
END;
$$;


--
-- Name: calculate_combo_pricing(uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_combo_pricing(p_combo_id uuid, p_current_time timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_combo RECORD;
  v_item RECORD;
  v_pricing JSONB;
  v_original_total NUMERIC := 0;
  v_combo_total NUMERIC := 0;
  v_items JSONB := '[]'::JSONB;
BEGIN
  SELECT * INTO v_combo FROM combos WHERE id = p_combo_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('combo_id', p_combo_id, 'error', 'Combo not found');
  END IF;

  FOR v_item IN
    SELECT ci.*, p.price, p.category_id
    FROM combo_items ci
    JOIN products p ON p.id = ci.product_id
    WHERE ci.combo_id = p_combo_id
    ORDER BY ci.sort_order
  LOOP
    v_pricing := calculate_effective_price(v_item.product_id, v_item.quantity, v_item.category_id, p_current_time);
    v_original_total := v_original_total + (v_pricing->>'base_price')::NUMERIC * v_item.quantity;
    v_combo_total := v_combo_total + (v_pricing->>'effective_price')::NUMERIC * v_item.quantity;

    v_items := v_items || jsonb_build_object(
      'product_id', v_item.product_id,
      'quantity', v_item.quantity,
      'base_price', v_pricing->>'base_price',
      'effective_price', v_pricing->>'effective_price'
    );
  END LOOP;

  RETURN jsonb_build_object(
    'combo_id', p_combo_id,
    'combo_name', v_combo.name,
    'combo_price', COALESCE(v_combo.price, v_combo_total),
    'original_total', v_original_total,
    'combo_total', v_combo_total,
    'you_save', GREATEST(0, v_original_total - v_combo_total),
    'items', v_items
  );
END;
$$;


--
-- Name: calculate_delivery_fee(text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_delivery_fee(p_zone_name text, p_order_amount numeric DEFAULT 0, p_customer_address text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_zone RECORD;
BEGIN
  SELECT * INTO v_zone
  FROM delivery_zones
  WHERE LOWER(name) = LOWER(p_zone_name)
    AND is_active = true
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Zone not found',
      'fee', 0,
      'zone', p_zone_name
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'fee', v_zone.fee,
    'zone', v_zone.name,
    'free_delivery_threshold', v_zone.free_delivery_threshold,
    'estimated_minutes', v_zone.estimated_minutes,
    'is_free', p_order_amount >= COALESCE(v_zone.free_delivery_threshold, 9999999)
  );
END;
$$;


--
-- Name: calculate_effective_price(uuid, integer, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_effective_price(p_product_id uuid, p_quantity integer DEFAULT 1, p_category_id uuid DEFAULT NULL::uuid, p_current_time timestamp with time zone DEFAULT now()) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_product RECORD;
  v_campaign RECORD;
  v_base_price NUMERIC;
  v_effective_price NUMERIC;
  v_discount_amount NUMERIC := 0;
  v_discount_type TEXT;
BEGIN
  SELECT id, price, category_id INTO v_product FROM products WHERE id = p_product_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('product_id', p_product_id, 'base_price', 0, 'effective_price', 0, 'discount_amount', 0);
  END IF;

  v_base_price := COALESCE(v_product.price, 0);

  SELECT * INTO v_campaign FROM campaigns
  WHERE status = 'active'
    AND (start_date IS NULL OR start_date <= p_current_time::DATE)
    AND (end_date IS NULL OR end_date >= p_current_time::DATE)
    AND (start_time IS NULL OR start_time <= p_current_time::TIME)
    AND (end_time IS NULL OR end_time >= p_current_time::TIME)
    AND (max_uses IS NULL OR max_uses = 0 OR current_uses < max_uses)
    AND (
      (target_type = 'product' AND target_id = p_product_id)
      OR (target_type = 'category' AND (target_id = p_category_id OR target_id = v_product.category_id::TEXT))
      OR (target_type = 'all')
      OR (target_type = 'combo')
    )
  ORDER BY priority DESC, created_at DESC
  LIMIT 1;

  IF FOUND THEN
    IF v_campaign.type IN ('PERCENTAGE', 'HAPPY_HOUR') THEN
      v_discount_amount := v_base_price * (COALESCE(v_campaign.discount_value, 0) / 100);
    ELSIF v_campaign.type = 'FIXED_AMOUNT' THEN
      v_discount_amount := COALESCE(v_campaign.discount_value, 0);
    ELSIF v_campaign.type = 'BOGO' THEN
      v_discount_amount := v_base_price * 0.5;
    ELSIF v_campaign.type = 'BUY2GET1' THEN
      v_discount_amount := v_base_price / 3;
    END IF;

    IF v_campaign.max_discount_amount IS NOT NULL AND v_discount_amount > v_campaign.max_discount_amount THEN
      v_discount_amount := v_campaign.max_discount_amount;
    END IF;

    v_discount_type := v_campaign.type;
  END IF;

  v_effective_price := GREATEST(0, v_base_price - v_discount_amount);

  RETURN jsonb_build_object(
    'product_id', p_product_id,
    'base_price', v_base_price,
    'effective_price', v_effective_price,
    'discount_amount', v_discount_amount,
    'discount_type', v_discount_type,
    'campaign_id', CASE WHEN v_campaign.id IS NOT NULL THEN v_campaign.id ELSE NULL END,
    'campaign_label', v_campaign.label,
    'campaign_badge', v_campaign.badge_color
  );
END;
$$;


--
-- Name: calculate_labor_cost(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_labor_cost(p_start_date date DEFAULT (CURRENT_DATE - '7 days'::interval), p_end_date date DEFAULT CURRENT_DATE) RETURNS TABLE(staff_id uuid, staff_name text, role_name text, total_shifts bigint, total_minutes numeric, regular_minutes numeric, overtime_minutes numeric, regular_pay numeric, overtime_pay numeric, total_labor_cost numeric, avg_hourly_cost numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id AS staff_id,
    s.name AS staff_name,
    r.name AS role_name,
    COUNT(sh.id) AS total_shifts,
    -- Total actual minutes worked (clock-in to clock-out only)
    SUM(EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60) AS total_minutes,
    -- Regular minutes (up to max_weekly_hours per week)
    SUM(
      LEAST(
        EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60,
        (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0)
      )
    ) AS regular_minutes,
    -- Overtime minutes (anything beyond max)
    SUM(
      GREATEST(
        EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60 - (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0),
        0
      )
    ) AS overtime_minutes,
    -- Regular pay
    SUM(
      LEAST(
        EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60,
        (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0)
      ) / 60.0 * s.hourly_rate
    ) AS regular_pay,
    -- Overtime pay
    SUM(
      GREATEST(
        EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60 - (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0),
        0
      ) / 60.0 * s.hourly_rate * s.overtime_rate
    ) AS overtime_pay,
    -- Total labor cost
    SUM(
      LEAST(
        EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60,
        (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0)
      ) / 60.0 * s.hourly_rate
    ) + SUM(
      GREATEST(
        EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60 - (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0),
        0
      ) / 60.0 * s.hourly_rate * s.overtime_rate
    ) AS total_labor_cost,
    -- Average hourly cost
    CASE WHEN SUM(EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60) > 0
      THEN (
        SUM(
          LEAST(
            EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60,
            (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0)
          ) / 60.0 * s.hourly_rate
        ) + SUM(
          GREATEST(
            EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60 - (s.max_weekly_hours * 60.0) / NULLIF(COUNT(sh.id) OVER (PARTITION BY s.id), 0),
            0
          ) / 60.0 * s.hourly_rate * s.overtime_rate
        )
      ) / (SUM(EXTRACT(EPOCH FROM (sh.closed_at - sh.opened_at)) / 60) / 60.0)
      ELSE 0
    END AS avg_hourly_cost
  FROM staff s
  JOIN roles r ON r.id = s.role_id
  JOIN shifts sh ON sh.staff_id = s.id
  WHERE sh.closed_at IS NOT NULL
    AND sh.opened_at::date BETWEEN p_start_date AND p_end_date
  GROUP BY s.id, s.name, r.name, s.hourly_rate, s.overtime_rate, s.max_weekly_hours
  ORDER BY total_labor_cost DESC;
END;
$$;


--
-- Name: calculate_order_total(jsonb, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_order_total(p_items jsonb, p_campaign_id uuid DEFAULT NULL::uuid, p_discount_amount numeric DEFAULT 0, p_discount_type text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_subtotal NUMERIC := 0;
  v_item_discount NUMERIC := 0;
  v_discount NUMERIC := 0;
BEGIN
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_subtotal := v_subtotal
      + COALESCE(
          (v_item->>'original_unit_price')::NUMERIC,
          (v_item->>'unit_price')::NUMERIC,
          0
        ) * COALESCE((v_item->>'quantity')::INT, 1);
    v_item_discount := v_item_discount
      + GREATEST(
          0,
          COALESCE(
            (v_item->>'original_unit_price')::NUMERIC,
            (v_item->>'unit_price')::NUMERIC,
            0
          ) - COALESCE((v_item->>'unit_price')::NUMERIC, 0)
        ) * COALESCE((v_item->>'quantity')::INT, 1);
  END LOOP;

  v_discount := LEAST(GREATEST(COALESCE(p_discount_amount, 0), 0), v_subtotal);

  RETURN jsonb_build_object(
    'success', true,
    'subtotal', ROUND(v_subtotal, 2),
    'item_discount', ROUND(v_item_discount, 2),
    'discount', ROUND(v_discount, 2),
    'total', ROUND(GREATEST(0, v_subtotal - v_discount), 2)
  );
END;
$$;


--
-- Name: calculate_order_total_v2(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_order_total_v2(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_items_total NUMERIC;
  v_discount_total NUMERIC;
  v_subtotal NUMERIC;
  v_sc NUMERIC;
  v_tax NUMERIC;
  v_grand_total NUMERIC;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- Sum non-cancelled items
  SELECT
    COALESCE(SUM(total_price), 0),
    COALESCE(SUM(COALESCE(
      (SELECT SUM(d.amount) FROM jsonb_array_elements_text(
        COALESCE(price_snapshot->'discounts', '[]'::JSONB)
      ) AS d(amount)), 0
    ), 0), 0)
  INTO v_items_total, v_discount_total
  FROM order_items
  WHERE order_id = p_order_id
    AND kitchen_status NOT IN ('cancelled');

  v_subtotal := v_items_total - v_discount_total;
  v_sc := round(v_subtotal * COALESCE(v_order.service_charge_pct, 0) / 100, 2);
  v_tax := round((v_subtotal + v_sc) * COALESCE(v_order.tax_pct, 0) / 100, 2);
  v_grand_total := v_subtotal + v_sc + v_tax;

  UPDATE orders SET
    subtotal = v_subtotal,
    discount = v_discount_total,
    service_charge_amount = v_sc,
    tax_amount = v_tax,
    total_amount = v_grand_total,
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'order_id', p_order_id,
    'items_total', v_items_total,
    'discount', v_discount_total,
    'subtotal', v_subtotal,
    'service_charge_pct', v_order.service_charge_pct,
    'service_charge_amount', v_sc,
    'tax_pct', v_order.tax_pct,
    'tax_amount', v_tax,
    'tip_amount', v_order.tip_amount,
    'grand_total', v_grand_total
  );
END;
$$;


--
-- Name: calculate_order_total_v3(uuid, boolean, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_order_total_v3(p_order_id uuid, p_apply_vat boolean DEFAULT false, p_apply_service boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_subtotal NUMERIC;
  v_vat_pct  NUMERIC := 0;
  v_vat_amt  NUMERIC := 0;
  v_svc_pct  NUMERIC := 0;
  v_svc_amt  NUMERIC := 0;
  v_disc     NUMERIC := 0;
  v_total    NUMERIC;
  v_cfg      RECORD;
  v_order    RECORD;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  SELECT vat_percentage, receipt_show_service_fee, receipt_service_fee_pct
    INTO v_cfg
    FROM public.settings WHERE id = '1';

  -- Subtotal: active items only (void/cancel excluded).
  SELECT COALESCE(SUM(total_price), 0) INTO v_subtotal
    FROM public.order_items
   WHERE order_id = p_order_id
     AND kitchen_status NOT IN ('cancelled','voided');

  -- VAT: the per-order toggle (p_apply_vat) is the authority.
  -- Percentage from settings.vat_percentage.
  IF p_apply_vat THEN
    v_vat_pct := COALESCE(v_cfg.vat_percentage, 0);
    v_vat_amt := ROUND(v_subtotal * v_vat_pct / 100, 2);
  END IF;

  -- Service charge (opt-in, R1: on SUBTOTAL — no tax-on-tax).
  IF p_apply_service AND COALESCE(v_cfg.receipt_show_service_fee, false) THEN
    v_svc_pct := COALESCE(v_cfg.receipt_service_fee_pct, 0);
    v_svc_amt := ROUND(v_subtotal * v_svc_pct / 100, 2);
  END IF;

  SELECT COALESCE(discount_amount, 0) INTO v_disc FROM public.orders WHERE id = p_order_id;

  v_total := v_subtotal + v_vat_amt + v_svc_amt - v_disc;
  IF v_total < 0 THEN v_total := 0; END IF;

  UPDATE public.orders SET
    total_amount          = v_total,
    tax_pct               = v_vat_pct,
    tax_amount            = v_vat_amt,
    service_charge_pct    = v_svc_pct,
    service_charge_amount = v_svc_amt,
    apply_vat             = p_apply_vat,
    version               = COALESCE(v_order.version, 0) + 1,
    updated_at            = NOW()
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'subtotal', v_subtotal,
    'tax_amount', v_vat_amt,
    'service_charge_amount', v_svc_amt,
    'discount_amount', v_disc,
    'total', v_total
  );
END;
$$;


SET default_table_access_method = heap;

--
-- Name: campaign_rules; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.campaign_rules (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    campaign_id uuid NOT NULL,
    rule_type text NOT NULL,
    percentage numeric(5,2),
    fixed_amount numeric(10,2),
    min_purchase_amount numeric(10,2),
    buy_quantity integer,
    pay_quantity integer,
    free_quantity integer,
    reward_product_id uuid,
    reward_category_id uuid,
    reward_same_as_buy boolean DEFAULT true,
    start_time time without time zone,
    end_time time without time zone,
    weekdays integer[] DEFAULT '{1,2,3,4,5,6,7}'::integer[],
    is_recurring boolean DEFAULT false,
    delivery_min_order numeric(10,2),
    delivery_zones text[],
    combo_id uuid,
    combo_discount_type text DEFAULT 'fixed'::text,
    combo_discount_value numeric(10,2) DEFAULT 0,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    updated_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT campaign_rules_rule_type_check CHECK ((rule_type = ANY (ARRAY['percentage'::text, 'fixed_amount'::text, 'buy_x_pay_y'::text, 'buy_x_get_y'::text, 'happy_hour'::text, 'free_delivery'::text, 'combo'::text])))
);


--
-- Name: calculate_rule_discount(public.campaign_rules, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_rule_discount(p_rule public.campaign_rules, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_discount NUMERIC := 0;
  v_free_items INTEGER := 0;
  v_message TEXT := '';
  v_item JSONB;
  v_applicable_count INTEGER := 0;
  v_sorted_items JSONB;
  v_price NUMERIC;
BEGIN
  IF p_rule.rule_type = 'percentage' THEN
    v_discount := 0;
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      v_price := COALESCE((v_item->>'unit_price')::NUMERIC, 0);
      v_discount := v_discount + (v_price * (p_rule.percentage / 100));
    END LOOP;
    v_message := format('%s%% endirim', p_rule.percentage);

  ELSIF p_rule.rule_type = 'fixed_amount' THEN
    v_discount := LEAST(COALESCE(p_rule.fixed_amount, 0), (SELECT SUM((item->>'unit_price')::NUMERIC) FROM jsonb_array_elements(p_items) item));
    v_message := format('₼%s endirim', p_rule.fixed_amount);

  ELSIF p_rule.rule_type = 'buy_x_pay_y' THEN
    v_applicable_count := (SELECT SUM((item->>'quantity')::INTEGER) FROM jsonb_array_elements(p_items) item);
    IF v_applicable_count >= COALESCE(p_rule.buy_quantity, 1) THEN
      v_free_items := (v_applicable_count / p_rule.buy_quantity) * (p_rule.buy_quantity - p_rule.pay_quantity);
      IF v_free_items > 0 THEN
        v_sorted_items := (SELECT jsonb_agg(item) FROM jsonb_array_elements(p_items) item ORDER BY (item->>'unit_price')::NUMERIC DESC);
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_sorted_items)
        LOOP
          IF v_free_items <= 0 THEN EXIT; END IF;
          v_price := COALESCE((v_item->>'unit_price')::NUMERIC, 0);
          v_discount := v_discount + v_price;
          v_free_items := v_free_items - 1;
        END LOOP;
        v_free_items := (v_applicable_count / p_rule.buy_quantity) * (p_rule.buy_quantity - p_rule.pay_quantity);
      END IF;
      v_message := format('%s al %s ödə', p_rule.buy_quantity, p_rule.pay_quantity);
    END IF;

  ELSIF p_rule.rule_type = 'buy_x_get_y' THEN
    v_applicable_count := (SELECT SUM((item->>'quantity')::INTEGER) FROM jsonb_array_elements(p_items) item);
    IF v_applicable_count >= COALESCE(p_rule.buy_quantity, 1) THEN
      v_free_items := (v_applicable_count / (p_rule.buy_quantity + p_rule.free_quantity)) * p_rule.free_quantity;
      IF v_free_items > 0 THEN
        v_sorted_items := (SELECT jsonb_agg(item) FROM jsonb_array_elements(p_items) item ORDER BY (item->>'unit_price')::NUMERIC DESC);
        FOR v_item IN SELECT * FROM jsonb_array_elements(v_sorted_items)
        LOOP
          IF v_free_items <= 0 THEN EXIT; END IF;
          v_price := COALESCE((v_item->>'unit_price')::NUMERIC, 0);
          v_discount := v_discount + v_price;
          v_free_items := v_free_items - 1;
        END LOOP;
        v_free_items := (v_applicable_count / (p_rule.buy_quantity + p_rule.free_quantity)) * p_rule.free_quantity;
      END IF;
      v_message := format('%s al %s pulsuz', p_rule.buy_quantity, p_rule.free_quantity);
    END IF;

  ELSIF p_rule.rule_type = 'happy_hour' THEN
    v_discount := 0;
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      v_price := COALESCE((v_item->>'unit_price')::NUMERIC, 0);
      v_discount := v_discount + (v_price * (COALESCE(p_rule.percentage, 0) / 100));
    END LOOP;
    v_message := format('Happy Hour: %s%%', COALESCE(p_rule.percentage, 0));

  ELSIF p_rule.rule_type = 'free_delivery' THEN
    v_discount := 0;
    v_message := 'Pulsuz çatdırılma';
  END IF;

  RETURN jsonb_build_object(
    'discount_amount', ROUND(v_discount::NUMERIC, 2),
    'free_items', v_free_items,
    'message', v_message
  );
END;
$$;


--
-- Name: calculate_shift_overtime(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_shift_overtime(p_shift_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_shift RECORD;
  v_rate NUMERIC;
  v_tz text;
  v_worked NUMERIC;
  v_day_worked NUMERIC;
  v_week_worked NUMERIC;
  v_week_daily_ot NUMERIC;
  v_daily_ot NUMERIC;
  v_double_ot NUMERIC;
  v_weekly_ot NUMERIC;
  v_daily_th NUMERIC := 8;
  v_double_th NUMERIC := 12;
  v_weekly_th NUMERIC := 40;
  v_daily_rate NUMERIC := 1.5;
  v_double_rate NUMERIC := 2.0;
  v_weekly_rate NUMERIC := 1.5;
  v_bdate date;
  v_week_monday date;
  v_week_sunday date;
  v_week_start timestamptz;
  v_week_end timestamptz;
BEGIN
  -- S-04 harden: serialize per-shift recompute (TOCTOU window on delete+insert)
  PERFORM pg_advisory_xact_lock(hashtext(p_shift_id::text));

  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id;
  IF NOT FOUND OR v_shift.closed_at IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Shift not found or not closed');
  END IF;

  SELECT hours INTO v_daily_th FROM overtime_thresholds WHERE threshold_type='daily' AND is_active LIMIT 1;
  SELECT hours INTO v_double_th FROM overtime_thresholds WHERE threshold_type='double' AND is_active LIMIT 1;
  SELECT hours INTO v_weekly_th FROM overtime_thresholds WHERE threshold_type='weekly' AND is_active LIMIT 1;
  SELECT rate_multiplier INTO v_daily_rate FROM overtime_thresholds WHERE threshold_type='daily' AND is_active LIMIT 1;
  SELECT rate_multiplier INTO v_double_rate FROM overtime_thresholds WHERE threshold_type='double' AND is_active LIMIT 1;
  SELECT rate_multiplier INTO v_weekly_rate FROM overtime_thresholds WHERE threshold_type='weekly' AND is_active LIMIT 1;
  v_daily_th := coalesce(v_daily_th, 8); v_double_th := coalesce(v_double_th, 12);
  v_weekly_th := coalesce(v_weekly_th, 40);
  v_daily_rate := coalesce(v_daily_rate, 1.5); v_double_rate := coalesce(v_double_rate, 2.0);
  v_weekly_rate := coalesce(v_weekly_rate, 1.5);

  v_tz := COALESCE((SELECT timezone FROM locations WHERE id = v_shift.location_id), current_setting('TimeZone'));
  v_rate := (SELECT hourly_rate FROM staff WHERE id = v_shift.staff_id);
  v_bdate := public.local_day(v_shift.opened_at, v_shift.location_id);

  SELECT COALESCE(EXTRACT(EPOCH FROM (v_shift.closed_at - v_shift.opened_at))/3600.0, 0)
       - COALESCE(EXTRACT(EPOCH FROM (
             SELECT SUM(sb.ended_at - sb.started_at)
             FROM shift_breaks sb WHERE sb.shift_id = v_shift.id AND sb.ended_at IS NOT NULL
           ))/3600.0, 0)
    INTO v_worked;
  v_worked := GREATEST(v_worked, 0);

  SELECT COALESCE(SUM(
        GREATEST(EXTRACT(EPOCH FROM (s.closed_at - s.opened_at))/3600.0
        - COALESCE(EXTRACT(EPOCH FROM (
             SELECT SUM(sb.ended_at - sb.started_at) FROM shift_breaks sb
             WHERE sb.shift_id = s.id AND sb.ended_at IS NOT NULL)) / 3600.0, 0), 0)
      ), 0) INTO v_day_worked
  FROM shifts s
  WHERE s.staff_id = v_shift.staff_id AND s.closed_at IS NOT NULL
    AND public.local_day(s.opened_at, s.location_id) = v_bdate;

  v_week_monday := v_bdate - extract(isodow FROM v_bdate::timestamp)::int + 1;
  v_week_sunday := v_week_monday + 6;
  v_week_start := (v_week_monday::timestamp AT TIME ZONE v_tz);
  v_week_end   := ((v_week_monday + 7)::timestamp AT TIME ZONE v_tz);

  SELECT COALESCE(SUM(
        GREATEST(EXTRACT(EPOCH FROM (s.closed_at - s.opened_at))/3600.0
        - COALESCE(EXTRACT(EPOCH FROM (
             SELECT SUM(sb.ended_at - sb.started_at) FROM shift_breaks sb
             WHERE sb.shift_id = s.id AND sb.ended_at IS NOT NULL)) / 3600.0, 0), 0)
      ), 0) INTO v_week_worked
  FROM shifts s
  WHERE s.staff_id = v_shift.staff_id AND s.closed_at IS NOT NULL
    AND s.opened_at >= v_week_start AND s.opened_at < v_week_end;

  SELECT COALESCE(SUM(
        GREATEST(LEAST(day_w, v_double_th) - v_daily_th, 0)
      + GREATEST(day_w - v_double_th, 0)), 0) INTO v_week_daily_ot
  FROM (
    SELECT COALESCE(SUM(
              GREATEST(EXTRACT(EPOCH FROM (s.closed_at - s.opened_at))/3600.0
              - COALESCE(EXTRACT(EPOCH FROM (
                   SELECT SUM(sb.ended_at - sb.started_at) FROM shift_breaks sb
                   WHERE sb.shift_id = s.id AND sb.ended_at IS NOT NULL)) / 3600.0, 0), 0)
            ), 0) AS day_w
    FROM shifts s
    WHERE s.staff_id = v_shift.staff_id AND s.closed_at IS NOT NULL
      AND s.opened_at >= v_week_start AND s.opened_at < v_week_end
    GROUP BY public.local_day(s.opened_at, s.location_id)
  ) d;

  v_daily_ot  := GREATEST(LEAST(v_day_worked, v_double_th) - v_daily_th, 0);
  v_double_ot := GREATEST(v_day_worked - v_double_th, 0);
  v_weekly_ot := GREATEST(v_week_worked - v_weekly_th - v_week_daily_ot, 0);

  DELETE FROM overtime_records
  WHERE staff_id = v_shift.staff_id AND overtime_type IN ('daily','double')
    AND approved = false AND business_date = v_bdate;
  DELETE FROM overtime_records
  WHERE staff_id = v_shift.staff_id AND overtime_type = 'weekly' AND approved = false
    AND business_date >= v_week_monday AND business_date <= v_week_sunday;

  IF v_daily_ot > 0 AND v_rate IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM overtime_records
                     WHERE staff_id=v_shift.staff_id AND overtime_type='daily' AND approved=true AND business_date=v_bdate) THEN
    INSERT INTO overtime_records (staff_id, shift_id, overtime_type, hours, rate_multiplier, calculated_amount, business_date, approved)
    VALUES (v_shift.staff_id, v_shift.id, 'daily', ROUND(v_daily_ot,3), v_daily_rate, ROUND(v_daily_ot * v_rate * v_daily_rate, 2), v_bdate, false);
  END IF;
  IF v_double_ot > 0 AND v_rate IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM overtime_records
                     WHERE staff_id=v_shift.staff_id AND overtime_type='double' AND approved=true AND business_date=v_bdate) THEN
    INSERT INTO overtime_records (staff_id, shift_id, overtime_type, hours, rate_multiplier, calculated_amount, business_date, approved)
    VALUES (v_shift.staff_id, v_shift.id, 'double', ROUND(v_double_ot,3), v_double_rate, ROUND(v_double_ot * v_rate * v_double_rate, 2), v_bdate, false);
  END IF;
  IF v_weekly_ot > 0 AND v_rate IS NOT NULL
     AND NOT EXISTS (SELECT 1 FROM overtime_records
                     WHERE staff_id=v_shift.staff_id AND overtime_type='weekly' AND approved=true
                       AND business_date >= v_week_monday AND business_date <= v_week_sunday) THEN
    INSERT INTO overtime_records (staff_id, shift_id, overtime_type, hours, rate_multiplier, calculated_amount, business_date, approved)
    VALUES (v_shift.staff_id, v_shift.id, 'weekly', ROUND(v_weekly_ot,3), v_weekly_rate, ROUND(v_weekly_ot * v_rate * v_weekly_rate, 2), v_bdate, false);
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'shift_id', p_shift_id, 'business_date', v_bdate,
    'worked_hours', ROUND(v_worked,3), 'day_worked', ROUND(v_day_worked,3),
    'week_worked', ROUND(v_week_worked,3),
    'daily_ot_hours', ROUND(v_daily_ot,3), 'double_ot_hours', ROUND(v_double_ot,3),
    'weekly_ot_hours', ROUND(v_weekly_ot,3), 'hourly_rate', v_rate
  );
END;
$$;


--
-- Name: calculate_tip_shortfall(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_tip_shortfall(p_staff_id uuid, p_period_start date, p_period_end date) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hours DECIMAL := 0;
  v_tips DECIMAL := 0;
  v_min_wage DECIMAL := 15.0;
  v_tipped_wage DECIMAL := 5.0;
  v_shortfall DECIMAL := 0;
BEGIN
  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (clock_out - clock_in)) / 3600), 0)
  INTO v_hours
  FROM time_clock_entries
  WHERE staff_id = p_staff_id
    AND DATE(clock_in) BETWEEN p_period_start AND p_period_end;

  SELECT COALESCE(SUM(declared_cash_tips + non_cash_tips), 0)
  INTO v_tips
  FROM shift_reviews sr
  JOIN shifts s ON s.id = sr.shift_id
  WHERE sr.staff_id = p_staff_id
    AND DATE(s.opened_at) BETWEEN p_period_start AND p_period_end;

  IF (v_hours * v_tipped_wage + v_tips) < (v_hours * v_min_wage) THEN
    v_shortfall := (v_hours * v_min_wage) - (v_hours * v_tipped_wage + v_tips);
  END IF;

  RETURN json_build_object(
    'hours_worked', v_hours,
    'tips_earned', v_tips,
    'shortfall_amount', v_shortfall,
    'minimum_wage', v_min_wage
  );
END;
$$;


--
-- Name: calculate_tip_shortfall_v2(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.calculate_tip_shortfall_v2(p_staff_id uuid, p_period_start date, p_period_end date) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hours DECIMAL := 0;
  v_tips DECIMAL := 0;
  v_min_wage DECIMAL := 15.0;
  v_tipped_wage DECIMAL := 5.0;
  v_shortfall DECIMAL := 0;
  v_shift_review_id UUID;
BEGIN
  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (tce.clock_out - tce.clock_in)) / 3600), 0)
  INTO v_hours
  FROM time_clock_entries tce
  WHERE tce.staff_id = p_staff_id
    AND DATE(tce.clock_in) BETWEEN p_period_start AND p_period_end;

  SELECT COALESCE(SUM(sr.declared_cash_tips), 0)
  INTO v_tips
  FROM shift_reviews sr
  JOIN shifts s ON s.id = sr.shift_id
  WHERE sr.staff_id = p_staff_id
    AND DATE(s.opened_at) BETWEEN p_period_start AND p_period_end;

  IF (v_hours * v_tipped_wage + v_tips) < (v_hours * v_min_wage) THEN
    v_shortfall := (v_hours * v_min_wage) - (v_hours * v_tipped_wage + v_tips);
  END IF;

  INSERT INTO tip_shortfalls (
    staff_id, period_start, period_end, hours_worked, tipped_wage_rate,
    minimum_wage, tips_earned, shortfall_amount
  ) VALUES (
    p_staff_id, p_period_start, p_period_end, v_hours, v_tipped_wage,
    v_min_wage, v_tips, v_shortfall
  )
  ON CONFLICT (staff_id, period_start, period_end)
  DO UPDATE SET
    hours_worked = EXCLUDED.hours_worked,
    tipped_wage_rate = EXCLUDED.tipped_wage_rate,
    minimum_wage = EXCLUDED.minimum_wage,
    tips_earned = EXCLUDED.tips_earned,
    shortfall_amount = EXCLUDED.shortfall_amount;

  RETURN json_build_object(
    'hours_worked', v_hours,
    'tips_earned', v_tips,
    'shortfall_amount', v_shortfall,
    'minimum_wage', v_min_wage
  );
END;
$$;


--
-- Name: cancel_delivery_order(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_delivery_order(p_order_id uuid, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status IN ('paid', 'closed', 'cancelled') THEN
    RAISE EXCEPTION 'CANNOT_CANCEL' USING ERRCODE = 'P0001';
  END IF;

  -- Free courier if assigned
  IF v_order.courier_id IS NOT NULL THEN
    UPDATE couriers SET current_order_id = NULL WHERE id = v_order.courier_id;
  END IF;

  UPDATE orders SET
    status = 'cancelled',
    delivery_status = 'cancelled',
    kitchen_status = 'cancelled',
    cancelled_at = now(),
    cancelled_reason = p_reason,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  -- Cancel all active items
  UPDATE order_items SET kitchen_status = 'cancelled'
  WHERE order_id = p_order_id
    AND kitchen_status NOT IN ('cancelled', 'served', 'completed');

  PERFORM log_order_event(
    p_order_id, 'order_cancelled',
    jsonb_build_object('status', v_order.status, 'delivery_status', v_order.delivery_status),
    jsonb_build_object('reason', p_reason),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id);
END;
$$;


--
-- Name: cancel_loss_table(text, integer, text, text, numeric, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_loss_table(p_token text, p_table_number integer, p_reason text, p_reason_text text, p_total_amount numeric, p_items jsonb, p_performed_by uuid, p_terminal_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_sess_loc uuid;
  v_table RECORD;
  v_order_ids uuid[];
  v_order_id  uuid;
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF v_staff_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(v_staff_id, 'orders.cancel'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  SELECT * INTO v_table FROM public.table_floors
    WHERE table_number = p_table_number AND (v_sess_loc IS NULL OR location_id = v_sess_loc) FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  IF NOT has_location_access(v_table.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;

  INSERT INTO public.cancelled_orders (order_id, table_number, reason, reason_text, total_amount, items, created_at)
  SELECT o.id, p_table_number, p_reason, COALESCE(p_reason_text, p_reason), p_total_amount, p_items, now()
  FROM public.orders o
  WHERE o.table_number = p_table_number
    AND o.location_id = v_table.location_id
    AND o.status NOT IN ('paid', 'cancelled')
  RETURNING order_id INTO v_order_ids;

  FOREACH v_order_id IN ARRAY v_order_ids LOOP
    -- items -> cancelled (item machine allows every non-cancelled -> cancelled)
    UPDATE public.order_items
    SET kitchen_status = 'cancelled', updated_at = now()
    WHERE order_id = v_order_id AND kitchen_status IS DISTINCT FROM 'cancelled';

    -- order -> cancelled via the canonical permissioned+locationed atomic (re-authz is
    -- safe: same location, and the actor holds orders.cancel). Token carried through.
    PERFORM public.transition_order_atomic(p_token, v_order_id, 'cancelled', p_reason,
      jsonb_build_object('source','cancel_loss_table','table_number', p_table_number));
  END LOOP;

  UPDATE public.table_floors
  SET status = 'empty',
      guest_count = NULL,
      reservation_id = NULL, reservation_name = NULL, reservation_phone = NULL, reservation_time = NULL,
      merged_into_table = NULL,
      current_order_id = NULL,
      has_pending = false, oldest_pending_at = NULL,
      updated_at = now(),
      updated_by_terminal_id = p_terminal_id
  WHERE table_number = p_table_number;

  PERFORM public.log_audit(
    'loss_table_cancelled', NULL, NULL, v_staff_id,
    NULL, NULL, NULL, NULL,
    jsonb_build_object('table_number', p_table_number, 'reason', p_reason, 'orders_cancelled', coalesce(array_length(v_order_ids,1),0)),
    NULL, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'orders_cancelled', coalesce(array_length(v_order_ids,1),0));
END;
$$;


--
-- Name: cancel_order_items(uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_order_items(p_order_id uuid, p_items jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_item JSONB;
  v_rev jsonb;
  v_item_id uuid;
  v_reversed INTEGER := 0;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- Full cancel / delete every requested item; reversal (when it was
  -- consumed) is applied by the canonical helper. No-op when the item
  -- was never consumed, and idempotency-keyed otherwise (H6).
  -- A consumed item cannot be hard-deleted (immutable ledger rows still
  -- reference it via FK), so it is soft-cancelled instead — the same
  -- terminal-state treatment used by the canonical void/waste paths.
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items) LOOP
    v_item_id := (v_item->>'order_item_id')::uuid;

    v_rev := public._inventory_reverse_item(
      v_item_id,
      'cancel',
      NULL
    );

    IF EXISTS (
      SELECT 1 FROM public.inventory_logs WHERE order_item_id = v_item_id
    ) THEN
      UPDATE public.order_items SET
        kitchen_status = 'cancelled',
        total_price = 0,
        served_at = NULL,
        updated_at = now()
      WHERE id = v_item_id AND order_id = p_order_id;
    ELSE
      DELETE FROM public.order_items
      WHERE id = v_item_id AND order_id = p_order_id;
    END IF;

    IF (v_rev->>'reversed')::int > 0 THEN
      v_reversed := v_reversed + (v_rev->>'reversed')::int;
    END IF;
  END LOOP;

  UPDATE public.orders SET
    total_amount = GREATEST(0, (
      SELECT COALESCE(SUM(total_price), 0) FROM public.order_items
      WHERE order_id = p_order_id
        AND kitchen_status NOT IN ('cancelled', 'voided', 'wasted', 'comped')
    )),
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'cancelled_items', jsonb_array_length(p_items),
    'reversed_stock', v_reversed
  );
END;
$$;


--
-- Name: cancel_reservation_atomic(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_reservation_atomic(p_reservation_id uuid, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
  v_reservation RECORD;
  v_table RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;

  IF v_reservation.status IN ('cancelled', 'completed', 'no_show') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation already final');
  END IF;

  -- Delete pre-order items
  DELETE FROM public.reservation_preorder_items WHERE reservation_id = p_reservation_id;

  -- Update reservation
  UPDATE public.reservations SET
    status = 'cancelled',
    cancelled_at = NOW(),
    cancelled_reason = p_reason,
    updated_at = NOW()
  WHERE id = p_reservation_id;

  -- Free table if assigned
  IF v_reservation.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      status = 'empty',
      reservation_id = NULL,
      reservation_name = NULL,
      reservation_phone = NULL,
      reservation_time = NULL,
      current_order_id = NULL,
      updated_at = NOW()
    WHERE table_number = v_reservation.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    reservation_id, action, old_values, new_values, performed_by
  ) VALUES (
    p_reservation_id,
    'cancel_reservation',
    jsonb_build_object('status', v_reservation.status),
    jsonb_build_object('status', 'cancelled', 'reason', p_reason),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: cancel_reservation_from_pos(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_reservation_from_pos(p_reservation_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
begin
  update public.reservations
    set status = 'cancelled',
        cancelled_at = now(),
        cancelled_reason = 'cancelled_from_pos',
        pre_order_items = '[]'::jsonb,
        pre_order_total = 0,
        updated_at = now()
  where id = p_reservation_id;
end;
$$;


--
-- Name: cancel_table_orders(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_table_orders(p_table_number integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_orders RECORD;
  v_order_ids UUID[];
  v_reversed_count INTEGER := 0;
  v_item RECORD;
BEGIN
  FOR v_orders IN
    SELECT id FROM public.orders
    WHERE table_number = p_table_number AND status NOT IN ('paid', 'cancelled', 'closed')
    FOR UPDATE
  LOOP
    v_order_ids := array_append(v_order_ids, v_orders.id);
  END LOOP;

  IF array_length(v_order_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', true, 'cancelled_orders', 0);
  END IF;

  -- Canonical reversal for every consumed item on the cancelled orders.
  FOR v_item IN
    SELECT id FROM public.order_items
    WHERE order_id = ANY(v_order_ids)
      AND kitchen_status IS DISTINCT FROM 'cancelled'
      AND (served_quantity IS NULL OR served_quantity = 0)
  LOOP
    PERFORM public._inventory_reverse_item(v_item.id, 'cancel', p_performed_by);
  END LOOP;

  UPDATE public.order_items
  SET kitchen_status = 'cancelled'
  WHERE order_id = ANY(v_order_ids)
    AND kitchen_status IS DISTINCT FROM 'cancelled';

  UPDATE public.orders
  SET status = 'cancelled', kitchen_status = 'cancelled', version = COALESCE(version, 0) + 1
  WHERE id = ANY(v_order_ids);

  UPDATE public.table_floors
  SET
    status = 'empty',
    guest_count = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    merged_into_table = NULL
  WHERE table_number = p_table_number;

  INSERT INTO public.audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'orders',
    v_order_ids[1],
    'cancel',
    jsonb_build_object('table_number', p_table_number, 'order_ids', v_order_ids),
    jsonb_build_object('status', 'cancelled'),
    p_performed_by,
    now()
  );

  -- Count reversed ledger rows for the audit/return
  SELECT COUNT(*) INTO v_reversed_count
  FROM public.inventory_logs l
  JOIN public.order_items oi ON oi.id = l.order_item_id
  WHERE oi.order_id = ANY(v_order_ids) AND l.type = 'reversal';

  RETURN jsonb_build_object(
    'success', true,
    'cancelled_orders', array_length(v_order_ids, 1),
    'reversed_items', v_reversed_count
  );
END;
$$;


--
-- Name: cancel_table_orders(integer, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_table_orders(p_table_number integer, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_count integer := 0;
BEGIN
  FOR v_order IN
    SELECT * FROM public.orders
    WHERE table_number = p_table_number
      AND status NOT IN ('paid', 'cancelled', 'closed', 'completed')
    FOR UPDATE
  LOOP
    UPDATE public.orders SET
      status = 'cancelled',
      cancelled_at = NOW(),
      cancelled_reason = COALESCE(p_reason, 'Cancelled by staff'),
      updated_at = NOW(),
      version = COALESCE(v_order.version, 0) + 1
    WHERE id = v_order.id;
    v_count := v_count + 1;
  END LOOP;

  UPDATE public.table_floors SET
    status = 'empty',
    guest_count = NULL,
    order_count = 0,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    merged_into_table = NULL,
    updated_at = NOW()
  WHERE table_number = p_table_number;

  INSERT INTO public.operation_logs (
    table_number, action, old_values, new_values, performed_by
  ) VALUES (
    p_table_number,
    'cancel_table_orders',
    jsonb_build_object('cancelled_orders', v_count),
    jsonb_build_object('status', 'empty', 'order_count', 0),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'cancelled_orders', v_count);
END;
$$;


--
-- Name: cancel_takeaway_order(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_takeaway_order(p_order_id uuid, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status IN ('paid', 'closed', 'cancelled') THEN
    RAISE EXCEPTION 'CANNOT_CANCEL' USING ERRCODE = 'P0001';
  END IF;

  UPDATE orders SET
    status = 'cancelled',
    kitchen_status = 'cancelled',
    cancelled_at = now(),
    cancelled_reason = p_reason,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  -- Cancel all active items
  UPDATE order_items SET kitchen_status = 'cancelled'
  WHERE order_id = p_order_id
    AND kitchen_status NOT IN ('cancelled', 'served', 'completed');

  PERFORM log_order_event(
    p_order_id, 'order_cancelled',
    jsonb_build_object('status', v_order.status),
    jsonb_build_object('reason', p_reason),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id);
END;
$$;


--
-- Name: cancel_ticket_atomic(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cancel_ticket_atomic(p_order_id uuid, p_reason text DEFAULT 'kitchen_cancel'::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status IN ('cancelled', 'served', 'ready') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order cannot be cancelled from current status');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'cancelled',
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  UPDATE public.order_items SET
    kitchen_status = 'cancelled',
    updated_at = NOW()
  WHERE order_id = p_order_id AND kitchen_status NOT IN ('cancelled', 'served');

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'cancelled',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'cancel_ticket',
    jsonb_build_object('kitchen_status', v_order.kitchen_status),
    jsonb_build_object('kitchen_status', 'cancelled', 'reason', p_reason),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: cash_in_atomic(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cash_in_atomic(p_session_id uuid, p_amount numeric, p_description text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session RECORD;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
BEGIN
  IF p_amount IS NULL OR p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount must be positive');
  END IF;

  SELECT * INTO v_session FROM public.cash_drawer_sessions
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Session not found');
  END IF;

  IF v_session.status != 'open' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Session is not open');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  INSERT INTO public.cash_drawer_log (session_id, type, amount, description, created_by)
  VALUES (p_session_id, 'cash_in', p_amount, COALESCE(p_description, 'Kassa daxilolma'), p_performed_by);

  PERFORM public.log_audit(
    'cash_in', 'cash_drawer_session', p_session_id::text,
    p_performed_by, v_performer_name,
    NULL,
    jsonb_build_object('amount', p_amount, 'type', 'cash_in', 'description', p_description),
    jsonb_build_object('session_id', p_session_id),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'session_id', p_session_id,
    'amount', p_amount,
    'type', 'cash_in',
    'created_at', v_now
  );
END;
$$;


