--
-- Name: check_break_eligibility(uuid, uuid, character varying); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_break_eligibility(p_staff_id uuid, p_shift_id uuid, p_break_type character varying) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_hours_worked DECIMAL;
  v_eligible BOOLEAN := false;
  v_reason TEXT := '';
BEGIN
  SELECT EXTRACT(EPOCH FROM (NOW() - opened_at)) / 3600
  INTO v_hours_worked
  FROM shifts
  WHERE id = p_shift_id AND closed_at IS NULL;

  IF p_break_type = 'meal' THEN
    IF v_hours_worked >= 5 THEN
      v_eligible := true;
    ELSE
      v_eligible := false;
      v_reason := 'Meal break requires 5+ hours worked';
    END IF;
  ELSIF p_break_type = 'rest' THEN
    IF v_hours_worked >= 2 THEN
      v_eligible := true;
    ELSE
      v_eligible := false;
      v_reason := 'Rest break requires 2+ hours worked';
    END IF;
  END IF;

  RETURN json_build_object('eligible', v_eligible, 'hours_worked', v_hours_worked, 'reason', v_reason);
END;
$$;


--
-- Name: check_campaign_expiry(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_campaign_expiry() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'active' THEN
    IF NEW.end_date IS NOT NULL AND NEW.end_date < CURRENT_DATE THEN
      NEW.status := 'expired';
    END IF;
    IF NEW.end_time IS NOT NULL AND NEW.start_time IS NOT NULL THEN
      IF NEW.end_time < TO_CHAR(NOW(), 'HH24:MI') AND NEW.start_time > NEW.end_time THEN
        NEW.status := 'expired';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: check_compliance(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_compliance(p_staff_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_daily_hours DECIMAL;
  v_weekly_hours DECIMAL;
  v_violations JSONB := '[]'::JSONB;
BEGIN
  -- Calculate daily hours
  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600), 0)
  INTO v_daily_hours
  FROM shifts
  WHERE staff_id = p_staff_id AND DATE(opened_at) = p_date;

  -- Calculate weekly hours
  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600), 0)
  INTO v_weekly_hours
  FROM shifts
  WHERE staff_id = p_staff_id
  AND opened_at >= date_trunc('week', p_date::TIMESTAMP)
  AND opened_at < date_trunc('week', p_date::TIMESTAMP) + INTERVAL '7 days';

  -- Check daily limit
  IF v_daily_hours > 8 THEN
    v_violations := v_violations || jsonb_build_object('type', 'daily_overtime', 'hours', v_daily_hours);
  END IF;

  -- Check weekly limit
  IF v_weekly_hours > 40 THEN
    v_violations := v_violations || jsonb_build_object('type', 'weekly_overtime', 'hours', v_weekly_hours);
  END IF;

  RETURN json_build_object(
    'daily_hours', v_daily_hours,
    'weekly_hours', v_weekly_hours,
    'violations', v_violations,
    'compliant', jsonb_array_length(v_violations) = 0
  );
END;
$$;


--
-- Name: check_idempotency(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_idempotency(p_key text, p_table_name text DEFAULT 'operation_logs'::text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_exists BOOLEAN;
BEGIN
  IF p_key IS NULL THEN
    RETURN false;
  END IF;
  EXECUTE format(
    'SELECT EXISTS(SELECT 1 FROM %I WHERE idempotency_key = $1 LIMIT 1)',
    p_table_name
  ) INTO v_exists USING p_key;
  RETURN v_exists;
END;
$_$;


--
-- Name: check_login_allowed(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_login_allowed(p_staff_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_status staff_status;
    v_locked timestamptz;
BEGIN
    SELECT status, locked_until INTO v_status, v_locked
    FROM staff WHERE id = p_staff_id;

    -- Staff must be ACTIVE
    IF v_status != 'ACTIVE' THEN
        RETURN false;
    END IF;

    -- Account must not be locked
    IF v_locked IS NOT NULL AND v_locked > now() THEN
        RETURN false;
    END IF;

    -- Clear lock if expired
    IF v_locked IS NOT NULL AND v_locked <= now() THEN
        UPDATE staff SET failed_login_attempts = 0, locked_until = NULL WHERE id = p_staff_id;
    END IF;

    RETURN true;
END;
$$;


--
-- Name: check_login_rate_limit(text, text, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_login_rate_limit(p_identifier text, p_ip text DEFAULT NULL::text, p_max_attempts integer DEFAULT 5, p_window_seconds integer DEFAULT 900) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count bigint;
  v_blocked_until timestamptz;
  v_attempt record;
BEGIN
  -- Count failed attempts in window
  SELECT COUNT(*) INTO v_count FROM public.login_attempts
  WHERE identifier = p_identifier
    AND success = false
    AND created_at > NOW() - (p_window_seconds || ' seconds')::interval;

  -- Also check by IP
  IF p_ip IS NOT NULL THEN
    SELECT COUNT(*) INTO v_count FROM public.login_attempts
    WHERE (identifier = p_identifier OR ip_address = p_ip)
      AND success = false
      AND created_at > NOW() - (p_window_seconds || ' seconds')::interval;
  END IF;

  IF v_count >= p_max_attempts THEN
    RETURN jsonb_build_object(
      'allowed', false,
      'attempts_used', v_count,
      'retry_after_seconds', p_window_seconds,
      'error', 'Çoxsaylı uğursuz cəhd. ' || p_window_seconds || ' saniyə gözləyin.'
    );
  END IF;

  RETURN jsonb_build_object(
    'allowed', true,
    'attempts_used', v_count,
    'remaining', p_max_attempts - v_count
  );
END;
$$;


--
-- Name: check_stock_thresholds(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.check_stock_thresholds() RETURNS TABLE(ingredient_id uuid, ingredient_name text, current_stock numeric, critical_limit numeric, unit text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ingredient RECORD;
BEGIN
  FOR v_ingredient IN
    SELECT * FROM ingredients i
    WHERE i.current_stock <= i.critical_limit AND i.critical_limit > 0
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM discrepancy_alerts
      WHERE source_id = v_ingredient.id::text
        AND source_table = 'ingredients'
        AND type = 'stock_vs_sales'
        AND status = 'open'
    ) THEN
      INSERT INTO discrepancy_alerts (type, severity, title, description, source_id, source_table, value, expected_value, variance_pct, status, created_at)
      VALUES ('stock_vs_sales',
        CASE WHEN v_ingredient.current_stock <= 0 THEN 'critical'
             WHEN v_ingredient.current_stock <= v_ingredient.critical_limit * 0.5 THEN 'high'
             ELSE 'medium' END,
        'Low stock: ' || v_ingredient.name,
        'Current: ' || v_ingredient.current_stock || ' ' || v_ingredient.unit || ' (threshold: ' || v_ingredient.critical_limit || ')',
        v_ingredient.id, 'ingredients', v_ingredient.current_stock, v_ingredient.critical_limit,
        GREATEST(0, (1 - v_ingredient.current_stock / NULLIF(v_ingredient.critical_limit, 0)) * 100), 'open', now());
    END IF;

    -- dedupe: suppress if the same stock notification exists within 4 hours
    IF NOT EXISTS (
      SELECT 1 FROM notifications
      WHERE type = 'stock'
        AND title = 'Ehtiyat azalıb: ' || v_ingredient.name
        AND created_at >= now() - interval '4 hours'
    ) THEN
      INSERT INTO notifications (type, title, body, data, created_at)
      VALUES ('stock', 'Ehtiyat azalıb: ' || v_ingredient.name,
        'Cari: ' || v_ingredient.current_stock || ' ' || v_ingredient.unit || ' (limit: ' || v_ingredient.critical_limit || ')',
        jsonb_build_object('ingredient_id', v_ingredient.id, 'current_stock', v_ingredient.current_stock, 'critical_limit', v_ingredient.critical_limit, 'unit', v_ingredient.unit), now());
    END IF;
  END LOOP;

  RETURN QUERY SELECT i.id, i.name::TEXT, i.current_stock, i.critical_limit, i.unit
    FROM ingredients i WHERE i.current_stock <= i.critical_limit AND i.critical_limit > 0;
END;
$$;


--
-- Name: cleanup_expired_sessions(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_expired_sessions() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_count integer;
BEGIN
    UPDATE sessions
    SET status = 'EXPIRED'
    WHERE status = 'ACTIVE' AND expires_at <= now();

    GET DIAGNOSTICS v_count = ROW_COUNT;
    RETURN v_count;
END;
$$;


--
-- Name: cleanup_reservation_draft_orders(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.cleanup_reservation_draft_orders() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('cancelled', 'no_show') THEN
    UPDATE orders
    SET status = 'cancelled', cancelled_at = now()
    WHERE reservation_id = NEW.id
      AND status NOT IN ('paid', 'cancelled');
    UPDATE table_floors
    SET status = 'empty',
        reservation_id = NULL,
        reservation_name = NULL,
        reservation_phone = NULL,
        reservation_time = NULL,
        guest_count = NULL,
        bill_requested = false,
        has_pending = false
    WHERE reservation_id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: clear_bill_requested_on_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_bill_requested_on_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'paid' AND OLD.status != 'paid' THEN
    UPDATE table_floors
    SET bill_requested = false
    WHERE table_number = NEW.table_number;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: clear_pre_order_cache(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_pre_order_cache() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    UPDATE public.reservations
    SET pre_order_items = '[]'::jsonb,
        pre_order_total = NULL
    WHERE id = OLD.reservation_id;
  END IF;
  RETURN OLD;
END;
$$;


--
-- Name: clear_stale_table_order_pointer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_stale_table_order_pointer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- order moved tables (or unbound) → any pointer on ANOTHER table is stale
  IF OLD.id IS NOT NULL THEN
    UPDATE table_floors
    SET current_order_id = NULL
    WHERE current_order_id = OLD.id
      AND table_number IS DISTINCT FROM NEW.table_number;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: clear_table_atomic(text, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_table_atomic(p_token text, p_table_number integer, p_performed_by uuid, p_terminal_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_table RECORD;
  v_old_state jsonb;
BEGIN
  PERFORM public.set_session_staff(p_token);
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_table FROM public.table_floors WHERE table_number = p_table_number AND (v_sess_loc IS NULL OR location_id = v_sess_loc) FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  IF NOT has_location_access(v_table.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF v_table.current_order_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_CLEAR_ORDER_POINTER');
  END IF;
  IF EXISTS (SELECT 1 FROM public.orders o
             WHERE o.table_number = p_table_number
               AND o.status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_CLEAR_OPEN_ORDERS');
  END IF;
  IF v_table.reservation_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_CLEAR_RESERVED');
  END IF;

  v_old_state := jsonb_build_object('status', v_table.status, 'kitchen_status', v_table.kitchen_status);

  UPDATE public.table_floors SET
    status = 'empty',
    total_amount = 0,
    order_count = 0,
    guest_count = NULL,
    current_order_id = NULL,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    reservation_status_snapshot = NULL,
    reserved_at = NULL,
    reserved_until = NULL,
    has_pending = false,
    oldest_pending_at = NULL,
    bill_requested = false,
    order_ids = '{}'::text[],
    updated_at = now(),
    updated_by_terminal_id = p_terminal_id
  WHERE table_number = p_table_number;

  PERFORM public.g_table_audit(
    'clear_table', 'table.cleared',
    p_table_number, v_table.id, NULL,
    v_old_state,
    jsonb_build_object('status', 'empty', 'kitchen_status', NULL::text),
    p_performed_by, p_terminal_id, 'contract-clear',
    p_table_number, NULL, v_table.location_id, v_table.organization_id);

  RETURN jsonb_build_object('success', true, 'table_status', 'empty');
END;
$$;


--
-- Name: clear_table_badges_on_release(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_table_badges_on_release() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status IN ('empty', 'cleaning', 'reserved') THEN
    UPDATE table_floors 
    SET bill_requested = false, has_pending = false 
    WHERE id = NEW.id AND (bill_requested = true OR has_pending = true);
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: clear_table_on_reservation_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clear_table_on_reservation_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  update public.table_floors
    set status = 'empty',
        reservation_id = null,
        reservation_name = null,
        reservation_phone = null,
        reservation_time = null,
        guest_count = null,
        reservation_status_snapshot = 'deleted',
        reservation_updated_at = now(),
        updated_at = now()
  where reservation_id = old.id;
 
  return old;
end;
$$;


--
-- Name: clock_in_atomic_fixed(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_in_atomic_fixed(p_staff_id uuid, p_notes text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff staff%ROWTYPE;
  v_open_shift shifts%ROWTYPE;
  v_result shifts%ROWTYPE;
BEGIN
  SELECT * INTO v_staff FROM staff WHERE id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'STAFF_NOT_FOUND');
  END IF;
  
  IF NOT v_staff.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'STAFF_INACTIVE');
  END IF;
  
  SELECT * INTO v_open_shift FROM shifts WHERE staff_id = p_staff_id AND closed_at IS NULL FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALREADY_CLOCKED_IN', 'shift_id', v_open_shift.id, 'opened_at', v_open_shift.opened_at);
  END IF;
  
  INSERT INTO shifts (staff_id, opened_at, notes) VALUES (p_staff_id, now(), p_notes) RETURNING * INTO v_result;
  
  PERFORM log_audit('clock_in', 'staff', p_staff_id::text, p_performed_by, NULL, jsonb_build_object('shift_id', v_result.id), NULL, NULL, NULL);
  
  RETURN jsonb_build_object('success', true, 'shift_id', v_result.id::text, 'staff_id', p_staff_id, 'opened_at', now());
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: clock_in_atomic_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_in_atomic_token(p_token text, p_target_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_target uuid;
  v_override boolean;
  v_staff staff%ROWTYPE;
  v_open_shift shifts%ROWTYPE;
  v_result shifts%ROWTYPE;
  v_loc uuid;
BEGIN
  PERFORM set_session_staff(p_token);
  v_actor := current_staff_id();
  v_target := COALESCE(p_target_id, v_actor);

  v_override := (v_target IS DISTINCT FROM v_actor)
                AND coalesce(has_permission(v_actor, 'timeclock.override'), false);
  IF v_target IS DISTINCT FROM v_actor AND NOT v_override THEN
    INSERT INTO security_events (staff_id, event_type, success, metadata)
    VALUES (v_actor, 'permission_denied', false,
      jsonb_build_object('action', 'clock_in_atomic', 'target', v_target));
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

    -- GATE R1: serialize per-staff open-shift creation (trigger count is RC-isolated)
  PERFORM pg_advisory_xact_lock(hashtext(v_target::text));
SELECT * INTO v_staff FROM staff WHERE id = v_target FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'STAFF_NOT_FOUND');
  END IF;
  IF NOT v_staff.is_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'STAFF_INACTIVE');
  END IF;

  SELECT * INTO v_open_shift FROM shifts
  WHERE staff_id = v_target AND closed_at IS NULL FOR UPDATE;
  IF FOUND THEN
    RETURN jsonb_build_object(
      'success', false, 'error', 'ALREADY_CLOCKED_IN',
      'shift_id', v_open_shift.id, 'opened_at', v_open_shift.opened_at
    );
  END IF;

  SELECT l.location_id INTO v_loc
  FROM staff_locations l
  WHERE l.staff_id = v_target AND l.active = true
    AND (l.is_primary = true OR NOT EXISTS (
        SELECT 1 FROM staff_locations l2
        WHERE l2.staff_id = v_target AND l2.active = true AND l2.is_primary = true))
  LIMIT 1;
  IF v_loc IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_LOCATION_ASSIGNED');
  END IF;

  INSERT INTO shifts (staff_id, opened_at, organization_id, location_id)
  VALUES (v_target, now(), v_staff.organization_id, v_loc)
  RETURNING * INTO v_result;

  PERFORM log_audit(
    'clock_in'::text, 'staff'::text, v_target::text, v_actor, NULL::text,
    jsonb_build_object('shift_id', v_result.id, 'location_id', v_loc, 'override', v_override),
    NULL::jsonb, NULL::jsonb, NULL::text
  );

  RETURN jsonb_build_object(
    'success', true, 'shift_id', v_result.id::text, 'staff_id', v_target,
    'location_id', v_loc, 'override', v_override, 'opened_at', now()
  );
END;
$$;


--
-- Name: clock_in_token(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_in_token(p_token text, p_target_id uuid, p_source text DEFAULT 'pos_terminal'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_override boolean;
  v_staff RECORD;
  v_latest_entry RECORD;
  v_shift_id UUID;
  v_loc uuid;
  v_today date;
BEGIN
  PERFORM set_session_staff(p_token);
  v_actor := current_staff_id();

  v_override := (p_target_id IS DISTINCT FROM v_actor)
                AND coalesce(has_permission(v_actor, 'timeclock.override'), false);
  IF p_target_id IS DISTINCT FROM v_actor AND NOT v_override THEN
    INSERT INTO security_events (staff_id, event_type, success, metadata)
    VALUES (v_actor, 'permission_denied', false,
      jsonb_build_object('action', 'clock_in', 'target', p_target_id));
    RETURN json_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

    -- GATE R1: serialize per-staff open-shift creation
  PERFORM pg_advisory_xact_lock(hashtext(p_target_id::text));
SELECT * INTO v_staff FROM staff WHERE id = p_target_id AND is_active = true;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Staff not found or inactive');
  END IF;

  SELECT l.location_id INTO v_loc
  FROM staff_locations l
  WHERE l.staff_id = v_staff.id AND l.active = true
    AND (l.is_primary = true OR NOT EXISTS (
        SELECT 1 FROM staff_locations l2
        WHERE l2.staff_id = v_staff.id AND l2.active = true AND l2.is_primary = true))
  LIMIT 1;
  IF v_loc IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'NO_LOCATION_ASSIGNED');
  END IF;

  -- S-05: business "today" in the location's timezone
  v_today := public.local_day(now(), v_loc);

  SELECT * INTO v_latest_entry FROM time_clock_entries
  WHERE staff_id = p_target_id AND timestamp > (v_today::timestamp AT TIME ZONE COALESCE(
             (SELECT timezone FROM locations WHERE id = v_loc), current_setting('TimeZone')))
  ORDER BY timestamp DESC LIMIT 1;
  IF v_latest_entry.entry_type IN ('clock_in', 'break_end') THEN
    RETURN json_build_object('success', false, 'error', 'Already clocked in');
  END IF;

  INSERT INTO shifts (staff_id, report_date, opened_at, starting_cash, organization_id, location_id)
  VALUES (v_staff.id, v_today, NOW(), 0, v_staff.organization_id, v_loc)
  RETURNING id INTO v_shift_id;

  INSERT INTO time_clock_entries (staff_id, entry_type, pin_verified, source, timestamp)
  VALUES (v_staff.id, 'clock_in', true, p_source, NOW());

  INSERT INTO time_clock_audit (action, performed_by, details)
  VALUES ('clock_in', v_staff.id,
    jsonb_build_object('shift_id', v_shift_id, 'location_id', v_loc, 'report_date', v_today,
                       'actor', v_actor, 'override', v_override, 'pin_verified_by', 'route_verifyPin'));

  RETURN json_build_object(
    'success', true, 'shift_id', v_shift_id, 'staff_name', v_staff.full_name,
    'location_id', v_loc, 'report_date', v_today, 'override', v_override, 'timestamp', NOW()
  );
END;
$$;


--
-- Name: clock_out_atomic_token(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_out_atomic_token(p_token text, p_target_id uuid DEFAULT NULL::uuid, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid; v_target uuid; v_override boolean;
  v_staff staff%ROWTYPE; v_open_shift shifts%ROWTYPE; v_result shifts%ROWTYPE; v_ot jsonb; v_drawer uuid;
BEGIN
  PERFORM set_session_staff(p_token);
  v_actor := current_staff_id();
  v_target := COALESCE(p_target_id, v_actor);
  v_override := (v_target IS DISTINCT FROM v_actor) AND coalesce(has_permission(v_actor, 'timeclock.override'), false);
  IF v_target IS DISTINCT FROM v_actor AND NOT v_override THEN
    INSERT INTO security_events (staff_id, event_type, success, metadata)
    VALUES (v_actor, 'permission_denied', false, jsonb_build_object('action', 'clock_out_atomic', 'target', v_target));
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;
  SELECT * INTO v_staff FROM staff WHERE id = v_target FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'STAFF_NOT_FOUND'); END IF;
  IF NOT v_staff.is_active THEN RETURN jsonb_build_object('success', false, 'error', 'STAFF_INACTIVE'); END IF;
  SELECT * INTO v_open_shift FROM shifts WHERE staff_id = v_target AND closed_at IS NULL FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'NO_OPEN_SHIFT'); END IF;

  SELECT id INTO v_drawer FROM cash_drawer_sessions
  WHERE shift_id = v_open_shift.id AND status = 'open';
  IF FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'DRAWER_OPEN', 'drawer_id', v_drawer);
  END IF;

  UPDATE shifts SET closed_at = now(), status = 'CLOSED',
    notes = CASE WHEN notes IS NULL OR notes = '' THEN p_notes ELSE notes || ' | ' || p_notes END,
    updated_at = now()
  WHERE id = v_open_shift.id RETURNING * INTO v_result;

  BEGIN
    v_ot := public.calculate_shift_overtime(v_result.id);
  EXCEPTION WHEN OTHERS THEN
    v_ot := jsonb_build_object('success', false, 'error', SQLERRM);
  END;

  PERFORM log_audit('clock_out'::text, 'staff'::text, v_target::text, v_actor, NULL::text,
    jsonb_build_object('shift_id', v_open_shift.id, 'override', v_override),
    jsonb_build_object('shift_id', v_result.id, 'closed_at', now(), 'status', 'CLOSED', 'overtime', v_ot),
    NULL::jsonb, NULL::text);
  RETURN jsonb_build_object('success', true, 'shift_id', v_result.id::text, 'staff_id', v_target, 'override', v_override, 'closed_at', now(), 'overtime', v_ot);
END;
$$;


--
-- Name: clock_out_token(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.clock_out_token(p_token text, p_target_id uuid, p_notes text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid; v_override boolean; v_latest_entry RECORD; v_active_break RECORD;
  v_shifts uuid[]; v_sid uuid; v_open_loc uuid; v_tz text; v_drawer uuid;
BEGIN
  PERFORM set_session_staff(p_token);
  v_actor := current_staff_id();
  v_override := (p_target_id IS DISTINCT FROM v_actor)
                AND coalesce(has_permission(v_actor, 'timeclock.override'), false);
  IF p_target_id IS DISTINCT FROM v_actor AND NOT v_override THEN
    INSERT INTO security_events (staff_id, event_type, success, metadata)
    VALUES (v_actor, 'permission_denied', false, jsonb_build_object('action', 'clock_out', 'target', p_target_id));
    RETURN json_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  SELECT location_id INTO v_open_loc FROM shifts
  WHERE staff_id = p_target_id AND closed_at IS NULL
  ORDER BY opened_at DESC LIMIT 1;
  IF v_open_loc IS NULL THEN
    RETURN json_build_object('success', false, 'error', 'Not clocked in');
  END IF;

  SELECT id INTO v_drawer FROM cash_drawer_sessions
  WHERE shift_id = (SELECT id FROM shifts WHERE staff_id=p_target_id AND closed_at IS NULL ORDER BY opened_at DESC LIMIT 1)
    AND status = 'open';
  IF FOUND THEN
    RETURN json_build_object('success', false, 'error', 'DRAWER_OPEN', 'drawer_id', v_drawer);
  END IF;

  v_tz := COALESCE((SELECT timezone FROM locations WHERE id = v_open_loc), current_setting('TimeZone'));

  SELECT * INTO v_latest_entry FROM time_clock_entries
  WHERE staff_id = p_target_id
    AND timestamp > (public.local_day(now(), v_open_loc)::timestamp AT TIME ZONE v_tz)
  ORDER BY timestamp DESC LIMIT 1;
  IF v_latest_entry IS NULL OR v_latest_entry.entry_type = 'clock_out' THEN
    RETURN json_build_object('success', false, 'error', 'Not clocked in');
  END IF;

  SELECT * INTO v_active_break FROM shift_breaks sb JOIN shifts s ON s.id = sb.shift_id
  WHERE s.staff_id = p_target_id AND sb.ended_at IS NULL;
  IF FOUND THEN
    UPDATE shift_breaks SET ended_at = NOW() WHERE id = v_active_break.id;
    INSERT INTO time_clock_entries (staff_id, entry_type, source, timestamp)
    VALUES (p_target_id, 'break_end', 'pos_terminal', NOW());
  END IF;

  SELECT array_agg(id) INTO v_shifts FROM shifts WHERE staff_id = p_target_id AND closed_at IS NULL;
  UPDATE shifts SET closed_at = NOW(), status = 'CLOSED', notes = COALESCE(p_notes, notes)
  WHERE staff_id = p_target_id AND closed_at IS NULL;

  INSERT INTO time_clock_entries (staff_id, entry_type, pin_verified, notes, source, timestamp)
  VALUES (p_target_id, 'clock_out', true, p_notes, 'pos_terminal', NOW());

  IF v_shifts IS NOT NULL THEN
    FOREACH v_sid IN ARRAY v_shifts LOOP
      BEGIN PERFORM public.calculate_shift_overtime(v_sid); EXCEPTION WHEN OTHERS THEN NULL; END;
    END LOOP;
  END IF;

  INSERT INTO time_clock_audit (action, performed_by, details)
  VALUES ('clock_out', p_target_id, jsonb_build_object('notes', p_notes, 'actor', v_actor, 'override', v_override, 'pin_verified_by', 'route_verifyPin'));

  RETURN json_build_object('success', true, 'override', v_override, 'timestamp', NOW());
END;
$$;


--
-- Name: close_cash_register(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_cash_register(p_shift_id uuid, p_actual_cash numeric, p_notes text DEFAULT NULL::text, p_manager_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
  v_shift RECORD;
  v_expected NUMERIC;
  v_difference NUMERIC;
BEGIN
  IF p_manager_id IS NOT NULL THEN
    PERFORM public.validate_actor(p_manager_id);
  END IF;
  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'SHIFT_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_shift.closed_at IS NOT NULL THEN
    RAISE EXCEPTION 'SHIFT_ALREADY_CLOSED' USING ERRCODE = 'P0001';
  END IF;

  -- Calculate expected cash from orders during shift
  SELECT COALESCE(SUM(total_amount), 0) INTO v_expected
  FROM orders
  WHERE status = 'paid'
    AND created_by = v_shift.staff_id
    AND paid_at BETWEEN v_shift.opened_at AND now()
    AND payment_method IN ('cash', 'nağd');

  v_difference := p_actual_cash - v_expected;

  UPDATE shifts SET
    closed_at = now(),
    expected_cash = v_expected,
    actual_cash = p_actual_cash,
    difference = v_difference,
    manager_approved = (p_manager_id IS NOT NULL),
    manager_id = p_manager_id,
    notes = COALESCE(p_notes, notes),
    updated_at = now()
  WHERE id = p_shift_id;

  RETURN jsonb_build_object(
    'success', true,
    'shift_id', p_shift_id,
    'expected_cash', v_expected,
    'actual_cash', p_actual_cash,
    'difference', v_difference,
    'closed_at', now()
  );
END;
$$;


--
-- Name: close_cash_register_v2(uuid, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_cash_register_v2(p_session_id uuid, p_actual_cash numeric, p_notes text, p_manager_id uuid, p_performed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session RECORD;
  v_expected_balance NUMERIC;
  v_difference NUMERIC;
  v_log_entry RECORD;
  v_manager_name TEXT;
  v_performer_name TEXT;
  v_requires_approval BOOLEAN := false;
  v_metadata JSONB;
  v_now TIMESTAMPTZ := NOW();
  v_threshold NUMERIC;
  v_manager_required BOOLEAN;
  v_shift RECORD;
  v_shift_closed BOOLEAN := false;
  v_ot jsonb;
BEGIN
  SELECT * INTO v_session FROM public.cash_drawer_sessions
  WHERE id = p_session_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Session not found');
  END IF;

  IF v_session.status = 'closed' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Session already closed', 'closed_at', v_session.closed_at);
  END IF;

  -- Read policy from settings
  SELECT cash_close_variance_threshold, cash_close_manager_required
    INTO v_threshold, v_manager_required
  FROM public.settings LIMIT 1;

  v_threshold := COALESCE(v_threshold, 0);
  v_manager_required := COALESCE(v_manager_required, false);

  -- Calculate expected balance SERVER-SIDE from the LEDGER (never trust client).
  -- Bug fix: the original also started from opening_balance, double-counting the
  -- opening float (open_cash_register writes an 'open' ledger row for it). The
  -- ledger is the single source of truth (SSOT); start from 0.
  v_expected_balance := 0;
  FOR v_log_entry IN
    SELECT type, amount FROM public.cash_drawer_log
    WHERE session_id = p_session_id
    ORDER BY created_at ASC
  LOOP
    IF v_log_entry.type IN ('cash_in', 'payment', 'open') THEN
      v_expected_balance := v_expected_balance + v_log_entry.amount;
    ELSIF v_log_entry.type IN ('cash_out', 'close') THEN
      v_expected_balance := v_expected_balance - v_log_entry.amount;
    END IF;
  END LOOP;

  v_difference := COALESCE(p_actual_cash, 0) - v_expected_balance;

  -- Manager approval required when: variance exceeds threshold OR policy demands it
  v_requires_approval := (ABS(v_difference) > v_threshold) OR v_manager_required;

  IF v_requires_approval THEN
    IF p_manager_id IS NULL THEN
      RETURN jsonb_build_object(
        'success', false,
        'error', 'Manager approval required',
        'requires_approval', true,
        'difference', v_difference,
        'expected_balance', v_expected_balance,
        'threshold', v_threshold,
        'manager_required_policy', v_manager_required
      );
    END IF;

    -- Bug fix: original referenced non-existent staff.role (it is role_id).
    -- Correct A-frozen pattern: normalize_role(roles.name) via staff→roles join.
    IF NOT EXISTS (
      SELECT 1 FROM public.staff st
      JOIN public.roles r ON r.id = st.role_id
      WHERE st.id = p_manager_id
        AND normalize_role(r.name) IN ('superadmin', 'admin', 'manager')
        AND st.is_active = true
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Invalid manager credentials');
    END IF;

    SELECT name INTO v_manager_name FROM public.staff WHERE id = p_manager_id;
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  UPDATE public.cash_drawer_sessions SET
    status = 'closed',
    closing_balance = p_actual_cash,
    expected_balance = v_expected_balance,
    difference = v_difference,
    closed_at = v_now,
    closed_by = p_performed_by,
    notes = COALESCE(p_notes, notes),
    approved_by = CASE WHEN v_requires_approval THEN p_manager_id ELSE NULL END,
    approval_note = CASE WHEN v_requires_approval THEN 'manager approval ' || coalesce(p_manager_id::text, '') ELSE NULL END
  WHERE id = p_session_id;

  INSERT INTO public.cash_drawer_log (
    session_id, type, amount, description, created_by
  ) VALUES (
    p_session_id, 'close', COALESCE(p_actual_cash, 0),
    COALESCE(p_notes, 'Kassa bağlandı. Fərq: ' || ROUND(v_difference, 2) || '₼'),
    p_performed_by
  );

  v_metadata := jsonb_build_object(
    'session_id', p_session_id,
    'opening_balance', v_session.opening_balance,
    'expected_balance', v_expected_balance,
    'actual_cash', p_actual_cash,
    'difference', v_difference,
    'requires_approval', v_requires_approval,
    'manager_id', p_manager_id,
    'manager_name', v_manager_name,
    'notes', p_notes,
    'threshold', v_threshold,
    'manager_required_policy', v_manager_required
  );

  PERFORM public.log_audit(
    'cash_close', 'cash_drawer_session', p_session_id::text,
    p_performed_by, v_performer_name,
    jsonb_build_object('status', 'open', 'opening_balance', v_session.opening_balance),
    jsonb_build_object('status', 'closed', 'closing_balance', p_actual_cash, 'difference', v_difference),
    v_metadata, NULL
  );

  IF v_requires_approval AND p_manager_id IS NOT NULL THEN
    PERFORM public.log_audit(
      'manager_approval', 'cash_drawer_session', p_session_id::text,
      p_manager_id, v_manager_name, NULL,
      jsonb_build_object('approved', true, 'difference', v_difference),
      jsonb_build_object('variance', v_difference, 'cashier_id', p_performed_by, 'cashier_name', v_performer_name),
      NULL
    );
  END IF;

  -- ===========================================================================
  -- S-08 (frozen 1:1 + bind&derive): atomically close the bound shift.
  -- expected_cash := drawer expected_balance (server-derived, NEVER 0);
  -- actual_cash := counted. Writes the cash_drawer_logs audit row and triggers
  -- overtime (S-04 hook). Best-effort: if the shift is already closed we still
  -- keep the drawer closed and report it.
  -- ===========================================================================
  IF v_session.shift_id IS NOT NULL THEN
    SELECT * INTO v_shift FROM public.shifts
    WHERE id = v_session.shift_id FOR UPDATE;
    IF FOUND AND v_shift.closed_at IS NULL THEN
      UPDATE public.shifts SET
        closed_at = v_now,
        status = 'CLOSED',
        expected_cash = v_expected_balance,
        actual_cash = COALESCE(p_actual_cash, 0),
        difference = v_difference,
        notes = COALESCE(p_notes, notes)
      WHERE id = v_shift.id;
      v_shift_closed := true;

      INSERT INTO public.cash_drawer_logs (
        shift_id, staff_id, action, amount, description,
        starting_cash, expected_cash, actual_cash, difference,
        opened_at, closed_at, notes
      ) VALUES (
        v_shift.id, v_shift.staff_id, 'close_day',
        v_expected_balance,
        'Drawer close → shift close (expected from cash_drawer_session ' || left(p_session_id::text, 8) || ')',
        COALESCE(v_shift.starting_cash, 0),
        v_expected_balance,
        COALESCE(p_actual_cash, 0),
        v_difference,
        v_shift.opened_at,
        v_now,
        p_notes
      );

      -- S-04: overtime on close (idempotent)
      BEGIN
        v_ot := public.calculate_shift_overtime(v_shift.id);
      EXCEPTION WHEN OTHERS THEN
        v_ot := jsonb_build_object('success', false, 'error', SQLERRM);
      END;

      PERFORM public.log_audit(
        'shift_closed_via_drawer', 'shift', v_shift.id::text,
        COALESCE(p_performed_by, v_shift.staff_id), v_performer_name,
        jsonb_build_object('status', 'OPEN', 'expected_cash', v_expected_balance),
        jsonb_build_object('status', 'CLOSED', 'expected_cash', v_expected_balance,
                           'actual_cash', p_actual_cash, 'difference', v_difference, 'overtime', v_ot),
        NULL, NULL
      );
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'session_id', p_session_id,
    'expected_balance', v_expected_balance,
    'actual_cash', p_actual_cash,
    'difference', v_difference,
    'requires_approval', v_requires_approval,
    'manager_approved', v_requires_approval,
    'closed_at', v_now,
    'shift_id', v_session.shift_id,
    'shift_closed', v_shift_closed,
    'overtime', v_ot
  );
END;
$$;


--
-- Name: close_day_atomic(date, jsonb, jsonb, jsonb, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_day_atomic(p_report_date date, p_daily_report jsonb, p_shift jsonb, p_cash_drawer jsonb, p_audit_log jsonb DEFAULT NULL::jsonb, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
  v_report_id UUID;
  v_shift_id UUID;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  INSERT INTO public.daily_reports (
    report_date, total_revenue, total_orders, aov, cash_total, card_total,
    tips_total, discounts_total, voids_count, voids_amount, tax_collected,
    starting_cash, expected_cash, actual_cash, cash_difference, cogs,
    labor_cost, items_sold, raw_data, closed_at, closed_by, notes
  ) VALUES (
    p_report_date,
    COALESCE(p_daily_report->>'total_revenue', '0')::NUMERIC,
    COALESCE(p_daily_report->>'total_orders', '0')::INTEGER,
    COALESCE(p_daily_report->>'aov', '0')::NUMERIC,
    COALESCE(p_daily_report->>'cash_total', '0')::NUMERIC,
    COALESCE(p_daily_report->>'card_total', '0')::NUMERIC,
    COALESCE(p_daily_report->>'tips_total', '0')::NUMERIC,
    COALESCE(p_daily_report->>'discounts_total', '0')::NUMERIC,
    COALESCE(p_daily_report->>'voids_count', '0')::INTEGER,
    COALESCE(p_daily_report->>'voids_amount', '0')::NUMERIC,
    COALESCE(p_daily_report->>'tax_collected', '0')::NUMERIC,
    COALESCE(p_daily_report->>'starting_cash', '0')::NUMERIC,
    COALESCE(p_daily_report->>'expected_cash', '0')::NUMERIC,
    COALESCE(p_daily_report->>'actual_cash', '0')::NUMERIC,
    COALESCE(p_daily_report->>'cash_difference', '0')::NUMERIC,
    COALESCE(p_daily_report->>'cogs', '0')::NUMERIC,
    COALESCE(p_daily_report->>'labor_cost', '0')::NUMERIC,
    COALESCE(p_daily_report->>'items_sold', '0')::INTEGER,
    COALESCE(p_daily_report->'raw_data', '{}'::jsonb),
    NOW(),
    p_performed_by,
    p_daily_report->>'notes'
  ) RETURNING id INTO v_report_id;

  INSERT INTO public.shifts (
    id, report_id, report_date, staff_id, opened_at, closed_at,
    starting_cash, expected_cash, actual_cash, difference, notes
  ) VALUES (
    COALESCE(p_shift->>'id', gen_random_uuid()),
    v_report_id,
    p_report_date,
    COALESCE(p_shift->>'staff_id', p_performed_by),
    COALESCE((p_shift->>'opened_at')::TIMESTAMPTZ, NOW()),
    COALESCE((p_shift->>'closed_at')::TIMESTAMPTZ, NOW()),
    COALESCE(p_shift->>'starting_cash', '0')::NUMERIC,
    COALESCE(p_shift->>'expected_cash', '0')::NUMERIC,
    COALESCE(p_shift->>'actual_cash', '0')::NUMERIC,
    COALESCE(p_shift->>'difference', '0')::NUMERIC,
    p_shift->>'notes'
  ) RETURNING id INTO v_shift_id;

  INSERT INTO public.cash_drawer_logs (
    shift_id, staff_id, action, amount, description,
    starting_cash, expected_cash, actual_cash, difference,
    opened_at, closed_at, notes
  ) VALUES (
    v_shift_id,
    COALESCE(p_cash_drawer->>'staff_id', p_performed_by),
    COALESCE(p_cash_drawer->>'action', 'close_day'),
    COALESCE(p_cash_drawer->>'amount', '0')::NUMERIC,
    p_cash_drawer->>'description',
    COALESCE(p_cash_drawer->>'starting_cash', '0')::NUMERIC,
    COALESCE(p_cash_drawer->>'expected_cash', '0')::NUMERIC,
    COALESCE(p_cash_drawer->>'actual_cash', '0')::NUMERIC,
    COALESCE(p_cash_drawer->>'difference', '0')::NUMERIC,
    COALESCE((p_cash_drawer->>'opened_at')::TIMESTAMPTZ, NOW()),
    COALESCE((p_cash_drawer->>'closed_at')::TIMESTAMPTZ, NOW()),
    p_cash_drawer->>'notes'
  );

  IF p_audit_log IS NOT NULL THEN
    INSERT INTO public.operation_logs (
      action, old_values, new_values, performed_by
    ) VALUES (
      COALESCE(p_audit_log->>'action', 'close_day'),
      COALESCE(p_audit_log->>'old_values', '{}'::jsonb),
      COALESCE(p_audit_log->>'new_values', jsonb_build_object('report_id', v_report_id, 'shift_id', v_shift_id)),
      p_performed_by
    );
  END IF;

  RETURN jsonb_build_object('success', true, 'report_id', v_report_id, 'shift_id', v_shift_id);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: close_shift(text, uuid, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_shift(p_token text, p_shift_id uuid, p_actual_cash numeric DEFAULT 0, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid;
    v_org_id uuid;
    v_shift RECORD;
    v_ot jsonb;
    v_open_drawer uuid;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    v_org_id := current_org_id();

    SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Shift not found'; END IF;
    IF v_shift.staff_id != v_staff_id AND NOT is_superadmin() THEN
        RAISE EXCEPTION 'Cannot close another staff shift';
    END IF;
    IF v_shift.status = 'CLOSED' THEN
        RAISE EXCEPTION 'Shift already closed';
    END IF;

    -- S-08 (frozen): if a drawer is still OPEN and bound to this shift, the
    -- drawer must be closed first (close_cash_register_v2 closes the shift
    -- atomically). Prevents losing the expected_cash derivation.
    SELECT id INTO v_open_drawer FROM cash_drawer_sessions
    WHERE shift_id = p_shift_id AND status = 'open';
    IF FOUND THEN
        RAISE EXCEPTION 'DRAWER_OPEN: close the cash drawer first (session %)', v_open_drawer;
    END IF;

    UPDATE shifts
    SET closed_at = now(), status = 'CLOSED', actual_cash = p_actual_cash,
        difference = p_actual_cash - v_shift.expected_cash,
        notes = COALESCE(p_notes, notes)
    WHERE id = p_shift_id;

    -- S-04: compute overtime on close (idempotent)
    BEGIN
      v_ot := public.calculate_shift_overtime(p_shift_id);
    EXCEPTION WHEN OTHERS THEN
      v_ot := jsonb_build_object('success', false, 'error', SQLERRM);
    END;

    INSERT INTO operation_logs (entity_type, entity_id, operation, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('shift', p_shift_id, 'shift.closed',
            jsonb_build_object('actual_cash', p_actual_cash, 'difference', p_actual_cash - v_shift.expected_cash, 'overtime', v_ot),
            v_staff_id, gen_random_uuid(), v_shift.location_id, v_org_id);

    RETURN jsonb_build_object('shift_id', p_shift_id, 'status', 'CLOSED',
                              'difference', p_actual_cash - v_shift.expected_cash, 'overtime', v_ot);
END;
$$;


--
-- Name: close_shift_atomic(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.close_shift_atomic(p_shift_id uuid, p_actual_cash numeric, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_shift shifts%ROWTYPE;
  v_expected numeric;
  v_difference numeric;
  v_requires_review boolean;
BEGIN
  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'SHIFT_NOT_FOUND');
  END IF;

  IF v_shift.closed_at IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'SHIFT_ALREADY_CLOSED');
  END IF;

  -- Calculate expected cash
  v_expected := COALESCE(v_shift.starting_cash, 0) + COALESCE(v_shift.expected_cash, 0);
  v_difference := p_actual_cash - v_expected;
  v_requires_review := ABS(v_difference) > 10;

  -- Close shift
  UPDATE shifts SET
    closed_at = now(),
    status = 'CLOSED',              -- 045 (E/S, proven regression): 019 invariant
    actual_cash = p_actual_cash,
    expected_cash = v_expected,
    difference = v_difference,
    notes = COALESCE(notes, '') || COALESCE(' | Close: ' || p_reason, ''),
    updated_at = now()
  WHERE id = p_shift_id;

  -- Audit
  PERFORM log_audit(
    'shift_closed', 'shifts', p_shift_id::text, p_performed_by,
    jsonb_build_object(
      'starting_cash', v_shift.starting_cash,
      'expected', v_expected
    ),
    jsonb_build_object(
      'actual_cash', p_actual_cash,
      'difference', v_difference,
      'requires_review', v_requires_review
    ),
    NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'shift_id', p_shift_id,
    'expected_cash', v_expected,
    'actual_cash', p_actual_cash,
    'difference', v_difference,
    'requires_review', v_requires_review
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: comp_order_item_atomic(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.comp_order_item_atomic(p_order_item_id uuid, p_reason text DEFAULT 'comp'::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
  v_item RECORD;
  v_order RECORD;
  v_new_total NUMERIC := 0;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order item not found');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_item.kitchen_status = 'comped' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item already comped');
  END IF;

  UPDATE public.order_items SET
    kitchen_status = 'comped',
    updated_at = NOW()
  WHERE id = p_order_item_id;

  SELECT COALESCE(SUM(total_price), 0) INTO v_new_total FROM public.order_items WHERE order_id = v_order.id AND kitchen_status != 'cancelled';

  UPDATE public.orders SET
    total_amount = v_new_total,
    version = COALESCE(version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id,
    updated_at = NOW()
  WHERE id = v_order.id;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, v_order.id, 'comp_order_item',
    jsonb_build_object('item_id', p_order_item_id, 'kitchen_status', v_item.kitchen_status, 'order_total', v_order.total_amount),
    jsonb_build_object('item_id', p_order_item_id, 'kitchen_status', 'comped', 'reason', p_reason, 'order_total', v_new_total),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'new_order_total', v_new_total);
END;
$$;


--
-- Name: complete_item_atomic(text, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_item_atomic(p_token text, p_item_id uuid, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_correlation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT item_kitchen_step(p_token, p_item_id, 'completed', p_reason, p_metadata, p_correlation_id)
$$;


--
-- Name: complete_onboarding_task(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_onboarding_task(p_task_id uuid, p_completed_by uuid) RETURNS json
