--
-- Name: complete_payment_atomic(uuid, jsonb, text, numeric, numeric, numeric, numeric, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_payment_atomic(p_order_id uuid, p_payments jsonb, p_payment_method text DEFAULT 'cash'::text, p_cash_amount numeric DEFAULT 0, p_card_amount numeric DEFAULT 0, p_tip_amount numeric DEFAULT 0, p_discount_amount numeric DEFAULT 0, p_discount_type text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_payment JSONB;
  v_total_paid NUMERIC := 0;
  v_table RECORD;
  v_other_active_count INT;
BEGIN
  PERFORM public.validate_actor(p_performed_by);

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status = 'paid' THEN
    RETURN jsonb_build_object('success', true, 'message', 'Already paid');
  END IF;

  IF v_order.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot pay cancelled order');
  END IF;

  FOR v_payment IN SELECT * FROM jsonb_array_elements(p_payments) LOOP
    INSERT INTO public.order_payments (
      order_id, payment_method, method, amount, currency, status,
      split_group_id, is_partial, is_refund, created_by
    ) VALUES (
      p_order_id,
      COALESCE(v_payment->>'method', 'cash'),
      COALESCE(v_payment->>'method', 'cash'),
      COALESCE((v_payment->>'amount')::NUMERIC, 0),
      COALESCE(v_payment->>'currency', 'AZN'),
      v_payment->>'status',
      (v_payment->>'split_group_id')::UUID,
      COALESCE((v_payment->>'is_partial')::BOOLEAN, false),
      COALESCE((v_payment->>'is_refund')::BOOLEAN, false),
      p_performed_by
    );
    v_total_paid := v_total_paid + COALESCE((v_payment->>'amount')::NUMERIC, 0);
  END LOOP;

  UPDATE public.orders SET
    paid_amount = v_total_paid,
    cash_amount = p_cash_amount,
    card_amount = p_card_amount,
    tip_amount = p_tip_amount,
    discount_amount = p_discount_amount,
    discount_type = p_discount_type,
    payment_method = p_payment_method,
    status = CASE WHEN v_total_paid >= (v_order.total_amount - COALESCE(p_discount_amount, 0)) THEN 'paid' ELSE v_order.status END,
    paid_at = CASE WHEN v_total_paid >= (v_order.total_amount - COALESCE(p_discount_amount, 0)) THEN NOW() ELSE v_order.paid_at END,
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id,
    updated_at = NOW()
  WHERE id = p_order_id;

  IF v_total_paid >= (v_order.total_amount - COALESCE(p_discount_amount, 0)) THEN
    -- NOTE: no deduct_stock_for_order here — consumption already happened at READY/serve (M2/M3).

    IF v_order.table_number IS NOT NULL AND v_order.table_number > 0 THEN
      SELECT COUNT(*) INTO v_other_active_count FROM public.orders
        WHERE table_number = v_order.table_number
          AND id != p_order_id
          AND status NOT IN ('paid', 'cancelled', 'closed');

      IF v_other_active_count = 0 THEN
        SELECT * INTO v_table FROM public.table_floors WHERE table_number = v_order.table_number FOR UPDATE;
        IF FOUND THEN
          UPDATE public.table_floors SET
            status = 'dirty',
            current_order_id = NULL,
            guest_count = NULL,
            total_amount = 0,
            order_count = 0,
            bill_requested = false,
            kitchen_status = NULL,
            updated_at = NOW()
          WHERE table_number = v_order.table_number;
        END IF;
      END IF;
    END IF;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'complete_payment',
    jsonb_build_object('status', v_order.status, 'paid_amount', v_order.paid_amount),
    jsonb_build_object('status', 'paid', 'paid_amount', v_total_paid),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id, 'paid_amount', v_total_paid);
END;
$$;


--
-- Name: complete_payment_atomic(uuid, jsonb, text, numeric, numeric, numeric, numeric, text, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_payment_atomic(p_order_id uuid, p_payments jsonb, p_payment_method text DEFAULT 'cash'::text, p_cash_amount numeric DEFAULT 0, p_card_amount numeric DEFAULT 0, p_tip_amount numeric DEFAULT 0, p_discount_amount numeric DEFAULT 0, p_discount_type text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text, p_cash_drawer_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_payment JSONB;
  v_total_paid NUMERIC := 0;
  v_table RECORD;
  v_other_active_count INT;
BEGIN
  PERFORM public.validate_actor(p_performed_by);

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status = 'paid' THEN
    RETURN jsonb_build_object('success', true, 'message', 'Already paid');
  END IF;

  IF v_order.status = 'cancelled' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot pay cancelled order');
  END IF;

  FOR v_payment IN SELECT * FROM jsonb_array_elements(p_payments) LOOP
    INSERT INTO public.order_payments (
      order_id, payment_method, method, amount, currency, status,
      split_group_id, is_partial, is_refund, created_by
    ) VALUES (
      p_order_id,
      COALESCE(v_payment->>'method', 'cash'),
      COALESCE(v_payment->>'method', 'cash'),
      COALESCE((v_payment->>'amount')::NUMERIC, 0),
      COALESCE(v_payment->>'currency', 'AZN'),
      v_payment->>'status',
      (v_payment->>'split_group_id')::UUID,
      COALESCE((v_payment->>'is_partial')::BOOLEAN, false),
      COALESCE((v_payment->>'is_refund')::BOOLEAN, false),
      p_performed_by
    );
    v_total_paid := v_total_paid + COALESCE((v_payment->>'amount')::NUMERIC, 0);
  END LOOP;

  UPDATE public.orders SET
    paid_amount = v_total_paid,
    cash_amount = p_cash_amount,
    card_amount = p_card_amount,
    tip_amount = p_tip_amount,
    discount_amount = p_discount_amount,
    discount_type = p_discount_type,
    payment_method = p_payment_method,
    status = CASE WHEN v_total_paid >= (v_order.total_amount - COALESCE(p_discount_amount, 0)) THEN 'paid' ELSE v_order.status END,
    paid_at = CASE WHEN v_total_paid >= (v_order.total_amount - COALESCE(p_discount_amount, 0)) THEN NOW() ELSE v_order.paid_at END,
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id,
    updated_at = NOW()
  WHERE id = p_order_id;

  IF v_total_paid >= (v_order.total_amount - COALESCE(p_discount_amount, 0)) THEN
    -- NOTE: no deduct_stock_for_order here — consumption already happened at READY/serve (M2/M3).

    IF v_order.table_number IS NOT NULL AND v_order.table_number > 0 THEN
      SELECT COUNT(*) INTO v_other_active_count FROM public.orders
        WHERE table_number = v_order.table_number
          AND id != p_order_id
          AND status NOT IN ('paid', 'cancelled', 'closed');

      IF v_other_active_count = 0 THEN
        SELECT * INTO v_table FROM public.table_floors WHERE table_number = v_order.table_number FOR UPDATE;
        IF FOUND THEN
          UPDATE public.table_floors SET
            status = 'dirty',
            current_order_id = NULL,
            guest_count = NULL,
            total_amount = 0,
            order_count = 0,
            bill_requested = false,
            kitchen_status = NULL,
            updated_at = NOW()
          WHERE table_number = v_order.table_number;
        END IF;
      END IF;
    END IF;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'complete_payment',
    jsonb_build_object('status', v_order.status, 'paid_amount', v_order.paid_amount),
    jsonb_build_object('status', 'paid', 'paid_amount', v_total_paid),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id, 'paid_amount', v_total_paid);
END;
$$;


--
-- Name: complete_payment_atomic_v2(uuid, jsonb, text, numeric, numeric, numeric, numeric, text, uuid, text, uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_payment_atomic_v2(p_order_id uuid, p_payments jsonb DEFAULT '[]'::jsonb, p_payment_method text DEFAULT 'cash'::text, p_cash_amount numeric DEFAULT 0, p_card_amount numeric DEFAULT 0, p_tip_amount numeric DEFAULT 0, p_discount_amount numeric DEFAULT 0, p_discount_type text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text, p_cash_drawer_session_id uuid DEFAULT NULL::uuid, p_cash_received numeric DEFAULT NULL::numeric, p_idempotency_key text DEFAULT NULL::text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_payment JSONB;
  v_amount NUMERIC;
  v_is_refund BOOLEAN;
  v_method TEXT;
  v_non_refund_total NUMERIC := 0;
  v_refund_total NUMERIC := 0;
  v_cash_total NUMERIC := 0;
  v_card_total NUMERIC := 0;
  v_now TIMESTAMPTZ := NOW();
  v_payment_ids UUID[] := '{}';
  v_new_paid NUMERIC;
  v_new_refund NUMERIC;
  v_new_status TEXT;
  v_remaining NUMERIC;
  v_change NUMERIC := 0;
  v_performer_name TEXT;
  v_idem_result JSONB;
  v_idem_namespace TEXT;
  v_idem_effect NUMERIC;
  v_idem_order UUID;
  v_idem_amount NUMERIC;
  v_result JSONB;
  v_ledger_id UUID;
  v_order_loc uuid;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  -- ═══ P-1 M2: LOCATION ASSERTION (fail-closed, D-5; ratified 2026-09-12) ═══
  -- p_location_id = the operator's SESSION-RESOLVED location (server-derived in the
  -- route via resolveWriteLocationContext — never client-supplied). The order must
  -- sit at exactly that location, and the actor must be allowed there
  -- (active staff_locations binding ∪ superadmin/owner ∪ documented
  -- single-location-with-data fallback). No location context => fail closed.
  IF p_location_id IS NULL THEN
    RAISE EXCEPTION 'LOCATION_CONTEXT_MISSING' USING ERRCODE = 'P0001';
  END IF;
  SELECT location_id INTO v_order_loc FROM orders WHERE id = p_order_id;
  IF v_order_loc IS NULL THEN
    RAISE EXCEPTION 'ORDER_LOCATION_NULL' USING ERRCODE = 'P0001';
  END IF;
  IF v_order_loc IS DISTINCT FROM p_location_id THEN
    RAISE EXCEPTION 'LOCATION_MISMATCH: order location % != operator session location %',
      v_order_loc, p_location_id USING ERRCODE = '42501';
  END IF;
  IF p_performed_by IS NOT NULL
     AND NOT public.p1_actor_allowed_at_location(p_performed_by, p_location_id) THEN
    RAISE EXCEPTION 'LOCATION_ACCESS_DENIED: actor not allowed at location %',
      p_location_id USING ERRCODE = '42501';
  END IF;
  SELECT name INTO v_performer_name FROM staff WHERE id = p_performed_by;

  -- ═══ 1. LOCK ORDER (serialization point for concurrency) ═══
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_NOT_FOUND');
  END IF;

  -- ═══ 2. (P-4) idempotency dedupe lives at 3b — after the payments parse — so
  -- the replay binding check (order_id + signed amount, ratified D-3) can use
  -- the parsed financial effect. It still runs BEFORE all domain guards, so a
  -- retry replays instead of tripping ORDER_ALREADY_PAID / overpay / refund-cap.
  -- Concurrency: the order FOR UPDATE lock in section 1 serializes same-key pairs. ═══

  -- ═══ 3. PARSE PAYMENTS (split non-refund vs refund) ═══
  FOR v_payment IN SELECT * FROM jsonb_array_elements(p_payments) LOOP
    v_amount := COALESCE((v_payment->>'amount')::NUMERIC, 0);
    v_is_refund := COALESCE((v_payment->>'is_refund')::BOOLEAN, false);
    v_method := COALESCE((v_payment->>'method')::TEXT, 'cash');

    IF v_is_refund THEN
      v_refund_total := v_refund_total + v_amount;
    ELSE
      v_non_refund_total := v_non_refund_total + v_amount;
      IF v_method = 'cash' THEN
        v_cash_total := v_cash_total + v_amount;
      ELSE
        v_card_total := v_card_total + v_amount;
      END IF;
    END IF;
  END LOOP;

  -- ═══ 3b. P-4 C-1/C-2/C-3: IDENTITY BOUNDARY (ratified D-1/D-2/D-3/D-5) ═══
  -- namespace is derived from the OPERATION, never from the key text: refunds
  -- live in 'refund', everything else in 'payment'. Binding = (namespace,key)
  -- unique + row bound to (order_id, signed amount). Reuse with a different
  -- order OR amount = IDEMPOTENCY_CONFLICT (409), full rollback, zero mutation.
  v_idem_namespace := CASE WHEN v_refund_total > 0 THEN 'refund' ELSE 'payment' END;
  v_idem_effect := v_non_refund_total - v_refund_total;
  IF p_idempotency_key IS NOT NULL THEN
    SELECT order_id, amount, result INTO v_idem_order, v_idem_amount, v_idem_result
    FROM payment_idempotency_keys
    WHERE namespace = v_idem_namespace AND key = p_idempotency_key;
    IF FOUND THEN
      IF v_idem_order IS DISTINCT FROM p_order_id
         OR v_idem_amount IS DISTINCT FROM v_idem_effect THEN
        RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: key % is bound to a different operation (order %, amount %); request was (order %, amount %)',
          p_idempotency_key, v_idem_order, v_idem_amount, p_order_id, v_idem_effect ;
      END IF;
      RETURN (COALESCE(v_idem_result, jsonb_build_object('success', false, 'error', 'IDEMPOTENCY_DATA_MISSING')))
        || jsonb_build_object('idempotent', true, 'duplicate', true,
             'original', COALESCE(v_idem_result, '{}'::jsonb),
             'current', jsonb_build_object(
               'status', v_order.status,
               'paid_amount', v_order.paid_amount,
               'refund_amount', COALESCE(v_order.refund_amount, 0),
               'remaining', GREATEST(0, COALESCE(v_order.total_amount, 0) - COALESCE(v_order.paid_amount, 0)),
               'replayed_at', v_now));
    END IF;
  END IF;

  -- ═══ 4. REFUND GUARD (refund ≤ net paid) ═══
  IF v_refund_total > 0 THEN
    IF v_refund_total > COALESCE(v_order.paid_amount, 0) - COALESCE(v_order.refund_amount, 0) + 0.01 THEN
      RAISE EXCEPTION 'REFUND_EXCEEDS_PAID: refund % > net_paid % (paid % - refunded %)',
        v_refund_total,
        COALESCE(v_order.paid_amount, 0) - COALESCE(v_order.refund_amount, 0),
        v_order.paid_amount, COALESCE(v_order.refund_amount, 0);
    END IF;
  END IF;

  -- ═══ 5. ALREADY-PAID GUARD (non-refund on a fully-paid order → reject) ═══
  -- Placed BEFORE the overpay guard so a full re-pay of a paid order surfaces
  -- ORDER_ALREADY_PAID (route maps it to HTTP 409) rather than a generic
  -- overpay error. Refunds are exempt (v_non_refund_total = 0) and still flow
  -- into the already-paid order below.
  IF v_non_refund_total > 0
     AND v_order.status = 'paid'
     AND COALESCE(v_order.paid_amount, 0) >= COALESCE(v_order.total_amount, 0) - 0.01 THEN
    RAISE EXCEPTION 'ORDER_ALREADY_PAID';
  END IF;

  -- ═══ 6. OVERPAY GUARD (DB-enforced; holds under race via FOR UPDATE) ═══
  -- Catches partial overpay (paid < total but payment > remaining).
  v_remaining := COALESCE(v_order.total_amount, 0) - COALESCE(v_order.paid_amount, 0);
  IF v_non_refund_total > v_remaining + 0.01 THEN
    RAISE EXCEPTION 'PAYMENT_EXCEEDS_REMAINING: payment % > remaining % (total %)',
      v_non_refund_total, v_remaining, v_order.total_amount;
  END IF;

  -- ═══ 7a. COMPUTE NEW VALUES ═══
  v_new_paid := COALESCE(v_order.paid_amount, 0) + v_non_refund_total - v_refund_total;
  v_new_refund := COALESCE(v_order.refund_amount, 0) + v_refund_total;

  IF v_refund_total > 0 THEN
    v_new_status := CASE
      WHEN v_new_paid <= 0.01 THEN 'refunded'
      ELSE 'partially_refunded'
    END;
  ELSE
    v_new_status := CASE
      WHEN v_new_paid >= COALESCE(v_order.total_amount, 0) - 0.01 THEN 'paid'
      ELSE v_order.status
    END;
  END IF;

  -- ═══ 7b. D-7: WRITE ORDER_PAYMENTS LEDGER ROWS (atomic, same txn) ═══
  -- validate_payment_order_balance trigger adds a second overpay layer.
  FOR v_payment IN SELECT * FROM jsonb_array_elements(p_payments) LOOP
    v_amount := COALESCE((v_payment->>'amount')::NUMERIC, 0);
    IF v_amount <= 0 THEN CONTINUE; END IF;
    v_is_refund := COALESCE((v_payment->>'is_refund')::BOOLEAN, false);
    v_method := COALESCE((v_payment->>'method')::TEXT, 'cash');

    INSERT INTO order_payments (
      order_id, payment_method, method, amount, status,
      is_refund, is_partial, created_by, reference, split_group_id, currency
    ) VALUES (
      p_order_id, v_method, v_method, v_amount, 'captured',
      v_is_refund,
      COALESCE((v_payment->>'is_partial')::BOOLEAN, false),
      p_performed_by, p_idempotency_key,
      (v_payment->>'split_group_id')::UUID,
      COALESCE((v_payment->>'currency')::TEXT, 'AZN')
    ) RETURNING id INTO v_ledger_id;

    v_payment_ids := array_append(v_payment_ids, v_ledger_id);
  END LOOP;

  -- ═══ 7c. UPDATE ORDER ═══
  UPDATE orders SET
    paid_amount = v_new_paid,
    refund_amount = v_new_refund,
    cash_amount = COALESCE(cash_amount, 0) + v_cash_total,
    card_amount = COALESCE(card_amount, 0) + v_card_total,
    tip_amount = COALESCE(tip_amount, 0) + p_tip_amount,
    discount_amount = p_discount_amount,
    discount_type = p_discount_type,
    payment_method = p_payment_method,
    status = v_new_status,
    cash_received = COALESCE(cash_received, 0) + COALESCE(p_cash_received, v_cash_total),
    change_amount = COALESCE(change_amount, 0) + v_change,
    paid_at = CASE WHEN v_new_status = 'paid' AND v_order.status != 'paid' THEN v_now ELSE paid_at END,
    updated_at = v_now,
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  -- ═══ 7d. BUILD RESULT ═══
  v_result := jsonb_build_object(
    'success', true,
    'action', CASE WHEN v_refund_total > 0 THEN 'refund' ELSE 'payment' END,
    'paid_amount', v_new_paid,
    'refund_amount', v_new_refund,
    'total_amount', v_order.total_amount,
    'remaining', GREATEST(0, COALESCE(v_order.total_amount, 0) - v_new_paid),
    'is_fully_paid', v_new_paid >= COALESCE(v_order.total_amount, 0) - 0.01,
    'status', v_new_status,
    'cash_received', p_cash_received,
    'change', v_change,
    'tip_amount', p_tip_amount,
    'payment_ids', to_jsonb(v_payment_ids),
    'idempotent', false,
    'table_number', v_order.table_number,
    'timestamp', v_now
  );

  -- ═══ 7e. P-4 C-2/C-6: STORE IDEMPOTENCY KEY + RESULT (atomic, scoped, TTL'd) ═══
  -- The row commits only with the successful financial write (ratified D-7:
  -- no financial mutation = no successful idempotency claim). Retention:
  -- P4_KEY_RETENTION_DAYS = 30 (key metadata only; the ledger is permanent).
  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO payment_idempotency_keys (namespace, key, order_id, amount, status, result, expires_at)
    VALUES (v_idem_namespace, p_idempotency_key, p_order_id, v_idem_effect, 'completed', v_result,
            now() + interval '30 days');
  END IF;

  -- ═══ 7f. AUDIT ═══
  PERFORM public.log_audit(
    CASE WHEN v_refund_total > 0 THEN 'refund' ELSE 'payment' END,
    'order', p_order_id::text,
    p_performed_by, v_performer_name,
    jsonb_build_object(
      'status', v_order.status,
      'paid_amount', v_order.paid_amount,
      'refund_amount', COALESCE(v_order.refund_amount, 0)
    ),
    jsonb_build_object(
      'status', v_new_status,
      'paid_amount', v_new_paid,
      'refund_amount', v_new_refund,
      'payment_method', p_payment_method,
      'amount', v_non_refund_total - v_refund_total
    ),
    jsonb_build_object(
      'payments', p_payments,
      'cash_received', p_cash_received,
      'change', v_change,
      'idempotency_key', p_idempotency_key
    ),
    NULL
  );

  RETURN v_result;
END;
$$;


--
-- Name: complete_payment_v4(uuid, text, numeric, numeric, numeric, numeric, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_payment_v4(p_order_id uuid, p_payment_method text, p_total_amount numeric, p_tax_amount numeric, p_service_amount numeric, p_discount_amount numeric, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table_id INTEGER;
  v_group_id UUID;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT table_number, group_id INTO v_table_id, v_group_id FROM orders WHERE id = p_order_id FOR UPDATE;
  UPDATE orders SET 
    status = 'COMPLETED',
    payment_method = p_payment_method,
    paid_amount = p_total_amount,
    total_amount = p_total_amount,
    updated_at = NOW()
  WHERE id = p_order_id;
  RETURN jsonb_build_object('success', true, 'order_id', p_order_id);
END;
$$;


--
-- Name: complete_reservation_on_table_clear(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.complete_reservation_on_table_clear() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF NEW.status = 'empty' AND OLD.status = 'dirty' AND OLD.reservation_id IS NOT NULL THEN
    IF NOT EXISTS (
      SELECT 1 FROM table_floors
      WHERE reservation_id = OLD.reservation_id
        AND status != 'empty'
        AND id != NEW.id
    ) THEN
      UPDATE reservations
      SET status = 'completed', updated_at = now()
      WHERE id = OLD.reservation_id
        AND status IN ('checked_in', 'seated');
    END IF;
    UPDATE table_floors
    SET reservation_id = NULL,
        reservation_name = NULL,
        reservation_phone = NULL,
        reservation_time = NULL,
        guest_count = NULL
    WHERE id = NEW.id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: confirm_and_checkin_atomic(uuid, integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.confirm_and_checkin_atomic(p_reservation_id uuid, p_table_ids integer[] DEFAULT '{}'::integer[], p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table RECORD;
  v_order_id UUID;
  v_order_ids UUID[] := '{}';
  v_item RECORD;
  v_now TIMESTAMPTZ := now();
  v_scheduled_for TIMESTAMPTZ;
  v_target_table_numbers INT[];
  v_result jsonb;
BEGIN
  SELECT * INTO v_reservation FROM public.reservations
    WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;

  IF v_reservation.status != 'pending' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation is not pending');
  END IF;

  IF p_table_ids IS NULL OR array_length(p_table_ids, 1) IS NULL OR array_length(p_table_ids, 1) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'At least one table required');
  END IF;

  UPDATE public.reservations SET
    status = 'confirmed',
    table_ids = p_table_ids,
    updated_at = NOW()
  WHERE id = p_reservation_id;

  DELETE FROM public.reservation_tables WHERE reservation_id = p_reservation_id;

  FOR v_target_table_numbers IN SELECT unnest(p_table_ids) LOOP
    INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
    VALUES (p_reservation_id, v_target_table_numbers, NOW())
    ON CONFLICT (reservation_id, table_number) DO NOTHING;

    UPDATE public.table_floors SET
      status = 'reserved',
      reservation_id = p_reservation_id,
      reservation_name = v_reservation.name,
      reservation_phone = v_reservation.phone,
      reserved_at = NOW(),
      reserved_until = v_reservation.date + v_reservation.time,
      updated_at = NOW()
    WHERE table_number = v_target_table_numbers;
  END LOOP;

  PERFORM public.log_reservation_operation(
    p_reservation_id,
    'confirm_and_checkin',
    jsonb_build_object('status', 'pending'),
    jsonb_build_object('status', 'confirmed', 'table_ids', p_table_ids),
    p_user_id
  );

  v_result := jsonb_build_object('success', true, 'reservation_id', p_reservation_id);
  RETURN v_result;
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: consume_stock_for_item(uuid, uuid, uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.consume_stock_for_item(p_order_item_id uuid, p_order_id uuid, p_product_id uuid, p_quantity integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prod RECORD;
  v_rec RECORD;
  v_key text;
  v_corr uuid := gen_random_uuid();
  v_qty numeric;
  v_unit text;
  v_ingredient_id uuid;
  v_id uuid;
  v_order_loc uuid;
  v_order_org uuid;
BEGIN
  IF p_performed_by IS NOT NULL THEN
    PERFORM public.validate_actor(p_performed_by);
  END IF;

  -- H4.2: serialize concurrent same-item consumptions (KDS + admin path).
  PERFORM pg_advisory_xact_lock(hashtext('consume:' || p_order_item_id::text));

  -- Location/org must mirror the order (enforce_inventory_log_order_location).
  SELECT location_id, organization_id INTO v_order_loc, v_order_org
  FROM public.orders WHERE id = p_order_id;

  -- Legacy guard under the lock: item already consumed (any shape — pre-H
  -- rows have NULL idempotency_key, so the unique index cannot dedupe them).
  IF EXISTS (
    SELECT 1 FROM public.inventory_logs
    WHERE order_item_id = p_order_item_id AND type = 'order_consumption'
  ) THEN
    RETURN;
  END IF;

  SELECT * INTO v_prod FROM public.products WHERE id = p_product_id;
  IF NOT FOUND THEN RETURN; END IF;

  -- Ready product: one row, qty = item qty, key per ingredient.
  IF v_prod.is_ready_product AND v_prod.direct_ingredient_id IS NOT NULL THEN
    v_ingredient_id := v_prod.direct_ingredient_id;
    SELECT COALESCE(unit, 'gram') INTO v_unit FROM public.ingredients WHERE id = v_ingredient_id;
    v_key := 'consume:' || p_order_item_id::text || ':' || v_ingredient_id::text;

    INSERT INTO public.inventory_logs
      (ingredient_id, type, quantity, unit, order_id, order_item_id, item_quantity,
       reference_type, reference_id, correlation_id, idempotency_key, performed_by, reason,
       location_id, organization_id)
    VALUES
      (v_ingredient_id, 'order_consumption', p_quantity, v_unit,
       p_order_id, p_order_item_id, p_quantity, 'order', p_order_id, v_corr, v_key, p_performed_by,
       'Hazır məhsul satışı', v_order_loc, v_order_org)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      PERFORM public.emit_outbox_event('inventory', v_ingredient_id, 'inventory.transaction.created',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_ingredient_id, 'quantity', p_quantity, 'type', 'order_consumption'),
        jsonb_build_object('correlation_id', v_corr));
      PERFORM public.emit_outbox_event('inventory', v_ingredient_id, 'inventory.stock_changed',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_ingredient_id, 'quantity', p_quantity),
        jsonb_build_object('correlation_id', v_corr));
    END IF;
    RETURN;
  END IF;

  -- Recipe product: one row per (item, ingredient); H3 math:
  --   ingredient consumption = COALESCE(quantity_brutto, quantity_required) x item qty
  FOR v_rec IN
    SELECT r.ingredient_id,
           COALESCE(r.quantity_brutto, r.quantity_required) AS qty,
           COALESCE(i.unit, 'gram') AS unit
    FROM public.recipes r
    JOIN public.ingredients i ON i.id = r.ingredient_id
    WHERE r.menu_item_id = p_product_id AND r.is_ai_suggested = false
  LOOP
    v_qty := v_rec.qty * p_quantity;
    v_key := 'consume:' || p_order_item_id::text || ':' || v_rec.ingredient_id::text;

    INSERT INTO public.inventory_logs
      (ingredient_id, type, quantity, unit, order_id, order_item_id, item_quantity,
       reference_type, reference_id, correlation_id, idempotency_key, performed_by, reason,
       location_id, organization_id)
    VALUES
      (v_rec.ingredient_id, 'order_consumption', v_qty, v_rec.unit,
       p_order_id, p_order_item_id, p_quantity, 'order', p_order_id, v_corr, v_key, p_performed_by,
       'Reseptli satış', v_order_loc, v_order_org)
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.transaction.created',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', v_qty, 'type', 'order_consumption'),
        jsonb_build_object('correlation_id', v_corr));
      PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.stock_changed',
        jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', v_qty),
        jsonb_build_object('correlation_id', v_corr));
    END IF;
  END LOOP;
END;
$$;


--
-- Name: correct_item_atomic(text, uuid, jsonb, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.correct_item_atomic(p_token text, p_item_id uuid, p_correction jsonb, p_reason text DEFAULT NULL::text, p_idempotency_key text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_item RECORD;
  v_order RECORD;
  v_rule jsonb;
  v_allowed jsonb;
  v_type text;
  v_qty int;
  v_mods jsonb;
  v_tax numeric;
  v_course text;
  v_seat int;
  v_notes text;
  v_old_total numeric;
  v_void_total numeric;
  v_pricing jsonb;
  v_new_total numeric;
  v_delta numeric;
  v_new_item uuid;
  v_corr uuid;
  v_corr_key text;
  v_prev RECORD;
  v_production boolean;
  v_stock_consumed boolean;
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  v_type := COALESCE(p_correction->>'type','void_readd');

  IF v_type NOT IN ('quantity','modifiers','price_tax','void_readd') THEN
    RAISE EXCEPTION 'UNKNOWN_CORRECTION_TYPE: % (quantity|modifiers|price_tax|void_readd)', v_type USING ERRCODE='P0001';
  END IF;
  v_qty  := COALESCE((p_correction->>'quantity')::int, NULL);
  v_mods := COALESCE(p_correction->'modifiers', NULL);
  v_tax  := COALESCE((p_correction->>'tax_rate')::numeric, NULL);
  v_course := p_correction->>'course';
  v_seat := NULLIF((p_correction->>'seat_number')::int, NULL);
  v_notes := p_correction->>'special_notes';

  IF v_type = 'quantity' AND v_qty IS NULL THEN
    RAISE EXCEPTION 'CORRECTION_REQUIRES_QTY: quantity correction needs quantity' USING ERRCODE='P0001';
  END IF;
  IF v_type = 'modifiers' AND v_mods IS NULL THEN
    RAISE EXCEPTION 'CORRECTION_REQUIRES_MODIFIERS' USING ERRCODE='P0001';
  END IF;
  IF v_type = 'price_tax' AND v_tax IS NULL THEN
    RAISE EXCEPTION 'CORRECTION_REQUIRES_TAX_RATE' USING ERRCODE='P0001';
  END IF;
  IF v_qty IS NOT NULL AND v_qty <= 0 THEN
    RAISE EXCEPTION 'INVALID_QTY: quantity must be > 0' USING ERRCODE='P0001';
  END IF;
  IF v_tax IS NOT NULL AND (v_tax < 0 OR v_tax > 100) THEN
    RAISE EXCEPTION 'INVALID_TAX_RATE: % (0..100)', v_tax USING ERRCODE='P0001';
  END IF;

  v_corr_key := COALESCE(p_idempotency_key, 'corr-' || v_staff_id || '-' || p_item_id || '-' || to_jsonb(p_correction)::text);
  SELECT * INTO v_prev FROM item_corrections WHERE idempotency_key = v_corr_key;
  IF FOUND THEN
    RETURN jsonb_build_object('success', true, 'duplicate', true,
      'correction_id', v_prev.id, 'original_item_id', v_prev.original_item_id,
      'replacement_item_id', v_prev.replacement_item_id);
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = (SELECT order_id FROM order_items WHERE id = p_item_id) FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE='P0001'; END IF;

  SELECT * INTO v_item FROM order_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE='P0001'; END IF;

  IF v_order.status IN ('paid','closed','cancelled','refunded','partially_refunded') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED: corrections not allowed on % orders — use refund/reversal workflow', v_order.status USING ERRCODE='P0001';
  END IF;

  IF v_item.kitchen_status IN ('voided','cancelled','comped','wasted','recalled') THEN
    RAISE EXCEPTION 'ITEM_CORRECTION_FROZEN: item is terminal (%) — correct the replacement item instead', v_item.kitchen_status USING ERRCODE='P0001';
  END IF;

  v_rule := validate_transition('item', v_item.kitchen_status, 'voided');
  IF NOT (v_rule->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_ITEM_TRANSITION: %', v_rule->>'error' USING ERRCODE='P0001';
  END IF;

  v_allowed := authorize(p_token, COALESCE(v_rule->>'requires_permission','order.void'), v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: % at % (reason: %)',
      COALESCE(v_rule->>'requires_permission','order.void'), v_order.location_id,
      v_allowed->>'reason' USING ERRCODE='P0001';
  END IF;

  IF COALESCE(v_rule->>'requires_manager_override','false')::boolean THEN
    PERFORM ensure_manager_override(v_staff_id,
      COALESCE(v_rule->>'requires_permission','order.void'),
      v_order.location_id, v_item.kitchen_status, 'voided');
  END IF;

  v_production := v_item.kitchen_status IN ('sent','accepted','preparing','ready','served','completed');
  v_stock_consumed := v_item.kitchen_status IN ('ready','served','completed');

  v_pricing := _price_replacement_snapshot(v_item.product_id,
    COALESCE(v_qty, v_item.quantity),
    COALESCE(v_mods, COALESCE(v_item.modifiers, '[]'::jsonb)),
    COALESCE(v_tax, COALESCE(v_item.tax_rate, 0)));

  v_old_total  := COALESCE(v_item.total_price, v_item.unit_price * v_item.quantity);
  v_void_total := v_old_total;
  v_new_total  := (v_pricing->>'total_price')::numeric;
  v_delta      := round(v_new_total - v_void_total, 2);

  v_corr := gen_random_uuid();

  UPDATE order_items SET
    kitchen_status = 'voided',
    total_price = 0,
    served_at = NULL,
    updated_at = now()
  WHERE id = p_item_id;

  UPDATE orders SET
    total_amount = GREATEST(0, COALESCE(total_amount, 0) - v_void_total),
    version = COALESCE(version, 0) + 1
  WHERE id = v_order.id;

  INSERT INTO order_items (
    order_id, product_id, product_name, quantity, unit_price, total_price,
    modifiers, course, seat_number, special_notes,
    kitchen_status, tax_rate, tax_amount, price_snapshot,
    station_id, idempotency_key, correlation_id
  ) VALUES (
    v_order.id, v_item.product_id, v_pricing->>'product_name', COALESCE(v_qty, v_item.quantity),
    (v_pricing->>'unit_price')::numeric, v_new_total,
    v_pricing->'modifiers',
    COALESCE(v_course, v_item.course),
    COALESCE(v_seat, v_item.seat_number),
    COALESCE(v_notes, v_item.special_notes),
    'pending', COALESCE(v_tax, COALESCE(v_item.tax_rate, 0)),
    (v_pricing->>'tax_amount')::numeric, v_pricing->'snapshot',
    (v_pricing->>'station_id')::uuid,
    NULL, v_corr
  ) RETURNING id INTO v_new_item;

  UPDATE orders SET
    total_amount = COALESCE(total_amount, 0) + v_new_total,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = v_order.id;

  INSERT INTO item_corrections (
    id, order_id, original_item_id, replacement_item_id, correction_type,
    reason, performed_by, idempotency_key, old_total, new_total, delta, closed_at
  ) VALUES (
    v_corr, v_order.id, p_item_id, v_new_item, v_type,
    p_reason, v_staff_id, v_corr_key, v_void_total, v_new_total, v_delta, now()
  );

  PERFORM log_order_event(v_order.id, 'item_voided',
    jsonb_build_object('item', p_item_id, 'total', v_void_total, 'status_before', v_item.kitchen_status, 'correction_type', v_type),
    jsonb_build_object('total', 0, 'reason', p_reason, 'replacement_item_id', v_new_item),
    COALESCE(p_metadata, jsonb_build_object('correction_id', v_corr)),
    v_staff_id, NULL, NULL, NULL);

  PERFORM log_order_event(v_order.id, 'item_added',
    NULL,
    jsonb_build_object('order_item_id', v_new_item, 'product_name', v_pricing->>'product_name',
      'quantity', COALESCE(v_qty, v_item.quantity), 'unit_price', (v_pricing->>'unit_price')::numeric,
      'total_price', v_new_total, 'tax_amount', (v_pricing->>'tax_amount')::numeric, 'replacement_of', p_item_id),
    jsonb_build_object('correction_id', v_corr, 'correction_type', v_type),
    v_staff_id, NULL, NULL, NULL);

  PERFORM log_order_event(v_order.id, 'item_corrected',
    jsonb_build_object('original_item_id', p_item_id, 'old_total', v_void_total),
    jsonb_build_object('replacement_item_id', v_new_item, 'new_total', v_new_total, 'delta', v_delta),
    jsonb_build_object('correction_type', v_type, 'reason', p_reason, 'correction_id', v_corr),
    v_staff_id, NULL, NULL, NULL);

  INSERT INTO operation_logs (operation, order_id, performed_by, reason, old_state, new_state,
                              location_id, organization_id, metadata)
  VALUES ('order_item.correct', v_order.id, v_staff_id, p_reason,
    jsonb_build_object('item', p_item_id, 'status', v_item.kitchen_status, 'total', v_void_total, 'correction_type', v_type),
    jsonb_build_object('replacement', v_new_item, 'status', 'pending', 'total', v_new_total, 'delta', v_delta),
    v_order.location_id, v_order.organization_id,
    COALESCE(p_metadata, '{}'::jsonb) || jsonb_build_object('correction_id', v_corr));

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', p_item_id, 'order_item.voided',
    jsonb_build_object('order_id', v_order.id, 'old_total', v_void_total, 'new_total', 0,
      'reason', p_reason, 'performed_by', v_staff_id, 'correction', true,
      'correction_type', v_type, 'replacement_item_id', v_new_item,
      'kitchen_aware', v_production, 'status_before', v_item.kitchen_status),
    'pending');

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', v_new_item, 'order_item.added',
    jsonb_build_object('order_id', v_order.id, 'product_id', v_item.product_id,
      'quantity', COALESCE(v_qty, v_item.quantity), 'unit_price', (v_pricing->>'unit_price')::numeric,
      'total_price', v_new_total, 'tax_amount', (v_pricing->>'tax_amount')::numeric,
      'performed_by', v_staff_id, 'replacement_of', p_item_id, 'correction_id', v_corr),
    'pending');

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', v_new_item, 'order_item.corrected',
    jsonb_build_object('order_id', v_order.id, 'original_item_id', p_item_id,
      'old_total', v_void_total, 'new_total', v_new_total, 'delta', v_delta,
      'correction_type', v_type, 'reason', p_reason, 'performed_by', v_staff_id),
    'pending');

  IF v_production THEN
    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
    VALUES ('order_item', p_item_id, 'order_item.kitchen_compensation',
      jsonb_build_object('order_id', v_order.id, 'item_id', p_item_id,
        'replacement_item_id', v_new_item, 'status_before', v_item.kitchen_status,
        'reason', p_reason),
      'pending');
  END IF;

  IF v_stock_consumed THEN
    -- H10.2: legacy direct 'legacy-underscore reversal event name' marker removed.
    -- _inventory_reverse_item() below emits the canonical reversal set in the
    -- same transaction: inventory.transaction.created + inventory.stock_changed
    -- + inventory.reversal.requested (single canonical signal, correlation id).
    PERFORM public._inventory_reverse_item(p_item_id, COALESCE(p_reason, 'correction'), v_staff_id, v_corr);
  END IF;

  RETURN jsonb_build_object('success', true,
    'correction_id', v_corr,
    'original_item_id', p_item_id,
    'replacement_item_id', v_new_item,
    'correction_type', v_type,
    'voided_total', v_void_total,
    'new_total', v_new_total,
    'delta', v_delta,
    'replacement_status', 'pending');
END;
$$;


--
-- Name: create_delivery_order(text, text, text, text, text, text, text, text, text, text, text, numeric, timestamp with time zone, jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_delivery_order(p_customer_phone text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_customer_note text DEFAULT NULL::text, p_delivery_address text DEFAULT NULL::text, p_delivery_district text DEFAULT NULL::text, p_delivery_street text DEFAULT NULL::text, p_delivery_building text DEFAULT NULL::text, p_delivery_floor text DEFAULT NULL::text, p_delivery_apartment text DEFAULT NULL::text, p_delivery_intercom text DEFAULT NULL::text, p_delivery_zone text DEFAULT NULL::text, p_delivery_fee numeric DEFAULT 0, p_estimated_delivery_time timestamp with time zone DEFAULT NULL::timestamp without time zone, p_items jsonb DEFAULT '[]'::jsonb, p_performed_by uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_id UUID;
  v_order_number TEXT;
  v_item JSONB;
  v_product_id UUID;
  v_quantity INTEGER;
  v_unit_price NUMERIC;
  v_total NUMERIC := 0;
BEGIN
  IF p_customer_phone IS NULL OR trim(p_customer_phone) = '' THEN
    RAISE EXCEPTION 'customer_phone is required';
  END IF;

  IF p_delivery_address IS NULL OR trim(p_delivery_address) = '' THEN
    RAISE EXCEPTION 'delivery_address is required';
  END IF;

  IF p_delivery_fee IS NULL OR p_delivery_fee < 0 THEN
    RAISE EXCEPTION 'delivery_fee must be a valid number >= 0';
  END IF;

  -- D-5: location/org are mandatory (NOT NULL columns). Route resolves them;
  -- reject a direct/NULL call explicitly (no defaulting).
  IF p_location_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'NO_LOCATION_CONTEXT' USING ERRCODE = 'P0001';
  END IF;

  v_order_number := generate_delivery_order_number();

  INSERT INTO orders (
    order_number, order_type, order_source, status, delivery_status,
    customer_phone, customer_name, customer_note,
    delivery_address, delivery_district, delivery_street, delivery_building,
    delivery_floor, delivery_apartment, delivery_intercom, delivery_zone,
    delivery_fee, estimated_delivery_time,
    total_amount, guest_count, is_draft, version, created_at,
    location_id, organization_id
  ) VALUES (
    v_order_number, 'delivery', 'delivery', 'new', 'pending',
    p_customer_phone, p_customer_name, p_customer_note,
    p_delivery_address, p_delivery_district, p_delivery_street, p_delivery_building,
    p_delivery_floor, p_delivery_apartment, p_delivery_intercom, p_delivery_zone,
    COALESCE(p_delivery_fee, 0), p_estimated_delivery_time,
    0, 1, false, 1, now(),
    p_location_id, p_organization_id
  )
  RETURNING id INTO v_order_id;

  IF jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      IF (v_item->>'product_id') IS NULL OR trim(v_item->>'product_id') = '' THEN
        RAISE EXCEPTION 'product_id is required';
      END IF;
      BEGIN
        v_product_id := (v_item->>'product_id')::UUID;
      EXCEPTION
        WHEN invalid_text_representation THEN
          RAISE EXCEPTION 'invalid product_id format';
      END;

      IF (v_item->>'product_name') IS NULL OR trim(v_item->>'product_name') = '' THEN
        RAISE EXCEPTION 'product_name is required';
      END IF;

      v_quantity := COALESCE((v_item->>'quantity')::INTEGER, 1);
      IF v_quantity <= 0 THEN
        RAISE EXCEPTION 'quantity must be greater than 0';
      END IF;

      IF (v_item->>'unit_price') IS NULL THEN
        RAISE EXCEPTION 'unit_price is required';
      END IF;
      v_unit_price := (v_item->>'unit_price')::NUMERIC;
      IF v_unit_price < 0 THEN
        RAISE EXCEPTION 'unit_price must be a valid number >= 0';
      END IF;

      INSERT INTO order_items (
        order_id, product_id, product_name, quantity, unit_price, total_price,
        modifiers, special_notes, kitchen_status
      ) VALUES (
        v_order_id,
        v_product_id,
        v_item->>'product_name',
        v_quantity,
        v_unit_price,
        v_unit_price * v_quantity,
        COALESCE(v_item->'modifiers', '[]'::JSONB),
        v_item->>'special_notes',
        'pending'
      );

      v_total := v_total + (v_unit_price * v_quantity);
    END LOOP;

    UPDATE orders SET total_amount = v_total WHERE id = v_order_id;
  END IF;

  PERFORM log_order_event(
    v_order_id, 'created',
    NULL,
    jsonb_build_object('order_number', v_order_number, 'source', 'delivery'),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number
  );
END;
$$;


