--
-- Name: create_location_atomic(text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_location_atomic(p_token text, p_organization_id uuid, p_name text, p_code text, p_slug text, p_timezone text DEFAULT 'Asia/Baku'::text, p_currency text DEFAULT 'AZN'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_staff_id uuid; v_org_id uuid; v_location_id uuid; v_corr uuid; v_new jsonb;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id(); v_org_id := current_org_id();
    IF NOT has_permission('settings.admin') AND NOT is_superadmin() THEN
        RAISE EXCEPTION 'Permission denied: settings.admin required';
    END IF;
    IF NOT has_org_access(p_organization_id) THEN
        RAISE EXCEPTION 'Cannot create location in another organization';
    END IF;
    IF p_name IS NULL OR length(trim(p_name)) = 0 THEN RAISE EXCEPTION 'Name required'; END IF;
    IF p_code IS NULL OR length(trim(p_code)) = 0 THEN RAISE EXCEPTION 'Code required'; END IF;
    IF p_slug IS NULL OR length(trim(p_slug)) = 0 THEN RAISE EXCEPTION 'Slug required'; END IF;
    IF p_currency !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'Currency must be 3-letter ISO code'; END IF;
    v_corr := gen_random_uuid();
    INSERT INTO locations (name, code, slug, organization_id, status, timezone, currency)
    VALUES (trim(p_name), trim(p_code), trim(p_slug), p_organization_id, 'ACTIVE', p_timezone, p_currency)
    RETURNING id INTO v_location_id;
    v_new := row_to_json(l.*)::jsonb FROM locations l WHERE l.id = v_location_id;
    INSERT INTO operation_logs (entity_type, entity_id, operation, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('location', v_location_id, 'location.created', v_new, v_staff_id, v_corr, v_location_id, p_organization_id);
    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, metadata, status)
    VALUES ('location', v_location_id, 'location.created', v_new,
            jsonb_build_object('organization_id', p_organization_id, 'actor_staff_id', v_staff_id, 'correlation_id', v_corr), 'pending');
    RETURN v_new;
END;
$_$;


--
-- Name: create_reconciliation(uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_reconciliation(p_shift_id uuid, p_staff_id uuid, p_denominations jsonb) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reconciliation_id UUID;
  v_shift RECORD;
  v_actual_cash DECIMAL;
  v_denomination RECORD;
  v_expected DECIMAL;
  v_difference DECIMAL;
BEGIN
  SELECT * INTO v_shift FROM shifts WHERE id = p_shift_id;

  -- Calculate actual cash from denominations
  v_actual_cash := 0;
  FOR v_denomination IN SELECT * FROM jsonb_array_elements(p_denominations)
  LOOP
    v_actual_cash := v_actual_cash + (v_denomination->>'denomination')::DECIMAL * (v_denomination->>'count')::INTEGER;

    INSERT INTO denomination_counts (reconciliation_id, denomination, count)
    VALUES (v_reconciliation_id, (v_denomination->>'denomination')::DECIMAL, (v_denomination->>'count')::INTEGER);
  END LOOP;

  v_expected := COALESCE(v_shift.expected_cash, 0);
  v_difference := v_actual_cash - v_expected;

  INSERT INTO cash_reconciliations (shift_id, staff_id, starting_cash, expected_cash, actual_cash, difference, over_short)
  VALUES (p_shift_id, p_staff_id, v_shift.starting_cash, v_expected, v_actual_cash, v_difference, CASE WHEN v_difference >= 0 THEN 'over' ELSE 'short' END)
  RETURNING id INTO v_reconciliation_id;

  RETURN json_build_object(
    'success', true,
    'reconciliation_id', v_reconciliation_id,
    'expected', v_expected,
    'actual', v_actual_cash,
    'difference', v_difference
  );
END;
$$;


