--
-- Name: create_schedule(uuid, date, time without time zone, time without time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_schedule(p_staff_id uuid, p_date date, p_start time without time zone, p_end time without time zone, p_notes text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_schedule_id UUID;
BEGIN
  IF p_start >= p_end THEN
    RETURN json_build_object('success', false, 'error', 'planned_start must be before planned_end');
  END IF;

  -- Early clean rejection (constraint is the atomic backstop for races)
  IF EXISTS (
    SELECT 1 FROM schedule
    WHERE staff_id = p_staff_id
      AND schedule_date = p_date
      AND (planned_start, planned_end) OVERLAPS (p_start, p_end)
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Schedule conflict detected');
  END IF;

  BEGIN
    INSERT INTO schedule (staff_id, schedule_date, planned_start, planned_end, notes)
    VALUES (p_staff_id, p_date, p_start, p_end, p_notes)
    RETURNING id INTO v_schedule_id;
  EXCEPTION WHEN exclusion_violation THEN
    RETURN json_build_object('success', false, 'error', 'Schedule conflict detected');
  END;

  RETURN json_build_object('success', true, 'schedule_id', v_schedule_id);
END;
$$;


--
-- Name: create_staff_atomic(text, text, text, text, uuid, text, numeric, text, uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_staff_atomic(p_name text, p_full_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_role_id uuid DEFAULT NULL::uuid, p_pin_hash text DEFAULT NULL::text, p_hourly_rate numeric DEFAULT NULL::numeric, p_shift text DEFAULT NULL::text, p_station_id uuid DEFAULT NULL::uuid, p_is_active boolean DEFAULT true, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_role_exists boolean;
BEGIN
  -- Validate role
  IF p_role_id IS NOT NULL THEN
    SELECT EXISTS(SELECT 1 FROM roles WHERE id = p_role_id) INTO v_role_exists;
    IF NOT v_role_exists THEN
      RETURN jsonb_build_object('success', false, 'error', 'ROLE_NOT_FOUND');
    END IF;
  END IF;

  -- Create staff
  INSERT INTO staff (name, full_name, email, phone, role_id, pin_hash, hourly_rate, shift, station_id, is_active)
  VALUES (p_name, p_full_name, p_email, p_phone, p_role_id, p_pin_hash, p_hourly_rate, p_shift, p_station_id, p_is_active)
  RETURNING id INTO v_staff_id;

  -- Audit
  PERFORM log_audit(
    'staff_created', 'staff', v_staff_id::text, p_performed_by,
    NULL,
    jsonb_build_object(
      'name', p_name,
      'role_id', p_role_id,
      'is_active', p_is_active
    ),
    NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'staff_id', v_staff_id,
    'name', p_name
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: create_takeaway_order(text, text, text, timestamp with time zone, jsonb, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_takeaway_order(p_customer_phone text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_customer_note text DEFAULT NULL::text, p_estimated_pickup_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_items jsonb DEFAULT '[]'::jsonb, p_performed_by uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_organization_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_order_id UUID;
  v_order_number TEXT;
  v_item JSONB;
  v_product_id UUID;
  v_quantity INTEGER;
  v_unit_price NUMERIC;
  v_cfg RECORD;
BEGIN
  IF p_customer_phone IS NULL OR trim(p_customer_phone) = '' THEN
    RAISE EXCEPTION 'customer_phone is required';
  END IF;
  IF p_location_id IS NULL OR p_organization_id IS NULL THEN
    RAISE EXCEPTION 'NO_LOCATION_CONTEXT' USING ERRCODE = 'P0001';
  END IF;

  v_order_number := generate_takeaway_order_number();

  INSERT INTO orders (
    order_number, order_type, order_source, status, kitchen_status,
    customer_phone, customer_name, customer_note,
    estimated_delivery_time, total_amount, guest_count,
    is_draft, version, created_at,
    location_id, organization_id
  ) VALUES (
    v_order_number, 'takeaway', 'takeaway', 'confirmed', 'pending',
    p_customer_phone, p_customer_name, p_customer_note,
    p_estimated_pickup_time, 0, 1,
    false, 1, now(),
    p_location_id, p_organization_id
  )
  RETURNING id INTO v_order_id;

  IF jsonb_array_length(p_items) > 0 THEN
    FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
    LOOP
      IF (v_item->>'product_id') IS NULL OR trim(v_item->>'product_id') = '' THEN
        RAISE EXCEPTION 'product_id is required';
      END IF;
      BEGIN
        v_product_id := (v_item->>'product_id')::UUID;
      EXCEPTION
        WHEN invalid_text_representation THEN
          RAISE EXCEPTION 'invalid product_id format';
      END;
      IF (v_item->>'product_name') IS NULL OR trim(v_item->>'product_name') = '' THEN
        RAISE EXCEPTION 'product_name is required';
      END IF;
      v_quantity := COALESCE((v_item->>'quantity')::INTEGER, 1);
      IF v_quantity <= 0 THEN
        RAISE EXCEPTION 'quantity must be greater than 0';
      END IF;
      IF (v_item->>'unit_price') IS NULL THEN
        RAISE EXCEPTION 'unit_price is required';
      END IF;
      v_unit_price := (v_item->>'unit_price')::NUMERIC;
      IF v_unit_price < 0 THEN
        RAISE EXCEPTION 'unit_price must be a valid number >= 0';
      END IF;

      INSERT INTO order_items (
        order_id, product_id, product_name, quantity, unit_price, total_price,
        modifiers, special_notes, kitchen_status, seat_number
      ) VALUES (
        v_order_id,
        v_product_id,
        v_item->>'product_name',
        v_quantity,
        v_unit_price,
        v_unit_price * v_quantity,
        COALESCE(v_item->'modifiers', '[]'::JSONB),
        v_item->>'special_notes',
        'pending',
        NULL
      );
    END LOOP;
  END IF;

  -- SSOT total on create: vat per settings.auto_apply_vat, service OFF
  -- (behavior-compatible: today's takeaway total = items only).
  SELECT auto_apply_vat INTO v_cfg FROM public.settings WHERE id = '1';
  PERFORM public.calculate_order_total_v3(
    v_order_id,
    COALESCE(v_cfg.auto_apply_vat, false),
    false
  );

  PERFORM log_order_event(
    v_order_id, 'created',
    NULL,
    jsonb_build_object('order_number', v_order_number, 'source', 'takeaway'),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', v_order_id,
    'order_number', v_order_number
  );
END;
$$;


--
-- Name: create_tip_pool(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.create_tip_pool(p_date date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool_id UUID;
  v_total DECIMAL;
BEGIN
  -- Calculate total tips from orders
  SELECT COALESCE(SUM(tip_amount), 0) INTO v_total
  FROM orders
  WHERE DATE(created_at) = p_date
  AND tip_amount > 0;

  INSERT INTO tip_pools (pool_date, total_amount)
  VALUES (p_date, v_total)
  RETURNING id INTO v_pool_id;

  RETURN json_build_object('success', true, 'pool_id', v_pool_id, 'total', v_total);
END;
$$;


