--
-- Name: deactivate_location_atomic(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deactivate_location_atomic(p_token text, p_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid; v_loc RECORD; v_old jsonb; v_new jsonb; v_corr uuid; v_blockers text[];
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    IF NOT has_permission('settings.admin') AND NOT is_superadmin() THEN RAISE EXCEPTION 'Permission denied'; END IF;
    SELECT * INTO v_loc FROM locations WHERE id = p_location_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Location not found'; END IF;
    IF NOT has_org_access(v_loc.organization_id) THEN RAISE EXCEPTION 'Cannot deactivate location in another org'; END IF;
    IF v_loc.status = 'INACTIVE' THEN RAISE EXCEPTION 'Already INACTIVE'; END IF;
    IF v_loc.status = 'ARCHIVED' THEN RAISE EXCEPTION 'ARCHIVED locations cannot be deactivated'; END IF;
    v_blockers := ARRAY[]::text[];
    IF EXISTS (SELECT 1 FROM orders WHERE location_id=p_location_id AND status IN ('draft','new','open','confirmed','in_kitchen','preparing','partially_ready','ready','served','payment_pending')) THEN
        v_blockers := array_append(v_blockers, 'open_orders'); END IF;
    IF EXISTS (SELECT 1 FROM shifts WHERE location_id=p_location_id AND opened_at IS NOT NULL AND closed_at IS NULL) THEN
        v_blockers := array_append(v_blockers, 'active_shifts'); END IF;
    IF EXISTS (SELECT 1 FROM cash_drawer_sessions WHERE location_id=p_location_id AND status='open') THEN
        v_blockers := array_append(v_blockers, 'open_cash_drawers'); END IF;
    IF EXISTS (SELECT 1 FROM reservations WHERE location_id=p_location_id AND status IN ('pending','confirmed','seated') AND date >= CURRENT_DATE) THEN
        v_blockers := array_append(v_blockers, 'active_reservations'); END IF;
    IF array_length(v_blockers, 1) > 0 THEN
        RAISE EXCEPTION 'Cannot deactivate: [%]', array_to_string(v_blockers, ', '); END IF;
    v_old := row_to_json(v_loc)::jsonb; v_corr := gen_random_uuid();
    UPDATE locations SET status='INACTIVE' WHERE id=p_location_id RETURNING row_to_json(locations.*)::jsonb INTO v_new;
    INSERT INTO operation_logs (entity_type, entity_id, operation, before_state, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('location', p_location_id, 'location.deactivated', v_old, v_new, v_staff_id, v_corr, p_location_id, v_loc.organization_id);
    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, metadata, status)
    VALUES ('location', p_location_id, 'location.deactivated', v_new,
            jsonb_build_object('organization_id', v_loc.organization_id, 'actor_staff_id', v_staff_id, 'correlation_id', v_corr), 'pending');
    RETURN v_new;
END;
$$;


