--
-- Name: deny_override(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.deny_override(p_token text, p_override_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid;
    v_org_id uuid;
    v_override RECORD;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    v_org_id := current_org_id();

    SELECT * INTO v_override FROM manager_overrides WHERE id = p_override_id;
    IF NOT FOUND THEN RAISE EXCEPTION 'Override not found'; END IF;
    IF v_override.status != 'PENDING' THEN RAISE EXCEPTION 'Override already %', v_override.status; END IF;

    UPDATE manager_overrides
    SET status = 'DENIED', approved_by = v_staff_id, denied_at = now(), denial_reason = p_reason
    WHERE id = p_override_id;

    INSERT INTO operation_logs (entity_type, entity_id, operation, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('manager_override', p_override_id, 'override.denied',
            jsonb_build_object('permission', v_override.permission, 'denial_reason', p_reason),
            v_staff_id, gen_random_uuid(), v_override.location_id, v_org_id);

    RETURN jsonb_build_object('override_id', p_override_id, 'status', 'DENIED');
END;
$$;


--
-- Name: dismiss_table_atomic(text, integer, text, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_table_atomic(p_token text, p_table_number integer, p_reason text, p_final_status text, p_performed_by uuid, p_terminal_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_table RECORD;
  v_order RECORD;
  v_active int;
  v_paid int;
  v_kitchen_active boolean;
  v_old_state jsonb;
BEGIN
  PERFORM public.set_session_staff(p_token);
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  PERFORM public.validate_actor(p_performed_by);
  IF p_final_status NOT IN ('empty','cleaning') THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_DISMISS_INVALID_FINAL');
  END IF;

  SELECT * INTO v_table FROM public.table_floors WHERE table_number = p_table_number AND (v_sess_loc IS NULL OR location_id = v_sess_loc) FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  IF NOT has_location_access(v_table.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF v_table.reservation_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TABLE_RESERVED');
  END IF;
  IF v_table.merged_into_table IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TABLE_MERGED');
  END IF;

  SELECT count(*) INTO v_active FROM public.orders
   WHERE table_number = p_table_number AND location_id = v_table.location_id
     AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided');
  IF v_active = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_NO_ACTIVE_ORDER');
  END IF;
  IF v_active > 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TABLE_MULTIPLE_ORDERS');
  END IF;

  SELECT * INTO v_order FROM public.orders
   WHERE table_number = p_table_number
     AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
   ORDER BY created_at ASC LIMIT 1;

  SELECT count(*) INTO v_paid FROM public.payments
   WHERE order_id = v_order.id AND status IN ('captured','pending');
  IF v_paid > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_DISMISS_ORDER_PAID');
  END IF;

  -- kitchen may not have produced anything yet (pending/reserved may be removed)
  SELECT EXISTS (
    SELECT 1 FROM public.order_items
    WHERE order_id = v_order.id
      AND kitchen_status IN ('sent','accepted','preparing','cooking','ready','partially_ready','served','completed')
  ) INTO v_kitchen_active;
  IF v_kitchen_active THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_DISMISS_KITCHEN_ACTIVE');
  END IF;

  v_old_state := jsonb_build_object('status', v_table.status,
    'order_id', v_order.id, 'order_status', v_order.status, 'total_amount', v_order.total_amount);

  -- registered edge (open/new/confirmed/... -> cancelled); triggers maintain timestamps
  UPDATE public.orders SET
    status = 'cancelled',
    cancelled_at = now(),
    cancelled_reason = p_reason,
    updated_at = now(),
    version = COALESCE(version,0) + 1,
    updated_by_terminal_id = p_terminal_id
  WHERE id = v_order.id;

  DELETE FROM public.order_items
   WHERE order_id = v_order.id AND kitchen_status IN ('pending','reserved','new');

  UPDATE public.table_floors SET
    status = p_final_status,
    guest_count = NULL,
    total_amount = 0,
    order_count = 0,
    current_order_id = NULL,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    has_pending = false,
    oldest_pending_at = NULL,
    bill_requested = false,
    updated_at = now(),
    updated_by_terminal_id = p_terminal_id
  WHERE table_number = p_table_number;

  PERFORM public.sync_table_order_aggregates(p_table_number);

  PERFORM public.g_table_audit(
    'dismiss_table', 'table.dismissed',
    p_table_number, v_table.id, v_order.id,
    v_old_state,
    jsonb_build_object('status', p_final_status, 'reason', p_reason, 'order_status', 'cancelled'),
    p_performed_by, p_terminal_id, p_reason,
    p_table_number, NULL, v_table.location_id, v_table.organization_id);

  RETURN jsonb_build_object('success', true, 'order_id', v_order.id, 'table_status', p_final_status);
END;
$$;


--
-- Name: dismiss_table_session(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_table_session(p_table_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_item RECORD;
  v_reservation_id UUID;
  v_reversed INTEGER := 0;
  v_notification_id UUID;
BEGIN
  -- Step 1: Reverse stock for all consumed items on unpaid orders via the
  --         canonical helper (no-op when never consumed).
  FOR v_order IN SELECT id FROM public.orders WHERE table_number = p_table_number AND status NOT IN ('paid', 'cancelled') LOOP
    FOR v_item IN SELECT id FROM public.order_items WHERE order_id = v_order.id LOOP
      PERFORM public._inventory_reverse_item(v_item.id, 'cancel', NULL);
      v_reversed := v_reversed + 1;
    END LOOP;
  END LOOP;

  -- Step 2: Cancel all unpaid orders
  UPDATE public.orders SET
    status = 'cancelled',
    cancelled_at = now(),
    kitchen_status = 'cancelled',
    version = COALESCE(version, 0) + 1
  WHERE table_number = p_table_number
    AND status NOT IN ('paid', 'cancelled');

  -- Step 3: For draft orders, clean up order_items
  DELETE FROM public.order_items
  WHERE order_id IN (SELECT id FROM public.orders WHERE table_number = p_table_number AND is_draft = true)
    AND kitchen_status IS DISTINCT FROM 'cancelled';

  -- Step 4: Unlink merged child tables
  UPDATE public.table_floors
  SET merged_into_table = NULL
  WHERE merged_into_table = p_table_number;

  -- Step 5: Cancel associated reservation
  SELECT reservation_id INTO v_reservation_id
  FROM public.table_floors WHERE table_number = p_table_number;

  IF v_reservation_id IS NOT NULL THEN
    UPDATE public.reservations SET
      status = 'cancelled',
      cancelled_at = now(),
      cancelled_reason = 'dismissed_table_session'
    WHERE id = v_reservation_id
      AND status NOT IN ('completed', 'cancelled', 'no_show');
  END IF;

  -- Step 6: Cancel kitchen schedules for this table
  UPDATE public.kitchen_schedule SET
    status = 'cancelled'
  WHERE table_number = p_table_number AND status = 'pending';

  -- Step 7: Reset table to empty
  UPDATE public.table_floors SET
    status = 'empty',
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    guest_count = NULL,
    total_amount = NULL,
    order_count = NULL,
    order_ids = NULL,
    has_pending = NULL,
    oldest_pending_at = NULL,
    last_activity_at = now(),
    updated_at = now()
  WHERE table_number = p_table_number;

  -- Step 8: Audit log
  INSERT INTO public.audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'table_floors',
    p_table_number::TEXT,
    'dismiss',
    jsonb_build_object('table_number', p_table_number),
    jsonb_build_object('action', 'dismissed', 'orders_cancelled', v_reversed, 'table_number', p_table_number),
    NULL,
    now()
  );

  -- Step 9: Notification
  INSERT INTO public.notifications (type, title, body, data, created_at)
  VALUES (
    'order',
    'Masa boşaldıldı',
    'Masa ' || p_table_number || ' — ləğv edildi (' || v_reversed || ' sifariş)',
    jsonb_build_object('table_number', p_table_number, 'cancelled_orders', v_reversed),
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_number', p_table_number,
    'orders_cancelled', v_reversed
  );
END;
$$;


--
-- Name: dismiss_table_state_aware(integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_table_state_aware(p_table_number integer, p_performed_by uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_item RECORD;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
  v_voided INT := 0;
  v_wasted INT := 0;
  v_paid_skipped INT := 0;
  v_order_ids uuid[] := ARRAY[]::uuid[];
BEGIN
  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  FOR v_order IN
    SELECT id, status FROM public.orders
    WHERE table_number = p_table_number
      AND status NOT IN ('paid', 'closed', 'refunded', 'cancelled')
    FOR UPDATE
  LOOP
    v_order_ids := array_append(v_order_ids, v_order.id);

    FOR v_item IN
      SELECT id, kitchen_status, quantity, product_name, unit_price, total_price
      FROM public.order_items WHERE order_id = v_order.id FOR UPDATE
    LOOP
      IF v_item.kitchen_status IS NULL OR v_item.kitchen_status IN ('pending', 'accepted', 'sent', 'preparing') THEN
        UPDATE public.order_items SET kitchen_status = 'voided', total_price = 0 WHERE id = v_item.id;
        v_voided := v_voided + 1;

      ELSIF v_item.kitchen_status IN ('ready', 'completed', 'served') THEN
        INSERT INTO public.cancelled_orders (order_id, reason, reason_text, items, created_at)
        VALUES (
          v_order.id, 'waste',
          COALESCE(p_reason, 'Dismiss — item was ' || v_item.kitchen_status),
          jsonb_build_array(jsonb_build_object(
            'order_item_id', v_item.id, 'product_name', v_item.product_name,
            'quantity', v_item.quantity, 'kitchen_status', v_item.kitchen_status,
            'unit_price', v_item.unit_price, 'reason', 'dismiss_waste'
          )),
          v_now
        );
        UPDATE public.order_items SET kitchen_status = 'voided', total_price = 0 WHERE id = v_item.id;
        v_wasted := v_wasted + 1;

      ELSIF v_item.kitchen_status = 'voided' THEN
        CONTINUE;
      END IF;
    END LOOP;

    UPDATE public.orders SET status = 'cancelled', kitchen_status = 'cancelled', cancelled_at = v_now WHERE id = v_order.id;
  END LOOP;

  FOR v_order IN
    SELECT id FROM public.orders WHERE table_number = p_table_number AND status = 'paid'
  LOOP
    v_paid_skipped := v_paid_skipped + 1;
  END LOOP;

  IF p_table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      status = 'empty', guest_count = NULL, reservation_id = NULL,
      reservation_name = NULL, reservation_phone = NULL, reservation_time = NULL,
      merged_into_table = NULL
    WHERE table_number = p_table_number;
  END IF;

  PERFORM public.log_audit(
    'dismiss_table', 'table', p_table_number::text,
    p_performed_by, v_performer_name, NULL,
    jsonb_build_object(
      'voided_items', v_voided, 'wasted_items', v_wasted,
      'paid_skipped', v_paid_skipped, 'order_ids', to_jsonb(v_order_ids)
    ),
    jsonb_build_object('table_number', p_table_number), NULL
  );

  RETURN jsonb_build_object(
    'success', true, 'action', 'dismiss',
    'voided_items', v_voided, 'wasted_items', v_wasted,
    'paid_orders_skipped', v_paid_skipped,
    'table_number', p_table_number, 'timestamp', v_now
  );
END;
$$;


--
-- Name: dismiss_table_v3(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_table_v3(p_table_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Mark all active orders as cancelled
  UPDATE orders SET status = 'cancelled', updated_at = now() 
  WHERE table_number = p_table_number AND status NOT IN ('paid', 'cancelled', 'closed');

  -- Also handle merged tables
  UPDATE orders SET status = 'cancelled', updated_at = now()
  WHERE id IN (
    SELECT id FROM orders o 
    JOIN table_floors tf ON o.table_number = tf.table_number 
    WHERE tf.merged_into_table = p_table_number
  );

  -- Reset all related table floors
  UPDATE table_floors SET 
    status = 'empty', 
    guest_count = NULL, 
    total_amount = 0, 
    merged_into_table = NULL,
    reservation_id = NULL
  WHERE table_number = p_table_number OR merged_into_table = p_table_number;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: dismiss_undo_atomic(text, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dismiss_undo_atomic(p_token text, p_table_number integer, p_performed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_caller_role text;
  v_loc uuid;
  v_cancelled_orders RECORD;
  v_order_ids UUID[];
  v_item RECORD;
  v_restored_count INTEGER := 0;
BEGIN
  -- F-01/F-02: token identity + manager tier (was: effective_admin_role +
  -- auth.role(), which is unreliable inside SECURITY DEFINER service-role calls)
  PERFORM public.set_session_staff(p_token);
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;
  SELECT public.effective_admin_role() INTO v_caller_role;

  -- F-02: location isolation (the table must be in the actor's accessible locations)
  SELECT location_id INTO v_loc FROM public.table_floors WHERE table_number = p_table_number AND (v_sess_loc IS NULL OR location_id = v_sess_loc);
  IF FOUND AND NOT has_location_access(v_loc) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;

  -- Find the most recent cancelled orders on this table (from the dismiss action)
  FOR v_cancelled_orders IN
    SELECT id, table_number, status, total_amount, guest_count, reservation_id,
           customer_name, customer_phone, kitchen_status, created_at, version
    FROM orders
    WHERE table_number = p_table_number
      AND status = 'cancelled'
      AND updated_at >= now() - interval '1 hour'
    ORDER BY updated_at DESC
    FOR UPDATE
  LOOP
    v_order_ids := array_append(v_order_ids, v_cancelled_orders.id);
  END LOOP;

  IF array_length(v_order_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No recent cancelled orders found to undo');
  END IF;

  -- Restore orders to their previous status (new/confirmed)
  UPDATE orders
  SET status = CASE WHEN kitchen_status = 'cancelled' THEN 'new' ELSE 'confirmed' END,
      kitchen_status = CASE WHEN kitchen_status = 'cancelled' THEN 'pending' ELSE kitchen_status END,
      cancelled_at = NULL,
      updated_at = now(),
      version = COALESCE(version, 0) + 1
  WHERE id = ANY(v_order_ids);

  -- Restore order items
  UPDATE order_items
  SET kitchen_status = 'pending'
  WHERE order_id = ANY(v_order_ids)
    AND kitchen_status = 'cancelled';

  -- Restore table state
  UPDATE table_floors
  SET
    status = 'occupied',
    guest_count = COALESCE((SELECT guest_count FROM orders WHERE id = v_order_ids[1]), 1),
    reservation_id = (SELECT reservation_id FROM orders WHERE id = v_order_ids[1]),
    reservation_name = (SELECT customer_name FROM orders WHERE id = v_order_ids[1]),
    reservation_phone = (SELECT customer_phone FROM orders WHERE id = v_order_ids[1]),
    current_order_id = v_order_ids[1],
    updated_at = now()
  WHERE table_number = p_table_number;

  -- Restore stock deductions
  FOR v_item IN
    SELECT oi.id, oi.product_id, oi.quantity, r.ingredient_id, r.quantity AS recipe_qty
    FROM order_items oi
    JOIN recipe_items r ON r.product_id = oi.product_id
    WHERE oi.order_id = ANY(v_order_ids)
  LOOP
    INSERT INTO inventory_logs (ingredient_id, quantity, type, unit_cost, reference_type, reference_id, created_at)
    VALUES (
      v_item.ingredient_id,
      v_item.recipe_qty * v_item.quantity,
      'stock_out'::inventory_log_type,
      0,
      'order',
      v_item.id,
      now()
    );
    v_restored_count := v_restored_count + 1;
  END LOOP;

  -- Audit
  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'orders',
    v_order_ids[1],
    'dismiss_undo',
    jsonb_build_object('table_number', p_table_number, 'order_ids', v_order_ids, 'status', 'cancelled'),
    jsonb_build_object('status', 'restored', 'restored_items', v_restored_count),
    p_performed_by,
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'restored_orders', array_length(v_order_ids, 1),
    'restored_items', v_restored_count
  );
END;
$$;


--
-- Name: dispute_reconciliation(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.dispute_reconciliation(p_reconciliation_id uuid, p_reason text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE cash_reconciliations
  SET status = 'disputed', notes = COALESCE(notes || E'\n' || p_reason, p_reason)
  WHERE id = p_reconciliation_id;

  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: distribute_tips(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.distribute_tips(p_pool_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool RECORD;
  v_rule RECORD;
  v_staff RECORD;
  v_total_hours DECIMAL;
  v_distribution_amount DECIMAL;
BEGIN
  SELECT * INTO v_pool FROM tip_pools WHERE id = p_pool_id;

  IF v_pool.status = 'distributed' THEN
    RETURN json_build_object('success', false, 'error', 'Tips already distributed');
  END IF;

  -- Get total hours worked for the day
  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600), 0) INTO v_total_hours
  FROM shifts
  WHERE DATE(opened_at) = v_pool.pool_date
  AND closed_at IS NOT NULL;

  -- Distribute based on rules
  FOR v_rule IN SELECT * FROM tip_distribution_rules WHERE is_active = true
  LOOP
    FOR v_staff IN
      SELECT s.staff_id, SUM(EXTRACT(EPOCH FROM (s.closed_at - s.opened_at)) / 3600) as hours
      FROM shifts s
      JOIN staff st ON st.id = s.staff_id
      WHERE DATE(s.opened_at) = v_pool.pool_date
      AND s.closed_at IS NOT NULL
      AND st.role_id = v_rule.role_id
      GROUP BY s.staff_id
    LOOP
      IF v_total_hours > 0 THEN
        v_distribution_amount := (v_staff.hours / v_total_hours) * v_pool.total_amount * (v_rule.percentage / 100);

        INSERT INTO tip_distributions (pool_id, staff_id, role_id, percentage, amount, hours_worked, points)
        VALUES (p_pool_id, v_staff.staff_id, v_rule.role_id, v_rule.percentage, v_distribution_amount, v_staff.hours, v_staff.hours * v_rule.percentage);
      END IF;
    END LOOP;
  END LOOP;

  UPDATE tip_pools SET status = 'distributed', distributed_at = NOW() WHERE id = p_pool_id;

  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: edit_item_atomic(text, uuid, integer, text, integer, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.edit_item_atomic(p_token text, p_item_id uuid, p_quantity integer DEFAULT NULL::integer, p_course text DEFAULT NULL::text, p_seat_number integer DEFAULT NULL::integer, p_special_notes text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_item RECORD;
  v_order RECORD;
  v_allowed jsonb;
  v_old_total numeric;
  v_new_total numeric;
  v_now timestamptz := now();
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  SELECT * INTO v_item FROM order_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE = 'P0001'; END IF;

  SELECT * INTO v_order FROM orders WHERE id = v_item.order_id FOR UPDATE;
  IF v_order.status IN ('paid','closed','cancelled') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED' USING ERRCODE = 'P0001';
  END IF;

  v_allowed := authorize(p_token, 'orders.edit', v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: orders.edit at % (reason: %)',
      v_order.location_id, v_allowed->>'reason' USING ERRCODE = 'P0001';
  END IF;

  -- edit rules by state
  IF v_item.kitchen_status IN ('voided','cancelled','comped','wasted','recalled') THEN
    RAISE EXCEPTION 'ITEM_EDIT_FROZEN: item is terminal (%) — use void+re-add', v_item.kitchen_status USING ERRCODE='P0001';
  END IF;

  IF p_quantity IS NOT NULL THEN
    IF p_quantity <= 0 THEN
      RAISE EXCEPTION 'INVALID_QTY: quantity must be > 0' USING ERRCODE = 'P0001';
    END IF;
    IF v_item.kitchen_status IN ('sent','accepted') AND p_quantity > v_item.quantity THEN
      RAISE EXCEPTION 'ITEM_QTY_FROZEN: item sent to kitchen — quantity can only be reduced (was %)', v_item.quantity USING ERRCODE='P0001';
    END IF;
    IF v_item.kitchen_status IN ('preparing','ready','served','completed','hot','bar','sushi') THEN
      RAISE EXCEPTION 'ITEM_QTY_FROZEN: in production (%) — correction via void+re-add', v_item.kitchen_status USING ERRCODE='P0001';
    END IF;
  END IF;

  v_old_total := COALESCE(v_item.total_price, v_item.unit_price * v_item.quantity);
  v_new_total := v_old_total;

  UPDATE order_items SET
    quantity    = COALESCE(p_quantity, quantity),
    total_price = CASE WHEN p_quantity IS NOT NULL THEN unit_price * p_quantity ELSE total_price END,
    course      = COALESCE(p_course, course),
    seat_number = COALESCE(p_seat_number, seat_number),
    special_notes = COALESCE(p_special_notes, special_notes),
    updated_at  = v_now
  WHERE id = p_item_id
  RETURNING total_price INTO v_new_total;

  IF v_new_total IS DISTINCT FROM v_old_total THEN
    UPDATE orders SET
      total_amount = GREATEST(0, COALESCE(total_amount, 0) + (v_new_total - v_old_total)),
      version = COALESCE(version, 0) + 1,
      updated_at = v_now
    WHERE id = v_order.id;
  END IF;

  PERFORM log_order_event(v_order.id,
    CASE WHEN p_quantity IS NOT NULL AND p_quantity <> v_item.quantity
         THEN 'quantity_changed' ELSE 'item_modified' END,
    jsonb_build_object('old_qty', v_item.quantity, 'old_total', v_old_total),
    jsonb_build_object('new_qty', COALESCE(p_quantity, v_item.quantity), 'new_total', v_new_total),
    jsonb_build_object('reason', p_reason),
    v_staff_id, NULL, NULL, NULL);

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', p_item_id, 'order_item.edited',
    jsonb_build_object('order_id', v_order.id, 'old_total', v_old_total,
      'new_total', v_new_total, 'performed_by', v_staff_id, 'reason', p_reason), 'pending');

  RETURN jsonb_build_object('success', true, 'order_item_id', p_item_id,
    'quantity', COALESCE(p_quantity, v_item.quantity), 'total_price', v_new_total);
END;
$$;


--
-- Name: emit_kds_ticket_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_kds_ticket_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_prev    TEXT;
  v_loc     uuid;
  v_org     uuid;
  v_tn      integer;
  v_src     text;
  v_ostatus text;
BEGIN
  v_prev := CASE WHEN TG_OP = 'UPDATE' THEN OLD.kitchen_status ELSE NULL END;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;

  -- kitchen-relevant transitions only (unchanged gating)
  IF NEW.kitchen_status IS DISTINCT FROM v_prev OR TG_OP = 'INSERT' THEN
    -- resolve the owning order's scope ONCE (location/station scoping at the
    -- event layer; a consumer must not be left to filter client-side)
    SELECT o.location_id, o.organization_id, o.table_number, o.order_source, o.status
      INTO v_loc, v_org, v_tn, v_src, v_ostatus
      FROM orders o
     WHERE o.id = NEW.order_id;

    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
    VALUES ('kds_ticket', NEW.id, 'kds.ticket.upsert',
      jsonb_build_object('order_id', NEW.order_id, 'item_id', NEW.id,
        'product_id', NEW.product_id, 'product_name', NEW.product_name,
        'quantity', NEW.quantity, 'course', NEW.course, 'seat_number', NEW.seat_number,
        'station_id', NEW.station_id, 'station', NEW.station,
        'item_status', NEW.kitchen_status, 'previous_status', v_prev,
        'is_terminal', NEW.kitchen_status IN ('voided','cancelled','comped','wasted','recalled'),
        'location_id', v_loc, 'organization_id', v_org,
        'table_number', v_tn, 'order_source', v_src, 'order_status', v_ostatus,
        'updated_at', now()),
      'pending');
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: emit_location_lifecycle_event(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_location_lifecycle_event() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_event TEXT;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_event := 'location.created';
  ELSIF TG_OP = 'DELETE' THEN
    v_event := 'location.deactivated';
    RETURN OLD;
  ELSE
    IF OLD.status IS DISTINCT FROM NEW.status THEN
      v_event := lower('location.' || NEW.status);
    ELSIF OLD.name IS DISTINCT FROM NEW.name OR OLD.code IS DISTINCT FROM NEW.code THEN
      v_event := 'location.updated';
    ELSE
      RETURN NEW;
    END IF;
  END IF;

  PERFORM emit_outbox_event(
    'location',
    COALESCE(NEW.id, OLD.id),
    v_event,
    jsonb_build_object(
      'name', COALESCE(NEW.name, OLD.name),
      'code', COALESCE(NEW.code, OLD.code),
      'status', COALESCE(NEW.status, OLD.status)
    ),
    jsonb_build_object('organization_id', COALESCE(NEW.organization_id, OLD.organization_id))
  );
  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: emit_outbox_event(text, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.emit_outbox_event(p_aggregate_type text, p_aggregate_id uuid, p_event_type text, p_payload jsonb DEFAULT '{}'::jsonb, p_metadata jsonb DEFAULT '{}'::jsonb) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, metadata)
  VALUES (p_aggregate_type, p_aggregate_id, p_event_type, p_payload, p_metadata)
  RETURNING id INTO v_id;
  RETURN v_id;
END;
$$;


