--
-- Name: end_break_token(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.end_break_token(p_token text, p_target_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_override boolean;
  v_shift RECORD;
  v_break RECORD;
  v_duration INTEGER;
BEGIN
  PERFORM set_session_staff(p_token);
  v_actor := current_staff_id();
  v_override := (p_target_id IS DISTINCT FROM v_actor)
                AND coalesce(has_permission(v_actor, 'timeclock.override'), false);
  IF p_target_id IS DISTINCT FROM v_actor AND NOT v_override THEN
    INSERT INTO security_events (staff_id, event_type, success, metadata)
    VALUES (v_actor, 'permission_denied', false,
      jsonb_build_object('action', 'end_break', 'target', p_target_id));
    RETURN json_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  SELECT * INTO v_shift FROM shifts
  WHERE staff_id = p_target_id AND closed_at IS NULL
  ORDER BY opened_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'No active shift');
  END IF;

  SELECT * INTO v_break FROM shift_breaks
  WHERE shift_id = v_shift.id AND ended_at IS NULL;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'No active break');
  END IF;

  UPDATE shift_breaks SET ended_at = NOW() WHERE id = v_break.id;
  v_duration := EXTRACT(EPOCH FROM (NOW() - v_break.started_at)) / 60;
  IF v_duration > 30 AND v_break.break_type = 'unpaid' THEN
    UPDATE shift_breaks SET is_compliant = false, violation_reason = 'Break exceeded 30 minutes'
    WHERE id = v_break.id;
  END IF;

  INSERT INTO time_clock_entries (staff_id, entry_type, source, timestamp)
  VALUES (p_target_id, 'break_end', 'pos_terminal', NOW());

  INSERT INTO time_clock_audit (action, performed_by, details)
  VALUES ('break_end', p_target_id, jsonb_build_object('duration_minutes', v_duration, 'actor', v_actor, 'override', v_override));

  RETURN json_build_object('success', true, 'duration_minutes', v_duration, 'override', v_override, 'ended_at', NOW());
END;
$$;


--
-- Name: enforce_cash_drawer_staff_org(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_cash_drawer_staff_org() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    st_org uuid;
BEGIN
    IF NEW.opened_by IS NOT NULL THEN
        SELECT organization_id INTO st_org FROM staff WHERE id = NEW.opened_by;
        IF FOUND AND st_org IS DISTINCT FROM NEW.organization_id THEN
            RAISE EXCEPTION 'Cash drawer opener must belong to same organization (staff org=% drawer org=%)', st_org, NEW.organization_id;
        END IF;
    END IF;
    IF NEW.closed_by IS NOT NULL THEN
        SELECT organization_id INTO st_org FROM staff WHERE id = NEW.closed_by;
        IF FOUND AND st_org IS DISTINCT FROM NEW.organization_id THEN
            RAISE EXCEPTION 'Cash drawer closer must belong to same organization (staff org=% drawer org=%)', st_org, NEW.organization_id;
        END IF;
    END IF;
    IF NEW.approved_by IS NOT NULL THEN
        SELECT organization_id INTO st_org FROM staff WHERE id = NEW.approved_by;
        IF FOUND AND st_org IS DISTINCT FROM NEW.organization_id THEN
            RAISE EXCEPTION 'Cash drawer approver must belong to same organization (staff org=% drawer org=%)', st_org, NEW.organization_id;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: enforce_inventory_log_order_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_inventory_log_order_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    ord_rec RECORD;
BEGIN
    IF NEW.order_id IS NULL THEN
        RETURN NEW;
    END IF;
    SELECT location_id, organization_id INTO ord_rec FROM orders WHERE id = NEW.order_id;
    IF NOT FOUND THEN
        RETURN NEW;
    END IF;
    IF NEW.location_id IS DISTINCT FROM ord_rec.location_id
       OR NEW.organization_id IS DISTINCT FROM ord_rec.organization_id THEN
        RAISE EXCEPTION 'Inventory log must belong to same location/organization as its order (log loc=% org=%, order loc=% org=%)',
            NEW.location_id, NEW.organization_id, ord_rec.location_id, ord_rec.organization_id;
    END IF;
    RETURN NEW;
END;
$$;


