--
-- Name: enforce_payment_record_on_paid(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_payment_record_on_paid() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- P-5 D-1c (ratified 2026-09-13): the financial invariant lives in the DB,
  -- not in one RPC. An order may enter 'paid' only when a non-refund CAPTURED
  -- order_payments row already exists in the same transaction (the payment
  -- RPCs INSERT the row BEFORE they UPDATE the order).
  IF NOT EXISTS (SELECT 1 FROM public.order_payments p
                 WHERE p.order_id = NEW.id
                   AND p.status = 'captured'
                   AND NOT p.is_refund) THEN
    RAISE EXCEPTION 'PAID_WITHOUT_RECORD: order % entered paid with no captured order_payments row; payment state can only be set by complete_payment_atomic_v2 / refund_with_inventory', NEW.id USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: enforce_reservation_table_location(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.enforce_reservation_table_location() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    t RECORD;
    mismatch boolean := false;
BEGIN
    IF NEW.table_ids IS NULL OR cardinality(NEW.table_ids) = 0 THEN
        RETURN NEW;
    END IF;
    FOR t IN
        SELECT tf.table_number, tf.location_id, tf.organization_id
        FROM table_floors tf
        WHERE tf.table_number = ANY (NEW.table_ids)
    LOOP
        IF t.location_id IS DISTINCT FROM NEW.location_id
           OR t.organization_id IS DISTINCT FROM NEW.organization_id THEN
            mismatch := true;
            EXIT;
        END IF;
    END LOOP;
    IF mismatch THEN
        RAISE EXCEPTION 'Reservation tables must belong to the same location/organization as the reservation (Allowed: location=% org=%)', NEW.location_id, NEW.organization_id;
    END IF;
    RETURN NEW;
END;
$$;


