END;
$$;


--
-- Name: ensure_manager_override(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ensure_manager_override(p_staff_id uuid, p_permission text, p_location_id uuid, p_from text, p_to text) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_approver_key text;
  v_has boolean := false;
  v_over boolean := false;
BEGIN
  v_approver_key := CASE WHEN p_permission LIKE '%refund%' THEN 'refund.approve' ELSE 'void.approve' END;
  SELECT COALESCE(has_permission(p_staff_id, v_approver_key), false) INTO v_has;
  IF NOT v_has THEN
    SELECT EXISTS(
      SELECT 1 FROM manager_overrides mo
      WHERE mo.requested_by = p_staff_id
        AND mo.permission = p_permission
        AND mo.location_id = p_location_id
        AND mo.status = 'APPROVED'
        AND mo.expires_at > now()
    ) INTO v_over;
    IF NOT v_over THEN
      RAISE EXCEPTION 'MANAGER_OVERRIDE_REQUIRED: % → % (approver perm [%])',
        p_from, p_to, v_approver_key USING ERRCODE = 'P0001';
    END IF;
  END IF;
END;
$$;


--
-- Name: fire_course_atomic(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fire_course_atomic(p_order_id uuid, p_course text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated INTEGER := 0;
BEGIN
  UPDATE order_items
  SET kitchen_status = 'preparing'
  WHERE order_id = p_order_id
    AND (course = p_course OR (course IS NULL AND p_course = 'main'))
    AND kitchen_status IN ('pending', 'accepted');

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'updated_items', v_updated);
END;
$$;


--
-- Name: fn_record_cash_payment(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.fn_record_cash_payment() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session_id uuid;
  v_amount numeric;
BEGIN
  -- Yalnız nağd ödənişləri izlə
  IF NEW.payment_method != 'cash' THEN
    RETURN NEW;
  END IF;

  -- Aktiv kassa sessiyası tap
  SELECT id INTO v_session_id
  FROM cash_drawer_sessions
  WHERE status = 'open'
  ORDER BY opened_at DESC
  LIMIT 1;

  IF v_session_id IS NULL THEN
    RETURN NEW;
  END IF;

  v_amount := COALESCE(NEW.paid_amount, 0) - COALESCE(NEW.tip_amount, 0);

  IF v_amount <= 0 THEN
    RETURN NEW;
  END IF;

  INSERT INTO cash_drawer_log (session_id, type, amount, description, order_id)
  VALUES (v_session_id, 'payment', v_amount, 'Nağd ödəniş', NEW.id);

  RETURN NEW;
END;
$$;


--
-- Name: force_clock_out(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.force_clock_out(p_staff_id uuid, p_reason text DEFAULT 'Forced by admin'::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_shift shifts%ROWTYPE;
  v_duration interval;
BEGIN
  -- Find active shift
  SELECT * INTO v_shift
  FROM shifts
  WHERE staff_id = p_staff_id AND closed_at IS NULL
  ORDER BY opened_at DESC
  LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_ACTIVE_SHIFT');
  END IF;

  v_duration := now() - v_shift.opened_at;

  -- Close the shift
  UPDATE shifts SET
    closed_at = now(),
    notes = COALESCE(notes, '') || ' | Force closed: ' || p_reason,
    updated_at = now()
  WHERE id = v_shift.id;

  -- End any active break
  UPDATE shift_breaks SET
    ended_at = now()
  WHERE shift_id = v_shift.id AND ended_at IS NULL;

  -- Close cash drawer session
  UPDATE cash_drawer_sessions SET
    closed_at = now(),
    status = 'force_closed'
  WHERE opened_by = p_staff_id AND closed_at IS NULL;

  -- Audit
  PERFORM log_audit(
    'force_clock_out', 'shifts', v_shift.id::text, p_performed_by,
    jsonb_build_object('opened_at', v_shift.opened_at, 'duration', v_duration),
    jsonb_build_object('reason', p_reason, 'forced_at', now()),
    NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'shift_id', v_shift.id,
    'duration_minutes', EXTRACT(EPOCH FROM v_duration) / 60,
    'reason', p_reason
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: force_logout_staff(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.force_logout_staff(p_staff_id uuid, p_performed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_count integer;
BEGIN
  UPDATE sessions SET status='REVOKED', revoked_at = now()
  WHERE user_id = p_staff_id AND status='ACTIVE';
  GET DIAGNOSTICS v_count = ROW_COUNT;
  PERFORM public.log_audit(
    'force_logout', 'staff', p_staff_id::text, p_performed_by, NULL,
    NULL, NULL, jsonb_build_object('sessions_revoked', v_count), NULL
  );
  RETURN jsonb_build_object('success', true, 'staff_id', p_staff_id, 'sessions_revoked', v_count);
END;
$$;


--
-- Name: g_table_audit(text, text, integer, uuid, uuid, jsonb, jsonb, uuid, text, text, integer, integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.g_table_audit(p_op text, p_event text, p_table_number integer, p_table_id uuid, p_order_id uuid, p_old jsonb, p_new jsonb, p_actor uuid, p_terminal text, p_reason text, p_source integer, p_target integer, p_loc uuid, p_org uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_corr uuid := gen_random_uuid();
BEGIN
  INSERT INTO public.operation_logs
    (operation, order_id, source_table_number, target_table_number,
     old_state, new_state, performed_by, reason,
     location_id, organization_id, correlation_id, created_at)
  VALUES
    (p_op, p_order_id, p_source, p_target,
     COALESCE(p_old, '{}'::jsonb), COALESCE(p_new, '{}'::jsonb), p_actor, p_reason,
     p_loc, p_org, v_corr, now());

  IF p_event IS NOT NULL THEN
    INSERT INTO public.outbox_events (aggregate_type, aggregate_id, event_type, payload, status, metadata)
    VALUES ('table', p_table_id, p_event,
      jsonb_build_object(
        'table_number',            p_table_number,
        'order_id',                p_order_id,
        'old_state',               p_old,
        'new_state',               p_new,
        'source_table_number',     p_source,
        'target_table_number',     p_target,
        'location_id',             p_loc,
        'organization_id',         p_org,
        'performed_by',            p_actor,
        'terminal_id',             p_terminal,
        'reason',                  p_reason,
        'correlation_id',          v_corr),
      'pending',
      jsonb_build_object('operation', p_op, 'terminal_id', p_terminal, 'correlation_id', v_corr));
  END IF;
END;
$$;


--
-- Name: generate_delivery_order_number(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.generate_delivery_order_number() RETURNS text
