--
-- Name: get_active_breaks(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_breaks() RETURNS TABLE(break_id uuid, staff_id uuid, staff_name text, break_type character varying, started_at timestamp with time zone, duration_minutes integer, shift_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    sb.id,
    s.staff_id,
    st.full_name,
    sb.break_type,
    sb.started_at,
    EXTRACT(EPOCH FROM (NOW() - sb.started_at)) / 60,
    sb.shift_id
  FROM shift_breaks sb
  JOIN shifts s ON s.id = sb.shift_id
  JOIN staff st ON st.id = s.staff_id
  WHERE sb.ended_at IS NULL
  AND s.closed_at IS NULL
  ORDER BY sb.started_at;
END;
$$;


--
-- Name: get_active_couriers(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_active_couriers() RETURNS TABLE(id uuid, name text, phone text, vehicle_type text, current_order_id uuid, total_deliveries integer, rating numeric, last_location_lat numeric, last_location_lng numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT c.id, c.name, c.phone, c.vehicle_type, c.current_order_id,
         c.total_deliveries, c.rating, c.last_location_lat, c.last_location_lng
  FROM couriers c
  WHERE c.is_active = true
  ORDER BY c.current_order_id NULLS FIRST, c.total_deliveries DESC;
END;
$$;


--
-- Name: get_best_cart_campaign(jsonb, uuid, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_best_cart_campaign(p_cart_items jsonb, p_customer_id uuid DEFAULT NULL::uuid, p_order_amount numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_campaign RECORD;
  v_best_campaign_id UUID := NULL;
  v_best_discount NUMERIC := 0;
  v_calc_result JSONB;
  v_now DATE := CURRENT_DATE;
  v_now_time TEXT := TO_CHAR(NOW(), 'HH24:MI');
BEGIN
  FOR v_campaign IN
    SELECT * FROM campaigns
    WHERE status = 'active'
      AND (start_date IS NULL OR start_date <= v_now)
      AND (end_date IS NULL OR end_date >= v_now)
      AND (start_time IS NULL OR start_time <= v_now_time)
      AND (end_time IS NULL OR end_time >= v_now_time)
    ORDER BY priority DESC, created_at DESC
  LOOP
    IF v_campaign.type IN ('PERCENTAGE', 'HAPPY_HOUR', 'FIXED_AMOUNT') THEN
      SELECT calculate_cart_campaign_discount(v_campaign.id, p_cart_items) INTO v_calc_result;
      IF (v_calc_result->>'discount_amount')::NUMERIC > v_best_discount THEN
        v_best_discount := (v_calc_result->>'discount_amount')::NUMERIC;
        v_best_campaign_id := v_campaign.id;
      END IF;
    ELSIF v_campaign.type IN ('BOGO', 'BUY2GET1') THEN
      SELECT calculate_cart_campaign_discount(v_campaign.id, p_cart_items) INTO v_calc_result;
      IF (v_calc_result->>'discount_amount')::NUMERIC > v_best_discount THEN
        v_best_discount := (v_calc_result->>'discount_amount')::NUMERIC;
        v_best_campaign_id := v_campaign.id;
      END IF;
    END IF;
  END LOOP;

  IF v_best_campaign_id IS NULL THEN
    RETURN jsonb_build_object('campaign_id', NULL, 'discount_amount', 0);
  END IF;

  RETURN jsonb_build_object('campaign_id', v_best_campaign_id, 'discount_amount', v_best_discount);
END;
$$;


--
-- Name: get_break_compliance(uuid, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_break_compliance(p_staff_id uuid, p_date date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total_minutes DECIMAL;
  v_required_breaks INTEGER;
  v_taken_breaks INTEGER;
  v_compliant BOOLEAN;
BEGIN
  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (ended_at - started_at)) / 60), 0),
         COUNT(*)
  INTO v_total_minutes, v_taken_breaks
  FROM shift_breaks sb
  JOIN shifts s ON s.id = sb.shift_id
  WHERE s.staff_id = p_staff_id
  AND DATE(sb.started_at) = p_date
  AND sb.ended_at IS NOT NULL;

  SELECT COUNT(*) INTO v_required_breaks
  FROM break_rules
  WHERE is_active = true
  AND work_duration_minutes <= v_total_minutes;

  v_compliant := v_taken_breaks >= v_required_breaks;

  RETURN json_build_object(
    'total_minutes', v_total_minutes,
    'required_breaks', v_required_breaks,
    'taken_breaks', v_taken_breaks,
    'compliant', v_compliant
  );
END;
$$;


