-- Name: get_customer_addresses(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_customer_addresses(p_customer_id uuid) RETURNS TABLE(id uuid, address_line text, address_line2 text, city text, district text, landmark text, delivery_notes text, lat numeric, lng numeric, is_default boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT ca.id, ca.address_line, ca.address_line2, ca.city, ca.district,
         ca.landmark, ca.delivery_notes, ca.lat, ca.lng, ca.is_default
