--
-- Name: get_expense_summary(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_expense_summary(p_start_date date DEFAULT (CURRENT_DATE - '30 days'::interval), p_end_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_total NUMERIC;
  v_by_category JSONB;
  v_daily JSONB;
BEGIN
  SELECT COALESCE(SUM(amount), 0) INTO v_total
  FROM expenses
  WHERE expense_date BETWEEN p_start_date AND p_end_date;

  SELECT COALESCE(jsonb_agg(row_to_json(c)), '[]'::JSONB) INTO v_by_category
  FROM (
    SELECT
      category,
      COUNT(*) AS count,
      COALESCE(SUM(amount), 0) AS total
    FROM expenses
    WHERE expense_date BETWEEN p_start_date AND p_end_date
    GROUP BY category
    ORDER BY total DESC
  ) c;

  SELECT COALESCE(jsonb_agg(row_to_json(d)), '[]'::JSONB) INTO v_daily
  FROM (
    SELECT
      expense_date AS date,
      COALESCE(SUM(amount), 0) AS total
    FROM expenses
    WHERE expense_date BETWEEN p_start_date AND p_end_date
    GROUP BY expense_date
    ORDER BY expense_date
  ) d;

  RETURN jsonb_build_object(
    'period', jsonb_build_object('start', p_start_date, 'end', p_end_date),
    'total', v_total,
    'by_category', v_by_category,
    'daily', v_daily
  );
END;
$$;


--
-- Name: get_handover_notes(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_handover_notes(p_shift_id uuid) RETURNS TABLE(note_id uuid, from_staff_name text, note_type character varying, priority character varying, content text, is_read boolean, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    shn.id,
    st.full_name,
    shn.note_type,
    shn.priority,
    shn.content,
    shn.is_read,
    shn.created_at
  FROM shift_handover_notes shn
  JOIN staff st ON st.id = shn.from_staff_id
  WHERE shn.shift_id = p_shift_id
  ORDER BY
    CASE shn.priority
      WHEN 'urgent' THEN 1
      WHEN 'high' THEN 2
      WHEN 'normal' THEN 3
      WHEN 'low' THEN 4
    END,
    shn.created_at DESC;
END;
$$;


