--
-- Name: get_ingredients(public.products, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_ingredients(product_row public.products, lang text) RETURNS text[]
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
    -- Return ingredients in requested language, fallback to 'az', then empty array
    RETURN COALESCE(
        (product_row.ingredients_i18n->>lang)::TEXT[],
        (product_row.ingredients_i18n->>'az')::TEXT[],
        product_row.ingredients,  -- Legacy fallback
        ARRAY[]::TEXT[]
    );
END;
$$;


--
-- Name: get_kitchen_queue(text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_kitchen_queue(p_station text, p_location_id uuid, p_organization_id uuid) RETURNS TABLE(order_id uuid, order_number text, table_number integer, order_source text, customer_name text, guest_count integer, is_rush boolean, created_at timestamp with time zone, order_age_seconds integer, item_id uuid, product_name text, quantity integer, modifiers jsonb, special_notes text, kitchen_status text, station text, is_hold boolean, course text, sent_to_kitchen_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    o.id, o.order_number, o.table_number, o.order_source, o.customer_name,
    o.guest_count, o.is_rush, o.created_at,
    EXTRACT(EPOCH FROM (now() - o.created_at))::INTEGER,
    oi.id, oi.product_name, oi.quantity, oi.modifiers, oi.special_notes,
    oi.kitchen_status::TEXT, COALESCE(oi.station,'all'), COALESCE(oi.is_hold,false),
    oi.course, oi.created_at
  FROM order_items oi
  JOIN orders o ON oi.order_id = o.id
  WHERE o.status NOT IN ('paid','closed','cancelled')
    AND oi.kitchen_status NOT IN ('completed','cancelled','served')
    AND o.location_id = p_location_id
    AND o.organization_id = p_organization_id
    AND (p_station IS NULL OR oi.station = p_station)
  ORDER BY o.is_rush DESC, o.created_at ASC, oi.created_at ASC;
END;
$$;


--
-- Name: get_kitchen_stats(integer, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_kitchen_stats(p_hours integer, p_location_id uuid, p_organization_id uuid) RETURNS TABLE(station text, total_items bigint, avg_prep_time_seconds numeric, items_ready bigint, items_delayed bigint, rush_count bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    COALESCE(oi.station,'all'),
    COUNT(*),
    ROUND(AVG(EXTRACT(EPOCH FROM (oi.served_at - oi.created_at))),0),
    COUNT(*) FILTER (WHERE oi.kitchen_status = 'ready'),
    COUNT(*) FILTER (WHERE oi.served_at IS NOT NULL AND EXTRACT(EPOCH FROM (oi.served_at - oi.created_at)) > 1200),
    COUNT(*) FILTER (WHERE o.is_rush = true)
  FROM order_items oi
  JOIN orders o ON oi.order_id = o.id
  WHERE oi.created_at >= now() - (p_hours || ' hours')::INTERVAL
    AND oi.kitchen_status NOT IN ('cancelled')
    AND o.location_id = p_location_id
    AND o.organization_id = p_organization_id
  GROUP BY COALESCE(oi.station,'all')
  ORDER BY total_items DESC;
END;
$$;


--
-- Name: get_live_shifts(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_live_shifts() RETURNS TABLE(staff_id uuid, staff_name text, role_name text, shift_id uuid, opened_at timestamp with time zone, starting_cash numeric)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id AS staff_id,
    s.name AS staff_name,
    r.name AS role_name,
    sh.id AS shift_id,
    sh.opened_at,
    sh.starting_cash
  FROM shifts sh
  JOIN staff s ON s.id = sh.staff_id
  LEFT JOIN roles r ON r.id = s.role_id
  WHERE sh.closed_at IS NULL
  ORDER BY sh.opened_at DESC;
END;
$$;


--
-- Name: get_location_context(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_location_context(p_token text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid;
    v_org_id uuid;
    v_loc_id uuid;
    v_loc RECORD;
    v_result jsonb;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    v_org_id := current_org_id();

    -- Read active_location_id from session
    SELECT sess.active_location_id INTO v_loc_id
    FROM sessions sess WHERE sess.token = p_token AND sess.expires_at > now() AND sess.revoked_at IS NULL;

    IF v_loc_id IS NOT NULL THEN
        SELECT * INTO v_loc FROM locations WHERE id = v_loc_id;
    END IF;

    v_result := jsonb_build_object(
        'staff_id', v_staff_id,
        'organization_id', v_org_id,
        'active_location_id', v_loc_id,
        'active_location_name', CASE WHEN v_loc IS NOT NULL THEN v_loc.name ELSE NULL END,
        'accessible_locations', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object(
                'id', l.id, 'name', l.name, 'code', l.code, 'slug', l.slug,
                'status', l.status, 'is_primary', sl.is_primary
            ) ORDER BY sl.is_primary DESC, l.name), '[]'::jsonb)
            FROM staff_locations sl
            JOIN locations l ON l.id = sl.location_id
            WHERE sl.staff_id = v_staff_id AND sl.active = true AND l.organization_id = v_org_id
        )
    );

    RETURN v_result;
END;
$$;


