CREATE FUNCTION public.get_messages(p_staff_id uuid, p_limit integer DEFAULT 50) RETURNS TABLE(message_id uuid, from_staff_name text, subject text, content text, message_type character varying, is_read boolean, created_at timestamp with time zone)
