--
-- Name: get_next_order_number(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_next_order_number(p_order_type text) RETURNS text
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_today DATE := CURRENT_DATE;
  v_next INTEGER;
BEGIN
  INSERT INTO public.order_counters (order_type, counter_date, last_number)
  VALUES (p_order_type, v_today, 1)
  ON CONFLICT (order_type, counter_date) DO UPDATE
    SET last_number = order_counters.last_number + 1
    RETURNING last_number INTO v_next;

  RETURN v_next::TEXT;
END;
$$;


--
-- Name: get_onboarding_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_onboarding_status(p_staff_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_workflow RECORD;
  v_total_tasks INTEGER;
  v_completed_tasks INTEGER;
BEGIN
  SELECT * INTO v_workflow FROM onboarding_workflows WHERE staff_id = p_staff_id ORDER BY created_at DESC LIMIT 1;

  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'No onboarding found');
  END IF;

  SELECT COUNT(*), COUNT(*) FILTER (WHERE is_completed = true)
  INTO v_total_tasks, v_completed_tasks
  FROM onboarding_tasks
  WHERE workflow_id = v_workflow.id;

  RETURN json_build_object(
    'workflow_id', v_workflow.id,
    'status', v_workflow.status,
    'total_tasks', v_total_tasks,
    'completed_tasks', v_completed_tasks,
    'progress', CASE WHEN v_total_tasks > 0 THEN (v_completed_tasks::DECIMAL / v_total_tasks * 100) ELSE 0 END
  );
END;
$$;


--
-- Name: get_overtime_summary(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_overtime_summary(p_staff_id uuid, p_start_date date DEFAULT (CURRENT_DATE - '7 days'::interval), p_end_date date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE sql STABLE
    SET search_path TO 'public'
    AS $$
  SELECT json_build_object(
    'daily_overtime',   COALESCE(SUM(CASE WHEN overtime_type='daily'  THEN hours ELSE 0 END),0),
    'weekly_overtime',  COALESCE(SUM(CASE WHEN overtime_type='weekly' THEN hours ELSE 0 END),0),
    'double_overtime',  COALESCE(SUM(CASE WHEN overtime_type='double' THEN hours ELSE 0 END),0),
    'total_overtime',   COALESCE(SUM(hours),0),
    'total_amount',     COALESCE(SUM(calculated_amount),0)
  )
  FROM overtime_records
  WHERE staff_id = p_staff_id
    AND business_date BETWEEN p_start_date AND p_end_date;
$$;


--
-- Name: get_payroll_export(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_payroll_export(p_period_start date, p_period_end date) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result JSON;
  entries JSON;
BEGIN
  SELECT json_agg(
    json_build_object(
      'staff_id', s.id,
      'staff_name', s.name,
      'role_name', COALESCE(r.name, '—'),
      'period_start', p_period_start,
      'period_end', p_period_end,
      'hours_worked', 0,
      'hourly_rate', COALESCE(s.hourly_rate, 0),
      'overtime_hours', 0,
      'overtime_rate', COALESCE(s.overtime_rate, 0),
      'tips_earned', 0,
      'tip_shortfall', 0,
      'gross_pay', 0,
      'deductions', 0,
      'net_pay', 0
    )
  ) INTO entries
  FROM staff s
  LEFT JOIN roles r ON r.id = s.role_id
  WHERE s.is_active = true;

  result := json_build_object('entries', COALESCE(entries, '[]'::json));
  RETURN result;
END;
$$;


