--
-- Name: get_role_specific_metrics(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_role_specific_metrics(p_staff_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role text;
  v_result jsonb;
  v_active_tickets bigint;
  v_completed_tickets bigint;
  v_avg_prep_time interval;
  v_late_tickets bigint;
  v_cancelled_tickets bigint;
  v_active_tables bigint;
  v_tables_served bigint;
  v_guests_served bigint;
  v_avg_turnaround interval;
  v_total_tips numeric;
  v_avg_ticket_size numeric;
  v_cash_sales numeric;
  v_card_sales numeric;
  v_voids_count bigint;
  v_discounts_amount numeric;
  v_refunds_amount numeric;
  v_drawer_variance numeric;
  v_orders_count bigint;
  v_avg_order_value numeric;
  v_total_sales numeric;
  v_open_checks bigint;
  v_items_prepared bigint;
  v_current_queue bigint;
BEGIN
  SELECT r.name INTO v_role
  FROM staff s
  JOIN roles r ON r.id = s.role_id
  WHERE s.id = p_staff_id;

  IF v_role IS NULL THEN
    RETURN '{}'::jsonb;
  END IF;

  CASE v_role
    WHEN 'kitchen', 'chef', 'cook' THEN
      SELECT
        COUNT(*) FILTER (WHERE kt.status IN ('pending', 'preparing')),
        COUNT(*) FILTER (WHERE kt.status = 'completed'),
        (SELECT AVG(kt2.completed_at - kt2.created_at) FROM kitchen_tickets kt2 WHERE kt2.assigned_to = p_staff_id AND kt2.created_at::date = CURRENT_DATE AND kt2.status = 'completed'),
        COUNT(*) FILTER (WHERE kt.status = 'completed' AND (kt.completed_at - kt.created_at) > interval '15 minutes'),
        COUNT(*) FILTER (WHERE kt.status = 'cancelled'),
        COUNT(*) FILTER (WHERE kt.status = 'pending')
      INTO v_active_tickets, v_completed_tickets, v_avg_prep_time, v_late_tickets, v_cancelled_tickets, v_current_queue
      FROM kitchen_tickets kt
      WHERE kt.assigned_to = p_staff_id
        AND kt.created_at::date = CURRENT_DATE;

      SELECT COUNT(*) INTO v_items_prepared
      FROM kitchen_ticket_items kti
      WHERE kti.ticket_id IN (
        SELECT kt2.id FROM kitchen_tickets kt2 WHERE kt2.assigned_to = p_staff_id AND kt2.created_at::date = CURRENT_DATE
      );

      v_result := jsonb_build_object(
        'role', v_role,
        'active_tickets', COALESCE(v_active_tickets, 0),
        'completed_tickets', COALESCE(v_completed_tickets, 0),
        'avg_prep_time_seconds', COALESCE(EXTRACT(EPOCH FROM v_avg_prep_time), 0),
        'late_tickets', COALESCE(v_late_tickets, 0),
        'cancelled_tickets', COALESCE(v_cancelled_tickets, 0),
        'current_queue', COALESCE(v_current_queue, 0),
        'items_prepared', COALESCE(v_items_prepared, 0)
      );

    WHEN 'waiter', 'server' THEN
      SELECT
        COUNT(*) FILTER (WHERE wa.status = 'occupied'),
        COUNT(*) FILTER (WHERE wa.status = 'completed'),
        COALESCE(SUM(wa.guest_count), 0),
        (SELECT AVG(wa2.completed_at - wa2.seated_at) FROM waiter_assignments wa2 WHERE wa2.waiter_id = p_staff_id AND wa2.created_at::date = CURRENT_DATE AND wa2.status = 'completed'),
        COALESCE(SUM(wa.tip_amount), 0),
        COALESCE(AVG(wa.total_amount), 0),
        COUNT(*) FILTER (WHERE wa.status = 'occupied')
      INTO v_active_tables, v_tables_served, v_guests_served, v_avg_turnaround, v_total_tips, v_avg_ticket_size, v_open_checks
      FROM waiter_assignments wa
      WHERE wa.waiter_id = p_staff_id
        AND wa.created_at::date = CURRENT_DATE;

      v_total_sales := COALESCE(v_avg_ticket_size * v_tables_served, 0);

      v_result := jsonb_build_object(
        'role', v_role,
        'active_tables', COALESCE(v_active_tables, 0),
        'tables_served', COALESCE(v_tables_served, 0),
        'guests_served', v_guests_served,
        'avg_turnaround_seconds', COALESCE(EXTRACT(EPOCH FROM v_avg_turnaround), 0),
        'total_tips', v_total_tips,
        'avg_ticket_size', v_avg_ticket_size,
        'total_sales', v_total_sales,
        'open_checks', COALESCE(v_open_checks, 0)
      );

    WHEN 'cashier', 'bartender' THEN
      SELECT
        COALESCE(SUM(o.cash_amount), 0),
        COALESCE(SUM(o.card_amount), 0),
        COALESCE(SUM(o.total_amount), 0),
        COUNT(*) FILTER (WHERE o.void_reason IS NOT NULL),
        COALESCE(SUM(o.discount_amount), 0),
        COALESCE(SUM(o.refund_amount), 0),
        COUNT(*),
        COALESCE(AVG(o.total_amount), 0)
      INTO v_cash_sales, v_card_sales, v_total_sales, v_voids_count, v_discounts_amount, v_refunds_amount, v_orders_count, v_avg_order_value
      FROM orders o
      WHERE o.created_by = p_staff_id
        AND o.created_at::date = CURRENT_DATE
        AND o.status IN ('confirmed', 'paid', 'completed');

      SELECT COALESCE(SUM(cds.difference), 0) INTO v_drawer_variance
      FROM cash_drawer_sessions cds
      WHERE cds.opened_by = p_staff_id AND cds.closed_at IS NOT NULL AND cds.created_at::date = CURRENT_DATE;

      v_result := jsonb_build_object(
        'role', v_role,
        'cash_sales', v_cash_sales,
        'card_sales', v_card_sales,
        'total_sales', v_total_sales,
        'voids_count', COALESCE(v_voids_count, 0),
        'discounts_amount', v_discounts_amount,
        'refunds_amount', v_refunds_amount,
        'drawer_variance', v_drawer_variance,
        'orders_count', COALESCE(v_orders_count, 0),
        'avg_order_value', v_avg_order_value
      );

    ELSE
      SELECT
        COUNT(*),
        COALESCE(SUM(o.total_amount), 0),
        COALESCE(AVG(o.total_amount), 0)
      INTO v_orders_count, v_total_sales, v_avg_order_value
      FROM orders o
      WHERE o.created_by = p_staff_id
        AND o.created_at::date = CURRENT_DATE
        AND o.status IN ('confirmed', 'paid', 'completed');

      v_result := jsonb_build_object(
        'role', v_role,
        'total_orders', COALESCE(v_orders_count, 0),
        'total_revenue', v_total_sales,
        'avg_order_value', v_avg_order_value
      );
  END CASE;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: get_sales_report(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_sales_report(p_start_date date DEFAULT CURRENT_DATE, p_end_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_daily JSONB;
  v_by_category JSONB;
  v_by_product JSONB;
  v_by_source JSONB;
BEGIN
  -- Daily breakdown
  SELECT COALESCE(jsonb_agg(row_to_json(d)), '[]'::JSONB) INTO v_daily
  FROM (
    SELECT
      DATE(o.paid_at) AS date,
      COUNT(*) AS orders,
      COALESCE(SUM(o.total_amount), 0) AS revenue,
      ROUND(AVG(o.total_amount), 2) AS aov,
      COUNT(*) FILTER (WHERE o.order_source = 'dine_in') AS dine_in_orders,
      COUNT(*) FILTER (WHERE o.order_source = 'takeaway') AS takeaway_orders,
      COUNT(*) FILTER (WHERE o.order_source = 'delivery') AS delivery_orders
    FROM orders o
    WHERE o.status = 'paid'
      AND DATE(o.paid_at) BETWEEN p_start_date AND p_end_date
    GROUP BY DATE(o.paid_at)
    ORDER BY DATE(o.paid_at)
  ) d;

  -- By category
  SELECT COALESCE(jsonb_agg(row_to_json(c)), '[]'::JSONB) INTO v_by_category
  FROM (
    SELECT
      cat.name AS category_name,
      COUNT(*) AS items_sold,
      COALESCE(SUM(oi.total_price), 0) AS revenue
    FROM order_items oi
    JOIN orders o ON oi.order_id = o.id
    JOIN products p ON oi.product_id = p.id
    JOIN categories cat ON p.category_id = cat.id
    WHERE o.status = 'paid'
      AND DATE(o.paid_at) BETWEEN p_start_date AND p_end_date
      AND oi.kitchen_status NOT IN ('cancelled')
    GROUP BY cat.name
    ORDER BY revenue DESC
  ) c;

  -- By product
  SELECT COALESCE(jsonb_agg(row_to_json(p)), '[]'::JSONB) INTO v_by_product
  FROM (
    SELECT
      oi.product_name,
      SUM(oi.quantity) AS quantity_sold,
      COALESCE(SUM(oi.total_price), 0) AS revenue,
      ROUND(AVG(oi.unit_price), 2) AS avg_price
    FROM order_items oi
    JOIN orders o ON oi.order_id = o.id
    WHERE o.status = 'paid'
      AND DATE(o.paid_at) BETWEEN p_start_date AND p_end_date
      AND oi.kitchen_status NOT IN ('cancelled')
    GROUP BY oi.product_name
    ORDER BY revenue DESC
    LIMIT 20
  ) p;

  -- By order source
  SELECT COALESCE(jsonb_agg(row_to_json(s)), '[]'::JSONB) INTO v_by_source
  FROM (
    SELECT
      o.order_source,
      COUNT(*) AS orders,
      COALESCE(SUM(o.total_amount), 0) AS revenue
    FROM orders o
    WHERE o.status = 'paid'
      AND DATE(o.paid_at) BETWEEN p_start_date AND p_end_date
    GROUP BY o.order_source
  ) s;

  RETURN jsonb_build_object(
    'period', jsonb_build_object('start', p_start_date, 'end', p_end_date),
    'daily', v_daily,
    'by_category', v_by_category,
    'by_product', v_by_product,
    'by_source', v_by_source
  );
END;
$$;


--
-- Name: get_shift_audit_log(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_shift_audit_log(p_shift_id uuid) RETURNS TABLE(id text, event_type text, description text, details jsonb, created_at timestamp with time zone, performed_by_name text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
BEGIN
  RETURN QUERY EXECUTE $q$
  SELECT t.id, t.event_type, t.description, t.details, t.created_at, t.performed_by_name
  FROM (
    SELECT
      ('shift_' || sh.id)::text AS id,
      CASE WHEN sh.closed_at IS NULL THEN 'clock_in' ELSE 'clock_out' END AS event_type,
      CASE WHEN sh.closed_at IS NULL THEN 'Shift started' ELSE 'Shift ended' END AS description,
      jsonb_build_object('opened_at', sh.opened_at, 'closed_at', sh.closed_at,
        'duration_minutes', EXTRACT(EPOCH FROM (COALESCE(sh.closed_at, now()) - sh.opened_at)) / 60,
        'starting_cash', sh.starting_cash) AS details,
      sh.opened_at AS created_at,
      s.name AS performed_by_name
    FROM shifts sh JOIN staff s ON s.id = sh.staff_id WHERE sh.id = $1
    UNION ALL
    SELECT
      ('break_' || sb.id)::text AS id,
      CASE WHEN sb.ended_at IS NULL THEN 'break_start' ELSE 'break_end' END AS event_type,
      CASE WHEN sb.ended_at IS NULL THEN 'Break started: ' || sb.break_type ELSE 'Break ended: ' || sb.break_type END AS description,
      jsonb_build_object('break_type', sb.break_type, 'started_at', sb.started_at, 'ended_at', sb.ended_at,
        'duration_minutes', EXTRACT(EPOCH FROM (COALESCE(sb.ended_at, now()) - sb.started_at)) / 60) AS details,
      sb.started_at AS created_at,
      s.name AS performed_by_name
    FROM shift_breaks sb JOIN staff s ON s.id = sb.staff_id WHERE sb.shift_id = $1
    UNION ALL
    SELECT
      ('order_' || o.id)::text AS id, 'order_created' AS event_type,
      'Order #' || COALESCE(o.order_number, '') || ' - ' || o.total_amount::text || ' AZN' AS description,
      jsonb_build_object('order_id', o.id, 'order_number', o.order_number, 'total', o.total_amount,
        'status', o.status, 'payment_method', o.payment_method, 'table_number', o.table_number) AS details,
      o.created_at AS created_at,
      s.name AS performed_by_name
    FROM orders o JOIN staff s ON s.id = o.created_by
    WHERE o.created_by = (SELECT staff_id FROM shifts WHERE id = $1)
      AND o.created_at >= (SELECT opened_at FROM shifts WHERE id = $1)
      AND ((SELECT closed_at FROM shifts WHERE id = $1) IS NULL
          OR o.created_at <= (SELECT closed_at FROM shifts WHERE id = $1))
    UNION ALL
    SELECT
      ('drawer_' || cds.id)::text AS id, 'drawer_' || cds.status AS event_type,
      CASE cds.status WHEN 'opened' THEN 'Cash drawer opened' WHEN 'closed' THEN 'Cash drawer closed'
        WHEN 'force_closed' THEN 'Cash drawer force closed' ELSE 'Cash drawer ' || cds.status END AS description,
      jsonb_build_object('opening_balance', cds.opening_balance, 'closing_balance', cds.closing_balance,
        'expected_balance', cds.expected_balance, 'difference', cds.difference, 'status', cds.status) AS details,
      cds.created_at AS created_at,
      s.name AS performed_by_name
    FROM cash_drawer_sessions cds JOIN staff s ON s.id = cds.opened_by
    WHERE cds.opened_by = (SELECT staff_id FROM shifts WHERE id = $1)
      AND cds.opened_at >= (SELECT opened_at FROM shifts WHERE id = $1)
      AND ((SELECT closed_at FROM shifts WHERE id = $1) IS NULL
          OR cds.opened_at <= (SELECT closed_at FROM shifts WHERE id = $1))
  ) t
  ORDER BY t.created_at DESC$q$ USING p_shift_id;
END;
$_$;


--
-- Name: get_shift_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_shift_detail(p_shift_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'shift', jsonb_build_object(
      'id', sh.id,
      'staff_id', sh.staff_id,
      'staff_name', s.name,
      'role', r.name,
      'opened_at', sh.opened_at,
      'closed_at', sh.closed_at,
      'starting_cash', sh.starting_cash,
      'expected_cash', sh.expected_cash,
      'actual_cash', sh.actual_cash,
      'difference', sh.difference,
      'notes', sh.notes
    ),
    'orders', (
      SELECT jsonb_agg(jsonb_build_object(
        'id', o.id,
        'order_number', o.order_number,
        'total', o.total_amount,
        'status', o.status,
        'created_at', o.created_at,
        'payment_method', o.payment_method
      ) ORDER BY o.created_at)
      FROM orders o
      WHERE o.created_by = sh.staff_id
        AND o.created_at >= sh.opened_at
        AND (sh.closed_at IS NULL OR o.created_at <= sh.closed_at)
    ),
    'cash_drawer', (
      SELECT jsonb_build_object(
        'session_id', cds.id,
        'opening_balance', cds.opening_balance,
        'closing_balance', cds.closing_balance,
        'expected_balance', cds.expected_balance,
        'difference', cds.difference,
        'status', cds.status
      )
      FROM cash_drawer_sessions cds
      WHERE cds.opened_by = sh.staff_id
        AND cds.opened_at >= sh.opened_at
        AND (sh.closed_at IS NULL OR cds.opened_at <= sh.closed_at)
      ORDER BY cds.opened_at DESC
      LIMIT 1
    ),
    'audit_events', (
      SELECT jsonb_agg(jsonb_build_object(
        'action', al.action,
        'created_at', al.created_at,
        'details', al.details
      ) ORDER BY al.created_at)
      FROM audit_logs al
      WHERE al.performed_by = sh.staff_id
        AND al.created_at >= sh.opened_at
        AND (sh.closed_at IS NULL OR al.created_at <= sh.closed_at)
    )
  ) INTO v_result
  FROM shifts sh
  JOIN staff s ON s.id = sh.staff_id
  LEFT JOIN roles r ON r.id = s.role_id
  WHERE sh.id = p_shift_id;

  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: get_splh_metrics(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_splh_metrics(p_staff_id uuid DEFAULT NULL::uuid, p_period_start date DEFAULT (CURRENT_DATE - '30 days'::interval), p_period_end date DEFAULT CURRENT_DATE) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    total_rev numeric := 0;
    total_hrs numeric := 0;
BEGIN
    SELECT COALESCE(SUM(o.total_amount), 0)
      INTO total_rev
      FROM public.orders o
     WHERE o.created_at::date BETWEEN p_period_start AND p_period_end
       AND o.status IN ('confirmed', 'paid', 'completed')
       AND o.created_by = COALESCE(p_staff_id, o.created_by);

    SELECT COALESCE(SUM(GREATEST(EXTRACT(EPOCH FROM (COALESCE(sh.closed_at, NOW()) - sh.opened_at)) / 3600, 0)), 0)
      INTO total_hrs
      FROM public.shifts sh
     WHERE DATE(sh.opened_at) BETWEEN p_period_start AND p_period_end
       AND sh.staff_id = COALESCE(p_staff_id, sh.staff_id);

    RETURN json_build_object(
        'total_revenue', ROUND(total_rev, 2),
        'total_hours',   ROUND(total_hrs, 2),
        'splh',          CASE WHEN total_hrs > 0 THEN ROUND((total_rev / total_hrs), 2) ELSE 0 END
    );
END;
$$;


--
-- Name: get_staff_activity(uuid, integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_activity(p_staff_id uuid, p_limit integer DEFAULT 50, p_offset integer DEFAULT 0) RETURNS TABLE(id text, event_type text, description text, details jsonb, created_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT * FROM (
    SELECT ('order_' || o.id)::text, 'order_closed', 'Order #' || COALESCE(o.order_number, ''),
           jsonb_build_object('total', o.total_amount), o.created_at
    FROM public.orders o WHERE o.created_by = p_staff_id
    UNION ALL
    SELECT ('void_' || o.id)::text, 'void', 'Voided',
           jsonb_build_object('reason', o.void_reason), o.created_at
    FROM public.orders o WHERE o.created_by = p_staff_id AND o.void_reason IS NOT NULL
    UNION ALL
    SELECT ('refund_' || o.id)::text, 'refund', 'Refund',
           jsonb_build_object('amount', o.refund_amount), o.created_at
    FROM public.orders o WHERE o.created_by = p_staff_id AND o.refund_amount > 0
    UNION ALL
    SELECT ('override_' || po.id)::text, 'price_override', 'Price override',
           jsonb_build_object('original', po.catalog_price, 'override', po.override_price, 'variance', po.variance),
           po.created_at
    FROM public.price_overrides po WHERE po.staff_id = p_staff_id
    UNION ALL
    SELECT ('security_' || se.id)::text, se.event_type, se.event_type,
           jsonb_build_object('success', se.success), se.created_at
    FROM public.security_events se WHERE se.staff_id = p_staff_id
  ) combined ORDER BY created_at DESC LIMIT p_limit OFFSET p_offset;
END;
$$;


--
-- Name: get_staff_detail(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_detail(p_staff_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_result jsonb;
BEGIN
  SELECT jsonb_build_object(
    'id', s.id, 'name', s.name, 'full_name', s.full_name,
    'email', s.email, 'phone', s.phone, 'is_active', s.is_active,
    'hourly_rate', s.hourly_rate, 'overtime_rate', s.overtime_rate,
    'shift', s.shift, 'role_id', s.role_id, 'role_name', r.name,
    'active_shift', (SELECT jsonb_build_object('id', sh.id, 'opened_at', sh.opened_at, 'starting_cash', sh.starting_cash, 'duration_min', EXTRACT(EPOCH FROM (now() - sh.opened_at)) / 60) FROM shifts sh WHERE sh.staff_id = p_staff_id AND sh.closed_at IS NULL ORDER BY sh.opened_at DESC LIMIT 1),
    'today_stats', (SELECT jsonb_build_object('orders', COUNT(*), 'revenue', COALESCE(SUM(o.total_amount), 0), 'cash', COALESCE(SUM(o.cash_amount), 0), 'card', COALESCE(SUM(o.card_amount), 0), 'voids', COUNT(*) FILTER (WHERE o.void_reason IS NOT NULL), 'refunds', COUNT(*) FILTER (WHERE o.refund_amount > 0), 'discounts', COUNT(*) FILTER (WHERE o.discount_amount > 0)) FROM orders o WHERE o.created_by = p_staff_id AND o.created_at::date = CURRENT_DATE AND o.status IN ('confirmed', 'paid', 'completed')),
    'lifetime_stats', (SELECT jsonb_build_object('total_orders', COUNT(*), 'total_revenue', COALESCE(SUM(o.total_amount), 0), 'total_shifts', (SELECT COUNT(*) FROM shifts WHERE staff_id = p_staff_id)) FROM orders o WHERE o.created_by = p_staff_id AND o.status IN ('confirmed', 'paid', 'completed')),
    'risk_score', COALESCE((SELECT rs.total_score FROM risk_scores rs WHERE rs.staff_id = p_staff_id AND rs.score_date = CURRENT_DATE), 0)
  ) INTO v_result
  FROM staff s LEFT JOIN roles r ON r.id = s.role_id WHERE s.id = p_staff_id;
  RETURN COALESCE(v_result, '{}'::jsonb);
END;
$$;


--
-- Name: get_staff_directory(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_directory() RETURNS TABLE(id uuid, name text, full_name text, email text, phone text, is_active boolean, hourly_rate numeric, overtime_rate numeric, shift text, role_id uuid, role_name text, shift_id uuid, shift_opened_at timestamp with time zone, shift_status text, total_orders bigint, total_revenue numeric, cash_sales numeric, card_sales numeric, total_voids bigint, total_refunds numeric, total_discounts numeric, drawer_variance numeric, avg_ticket_value numeric, active_tickets bigint, completed_tickets bigint, avg_prep_time interval, late_tickets bigint, active_tables bigint, tables_served bigint, guests_served bigint, total_tips numeric, risk_score integer, last_activity timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id, s.name, s.full_name, s.email, s.phone, s.is_active,
    s.hourly_rate, COALESCE(s.overtime_rate, 1.5), s.shift,
    s.role_id, r.name AS role_name,
    sh.id AS shift_id, sh.opened_at AS shift_opened_at,
    CASE WHEN sh.id IS NOT NULL AND sh.closed_at IS NULL THEN 'active' ELSE 'off' END,
    COALESCE(perf.total_orders, 0), COALESCE(perf.total_revenue, 0),
    COALESCE(perf.cash_sales, 0), COALESCE(perf.card_sales, 0),
    COALESCE(perf.total_voids, 0), COALESCE(perf.total_refunds, 0),
    COALESCE(perf.total_discounts, 0), COALESCE(perf.drawer_variance, 0),
    COALESCE(perf.avg_ticket, 0),
    COALESCE(kitchen.active_tickets, 0), COALESCE(kitchen.completed_tickets, 0),
    kitchen.avg_prep_time, COALESCE(kitchen.late_tickets, 0),
    COALESCE(waiter.active_tables, 0), COALESCE(waiter.tables_served, 0),
    COALESCE(waiter.guests_served, 0), COALESCE(waiter.total_tips, 0),
    COALESCE(rs.total_score, 0), perf.last_order_at
  FROM staff s
  LEFT JOIN roles r ON r.id = s.role_id
  LEFT JOIN LATERAL (SELECT * FROM shifts WHERE staff_id = s.id AND closed_at IS NULL ORDER BY opened_at DESC LIMIT 1) sh ON true
  LEFT JOIN LATERAL (
    SELECT COUNT(*) AS total_orders, SUM(o.total_amount) AS total_revenue,
      SUM(o.cash_amount) AS cash_sales, SUM(o.card_amount) AS card_sales,
      COUNT(*) FILTER (WHERE o.void_reason IS NOT NULL) AS total_voids,
      COALESCE(SUM(o.refund_amount), 0) AS total_refunds,
      COALESCE(SUM(o.discount_amount), 0) AS total_discounts,
      COALESCE((SELECT SUM(cds.difference) FROM cash_drawer_sessions cds WHERE cds.opened_by = s.id AND cds.closed_at IS NOT NULL AND cds.created_at::date = CURRENT_DATE), 0) AS drawer_variance,
      AVG(o.total_amount) AS avg_ticket, MAX(o.created_at) AS last_order_at
    FROM orders o WHERE o.created_by = s.id AND o.created_at::date = CURRENT_DATE AND o.status IN ('confirmed', 'paid', 'completed')
  ) perf ON true
  LEFT JOIN LATERAL (
    SELECT COUNT(*) FILTER (WHERE kt.status IN ('pending', 'preparing')) AS active_tickets,
      COUNT(*) FILTER (WHERE kt.status = 'completed') AS completed_tickets,
      AVG(kt.completed_at - kt.created_at) FILTER (WHERE kt.status = 'completed') AS avg_prep_time,
      COUNT(*) FILTER (WHERE kt.status = 'completed' AND (kt.completed_at - kt.created_at) > interval '15 minutes') AS late_tickets
    FROM kitchen_tickets kt WHERE kt.assigned_to = s.id AND kt.created_at::date = CURRENT_DATE
  ) kitchen ON true
  LEFT JOIN LATERAL (
    SELECT COUNT(*) FILTER (WHERE wa.status = 'occupied') AS active_tables,
      COUNT(*) FILTER (WHERE wa.status = 'completed') AS tables_served,
      SUM(wa.guest_count) AS guests_served, SUM(wa.tip_amount) AS total_tips
    FROM waiter_assignments wa WHERE wa.waiter_id = s.id AND wa.created_at::date = CURRENT_DATE
  ) waiter ON true
  LEFT JOIN LATERAL (SELECT rs.total_score FROM risk_scores rs WHERE rs.staff_id = s.id AND rs.score_date = CURRENT_DATE LIMIT 1) rs ON true
  ORDER BY CASE WHEN sh.id IS NOT NULL AND sh.closed_at IS NULL THEN 0 ELSE 1 END, s.name;
END;
$$;


--
-- Name: get_staff_directory_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_directory_v2() RETURNS TABLE(id uuid, name text, full_name text, email text, phone text, is_active boolean, hourly_rate numeric, role_id uuid, role_name text, shift text, shift_id uuid, shift_opened_at timestamp with time zone, shift_status text, active_shift jsonb, expected_cash numeric, total_orders integer, total_revenue numeric, cash_sales numeric, card_sales numeric, total_voids integer, total_refunds numeric, total_discounts numeric, drawer_variance numeric, avg_ticket_value numeric, avg_order_value numeric, active_tickets integer, completed_tickets integer, avg_prep_time text, late_tickets integer, items_prepared integer, re_fired integer, cancelled_tickets integer, waste_count integer, active_tables integer, tables_served integer, guests_served integer, total_tips numeric, approvals_count integer, exceptions_count integer, labor_cost_percent numeric, labor_efficiency numeric, void_refund_approvals integer, seated_guests integer, avg_wait_time text, table_turnover_rate text, no_shows integer, risk_score integer, risk_level text, risk_flags text[], last_activity timestamp with time zone, can_apply_discount boolean, can_void_items boolean, can_open_drawer_without_sale boolean, can_refund boolean, can_view_reports boolean, can_manage_staff boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id,
    s.name,
    s.full_name,
    s.email,
    s.phone,
    s.is_active,
    s.hourly_rate,
    s.role_id,
    r.name AS role_name,
    s.shift,
    sh.id AS shift_id,
    sh.opened_at AS shift_opened_at,
    CASE WHEN sh.id IS NOT NULL THEN 'active' ELSE 'off' END AS shift_status,
    CASE WHEN sh.id IS NOT NULL THEN
      jsonb_build_object(
        'id', sh.id,
        'opened_at', sh.opened_at,
        'starting_cash', sh.starting_cash,
        'duration_minutes', EXTRACT(EPOCH FROM (NOW() - sh.opened_at)) / 60
      )
    ELSE NULL END AS active_shift,
    s.expected_cash,
    COALESCE(ss.total_orders, 0),
    COALESCE(ss.total_revenue, 0),
    COALESCE(ss.cash_sales, 0),
    COALESCE(ss.card_sales, 0),
    COALESCE(ss.total_voids, 0),
    COALESCE(ss.total_refunds, 0),
    COALESCE(ss.total_discounts, 0),
    COALESCE(s.drawer_variance, 0),
    COALESCE(ss.avg_ticket_value, 0),
    COALESCE(ss.avg_order_value, 0),
    COALESCE(ss.active_tickets, 0),
    COALESCE(ss.completed_tickets, 0),
    ss.avg_prep_time,
    COALESCE(ss.late_tickets, 0),
    COALESCE(ss.items_prepared, 0),
    COALESCE(ss.re_fired, 0),
    COALESCE(ss.cancelled_tickets, 0),
    COALESCE(ss.waste_count, 0),
    COALESCE(ss.active_tables, 0),
    COALESCE(ss.tables_served, 0),
    COALESCE(ss.guests_served, 0),
    COALESCE(ss.total_tips, 0),
    COALESCE(ss.approvals_count, 0),
    COALESCE(ss.exceptions_count, 0),
    COALESCE(ss.labor_cost_percent, 0),
    COALESCE(ss.labor_efficiency, 0),
    COALESCE(ss.void_refund_approvals, 0),
    COALESCE(ss.seated_guests, 0),
    ss.avg_wait_time,
    ss.table_turnover_rate,
    COALESCE(ss.no_shows, 0),
    COALESCE(s.risk_score, 0),
    s.risk_level,
    s.risk_flags,
    s.last_activity,
    s.can_apply_discount,
    s.can_void_items,
    s.can_open_drawer_without_sale,
    s.can_refund,
    s.can_view_reports,
    s.can_manage_staff
  FROM staff s
  LEFT JOIN roles r ON r.id = s.role_id
  LEFT JOIN shifts sh ON sh.staff_id = s.id AND sh.closed_at IS NULL
  LEFT JOIN staff_stats ss ON ss.staff_id = s.id AND ss.period = CURRENT_DATE
  WHERE s.is_active = true
  ORDER BY s.name ASC;
END;
$$;


--
-- Name: get_staff_directory_v3(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_directory_v3() RETURNS SETOF json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    json_build_object(
      'id', s.id,
      'name', s.name,
      'full_name', s.full_name,
      'email', s.email,
      'phone', s.phone,
      'is_active', s.is_active,
      'status', s.status,
      'last_login_at', s.last_login_at,
      'hourly_rate', s.hourly_rate,
      'role_id', s.role_id,
      'role_name', r.name,
      'shift', s.shift,
      'shift_id', sh.id,
      'shift_opened_at', sh.opened_at,
      'shift_status', CASE WHEN sh.id IS NOT NULL THEN 'active' ELSE 'off' END,
      'active_shift', CASE WHEN sh.id IS NOT NULL THEN
        jsonb_build_object('id', sh.id, 'opened_at', sh.opened_at, 'starting_cash', sh.starting_cash,
          'duration_minutes', EXTRACT(EPOCH FROM (NOW() - sh.opened_at)) / 60)
        ELSE NULL END,
      'expected_cash', s.expected_cash,
      'total_orders', COALESCE(ss.total_orders, 0),
      'total_revenue', COALESCE(ss.total_revenue, 0),
      'cash_sales', COALESCE(ss.cash_sales, 0),
      'card_sales', COALESCE(ss.card_sales, 0),
      'total_voids', COALESCE(ss.total_voids, 0),
      'total_refunds', COALESCE(ss.total_refunds, 0),
      'total_discounts', COALESCE(ss.total_discounts, 0),
      'drawer_variance', COALESCE(s.drawer_variance, 0),
      'avg_ticket_value', COALESCE(ss.avg_ticket_value, 0),
      'avg_order_value', COALESCE(ss.avg_order_value, 0),
      'risk_score', COALESCE(s.risk_score, 0),
      'risk_level', s.risk_level,
      'risk_flags', s.risk_flags,
      'last_activity', s.last_activity
    )
  FROM staff s
  LEFT JOIN roles r ON r.id = s.role_id
  LEFT JOIN shifts sh ON sh.staff_id = s.id AND sh.closed_at IS NULL
  LEFT JOIN staff_stats ss ON ss.staff_id = s.id AND ss.period = CURRENT_DATE
  ORDER BY s.name ASC;
END;
$$;


--
-- Name: get_staff_kpis(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_kpis() RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  result JSON;
BEGIN
  SELECT json_build_object(
    'total_staff', (SELECT COUNT(*) FROM staff WHERE is_active = true),
    'active_staff', (SELECT COUNT(*) FROM staff WHERE is_active = true),
    'on_shift', (SELECT COUNT(*) FROM shifts WHERE closed_at IS NULL),
    'off_shift', (SELECT COUNT(*) FROM staff WHERE is_active = true) - (SELECT COUNT(*) FROM shifts WHERE closed_at IS NULL),
    'today_orders', COALESCE((SELECT COUNT(*) FROM orders WHERE DATE(created_at) = CURRENT_DATE), 0),
    'today_revenue', COALESCE((SELECT SUM(total_amount) FROM orders WHERE DATE(created_at) = CURRENT_DATE AND status = 'paid'), 0),
    'open_cash_drawers', COALESCE((SELECT COUNT(*) FROM cash_drawer_sessions WHERE status = 'open'), 0),
    'cash_variance', COALESCE((SELECT SUM(ABS(difference)) FROM shifts WHERE closed_at IS NULL AND difference IS NOT NULL), 0),
    'risk_alerts', COALESCE((SELECT COUNT(*) FROM staff WHERE risk_score > 50 AND is_active = true), 0),
    'labor_cost_today', COALESCE((SELECT SUM(total_labor_cost) FROM labor_summaries WHERE period = CURRENT_DATE), 0),
    'avg_ticket_size', COALESCE((SELECT AVG(total_amount) FROM orders WHERE DATE(created_at) = CURRENT_DATE AND status = 'paid'), 0),
    'high_risk_voids', COALESCE((SELECT COUNT(*) FROM operation_logs WHERE action = 'void' AND DATE(created_at) = CURRENT_DATE), 0)
  ) INTO result;

  RETURN result;
END;
$$;


--
-- Name: get_staff_lifecycle_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_lifecycle_status() RETURNS TABLE(staff_id uuid, phase text, scheduled_start time without time zone, scheduled_end time without time zone, has_schedule boolean, is_clocked_in boolean, shift_id uuid, shift_opened_at timestamp with time zone, clock_in_at timestamp with time zone, late_minutes integer, is_late boolean, on_break boolean, break_started_at timestamp with time zone, break_used_minutes integer, break_allowance_mins integer, hours_worked_net numeric, is_unclosed boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_member RECORD;
  v_sched RECORD;
  v_shift RECORD;
  v_break_total INTEGER := 0;
  v_has_break BOOLEAN := false;
  v_break_started_ts TIMESTAMPTZ := NULL;
  v_net_hours NUMERIC := 0;
  v_phase TEXT;
  v_late INTEGER := 0;
  v_clock_in_ts TIMESTAMPTZ := NULL;
BEGIN
  FOR v_member IN SELECT s.id, s.break_allowance_mins, r.name AS role_name
                  FROM public.staff s
                  LEFT JOIN public.roles r ON r.id = s.role_id
                  WHERE s.is_active = true
  LOOP
    -- today's planned schedule
    SELECT * INTO v_sched FROM public.schedule
    WHERE public.schedule.staff_id = v_member.id AND schedule_date = CURRENT_DATE
    ORDER BY planned_start LIMIT 1;

    -- active open shift (unclosed guard handled downstream)
    SELECT * INTO v_shift FROM public.shifts
    WHERE public.shifts.staff_id = v_member.id AND closed_at IS NULL
    ORDER BY opened_at DESC LIMIT 1;

    -- active break for that shift
    v_has_break := false;
    v_break_started_ts := NULL;
    IF v_shift.id IS NOT NULL THEN
      SELECT COUNT(*) > 0, MIN(started_at) INTO v_has_break, v_break_started_ts
      FROM public.shift_breaks
      WHERE shift_id = v_shift.id AND ended_at IS NULL;
    END IF;

    -- total break minutes today for this member
    SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (COALESCE(ended_at, NOW()) - started_at)) / 60)::int, 0)
      INTO v_break_total
    FROM public.shift_breaks sb
    JOIN public.shifts sh ON sh.id = sb.shift_id
    WHERE sh.staff_id = v_member.id AND DATE(sb.started_at) = CURRENT_DATE;

    -- net worked hours while clocked in (gross minus breaks)
    IF v_shift.id IS NOT NULL THEN
      SELECT COALESCE(
        (EXTRACT(EPOCH FROM (NOW() - sh.opened_at)) / 3600) -
        COALESCE((SELECT SUM(EXTRACT(EPOCH FROM (COALESCE(sb.ended_at, NOW()) - sb.started_at)) / 3600)
                  FROM public.shift_breaks sb WHERE sb.shift_id = sh.id), 0),
        0) INTO v_net_hours
      FROM public.shifts sh WHERE sh.id = v_shift.id;
    END IF;

    -- phase + late
    v_phase := 'no_schedule';
    IF v_shift.id IS NOT NULL THEN
      -- unclosed guard: > 12h and still open
      IF EXTRACT(EPOCH FROM (NOW() - v_shift.opened_at)) / 3600 > 12 THEN
        v_phase := 'unclosed';
      ELSIF v_has_break THEN
        v_phase := 'on_break';
      ELSE
        v_phase := 'on_shift';
      END IF;
    ELSIF v_sched.id IS NOT NULL THEN
      v_phase := 'scheduled';
    END IF;

    -- late flag: clock-in after scheduled_start + 15 min grace (only for today's scheduled shift)
    v_late := 0;
    IF v_sched.id IS NOT NULL AND v_phase IN ('on_shift', 'on_break', 'unclosed') THEN
      SELECT t.clock_in_at INTO v_clock_in_ts FROM (
        SELECT timestamp AS clock_in_at FROM public.time_clock_entries
        WHERE time_clock_entries.staff_id = v_member.id AND entry_type = 'clock_in' AND timestamp >= CURRENT_DATE
        ORDER BY timestamp DESC LIMIT 1
      ) t;
      IF v_clock_in_ts IS NOT NULL
         AND v_clock_in_ts::time > (v_sched.planned_start::time + INTERVAL '15 minutes') THEN
        v_late := (EXTRACT(EPOCH FROM (v_clock_in_ts::time - v_sched.planned_start::time)) / 60)::int;
      END IF;
    END IF;

    RETURN QUERY SELECT
      v_member.id,
      v_phase,
      v_sched.planned_start,
      v_sched.planned_end,
      v_sched.id IS NOT NULL,
      v_shift.id IS NOT NULL AND NOT v_has_break AND v_phase IN ('on_shift', 'unclosed'),
      v_shift.id,
      v_shift.opened_at,
      v_clock_in_ts,
      v_late,
      v_late > 0,
      v_has_break,
      v_break_started_ts,
      v_break_total,
      COALESCE(v_member.break_allowance_mins, 45),
      v_net_hours,
      v_phase = 'unclosed';
  END LOOP;
END;
$$;


--
-- Name: get_staff_locations(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_locations(p_staff_id uuid) RETURNS TABLE(location_id uuid, location_name text, is_primary boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT l.id, l.name::text, sl.is_primary
  FROM public.staff_locations sl
  JOIN public.locations l ON l.id = sl.location_id
  WHERE sl.staff_id = p_staff_id
  ORDER BY sl.is_primary DESC;
END;
$$;


--
-- Name: get_staff_performance(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_performance(p_start_date date DEFAULT (CURRENT_DATE - '7 days'::interval), p_end_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_by_staff JSONB;
  v_top_performers JSONB;
BEGIN
  -- Staff order stats
  SELECT COALESCE(jsonb_agg(row_to_json(s)), '[]'::JSONB) INTO v_by_staff
  FROM (
    SELECT
      o.created_by AS staff_id,
      COALESCE(s.name, 'Unknown') AS staff_name,
      COUNT(*) AS orders_handled,
      COALESCE(SUM(o.total_amount), 0) AS total_sales,
      ROUND(AVG(o.total_amount), 2) AS avg_order_value,
      COUNT(*) FILTER (WHERE o.status = 'cancelled') AS cancelled_orders
    FROM orders o
    LEFT JOIN staff s ON o.created_by = s.id
    WHERE DATE(o.created_at) BETWEEN p_start_date AND p_end_date
      AND o.status NOT IN ('draft')
    GROUP BY o.created_by, s.name
    ORDER BY total_sales DESC
  ) s;

  -- Top performers by sales
  v_top_performers := (
    SELECT COALESCE(jsonb_agg(row_to_json(t)), '[]'::JSONB)
    FROM (
      SELECT
        o.created_by AS staff_id,
        COALESCE(s.name, 'Unknown') AS staff_name,
        COALESCE(SUM(o.total_amount), 0) AS total_sales,
        COUNT(*) AS orders_count
      FROM orders o
      LEFT JOIN staff s ON o.created_by = s.id
      WHERE DATE(o.created_at) BETWEEN p_start_date AND p_end_date
        AND o.status = 'paid'
      GROUP BY o.created_by, s.name
      ORDER BY total_sales DESC
      LIMIT 5
    ) t
  );

  RETURN jsonb_build_object(
    'period', jsonb_build_object('start', p_start_date, 'end', p_end_date),
    'by_staff', v_by_staff,
    'top_performers', v_top_performers
  );
END;
$$;


--
-- Name: get_staff_permissions(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_permissions(p_staff_id uuid) RETURNS TABLE(permission_key text, permission_description text, permission_category text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_role_id uuid;
BEGIN
  SELECT role_id INTO v_role_id FROM staff WHERE id = p_staff_id;
  IF v_role_id IS NULL THEN
    RETURN;
  END IF;

  RETURN QUERY
  SELECT p.key, p.description, p.category
  FROM role_permissions rp
  JOIN permissions p ON p.key = rp.permission_key
  WHERE rp.role_id = v_role_id
  ORDER BY p.category, p.key;
END;
$$;


--
-- Name: get_staff_shifts(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_staff_shifts(p_staff_id uuid) RETURNS TABLE(id uuid, opened_at timestamp with time zone, closed_at timestamp with time zone, duration_minutes numeric, starting_cash numeric, expected_cash numeric, actual_cash numeric, difference numeric, orders_count bigint, status text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    sh.id,
    sh.opened_at,
    sh.closed_at,
    EXTRACT(EPOCH FROM (COALESCE(sh.closed_at, now()) - sh.opened_at)) / 60 AS duration_minutes,
    sh.starting_cash,
    sh.expected_cash,
    sh.actual_cash,
    sh.difference,
    (SELECT COUNT(*) FROM orders o WHERE o.created_by = p_staff_id AND o.created_at >= sh.opened_at AND (sh.closed_at IS NULL OR o.created_at <= sh.closed_at)) AS orders_count,
    CASE
      WHEN sh.closed_at IS NULL THEN 'active'
      WHEN sh.notes LIKE '%Force%' THEN 'force_closed'
      ELSE 'closed'
    END AS status
  FROM shifts sh
  WHERE sh.staff_id = p_staff_id
  ORDER BY sh.opened_at DESC
  LIMIT 50;
END;
$$;


--
-- Name: get_time_clock_history(uuid, date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_time_clock_history(p_staff_id uuid, p_start_date date DEFAULT (CURRENT_DATE - '7 days'::interval), p_end_date date DEFAULT CURRENT_DATE) RETURNS TABLE(entry_id uuid, entry_type character varying, entry_timestamp timestamp with time zone, pin_verified boolean, source character varying, notes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    tce.id,
    tce.entry_type,
    tce.timestamp,
    tce.pin_verified,
    tce.source,
    tce.notes
  FROM time_clock_entries tce
  WHERE tce.staff_id = p_staff_id
  AND DATE(tce.timestamp) BETWEEN p_start_date AND p_end_date
  ORDER BY tce.timestamp DESC;
END;
$$;


--
-- Name: get_time_clock_status(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_time_clock_status(p_staff_id uuid) RETURNS json
    LANGUAGE plpgsql STABLE
    SET search_path TO 'public'
    AS $$
DECLARE
  v_loc uuid;
  v_tz text;
  v_local_now timestamptz;
  v_local_day date;
  v_week_start timestamptz;
  v_latest RECORD;
  v_active_shift RECORD;
  v_active_break RECORD;
  v_today_hours DECIMAL;
  v_weekly_hours DECIMAL;
  v_has_shift BOOLEAN;
  v_has_break BOOLEAN;
  v_break_started TIMESTAMPTZ;
  v_break_id UUID;
  v_shift_id UUID;
  v_clocked_in BOOLEAN;
  v_on_break BOOLEAN;
BEGIN
  -- S-05: resolve the staff's location timezone (primary active assignment)
  SELECT l.location_id INTO v_loc
  FROM staff_locations l
  JOIN staff s ON s.id = l.staff_id
  WHERE l.staff_id = p_staff_id AND l.active = true
    AND (l.is_primary = true OR NOT EXISTS (
        SELECT 1 FROM staff_locations l2
        WHERE l2.staff_id = p_staff_id AND l2.active = true AND l2.is_primary = true))
  LIMIT 1;
  v_tz := COALESCE((SELECT timezone FROM locations WHERE id = v_loc), current_setting('TimeZone'));
  v_local_now := now() AT TIME ZONE v_tz;             -- wall-clock instant (no tz)
  v_local_day := v_local_now::date;                   -- business date
  -- local Monday 00:00 → back to timestamptz for range comparison
  v_week_start := ((v_local_day - extract(isodow from v_local_now)::int + 1)::timestamp AT TIME ZONE v_tz);

  SELECT * INTO v_latest FROM time_clock_entries
  WHERE staff_id = p_staff_id AND timestamp > (v_local_day::timestamp AT TIME ZONE v_tz)
  ORDER BY timestamp DESC LIMIT 1;

  SELECT * INTO v_active_shift FROM shifts
  WHERE staff_id = p_staff_id AND closed_at IS NULL
  ORDER BY opened_at DESC LIMIT 1;

  v_has_shift := v_active_shift.id IS NOT NULL;
  v_has_break := false;
  v_break_started := NULL;
  v_break_id := NULL;
  IF v_has_shift THEN
    SELECT sb.id, sb.started_at INTO v_break_id, v_break_started
    FROM shift_breaks sb
    WHERE sb.shift_id = v_active_shift.id AND sb.ended_at IS NULL
    LIMIT 1;
    v_has_break := v_break_id IS NOT NULL;
  END IF;

  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600), 0) INTO v_today_hours
  FROM shifts
  WHERE staff_id = p_staff_id
    AND public.local_day(opened_at, v_loc) = v_local_day;

  SELECT COALESCE(SUM(EXTRACT(EPOCH FROM (closed_at - opened_at)) / 3600), 0) INTO v_weekly_hours
  FROM shifts
  WHERE staff_id = p_staff_id
    AND opened_at >= v_week_start
    AND opened_at < v_week_start + INTERVAL '7 days';

  v_clocked_in := v_has_shift AND NOT v_has_break;
  v_on_break := v_has_shift AND v_has_break;

  RETURN json_build_object(
    'is_clocked_in', v_clocked_in,
    'on_break', v_on_break,
    'current_entry_type', COALESCE(v_latest.entry_type, NULL),
    'last_entry', v_latest.timestamp,
    'active_shift_id', v_active_shift.id,
    'active_break_id', v_break_id,
    'break_started_at', v_break_started,
    'today_hours', ROUND(v_today_hours, 2),
    'weekly_hours', ROUND(v_weekly_hours, 2),
    'approaching_daily_ot', v_today_hours >= 7.5,
    'approaching_weekly_ot', v_weekly_hours >= 37.5,
    'business_date', v_local_day,
    'timezone', v_tz
  );
END;
$$;


--
-- Name: get_tip_pool_summary(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_tip_pool_summary(p_pool_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pool RECORD;
  v_total_distributed DECIMAL;
  v_staff_count INTEGER;
BEGIN
  SELECT * INTO v_pool FROM tip_pools WHERE id = p_pool_id;

  SELECT COALESCE(SUM(amount), 0), COUNT(DISTINCT staff_id)
  INTO v_total_distributed, v_staff_count
  FROM tip_distributions
  WHERE pool_id = p_pool_id;

  RETURN json_build_object(
    'pool_id', v_pool.id,
    'date', v_pool.pool_date,
    'total_amount', v_pool.total_amount,
    'status', v_pool.status,
    'distributed_amount', v_total_distributed,
    'staff_count', v_staff_count,
    'distributed_at', v_pool.distributed_at
  );
END;
$$;


--
-- Name: get_valid_transitions(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_valid_transitions(p_entity text, p_current_status text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
BEGIN
  SELECT jsonb_agg(jsonb_build_object(
    'to_status', to_status,
    'description', description,
    'requires_role', requires_role,
    'requires_manager_pin', requires_manager_pin
  )) INTO v_result
  FROM state_transitions
  WHERE entity = p_entity
    AND from_status = p_current_status
    AND is_active = true;

  RETURN jsonb_build_object(
    'entity', p_entity,
    'current_status', p_current_status,
    'transitions', COALESCE(v_result, '[]'::JSONB)
  );
END;
$$;


--
-- Name: get_weekly_schedule(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_weekly_schedule(p_start_date date, p_end_date date) RETURNS TABLE(schedule_id uuid, staff_id uuid, staff_name text, role_name text, schedule_date date, planned_start time without time zone, planned_end time without time zone, notes text)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN QUERY
  SELECT
    s.id,
    s.staff_id,
    st.full_name,
    r.name,
    s.schedule_date,
    s.planned_start,
    s.planned_end,
    s.notes
  FROM schedule s
  JOIN staff st ON st.id = s.staff_id
  LEFT JOIN roles r ON r.id = st.role_id
  WHERE s.schedule_date BETWEEN p_start_date AND p_end_date
  ORDER BY s.schedule_date, s.planned_start;
END;
$$;


--
-- Name: get_z_report(date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.get_z_report(p_date date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB;
  v_total_revenue NUMERIC := 0;
  v_total_orders INTEGER := 0;
  v_aov NUMERIC := 0;
  v_items_sold INTEGER := 0;
  v_cash_total NUMERIC := 0;
  v_card_total NUMERIC := 0;
  v_tips_total NUMERIC := 0;
  v_discounts_total NUMERIC := 0;
  v_voids_count INTEGER := 0;
  v_voids_amount NUMERIC := 0;
  v_starting_cash NUMERIC := 0;
  v_expected_cash NUMERIC := 0;
  v_cogs NUMERIC := 0;
  v_labor_cost NUMERIC := 0;
  v_expenses_total NUMERIC := 0;
  v_expenses_breakdown JSONB;
  v_previous_report RECORD;
BEGIN
  -- Get previous report for starting cash
  SELECT * INTO v_previous_report
  FROM daily_reports
  WHERE report_date < p_date
  ORDER BY report_date DESC LIMIT 1;

  IF v_previous_report IS NOT NULL THEN
    v_starting_cash := COALESCE(v_previous_report.actual_cash, 0);
  END IF;

  -- Aggregate from orders
  SELECT
    COALESCE(SUM(total_amount), 0),
    COUNT(*),
    COALESCE(SUM(tip_amount), 0),
    COALESCE(SUM(discount_amount), 0)
  INTO v_total_revenue, v_total_orders, v_tips_total, v_discounts_total
  FROM orders
  WHERE status = 'paid'
    AND DATE(paid_at) = p_date;

  IF v_total_orders > 0 THEN
    v_aov := ROUND(v_total_revenue / v_total_orders, 2);
  END IF;

  -- Items sold
  SELECT COUNT(*) INTO v_items_sold
  FROM order_items oi
  JOIN orders o ON oi.order_id = o.id
  WHERE o.status = 'paid'
    AND DATE(o.paid_at) = p_date
    AND oi.kitchen_status NOT IN ('cancelled');

  -- Payment breakdown from order_payments
  SELECT
    COALESCE(SUM(CASE WHEN op.payment_method IN ('cash', 'nağd') THEN op.amount ELSE 0 END), 0),
    COALESCE(SUM(CASE WHEN op.payment_method IN ('card', 'kart') THEN op.amount ELSE 0 END), 0)
  INTO v_cash_total, v_card_total
  FROM order_payments op
  JOIN orders o ON op.order_id = o.id
  WHERE o.status = 'paid'
    AND DATE(o.paid_at) = p_date;

  -- Fallback to orders
  IF v_cash_total = 0 AND v_card_total = 0 AND v_total_revenue > 0 THEN
    SELECT
      COALESCE(SUM(CASE WHEN o.payment_method IN ('cash', 'nağd') THEN o.total_amount ELSE 0 END), 0),
      COALESCE(SUM(CASE WHEN o.payment_method IN ('card', 'kart') THEN o.total_amount ELSE 0 END), 0)
    INTO v_cash_total, v_card_total
    FROM orders o
    WHERE o.status = 'paid'
      AND DATE(o.paid_at) = p_date;
  END IF;

  -- Voids
  SELECT COUNT(*), COALESCE(SUM(total_amount), 0)
  INTO v_voids_count, v_voids_amount
  FROM orders
  WHERE status = 'cancelled'
    AND DATE(cancelled_at) = p_date;

  -- COGS from orders (if tracked)
  SELECT COALESCE(SUM(cogs), 0) INTO v_cogs
  FROM orders
  WHERE status = 'paid'
    AND DATE(paid_at) = p_date;

  -- Labor cost
  SELECT COALESCE(SUM(amount), 0) INTO v_labor_cost
  FROM expenses
  WHERE expense_date = p_date AND category = 'labor';

  -- Expenses breakdown
  SELECT COALESCE(jsonb_object_agg(category, total), '{}'::JSONB)
  INTO v_expenses_breakdown
  FROM (
    SELECT category, SUM(amount) AS total
    FROM expenses
    WHERE expense_date = p_date
    GROUP BY category
  ) sub;

  SELECT COALESCE(SUM(amount), 0) INTO v_expenses_total
  FROM expenses
  WHERE expense_date = p_date;

  v_expected_cash := v_starting_cash + v_cash_total - v_expenses_total;

  v_result := jsonb_build_object(
    'report_date', p_date,
    'sales', jsonb_build_object(
      'total_revenue', v_total_revenue,
      'total_orders', v_total_orders,
      'aov', v_aov,
      'items_sold', v_items_sold
    ),
    'payments', jsonb_build_object(
      'cash_total', v_cash_total,
      'card_total', v_card_total,
      'tips_total', v_tips_total,
      'discounts_total', v_discounts_total
    ),
    'voids', jsonb_build_object(
      'count', v_voids_count,
      'amount', v_voids_amount
    ),
    'cash_drawer', jsonb_build_object(
      'starting_cash', v_starting_cash,
      'expected_cash', v_expected_cash,
      'cash_received', v_cash_total
    ),
    'costs', jsonb_build_object(
      'cogs', v_cogs,
      'labor_cost', v_labor_cost,
      'total_expenses', v_expenses_total,
      'expenses_breakdown', v_expenses_breakdown
    ),
    'profit', jsonb_build_object(
      'gross', v_total_revenue - v_cogs,
      'net', v_total_revenue - v_cogs - v_labor_cost - v_expenses_total
    )
  );

  RETURN v_result;
END;
$$;


--
-- Name: gift_card_issue(text, numeric, uuid, text, uuid, timestamp with time zone); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gift_card_issue(p_code text, p_initial_balance numeric, p_issued_to uuid DEFAULT NULL::uuid, p_issued_to_name text DEFAULT NULL::text, p_issued_by uuid DEFAULT NULL::uuid, p_expires_at timestamp with time zone DEFAULT NULL::timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_card RECORD;
  v_performer_name TEXT;
BEGIN
  IF p_initial_balance <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Balance must be positive');
  END IF;

  IF p_issued_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_issued_by;
  END IF;

  INSERT INTO public.gift_cards (code, initial_balance, current_balance, issued_to, issued_to_name, issued_by, expires_at)
  VALUES (UPPER(TRIM(p_code)), p_initial_balance, p_initial_balance, p_issued_to, p_issued_to_name, p_issued_by, p_expires_at)
  RETURNING * INTO v_card;

  INSERT INTO public.gift_card_transactions (gift_card_id, type, amount, balance_after, performed_by, description)
  VALUES (v_card.id, 'issue', p_initial_balance, p_initial_balance, p_issued_by, 'Hədiyyə kartı buraxıldı');

  PERFORM public.log_audit(
    'gift_card_issue', 'gift_card', v_card.id::text,
    p_issued_by, v_performer_name,
    NULL,
    jsonb_build_object('code', p_code, 'balance', p_initial_balance),
    jsonb_build_object('card_id', v_card.id),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'card_id', v_card.id,
    'code', p_code,
    'balance', p_initial_balance
  );
END;
$$;


--
-- Name: gift_card_redeem(text, numeric, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gift_card_redeem(p_code text, p_amount numeric, p_order_id uuid DEFAULT NULL::uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_card RECORD;
  v_performer_name TEXT;
  v_new_balance NUMERIC;
BEGIN
  IF p_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Amount must be positive');
  END IF;

  SELECT * INTO v_card FROM public.gift_cards
  WHERE code = UPPER(TRIM(p_code)) AND status = 'active'
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gift card not found or inactive');
  END IF;

  IF v_card.expires_at IS NOT NULL AND v_card.expires_at < NOW() THEN
    RETURN jsonb_build_object('success', false, 'error', 'Gift card expired');
  END IF;

  IF v_card.current_balance < p_amount THEN
    RETURN jsonb_build_object('success', false, 'error', 'Insufficient balance', 'balance', v_card.current_balance);
  END IF;

  v_new_balance := v_card.current_balance - p_amount;

  UPDATE public.gift_cards SET current_balance = v_new_balance, updated_at = NOW() WHERE id = v_card.id;

  INSERT INTO public.gift_card_transactions (gift_card_id, type, amount, balance_after, order_id, performed_by, description)
  VALUES (v_card.id, 'redeem', p_amount, v_new_balance, p_order_id, p_performed_by, 'Ödəniş üçün istifadə');

  -- Auto-deactivate if depleted
  IF v_new_balance = 0 THEN
    UPDATE public.gift_cards SET status = 'depleted', updated_at = NOW() WHERE id = v_card.id;
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  PERFORM public.log_audit(
    'gift_card_redeem', 'gift_card', v_card.id::text,
    p_performed_by, v_performer_name,
    jsonb_build_object('balance', v_card.current_balance),
    jsonb_build_object('redeemed', p_amount, 'new_balance', v_new_balance, 'order_id', p_order_id),
    NULL,
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'card_id', v_card.id,
    'code', p_code,
    'redeemed', p_amount,
    'remaining_balance', v_new_balance
  );
END;
$$;


