--
-- Name: has_permission(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_permission_key text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
    SELECT EXISTS (
        SELECT 1
        FROM staff st
        JOIN role_permissions rp ON rp.role_id = st.role_id
        WHERE st.id = current_staff_id()
          AND rp.permission_key = p_permission_key
    );
$$;


--
-- Name: has_permission(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_token text, p_permission text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_result jsonb;
BEGIN
    v_result := authorize(p_token, p_permission);
    RETURN (v_result->>'allowed')::boolean;
END;
$$;


--
-- Name: has_permission(uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.has_permission(p_staff_id uuid, p_permission text) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ SELECT EXISTS ( SELECT 1 FROM staff s JOIN roles r ON r.id = s.role_id JOIN role_permissions rp ON rp.role_id = r.id WHERE s.id = p_staff_id AND s.is_active = true AND s.role_id IS NOT NULL AND rp.permission_key = p_permission ); $$;


--
-- Name: FUNCTION has_permission(p_staff_id uuid, p_permission text); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.has_permission(p_staff_id uuid, p_permission text) IS 'P-1 M1 (frozen 2026-09-12): THE permission SSOT — role_permissions x staff.is_active. Location scope is enforced at the financial-write layer (p1_actor_allowed_at_location inside complete_payment_atomic_v2 / refund_with_inventory), NOT here. See P1_AUTHZ_CONTRACT_FREEZE_2026-09-12.md.';


