$$;


--
-- Name: item_kitchen_step(text, uuid, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_kitchen_step(p_token text, p_item_id uuid, p_target text, p_reason text, p_metadata jsonb, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_order RECORD;
  v_item RECORD;
  v_rule jsonb;
  v_allowed jsonb;
  v_updated RECORD;
  v_corr uuid := COALESCE(p_correlation_id, gen_random_uuid());
  v_op text := 'order_item.' || p_target;
  v_event text;
  v_ok_from text[];
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  -- lock order row first (consistent lock ordering with terminal fn)
  SELECT o.id, o.status, o.location_id, o.organization_id
    INTO v_order
    FROM orders o
    JOIN order_items i ON i.order_id = o.id
   WHERE i.id = p_item_id
   FOR UPDATE OF o;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  SELECT * INTO v_item FROM order_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- idempotent re-entry: already at target → success noop
  IF v_item.kitchen_status = p_target THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true,
      'order_item_id', p_item_id, 'from_status', v_item.kitchen_status,
      'to_status', p_target, 'correlation_id', v_corr);
  END IF;

  IF v_order.status IN ('paid','cancelled','closed') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED: use refund/reversal workflow for paid orders'
      USING ERRCODE = 'P0001';
  END IF;

  -- K-G3: registry-aligned FORWARD whitelist (no skip of the producing step,
  -- no backward). Matches the frozen item machine's ->target edges:
  CASE p_target
    WHEN 'sent'      THEN v_ok_from := ARRAY['pending','reserved'];
    WHEN 'accepted'  THEN v_ok_from := ARRAY['sent'];
    WHEN 'preparing' THEN v_ok_from := ARRAY['accepted','reserved'];
    WHEN 'ready'     THEN v_ok_from := ARRAY['preparing','accepted','sent','pending','reserved','recalled','bar','hot','sushi'];
    WHEN 'served'    THEN v_ok_from := ARRAY['ready'];
    WHEN 'completed' THEN v_ok_from := ARRAY['served'];
    ELSE
      RAISE EXCEPTION 'UNKNOWN_TARGET: % (forward targets: sent, accepted, preparing, ready, served, completed)', p_target
        USING ERRCODE = 'P0001';
  END CASE;
  IF NOT (v_item.kitchen_status = ANY(v_ok_from)) THEN
    RAISE EXCEPTION 'INVALID_ITEM_TRANSITION: % → % not allowed on canonical path (corrections via terminal/recall workflow)',
      v_item.kitchen_status, p_target USING ERRCODE='P0001';
  END IF;

  -- registry check (also re-validated by the trigger)
  v_rule := validate_transition('item', v_item.kitchen_status, p_target);
  IF NOT (v_rule->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_ITEM_TRANSITION: % → % (%)',
      v_item.kitchen_status, p_target, v_rule->>'error' USING ERRCODE='P0001';
  END IF;

  v_allowed := authorize(
    p_token,
    COALESCE(v_rule->>'requires_permission', 'kitchen.manage'),
    v_order.location_id
  );
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: % → % requires [%] at % (reason: %)',
      v_item.kitchen_status, p_target,
      COALESCE(v_rule->>'requires_permission','kitchen.manage'),
      v_order.location_id, v_allowed->>'reason' USING ERRCODE='P0001';
  END IF;

  UPDATE order_items SET
    kitchen_status = p_target,
    updated_at = now()
  WHERE id = p_item_id
  RETURNING id, kitchen_status, sent_at, accepted_at, started_at, ready_at, served_at, completed_at
  INTO v_updated;

  PERFORM log_order_event(v_order.id, 'kitchen_status_changed',
    jsonb_build_object('item', p_item_id, 'from_status', v_item.kitchen_status),
    jsonb_build_object('item', p_item_id, 'to_status', p_target),
    jsonb_build_object('reason', p_reason, 'correlation_id', v_corr),
    v_staff_id, NULL, NULL, NULL);

  INSERT INTO operation_logs (
    operation, order_id, performed_by, reason, old_state, new_state,
    location_id, organization_id, metadata
  ) VALUES (
    v_op, v_order.id, v_staff_id, p_reason,
    jsonb_build_object('kitchen_status', v_item.kitchen_status),
    jsonb_build_object('kitchen_status', p_target),
    v_order.location_id, v_order.organization_id,
    jsonb_build_object('idempotency_key', NULL, 'correlation_id', v_corr)
  );

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', p_item_id, v_op,
    jsonb_build_object('order_id', v_order.id, 'item_id', p_item_id,
      'from_status', v_item.kitchen_status, 'to_status', p_target,
      'reason', p_reason, 'performed_by', v_staff_id, 'correlation_id', v_corr,
      'location_id', v_order.location_id),
    'pending');

  RETURN jsonb_build_object('success', true, 'idempotent', false,
    'order_item_id', v_updated.id, 'from_status', v_item.kitchen_status,
    'to_status', v_updated.kitchen_status,
    'correlation_id', v_corr);
END;
$$;


--
-- Name: item_kitchen_terminal(text, uuid, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_kitchen_terminal(p_token text, p_item_id uuid, p_action text, p_reason text, p_metadata jsonb, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_order RECORD;
  v_item RECORD;
  v_rule jsonb;
  v_allowed jsonb;
  v_target text;
  v_corr uuid := COALESCE(p_correlation_id, gen_random_uuid());
  v_op text := 'order_item.' || p_action;
  v_inv jsonb;
  v_total jsonb;
BEGIN
  IF p_action NOT IN ('voided','comped','wasted','cancelled','recalled') THEN
    RAISE EXCEPTION 'UNKNOWN_ACTION: % (allowed: voided, comped, wasted, cancelled, recalled)', p_action
      USING ERRCODE='P0001';
  END IF;
  -- 'recalled' is a KDS action, not an item status: it sends the item back to
  -- 'pending' (the frozen registry's recall semantics).
  v_target := CASE p_action WHEN 'recalled' THEN 'pending' ELSE p_action END;

  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  SELECT o.id, o.status, o.location_id, o.organization_id, o.apply_vat, o.service_charge_pct, o.total_amount INTO v_order
    FROM orders o JOIN order_items i ON i.order_id = o.id
   WHERE i.id = p_item_id FOR UPDATE OF o;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND' USING ERRCODE='P0001';
  END IF;
  SELECT * INTO v_item FROM order_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND' USING ERRCODE='P0001';
  END IF;

  -- idempotent re-entry (G4)
  IF v_item.kitchen_status = v_target THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true,
      'order_item_id', p_item_id, 'from_status', v_item.kitchen_status,
      'to_status', v_target, 'action', p_action, 'correlation_id', v_corr);
  END IF;

  -- finalized-order guard (G4): paid/closed/cancelled orders refuse KDS mutation
  IF v_order.status IN ('paid','closed','cancelled') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED: use refund/reversal workflow for % orders',
      v_order.status USING ERRCODE='P0001';
  END IF;

  -- registry = source of truth (perm + manager override per edge)
  v_rule := validate_transition('item', v_item.kitchen_status, v_target);
  IF NOT (v_rule->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_ITEM_TRANSITION: % → % (%)',
      v_item.kitchen_status, v_target, v_rule->>'error' USING ERRCODE='P0001';
  END IF;

  v_allowed := authorize(p_token, COALESCE(v_rule->>'requires_permission','kitchen.manage'), v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: % → % requires [%] at % (reason: %)',
      v_item.kitchen_status, v_target,
      COALESCE(v_rule->>'requires_permission','kitchen.manage'),
      v_order.location_id, v_allowed->>'reason' USING ERRCODE='P0001';
  END IF;

  IF COALESCE(v_rule->>'requires_manager_override','false')::boolean THEN
    IF NOT COALESCE((SELECT has_permission(v_staff_id, 'void.approve')), false)
       AND NOT COALESCE((SELECT has_permission(v_staff_id, 'refund.approve')), false)
       AND NOT EXISTS (
          SELECT 1 FROM manager_overrides mo
          WHERE mo.requested_by = v_staff_id
            AND mo.permission = COALESCE(v_rule->>'requires_permission','kitchen.manage')
            AND mo.location_id = v_order.location_id
            AND mo.status = 'APPROVED' AND mo.expires_at > now()
       ) THEN
      RAISE EXCEPTION 'MANAGER_OVERRIDE_REQUIRED: % → % (approver perm [void.approve/refund.approve])',
        v_item.kitchen_status, v_target USING ERRCODE='P0001';
    END IF;
  END IF;

  UPDATE order_items SET kitchen_status = v_target, updated_at = now()
  WHERE id = p_item_id;

  IF v_target IN ('voided','wasted') THEN
    v_inv := _inventory_reverse_item(p_item_id, COALESCE(p_reason, p_action), v_staff_id, v_corr);
  END IF;

  IF v_target IN ('voided','cancelled','comped','wasted') THEN
    v_total := calculate_order_total_v3(
      v_order.id,
      COALESCE(v_order.apply_vat, false),
      COALESCE(v_order.service_charge_pct, 0) > 0
    );
  END IF;

  PERFORM log_order_event(v_order.id, 'kitchen_status_changed',
    jsonb_build_object('item', p_item_id, 'from_status', v_item.kitchen_status),
    jsonb_build_object('item', p_item_id, 'to_status', v_target),
    jsonb_build_object('reason', p_reason, 'correlation_id', v_corr, 'action', p_action),
    v_staff_id, NULL, NULL, NULL);

  INSERT INTO operation_logs (
    operation, order_id, performed_by, reason, old_state, new_state,
    location_id, organization_id, metadata
  ) VALUES (
    v_op, v_order.id, v_staff_id, p_reason,
    jsonb_build_object('kitchen_status', v_item.kitchen_status, 'order_total', v_order.total_amount),
    jsonb_build_object('kitchen_status', v_target,
      'order_total', COALESCE(v_total->>'total', v_order.total_amount::text)),
    v_order.location_id, v_order.organization_id,
    jsonb_build_object('idempotency_key', NULL, 'correlation_id', v_corr, 'inventory', v_inv)
  );

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', p_item_id, v_op,
    jsonb_build_object('order_id', v_order.id, 'item_id', p_item_id,
      'from_status', v_item.kitchen_status, 'to_status', v_target,
      'reason', p_reason, 'performed_by', v_staff_id, 'correlation_id', v_corr,
      'location_id', v_order.location_id, 'action', p_action),
    'pending');

  RETURN jsonb_build_object('success', true, 'idempotent', false,
    'order_item_id', p_item_id, 'from_status', v_item.kitchen_status,
    'to_status', v_target, 'correlation_id', v_corr,
    'new_order_total', COALESCE(v_total->>'total', v_order.total_amount::text),
    'inventory', v_inv);
END;
$$;


--
-- Name: item_set_hold(text, uuid, boolean, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.item_set_hold(p_token text, p_item_id uuid, p_is_hold boolean, p_reason text, p_metadata jsonb, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_order RECORD;
  v_item RECORD;
  v_corr uuid := COALESCE(p_correlation_id, gen_random_uuid());
  v_allowed jsonb;
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  SELECT o.id, o.status, o.location_id, o.organization_id
    INTO v_order
    FROM orders o JOIN order_items i ON i.order_id = o.id
   WHERE i.id = p_item_id FOR UPDATE OF o;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND' USING ERRCODE='P0001';
  END IF;
  IF v_order.status IN ('paid','cancelled','closed') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED: use refund/reversal workflow' USING ERRCODE='P0001';
  END IF;
  SELECT * INTO v_item FROM order_items WHERE id = p_item_id FOR UPDATE;

  -- idempotent
  IF v_item.is_hold = p_is_hold THEN
    RETURN jsonb_build_object('success', true, 'idempotent', true, 'is_hold', v_item.is_hold, 'correlation_id', v_corr);
  END IF;

  v_allowed := authorize(p_token, 'kitchen.manage', v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: hold requires [kitchen.manage] at % (reason: %)',
      v_order.location_id, v_allowed->>'reason' USING ERRCODE='P0001';
  END IF;

  UPDATE order_items SET is_hold = p_is_hold,
    hold_until = CASE WHEN p_is_hold THEN now() ELSE NULL END,
    updated_at = now()
  WHERE id = p_item_id;

  PERFORM log_order_event(v_order.id, 'item_hold_changed',
    jsonb_build_object('item', p_item_id, 'is_hold', v_item.is_hold),
    jsonb_build_object('item', p_item_id, 'is_hold', p_is_hold),
    jsonb_build_object('reason', p_reason, 'correlation_id', v_corr),
    v_staff_id, NULL, NULL, NULL);

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', p_item_id, 'order_item.hold',
    jsonb_build_object('order_id', v_order.id, 'item_id', p_item_id, 'is_hold', p_is_hold,
      'performed_by', v_staff_id, 'correlation_id', v_corr, 'location_id', v_order.location_id),
    'pending');

  RETURN jsonb_build_object('success', true, 'idempotent', false, 'is_hold', p_is_hold, 'correlation_id', v_corr);
END;
$$;


