--
-- Name: kds_ticket_poll(uuid, uuid, text, timestamp with time zone, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kds_ticket_poll(p_location_id uuid, p_organization_id uuid, p_station text, p_since_created_at timestamp with time zone, p_since_id uuid, p_limit integer) RETURNS TABLE(id uuid, created_at timestamp with time zone, payload jsonb, anchor timestamp with time zone, oldest timestamp with time zone, resync_required boolean)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  anchor := now();

  SELECT min(o.created_at) INTO oldest
    FROM outbox_events o
   WHERE o.aggregate_type = 'kds_ticket'
     AND o.event_type = 'kds.ticket.upsert'
     AND o.payload->>'location_id' = p_location_id::text
     AND (p_organization_id IS NULL OR o.payload->>'organization_id' = p_organization_id::text)
     AND (p_station IS NULL OR o.payload->>'station' = p_station);

  -- first load (no cursor): return ONE DB-anchored row so the client anchors to
  -- the DATABASE clock (now() is guaranteed >= every event created before it,
  -- avoiding a Node/DB clock-skew gap). resync_required=true -> full DB rebuild.
  IF p_since_created_at IS NULL THEN
    RETURN QUERY
      SELECT o.id, o.created_at, o.payload, anchor, oldest, true
        FROM outbox_events o
       WHERE o.aggregate_type = 'kds_ticket'
         AND o.event_type = 'kds.ticket.upsert'
         AND o.payload->>'location_id' = p_location_id::text
         AND (p_organization_id IS NULL OR o.payload->>'organization_id' = p_organization_id::text)
         AND (p_station IS NULL OR o.payload->>'station' = p_station)
       ORDER BY o.created_at DESC, o.id DESC
       LIMIT 1;
    RETURN;
  END IF;

  -- gap = cursor is older than the oldest available event (events pruned)
  resync_required := COALESCE(oldest IS NOT NULL AND p_since_created_at < oldest, false);

  IF NOT resync_required THEN
    RETURN QUERY
      SELECT o.id, o.created_at, o.payload, anchor, oldest, false
        FROM outbox_events o
       WHERE o.aggregate_type = 'kds_ticket'
         AND o.event_type = 'kds.ticket.upsert'
         AND o.payload->>'location_id' = p_location_id::text
         AND (p_organization_id IS NULL OR o.payload->>'organization_id' = p_organization_id::text)
         AND (p_station IS NULL OR o.payload->>'station' = p_station)
         AND (o.created_at > p_since_created_at
              OR (o.created_at = p_since_created_at AND o.id > p_since_id))
       ORDER BY o.created_at ASC, o.id ASC
       LIMIT GREATEST(1, COALESCE(p_limit, 200));
  END IF;
END;
$$;


--
-- Name: kitchen_order_items_action(text, uuid, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.kitchen_order_items_action(p_token text, p_order_id uuid, p_action text, p_reason text, p_correlation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_order RECORD;
  v_perm text;
  v_allowed jsonb;
  v_item_ids uuid[];
  v_item_id uuid;
  v_done int := 0;
  v_denied int := 0;
  v_finalized int := 0;
  v_idem int := 0;
BEGIN
  IF p_action NOT IN ('cancel','recall') THEN
    RAISE EXCEPTION 'UNKNOWN_ACTION: % (allowed: cancel, recall)', p_action USING ERRCODE='P0001';
  END IF;
  v_perm := CASE p_action WHEN 'cancel' THEN 'order.void' ELSE 'kitchen.manage' END;

  -- identity + order lock
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE='P0001';
  END IF;

  -- order-level permission + location gate (fast fail, then per-item re-check)
  v_allowed := authorize(p_token, v_perm, v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: order % % requires [%] at % (reason: %)',
      p_order_id, p_action, v_perm, v_order.location_id, v_allowed->>'reason' USING ERRCODE='P0001';
  END IF;

  -- target items (not already terminal)
  IF p_action = 'cancel' THEN
    SELECT array_agg(id) INTO v_item_ids FROM order_items
      WHERE order_id = p_order_id AND kitchen_status NOT IN ('cancelled','voided','comped','wasted');
  ELSE
    SELECT array_agg(id) INTO v_item_ids FROM order_items
      WHERE order_id = p_order_id AND kitchen_status NOT IN ('pending','cancelled','voided','comped','wasted');
  END IF;

  IF v_item_ids IS NULL OR array_length(v_item_ids,1) IS NULL THEN
    RETURN jsonb_build_object('success', true, 'order_id', p_order_id, 'action', p_action,
      'cancelled', 0, 'done', 0, 'note', 'no target items');
  END IF;

  FOREACH v_item_id IN ARRAY v_item_ids LOOP
    BEGIN
      IF p_action = 'cancel' THEN
        PERFORM item_kitchen_terminal(p_token, v_item_id, 'cancelled', p_reason, NULL, p_correlation_id);
      ELSE
        -- recall = send-back-to-pending (terminal fn maps 'recalled' -> pending)
        PERFORM item_kitchen_terminal(p_token, v_item_id, 'recalled', p_reason, NULL, p_correlation_id);
      END IF;
      v_done := v_done + 1;
    EXCEPTION WHEN SQLSTATE 'P0001' THEN
      IF SQLERRM LIKE 'ORDER_FINALIZED%' THEN v_finalized := v_finalized + 1;
      ELSIF SQLERRM LIKE 'PERMISSION_DENIED%' OR SQLERRM LIKE 'MANAGER_OVERRIDE_REQUIRED%' THEN v_denied := v_denied + 1;
      ELSIF SQLERRM LIKE 'INVALID_ITEM_TRANSITION%' THEN v_denied := v_denied + 1;
      ELSE RAISE; END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object('success', v_denied = 0 OR v_done > 0,
    'order_id', p_order_id, 'action', p_action,
    'total', array_length(v_item_ids,1), 'done', v_done,
    'denied', v_denied, 'finalized_skipped', v_finalized,
    'performed_by', v_staff_id);
END;
$$;


