--
-- Name: login_commit(uuid, boolean, text, text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.login_commit(p_candidate_id uuid, p_success boolean, p_ip text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text, p_failure_reason text DEFAULT NULL::text, p_pin_banned boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_s RECORD;
  v_role_name text;
  v_token uuid;
  v_expires timestamptz;
  v_loc uuid;
  v_ip inet;
BEGIN
  IF p_ip IS NOT NULL AND p_ip <> '' THEN
    BEGIN
      v_ip := p_ip::inet;
    EXCEPTION WHEN OTHERS THEN
      v_ip := NULL;
    END;
  END IF;

  SELECT * INTO v_s FROM staff WHERE id = p_candidate_id FOR UPDATE;
  IF FOUND THEN
    SELECT r.name INTO v_role_name FROM roles r WHERE r.id = v_s.role_id;
  END IF;

  IF NOT FOUND THEN
    IF NOT p_success THEN
      INSERT INTO login_attempts (staff_id, success, failure_reason, ip_address, user_agent)
      VALUES (NULL, false, p_failure_reason, v_ip, p_user_agent);
    END IF;
    RETURN jsonb_build_object('success', false, 'reason', 'invalid');
  END IF;

  -- ====== FAIL path ======
  IF NOT p_success THEN
    INSERT INTO login_attempts (staff_id, success, failure_reason, ip_address, user_agent)
    VALUES (v_s.id, false, p_failure_reason, v_ip, p_user_agent);

    IF v_s.pin_hash NOT LIKE 'pbkdf2_sha256$260000%' THEN
      INSERT INTO security_events (staff_id, event_type, success, ip_address, user_agent, metadata)
      VALUES (v_s.id, 'weak_pin_hash_attempt', false, v_ip, p_user_agent,
        jsonb_build_object('reason', 'legacy_hash_format'));
    ELSE
      UPDATE staff SET failed_login_attempts = coalesce(failed_login_attempts, 0) + 1
      WHERE id = v_s.id;
      IF coalesce(v_s.failed_login_attempts, 0) + 1 >= 5 THEN
        UPDATE staff SET locked_until = now() + interval '15 minutes', failed_login_attempts = 0
        WHERE id = v_s.id;
        INSERT INTO security_events (staff_id, event_type, success, ip_address, user_agent, metadata)
        VALUES (v_s.id, 'lockout', false, v_ip, p_user_agent,
          jsonb_build_object('reason', '5_failed_attempts', 'locked_minutes', 15));
      ELSE
        INSERT INTO security_events (staff_id, event_type, success, ip_address, user_agent, metadata)
        VALUES (v_s.id, 'login_failed', false, v_ip, p_user_agent,
          jsonb_build_object('reason', coalesce(p_failure_reason, 'invalid_pin')));
      END IF;
    END IF;
    RETURN jsonb_build_object('success', false, 'reason', 'invalid');
  END IF;

  -- ====== SUCCESS path (race-safe) ======
  IF v_s.status <> 'ACTIVE' OR NOT v_s.is_active THEN
    INSERT INTO security_events (staff_id, event_type, success, ip_address, user_agent, metadata)
    VALUES (v_s.id, 'login_rejected_inactive', false, v_ip, p_user_agent,
      jsonb_build_object('status', v_s.status, 'is_active', v_s.is_active));
    RETURN jsonb_build_object('success', false, 'reason', 'inactive');
  END IF;
  IF v_s.locked_until IS NOT NULL AND v_s.locked_until > now() THEN
    INSERT INTO login_attempts (staff_id, success, failure_reason, ip_address, user_agent)
    VALUES (v_s.id, false, 'locked', v_ip, p_user_agent);
    RETURN jsonb_build_object('success', false, 'reason', 'invalid');
  END IF;
  IF v_s.pin_hash NOT LIKE 'pbkdf2_sha256$260000%' THEN
    -- G2: weak/legacy hash can never legitimately verify → never log in
    INSERT INTO security_events (staff_id, event_type, success, ip_address, user_agent, metadata)
    VALUES (v_s.id, 'weak_pin_hash_attempt', true, v_ip, p_user_agent,
      jsonb_build_object('reason', 'legacy_hash_rejected'));
    RETURN jsonb_build_object('success', false, 'reason', 'invalid');
  END IF;
  IF p_pin_banned THEN
    -- G1: banned default PIN → HARD reject (generic, no enumeration)
    INSERT INTO login_attempts (staff_id, success, failure_reason, ip_address, user_agent)
    VALUES (v_s.id, false, 'banned_pin', v_ip, p_user_agent);
    INSERT INTO security_events (staff_id, event_type, success, ip_address, user_agent, metadata)
    VALUES (v_s.id, 'weak_pin_login', false, v_ip, p_user_agent,
      jsonb_build_object('reason', 'banned_default_pin', 'action', 'pin_change_required'));
    RETURN jsonb_build_object('success', false, 'reason', 'banned_pin');
  END IF;

  v_token := gen_random_uuid();
  v_expires := now() + interval '12 hours';

  SELECT l.location_id INTO v_loc
  FROM staff_locations l
  WHERE l.staff_id = v_s.id AND l.active = true
    AND (l.is_primary = true OR NOT EXISTS (
        SELECT 1 FROM staff_locations l2
        WHERE l2.staff_id = v_s.id AND l2.active = true AND l2.is_primary = true))
  LIMIT 1;

  INSERT INTO sessions (token, user_id, role, expires_at, status,
                        organization_id, active_location_id)
  VALUES (v_token, v_s.id, coalesce(normalize_role(v_role_name), 'cashier'),
          v_expires, 'ACTIVE', v_s.organization_id, v_loc);

  INSERT INTO login_attempts (staff_id, success, ip_address, user_agent)
  VALUES (v_s.id, true, v_ip, p_user_agent);
  INSERT INTO security_events (staff_id, event_type, success, ip_address, user_agent, metadata)
  VALUES (v_s.id, 'login', true, v_ip, p_user_agent,
    jsonb_build_object('role', v_role_name, 'method', 'pin'));

  UPDATE staff SET failed_login_attempts = 0, locked_until = NULL, last_login_at = now()
  WHERE id = v_s.id;

  RETURN jsonb_build_object(
    'success', true, 'token', v_token, 'expires_at', v_expires,
    'staff_id', v_s.id, 'name', coalesce(v_s.full_name, v_s.name),
    'role', v_role_name, 'canonical_role', coalesce(normalize_role(v_role_name), 'cashier'),
    'shift', v_s.shift, 'pin_change_required', false
  );
END;
$_$;


--
-- Name: login_preflight(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.login_preflight(p_ip text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_ip_fails INT;
  v_candidates JSONB;
  v_row RECORD;
BEGIN
  -- 1) IP rate-limit: 10 wrong / 5 dəq
  -- IP rate-limit: 10 wrong/IP/5 dəq.
  -- LAN qeydi: restoran POS-ları eyni NAT/IP arxasında ola bilər → 10 fail
  -- bütün kassaları kilidləyə bilər. Buna görə:
  --   (a) per-staff lock (5 cəhd/15 dəq) əsas brute-force guard-dır,
  --   (b) IP limiti + GLOBAL backstop (50 wrong / 5 dəq — bütün sistem)
  --       real saldırını saxlayır, amma normal LAN istifadəsində nadir hallarda
  --       yalnız 5 dəq gözləmə tələb edir.
  IF p_ip IS NOT NULL THEN
    BEGIN
      SELECT count(*) INTO v_ip_fails
      FROM login_attempts
      WHERE success = false
        AND ip_address = p_ip::inet
        AND created_at > now() - interval '5 minutes';
    EXCEPTION WHEN OTHERS THEN
      v_ip_fails := 0;  -- invalid IP literal → no rate-limit for it
    END;
    IF v_ip_fails >= 10 THEN
      RETURN jsonb_build_object(
        'action', 'ip_locked',
        'retry_after_seconds', 300,
        'message', 'Çoxsaylı uğursuz cəhd. 5 dəqiqə gözləyin.'
      );
    END IF;
  END IF;

  -- Global backstop: 50 wrong / 5 dəq (bütün IP) — real brute-force.
  SELECT count(*) INTO v_ip_fails
  FROM login_attempts
  WHERE success = false
    AND created_at > now() - interval '5 minutes';
  IF v_ip_fails >= 50 THEN
    RETURN jsonb_build_object(
      'action', 'ip_locked',
      'retry_after_seconds', 300,
      'message', 'Sistem müvəqqəti əlçatansızdır. 5 dəqiqə sonra təkrar yoxlayın.'
    );
  END IF;

  -- 2) Candidates: active + ACTIVE + valid pbkdf2-260k hash (bounded loop,
  --    gate §2). Weak-hash staff candidate-DA DAXİL OLUR (login_commit-də
  --    weak_pin_hash event + inactive — amma route verify edə bilməz,
  --    deməli onları da göndəririk ki, route 'weak' flagini qoysun).
  SELECT coalesce(jsonb_agg(jsonb_build_object(
      'id', s.id,
      'pin_hash', s.pin_hash,
      'weak', s.pin_hash NOT LIKE 'pbkdf2_sha256$260000%'
  )), '[]'::jsonb) INTO v_candidates
  FROM staff s
  WHERE s.is_active = true
    AND s.status = 'ACTIVE'
    AND s.pin_hash IS NOT NULL
    AND s.pin_hash <> '';

  RETURN jsonb_build_object(
    'action', 'proceed',
    'candidates', v_candidates
  );
END;
$_$;


--
-- Name: loyalty_earn(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_earn(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order    RECORD;
  v_item     RECORD;
  v_acct     uuid;
  v_total    integer := 0;
  v_key      text;
  v_post     jsonb;
  v_pts_item integer;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_NOT_FOUND');
  END IF;
  IF v_order.customer_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'no_customer');
  END IF;
  -- Idempotent: already earned on this order (status flip retry).
  IF COALESCE(v_order.loyalty_points_earned, 0) > 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'already_earned', 'points', v_order.loyalty_points_earned);
  END IF;

  FOR v_item IN
    SELECT id, quantity, total_price, unit_price FROM public.order_items
     WHERE order_id = p_order_id
       AND COALESCE(kitchen_status, 'pending') NOT IN ('cancelled','voided','wasted')
  LOOP
    v_pts_item := public.loyalty_item_points(v_item.id);
    v_total    := v_total + v_pts_item;
    -- 000009: persist the per-item grant now — the item row may be DELETED
    -- later by a full refund, and the reversal must not depend on it.
    INSERT INTO public.loyalty_order_points (order_item_id, order_id, customer_id, points_earned, quantity_at_earn)
    VALUES (v_item.id, p_order_id, v_order.customer_id, v_pts_item, GREATEST(COALESCE(v_item.quantity, 1), 0))
    ON CONFLICT (order_item_id) DO UPDATE
      SET points_earned = EXCLUDED.points_earned,
          quantity_at_earn = EXCLUDED.quantity_at_earn;
  END LOOP;

  IF v_total <= 0 THEN
    UPDATE public.orders SET loyalty_points_earned = 0 WHERE id = p_order_id;
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'zero_points');
  END IF;

  v_acct := public.loyalty_ensure_account(v_order.customer_id);
  v_key  := 'earn:' || p_order_id::text;
  v_post := public._loyalty_post(v_acct, 'earn', v_total, 'order', p_order_id,
    'Spend earn (per-product rules)', p_performed_by, NULL, v_key);

  UPDATE public.orders SET loyalty_points_earned = v_total WHERE id = p_order_id;

  RETURN jsonb_build_object('success', true, 'result', 'posted',
    'points', v_total, 'balance_after', v_post->>'balance_after',
    'customer_id', v_order.customer_id, 'post', v_post);
END;
$$;


--
-- Name: loyalty_ensure_account(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_ensure_account(p_customer_id uuid) RETURNS uuid
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_acct uuid;
  v_loc  uuid;
  v_org  uuid;
BEGIN
  IF p_customer_id IS NULL THEN RETURN NULL; END IF;

  SELECT id INTO v_acct FROM public.loyalty_accounts
   WHERE customer_id = p_customer_id
   ORDER BY created_at LIMIT 1;
  IF FOUND THEN RETURN v_acct; END IF;

  -- Inherit org/location from the customer's most recent order, else NULL.
  SELECT organization_id, location_id INTO v_org, v_loc
    FROM public.orders
   WHERE customer_id = p_customer_id
     AND organization_id IS NOT NULL
   ORDER BY created_at DESC LIMIT 1;

  INSERT INTO public.loyalty_accounts
    (customer_id, organization_id, location_id, points_balance, total_earned, total_redeemed, is_active)
  VALUES (p_customer_id, v_org, v_loc, 0, 0, 0, true)
  ON CONFLICT (customer_id, organization_id) DO UPDATE SET customer_id = EXCLUDED.customer_id
  RETURNING id INTO v_acct;
  IF NOT FOUND THEN
    SELECT id INTO v_acct FROM public.loyalty_accounts
     WHERE customer_id = p_customer_id ORDER BY created_at LIMIT 1;
  END IF;
  RETURN v_acct;
END;
$$;


--
-- Name: loyalty_item_points(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_item_points(p_order_item_id uuid) RETURNS integer
    LANGUAGE plpgsql STABLE
    AS $$
DECLARE
  v_item   RECORD;
  v_prod   RECORD;
  v_cfg    RECORD;
  v_rule   RECORD;
  v_pts    integer;
BEGIN
  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id;
  IF NOT FOUND THEN RETURN 0; END IF;

  SELECT * INTO v_cfg FROM public.settings WHERE id = '1';
  IF NOT FOUND OR COALESCE(v_cfg.loyalty_enabled, false) = false THEN
    RETURN 0;
  END IF;

  IF v_item.product_id IS NOT NULL THEN
    SELECT * INTO v_prod FROM public.products WHERE id = v_item.product_id;
  END IF;

  -- (1) product rule
  IF v_item.product_id IS NOT NULL THEN
    SELECT * INTO v_rule FROM public.loyalty_product_rules
     WHERE scope = 'product' AND product_id = v_item.product_id AND is_active
     ORDER BY created_at LIMIT 1;
  END IF;
  -- (2) category rule
  IF v_rule.id IS NULL AND v_prod.category_id IS NOT NULL THEN
    SELECT * INTO v_rule FROM public.loyalty_product_rules
     WHERE scope = 'category' AND category_id = v_prod.category_id AND is_active
     ORDER BY created_at LIMIT 1;
  END IF;

  IF v_rule.id IS NOT NULL THEN
    IF v_rule.mode = 'points_per_unit' THEN
      v_pts := v_rule.points_per_unit * GREATEST(COALESCE(v_item.quantity, 1), 0);
    ELSE
      v_pts := floor(COALESCE(v_item.total_price, v_item.unit_price * COALESCE(v_item.quantity, 1), 0) * v_rule.multiplier);
    END IF;
    IF v_rule.cap_points_per_order IS NOT NULL THEN
      v_pts := LEAST(v_pts, v_rule.cap_points_per_order);
    END IF;
    RETURN GREATEST(v_pts, 0);
  END IF;

  -- (3) default: order-level spend rate on the item's total
  RETURN GREATEST(floor(COALESCE(v_item.total_price, 0) * COALESCE(v_cfg.loyalty_points_per_manat, 1)), 0);
END;
$$;


--
-- Name: loyalty_redeem(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_redeem(p_order_id uuid, p_points integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_order  RECORD;
  v_cfg    RECORD;
  v_acct   uuid;
  v_value  numeric;
  v_key    text;
  v_post   jsonb;
  v_total  jsonb;
BEGIN
  IF p_points IS NULL OR p_points <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'POINTS_REQUIRED');
  END IF;

  SELECT * INTO v_cfg FROM public.settings WHERE id = '1';
  IF NOT FOUND OR COALESCE(v_cfg.loyalty_enabled, false) = false THEN
    RETURN jsonb_build_object('success', false, 'error', 'LOYALTY_DISABLED');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_NOT_FOUND');
  END IF;
  IF v_order.customer_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_CUSTOMER_ATTACHED');
  END IF;
  IF COALESCE(v_order.status, '') IN ('paid','closed','cancelled','voided','refunded') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_NOT_OPEN');
  END IF;
  IF v_order.discount_amount > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'ALREADY_HAS_DISCOUNT');
  END IF;

  v_acct := public.loyalty_ensure_account(v_order.customer_id);
  IF v_acct IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'NO_LOYALTY_ACCOUNT');
  END IF;

  IF p_points > COALESCE((SELECT points_balance FROM public.loyalty_accounts WHERE id = v_acct), 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'INSUFFICIENT_POINTS',
                              'balance', (SELECT points_balance FROM public.loyalty_accounts WHERE id = v_acct));
  END IF;
  IF p_points < COALESCE(v_cfg.loyalty_min_redeem, 10) THEN
    RETURN jsonb_build_object('success', false, 'error', 'BELOW_MINIMUM',
                              'min', COALESCE(v_cfg.loyalty_min_redeem, 10));
  END IF;

  v_value  := ROUND(p_points * COALESCE(v_cfg.loyalty_point_value, 0.01), 2);
  IF v_value > COALESCE(v_order.total_amount, 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'EXCEEDS_ORDER_TOTAL', 'value', v_value);
  END IF;

  v_key := 'redeem:' || p_order_id::text;
  v_post := public._loyalty_post(v_acct, 'redeem', -p_points, 'order', p_order_id,
    'Redeemed as discount', p_performed_by, NULL, v_key);
  IF (v_post->>'result') = 'idempotent_replay' THEN
    RETURN v_post;
  END IF;
  IF COALESCE((v_post->>'success')::boolean, false) = false THEN
    RETURN v_post;
  END IF;

  -- Apply discount to order + SSOT total recompute (preserves vat flags).
  UPDATE public.orders SET
    discount_amount = v_value,
    discount_type   = 'loyalty',
    updated_at      = NOW()
  WHERE id = p_order_id;

  v_total := public.calculate_order_total_v3(
    p_order_id,
    COALESCE(v_order.apply_vat, false),
    COALESCE(v_order.service_charge_pct, 0) > 0
  );

  RETURN jsonb_build_object('success', true, 'result', 'redeemed',
    'points', -p_points, 'discount_value', v_value,
    'new_total', v_total->>'total', 'post', v_post);
END;
$$;


--
-- Name: loyalty_reverse(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_reverse(p_order_id uuid, p_reason text DEFAULT 'refund'::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_order RECORD;
  v_pts   integer;
  v_acct  uuid;
  v_key   text;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_NOT_FOUND');
  END IF;
  IF v_order.customer_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'no_customer');
  END IF;

  SELECT COALESCE(MAX(points), 0) INTO v_pts
    FROM public.loyalty_transactions
   WHERE reference_type = 'order' AND reference_id = p_order_id AND type = 'earn';
  IF COALESCE(v_pts, 0) <= 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'nothing_earned');
  END IF;

  v_acct := public.loyalty_ensure_account(v_order.customer_id);
  v_key  := 'reverse:' || p_order_id::text;

  -- NOTE: ledger CHECK constraint allows 'reversal' (not 'reverse').
  RETURN public._loyalty_post(v_acct, 'reversal', -v_pts, 'order', p_order_id,
    COALESCE(p_reason, 'refund'), p_performed_by, NULL, v_key);
END;
$$;


--
-- Name: loyalty_reverse(uuid, uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.loyalty_reverse(p_order_id uuid, p_order_item_id uuid DEFAULT NULL::uuid, p_reason text DEFAULT 'refund'::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order      RECORD;
  v_item_live  RECORD;
  v_acct       uuid;
  v_pts        integer := 0;
  v_snap       public.loyalty_order_points%ROWTYPE;
  v_key        text;
  v_post       jsonb;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_NOT_FOUND');
  END IF;
  IF v_order.customer_id IS NULL THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'no_customer');
  END IF;
  IF COALESCE(v_order.loyalty_points_earned, 0) <= 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'nothing_earned');
  END IF;

  IF p_order_item_id IS NULL THEN
    -- Full reversal: everything still counted in the snapshot (or recomputed
    -- for pre-migration orders without snapshot rows).
    FOR v_snap IN
      SELECT * FROM public.loyalty_order_points
       WHERE order_id = p_order_id
    LOOP
      v_pts := v_pts + v_snap.points_earned;
    END LOOP;
    IF v_pts = 0 THEN
      -- Pre-migration fallback: recompute from live item rows.
      FOR v_item_live IN
        SELECT id FROM public.order_items
         WHERE order_id = p_order_id
           AND COALESCE(kitchen_status, 'pending') NOT IN ('cancelled','voided','wasted')
      LOOP
        v_pts := v_pts + public.loyalty_item_points(v_item_live.id);
      END LOOP;
    END IF;
    v_key := 'reversal:' || p_order_id::text || ':all';
    UPDATE public.orders SET loyalty_points_earned = 0 WHERE id = p_order_id;
  ELSE
    -- 000009: snapshot FIRST — survives refund_with_inventory deleting the
    -- item row on a full-quantity refund (the old recompute returned 0 and
    -- silently kept the customer's points).
    SELECT * INTO v_snap FROM public.loyalty_order_points
     WHERE order_item_id = p_order_item_id AND order_id = p_order_id;
    IF FOUND THEN
      v_pts := v_snap.points_earned;
    ELSE
      v_pts := public.loyalty_item_points(p_order_item_id);
    END IF;
    v_key := 'reversal:' || p_order_id::text || ':' || p_order_item_id::text;
    UPDATE public.orders SET
      loyalty_points_earned = GREATEST(COALESCE(loyalty_points_earned, 0) - v_pts, 0)
    WHERE id = p_order_id;
  END IF;

  IF v_pts <= 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'skipped', 'reason', 'zero_points');
  END IF;

  v_acct := public.loyalty_ensure_account(v_order.customer_id);
  v_post := public._loyalty_post(v_acct, 'reversal', -v_pts, 'order', p_order_id,
    COALESCE(p_reason, 'refund'), p_performed_by, NULL, v_key);

  RETURN jsonb_build_object('success', true, 'result', 'posted',
    'points', -v_pts, 'balance_after', v_post->>'balance_after', 'post', v_post);
END;
$$;


--
-- Name: mark_delivered(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_delivered(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- Free courier
  IF v_order.courier_id IS NOT NULL THEN
    UPDATE couriers SET
      current_order_id = NULL,
      total_deliveries = total_deliveries + 1
    WHERE id = v_order.courier_id;
  END IF;

  UPDATE orders SET
    status = 'paid',
    delivery_status = 'delivered',
    delivered_at = now(),
    paid_at = now(),
    kitchen_status = 'completed',
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  PERFORM log_order_event(
    p_order_id, 'order_delivered',
    jsonb_build_object('delivery_status', v_order.delivery_status),
    jsonb_build_object('delivered_at', now()),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id);
END;
$$;


--
-- Name: mark_item_preparing(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_item_preparing(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE order_items SET
    kitchen_status = 'preparing',
    station = COALESCE(station, 'all')
  WHERE id = p_item_id
    AND kitchen_status IN ('pending', 'accepted');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND_OR_INVALID_STATUS' USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object('success', true, 'item_id', p_item_id, 'status', 'preparing');
END;
$$;


--
-- Name: mark_item_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_item_ready(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE order_items SET
    kitchen_status = 'ready'
  WHERE id = p_item_id
    AND kitchen_status IN ('preparing', 'cooking');

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND_OR_INVALID_STATUS' USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object('success', true, 'item_id', p_item_id, 'status', 'ready');
END;
$$;


--
-- Name: mark_item_ready_atomic(uuid, uuid[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_item_ready_atomic(p_order_id uuid, p_item_ids uuid[] DEFAULT NULL::uuid[], p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item_id uuid;
  v_oi RECORD;
  v_order RECORD;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
  v_marked INT := 0;
  v_skipped INT := 0;
  v_stock_failed INT := 0;
  v_already_ready INT := 0;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtext('mark_ready:' || p_order_id::text));

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status IN ('paid', 'closed', 'refunded', 'cancelled') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot mark items ready on ' || v_order.status || ' order');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  IF p_item_ids IS NULL THEN
    SELECT array_agg(id) INTO p_item_ids
    FROM public.order_items
    WHERE order_id = p_order_id
      AND kitchen_status NOT IN ('ready', 'completed', 'served', 'cancelled', 'voided');
  END IF;

  FOREACH v_item_id IN ARRAY p_item_ids
  LOOP
    SELECT * INTO v_oi FROM public.order_items WHERE id = v_item_id AND order_id = p_order_id FOR UPDATE;
    IF NOT FOUND THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    IF v_oi.kitchen_status IN ('ready', 'completed', 'served') THEN
      v_already_ready := v_already_ready + 1;
      CONTINUE;
    END IF;

    IF v_oi.kitchen_status NOT IN ('pending', 'accepted', 'sent', 'preparing') THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    BEGIN
      UPDATE public.order_items SET kitchen_status = 'ready', updated_at = v_now WHERE id = v_item_id;
      PERFORM public.consume_stock_for_item(v_item_id, p_order_id, v_oi.product_id, v_oi.quantity, p_performed_by);
      v_marked := v_marked + 1;
    EXCEPTION WHEN OTHERS THEN
      UPDATE public.order_items SET kitchen_status = v_oi.kitchen_status WHERE id = v_item_id;
      v_stock_failed := v_stock_failed + 1;
    END;
  END LOOP;

  IF NOT EXISTS (
    SELECT 1 FROM public.order_items
    WHERE order_id = p_order_id AND kitchen_status NOT IN ('ready', 'completed', 'served', 'cancelled', 'voided')
  ) THEN
    UPDATE public.orders SET kitchen_status = 'ready', kitchen_ready_at = v_now WHERE id = p_order_id;
  END IF;

  PERFORM public.log_audit(
    'mark_ready', 'order', p_order_id::text,
    p_performed_by, v_performer_name, NULL,
    jsonb_build_object(
      'marked_ready', v_marked, 'skipped', v_skipped,
      'stock_failed', v_stock_failed, 'already_ready', v_already_ready
    ),
    jsonb_build_object('order_id', p_order_id), NULL
  );

  RETURN jsonb_build_object(
    'success', true, 'action', 'mark_ready',
    'marked_ready', v_marked, 'skipped', v_skipped,
    'stock_failed', v_stock_failed, 'already_ready', v_already_ready,
    'order_id', p_order_id, 'timestamp', v_now
  );
END;
$$;


--
-- Name: mark_item_served(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_item_served(p_item_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE order_items SET
    kitchen_status = 'served',
    served_at = now()
  WHERE id = p_item_id
    AND kitchen_status = 'ready';

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ITEM_NOT_FOUND_OR_INVALID_STATUS' USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object('success', true, 'item_id', p_item_id, 'status', 'served');
END;
$$;


--
-- Name: mark_no_show_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_no_show_atomic(p_reservation_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
BEGIN
  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;

  IF v_reservation.status NOT IN ('pending', 'confirmed', 'waiting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot mark no show in current status');
  END IF;

  UPDATE public.reservations SET
    status = 'no_show',
    updated_at = NOW()
  WHERE id = p_reservation_id;

  IF v_reservation.table_ids IS NOT NULL THEN
    UPDATE public.table_floors SET
      status = 'empty',
      reservation_id = NULL,
      reservation_name = NULL,
      reservation_phone = NULL,
      reservation_time = NULL,
      updated_at = NOW()
    WHERE table_number = ANY(
      CASE 
        WHEN jsonb_typeof(v_reservation.table_ids::jsonb) = 'array' THEN
          (SELECT array_agg(x::int) FROM jsonb_array_elements_text(v_reservation.table_ids::jsonb) AS x)
        ELSE ARRAY[]::INT[]
      END
    );
  END IF;

  INSERT INTO public.operation_logs (
    reservation_id, action, old_values, new_values, performed_by
  ) VALUES (
    p_reservation_id,
    'mark_no_show',
    jsonb_build_object('status', v_reservation.status),
    jsonb_build_object('status', 'no_show'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: mark_order_all_served(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_order_all_served(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated INTEGER;
BEGIN
  UPDATE order_items SET
    kitchen_status = 'served',
    served_at = now()
  WHERE order_id = p_order_id
    AND kitchen_status = 'ready';

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  RETURN jsonb_build_object('success', true, 'items_served', v_updated);
END;
$$;


--
-- Name: mark_order_completed(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_order_completed(p_order_id uuid, p_performed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order   record;
  v_updated int := 0;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  -- K3-6 (044): finalized-order guard (ORDER_FINALIZED).
  IF v_order.status IN ('paid','cancelled','closed') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_FINALIZED',
      'order_id', p_order_id, 'order_status', v_order.status);
  END IF;

  UPDATE public.order_items
  SET    kitchen_status = 'completed',
         updated_at = now()
  WHERE  order_id = p_order_id
  AND    kitchen_status IS DISTINCT FROM 'completed'
  AND    kitchen_status NOT IN ('voided','cancelled','wasted');

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  UPDATE public.orders
  SET    kitchen_status = 'completed',
         updated_at = now()
  WHERE  id = p_order_id;

  PERFORM public.log_audit(
    'order_completed', 'order', p_order_id::text, p_performed_by,
    NULL, NULL, NULL,
    jsonb_build_object('items_completed', v_updated),
    NULL
  );

  RETURN jsonb_build_object('success', true, 'items_completed', v_updated);
END;
$$;


--
-- Name: mark_order_ready(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_order_ready(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_oi RECORD;
  v_consumed INTEGER := 0;
  v_failed INTEGER := 0;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('error', 'ORDER_NOT_FOUND');
  END IF;

  -- K3-6 (044, 2026-09-12, ratified): finalized-order guard (ORDER_FINALIZED).
  -- A paid/cancelled/closed order is never mutated by a KDS action; no stock
  -- change (it was already consumed at the original ready).
  IF v_order.status IN ('paid','cancelled','closed') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_FINALIZED',
      'order_id', p_order_id, 'order_status', v_order.status);
  END IF;

  -- Delegate consumption to the canonical writer BEFORE the status flip,
  -- over exactly the READY-boundary transition set (idempotent per item).
  FOR v_oi IN
    SELECT oi.id, oi.product_id, oi.quantity
    FROM order_items oi
    WHERE oi.order_id = p_order_id
      AND oi.kitchen_status IN ('pending', 'preparing', 'cooking', 'accepted')
  LOOP
    BEGIN
      PERFORM public.consume_stock_for_item(v_oi.id, p_order_id, v_oi.product_id, v_oi.quantity);
      v_consumed := v_consumed + 1;
    EXCEPTION WHEN OTHERS THEN
      v_failed := v_failed + 1;
    END;
  END LOOP;

  UPDATE order_items
  SET kitchen_status = 'ready'
  WHERE order_id = p_order_id
    AND kitchen_status IN ('pending', 'preparing', 'cooking', 'accepted');

  UPDATE orders SET
    kitchen_status = 'ready',
    kitchen_ready_at = now(),
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  IF v_order.order_source = 'delivery' AND COALESCE(v_order.delivery_status, 'pending') IN ('pending', 'confirmed', 'preparing') THEN
    UPDATE orders SET delivery_status = 'ready', updated_at = now() WHERE id = p_order_id;
  END IF;

  IF v_order.order_source = 'takeaway' AND v_order.status IN ('confirmed', 'in_kitchen') THEN
    UPDATE orders SET status = 'ready', updated_at = now() WHERE id = p_order_id;
  END IF;

  IF v_order.order_source = 'dine_in' AND v_order.status IN ('confirmed', 'in_kitchen', 'partially_ready') THEN
    UPDATE orders SET status = 'ready', updated_at = now() WHERE id = p_order_id;
  END IF;

  -- (b) REMOVED: the table status SET 'ready'. The table stays 'occupied'
  --     (decision A); the floor's kitchen chip is driven by table.kitchen_status
  --     (synced by trg_sync_table_kitchen_status), never by table.status.

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'status', 'ready',
    'deducted_ingredients', v_consumed,
    'consumed_items', v_consumed,
    'consumption_failed', v_failed
  );
END;
$$;


--
-- Name: mark_ready_atomic(uuid, uuid, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_ready_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text, p_complete boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_item RECORD;
  v_deducted INT := 0;
  v_final_kitchen_status TEXT := 'ready';
BEGIN
  PERFORM public.validate_actor(p_performed_by);

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF p_complete THEN
    IF v_order.kitchen_status NOT IN ('preparing', 'accepted', 'pending', 'ready') THEN
      RETURN jsonb_build_object('success', false, 'error', 'Order cannot be completed from current status');
    END IF;
    v_final_kitchen_status := 'served';
  ELSE
    IF v_order.kitchen_status NOT IN ('preparing', 'accepted', 'pending') THEN
      RETURN jsonb_build_object('success', false, 'error', 'Order cannot be marked ready');
    END IF;
    v_final_kitchen_status := 'ready';
  END IF;

  -- Canonical consumption for served (complete) orders that weren't yet paid.
  IF p_complete AND v_order.status != 'paid' THEN
    FOR v_item IN
      SELECT oi.id, oi.product_id, oi.quantity
      FROM public.order_items oi
      WHERE oi.order_id = p_order_id
      FOR UPDATE
    LOOP
      PERFORM public.consume_stock_for_item(
        v_item.id, p_order_id, v_item.product_id, COALESCE(v_item.quantity, 1), p_performed_by
      );
      v_deducted := v_deducted + 1;
    END LOOP;
  END IF;

  UPDATE public.orders SET
    kitchen_status = v_final_kitchen_status,
    kitchen_ready_at = CASE WHEN v_final_kitchen_status IN ('ready', 'served') THEN NOW() ELSE kitchen_ready_at END,
    completed_at = CASE WHEN p_complete THEN NOW() ELSE completed_at END,
    updated_at = NOW(),
    version = COALESCE(version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  UPDATE public.order_items SET
    kitchen_status = CASE WHEN p_complete THEN 'served' ELSE 'ready' END,
    updated_at = NOW()
  WHERE order_id = p_order_id AND kitchen_status NOT IN ('cancelled', 'comped', 'wasted', 'served');

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = v_final_kitchen_status,
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'mark_ready',
    jsonb_build_object('kitchen_status', v_order.kitchen_status, 'status', v_order.status),
    jsonb_build_object('kitchen_status', v_final_kitchen_status, 'status', v_order.status, 'inventory_deducted', v_deducted),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'inventory_deducted', v_deducted);
END;
$$;


--
-- Name: mark_served_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_served_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
  v_order RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status NOT IN ('ready', 'preparing') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order cannot be marked served');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'served',
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'served',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'mark_served',
    jsonb_build_object('kitchen_status', v_order.kitchen_status),
    jsonb_build_object('kitchen_status', 'served'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: mark_service_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_service_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status NOT IN ('ready') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order must be ready before marking as served');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'service',
    updated_at = NOW()
  WHERE id = p_order_id;

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'service',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'mark_service',
    jsonb_build_object('kitchen_status', v_order.kitchen_status),
    jsonb_build_object('kitchen_status', 'service'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: mark_sold_out_atomic(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mark_sold_out_atomic(p_product_id uuid, p_product_name text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_product RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_product FROM public.products WHERE id = p_product_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Product not found');
  END IF;

  -- H10.2-AUDIT-C: availability decision only - no stock movement.
  UPDATE public.products
     SET is_available = false,
         updated_at = NOW()
   WHERE id = p_product_id;

  INSERT INTO public.operation_logs (
    action, old_values, new_values, performed_by
  ) VALUES (
    'mark_sold_out',
    jsonb_build_object('product_id', p_product_id, 'is_available', v_product.is_available),
    jsonb_build_object('product_id', p_product_id, 'is_available', false, 'stock_moved', false),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'product_id', p_product_id, 'stock_moved', false);
END;
$$;


--
-- Name: merge_entities_atomic(integer[], uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_entities_atomic(p_table_numbers integer[], p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text, p_reservation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table table_floors%ROWTYPE;
  v_reservation reservations%ROWTYPE;
  v_order_id uuid;
  v_parent_table integer;
  v_merged_group_id text;
  v_now timestamptz := NOW();
  v_table_number integer;
  v_child_order_ids uuid[] := ARRAY[]::uuid[];
  v_child_total numeric := 0;
  v_child_guests integer := 0;
  v_active_child_order RECORD;
  v_blocking_reason text;
  v_needs_order boolean := false;
  v_source_table table_floors%ROWTYPE;
BEGIN
  IF p_table_numbers IS NULL OR array_length(p_table_numbers, 1) < 2 THEN
    RETURN jsonb_build_object('success', false, 'error', 'MERGE_REQUIRES_TWO_TABLES');
  END IF;
  p_table_numbers := (SELECT array_agg(tn ORDER BY tn) FROM unnest(p_table_numbers) AS tn);
  FOR v_table_number IN SELECT unnest(p_table_numbers) LOOP
    SELECT * INTO v_table FROM table_floors WHERE table_number = v_table_number FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND', 'table_number', v_table_number);
    END IF;
    IF v_table.status NOT IN ('empty', 'dirty') THEN
      RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_AVAILABLE', 'table_number', v_table_number, 'current_status', v_table.status);
    END IF;
  END LOOP;
  IF p_reservation_id IS NOT NULL THEN
    SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
    IF NOT FOUND THEN
      RETURN jsonb_build_object('success', false, 'error', 'RESERVATION_NOT_FOUND');
    END IF;
    IF v_reservation.status NOT IN ('pending', 'confirmed', 'waiting') THEN
      RETURN jsonb_build_object('success', false, 'error', 'CANNOT_MERGE_RESERVATION_STATUS');
    END IF;
  END IF;
  v_parent_table := p_table_numbers[1];
  v_needs_order := false;
  IF p_reservation_id IS NOT NULL THEN
    v_needs_order := true;
  ELSE
    FOR v_table_number IN SELECT unnest(p_table_numbers) LOOP
      SELECT status, current_order_id INTO v_source_table.status, v_source_table.current_order_id
      FROM table_floors WHERE table_number = v_table_number;
      IF v_source_table.status IN ('occupied', 'cooking', 'waiting', 'waiting_bill')
         OR v_source_table.current_order_id IS NOT NULL THEN
        v_needs_order := true;
      END IF;
    END LOOP;
  END IF;
  IF v_needs_order THEN
    SELECT id INTO v_order_id FROM public.orders
      WHERE table_number = v_parent_table
        AND status NOT IN ('paid', 'cancelled', 'closed', 'completed')
        AND merged_into IS NULL
      ORDER BY created_at ASC LIMIT 1;
    IF v_order_id IS NULL THEN
      INSERT INTO public.orders (
        table_number, reservation_id, status, guest_count,
        customer_name, customer_phone, customer_note,
        kitchen_status, order_source, total_amount,
        created_at, updated_at, version, is_draft, merged_into
      ) VALUES (
        v_parent_table,
        p_reservation_id,
        COALESCE((SELECT status FROM reservations WHERE id = p_reservation_id), 'confirmed'),
        COALESCE(v_reservation.guests, 0),
        COALESCE(v_reservation.name, NULL),
        COALESCE(v_reservation.phone, NULL),
        COALESCE(v_reservation.note, 'Merged reservation'),
        'reserved',
        'dine_in',
        0,
        v_now,
        v_now,
        1,
        true,
        NULL
      ) RETURNING id INTO v_order_id;
    ELSE
      UPDATE public.orders SET
        reservation_id = COALESCE(p_reservation_id, reservation_id),
        updated_at = v_now
      WHERE id = v_order_id;
    END IF;
  END IF;
  FOR v_table_number IN SELECT unnest(p_table_numbers[2:]) LOOP
    SELECT array_agg(id) INTO v_child_order_ids FROM public.orders
      WHERE table_number = v_table_number
        AND status NOT IN ('paid', 'cancelled', 'closed', 'completed')
        AND merged_into IS NULL;
    IF v_child_order_ids IS NOT NULL AND array_length(v_child_order_ids, 1) > 0 THEN
      SELECT EXISTS (
        SELECT 1 FROM public.order_items
        WHERE order_id = ANY(v_child_order_ids)
          AND kitchen_status IS DISTINCT FROM 'cancelled'
          AND (quantity > 0 OR total_price > 0)
      ) OR EXISTS (
        SELECT 1 FROM public.orders
        WHERE id = ANY(v_child_order_ids)
          AND (paid_amount > 0 OR payment_method IS NOT NULL OR discount_amount > 0)
      ) INTO v_blocking_reason;
      IF v_blocking_reason THEN
        RETURN jsonb_build_object('success', false, 'error', 'ACTIVE_CHILD_ORDER_EXISTS', 'table_number', v_table_number, 'child_order_ids', v_child_order_ids);
      END IF;
    END IF;
  END LOOP;
  FOR v_table_number IN SELECT unnest(p_table_numbers[2:]) LOOP
    SELECT array_agg(id) INTO v_child_order_ids FROM public.orders
      WHERE table_number = v_table_number
        AND status NOT IN ('paid', 'cancelled', 'closed', 'completed')
        AND merged_into IS NULL;
    IF v_child_order_ids IS NOT NULL AND array_length(v_child_order_ids, 1) > 0 THEN
      SELECT COALESCE(SUM(total_amount), 0), COALESCE(SUM(guest_count), 0) INTO v_child_total, v_child_guests
      FROM public.orders WHERE id = ANY(v_child_order_ids);
      UPDATE public.orders SET
        merged_into = v_order_id,
        merged_from_table = v_table_number,
        updated_at = v_now,
        version = COALESCE(version, 0) + 1,
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE id = ANY(v_child_order_ids);
      UPDATE public.orders SET
        total_amount = COALESCE(total_amount, 0) + v_child_total,
        guest_count = COALESCE(guest_count, 0) + v_child_guests,
        updated_at = v_now,
        version = COALESCE(version, 0) + 1
      WHERE id = v_order_id;
    END IF;
  END LOOP;
  UPDATE public.table_floors SET
    merged_into_table = v_parent_table,
    status = CASE
      WHEN p_reservation_id IS NOT NULL THEN 'reserved'
      WHEN v_needs_order THEN 'occupied'
      ELSE status
    END,
    reservation_id = p_reservation_id,
    current_order_id = v_order_id,
    order_count = 0,
    updated_at = v_now,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE table_number = ANY(p_table_numbers[2:]);
  UPDATE public.table_floors SET
    status = CASE
      WHEN p_reservation_id IS NOT NULL AND status = 'empty' THEN 'reserved'
      WHEN v_needs_order THEN 'occupied'
      ELSE status
    END,
    guest_count = COALESCE(guest_count, 0) + v_child_guests,
    reservation_id = p_reservation_id,
    current_order_id = v_order_id,
    last_activity_at = v_now,
    updated_at = v_now
  WHERE table_number = v_parent_table;
  IF p_reservation_id IS NOT NULL THEN
    v_merged_group_id := 'res-group-' || p_reservation_id;
    UPDATE public.reservations SET
      table_ids = p_table_numbers,
      reservation_merge_group_id = v_merged_group_id,
      updated_at = v_now
    WHERE id = p_reservation_id;
    DELETE FROM public.reservation_tables
    WHERE reservation_id = p_reservation_id
      AND table_number = ANY(p_table_numbers[2:]);
    INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
    SELECT p_reservation_id, tn, v_now
    FROM unnest(p_table_numbers) AS tn
    ON CONFLICT (reservation_id, table_number) DO NOTHING;
  END IF;
  INSERT INTO public.operation_logs (
    table_number, order_id, reservation_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_parent_table,
    v_order_id,
    p_reservation_id,
    'merge_entities',
    jsonb_build_object('table_numbers', p_table_numbers),
    jsonb_build_object(
      'parent_table', v_parent_table,
      'order_id', v_order_id,
      'merged_group_id', v_merged_group_id,
      'reservation_id', p_reservation_id
    ),
    p_performed_by
  );
  RETURN jsonb_build_object(
    'success', true,
    'parent_table', v_parent_table,
    'order_id', v_order_id,
    'merged_group_id', v_merged_group_id
  );
END;
$$;


--
-- Name: merge_orders_atomic(uuid[], uuid, numeric, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_orders_atomic(p_source_order_ids uuid[], p_target_order_id uuid, p_extra_amount numeric DEFAULT 0, p_extra_guests integer DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target RECORD;
  v_source RECORD;
  v_merged_count INTEGER := 0;
  v_all_ids UUID[];
BEGIN
  v_all_ids := array_append(p_source_order_ids, p_target_order_id);

  -- Lock target order
  SELECT * INTO v_target FROM orders WHERE id = p_target_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TARGET_ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_target.status IN ('paid', 'cancelled', 'closed') THEN
    RAISE EXCEPTION 'TARGET_ORDER_CLOSED' USING ERRCODE = 'P0001';
  END IF;

  -- Lock and validate all source orders
  FOR v_source IN
    SELECT * FROM orders WHERE id = ANY(p_source_order_ids) FOR UPDATE
  LOOP
    IF v_source.status IN ('paid', 'cancelled', 'closed') THEN
      RAISE EXCEPTION 'SOURCE_ORDER_CLOSED' USING ERRCODE = 'P0001';
    END IF;
    IF v_source.merged_into IS NOT NULL THEN
      RAISE EXCEPTION 'SOURCE_ALREADY_MERGED' USING ERRCODE = 'P0001';
    END IF;

    -- Mark source as merged
    UPDATE orders
    SET merged_into = p_target_order_id, version = COALESCE(version, 0) + 1
    WHERE id = v_source.id;

    v_merged_count := v_merged_count + 1;
  END LOOP;

  -- Update target order totals
  UPDATE orders
  SET
    total_amount = COALESCE(v_target.total_amount, 0) + COALESCE(p_extra_amount, 0),
    guest_count = COALESCE(v_target.guest_count, 1) + COALESCE(p_extra_guests, 0),
    version = COALESCE(v_target.version, 0) + 1
  WHERE id = p_target_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'target_order_id', p_target_order_id,
    'extra_amount', p_extra_amount,
    'extra_guests', p_extra_guests,
    'new_total', COALESCE(v_target.total_amount, 0) + COALESCE(p_extra_amount, 0),
    'merged_count', v_merged_count
  );
END;
$$;


--
-- Name: merge_reservation_tables_atomic(uuid, integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_reservation_tables_atomic(p_reservation_id uuid, p_table_numbers integer[], p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table RECORD;
  v_merged_group_id TEXT;
  v_old_table_ids integer[];
BEGIN
  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;

  IF v_reservation.status NOT IN ('pending', 'confirmed', 'waiting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot merge tables in current reservation status');
  END IF;

  IF array_length(p_table_numbers, 1) < 2 THEN
    RETURN jsonb_build_object('success', false, 'error', 'At least 2 tables required for merge');
  END IF;

  v_old_table_ids := v_reservation.table_ids;

  FOR v_table IN SELECT * FROM public.table_floors WHERE table_number = ANY(p_table_numbers) FOR UPDATE LOOP
    NULL;
  END LOOP;

  v_merged_group_id := 'res-group-' || p_reservation_id;

  UPDATE public.table_floors SET
    status = 'merged',
    merged_into_table = p_table_numbers[1],
    updated_at = NOW()
  WHERE table_number = ANY(p_table_numbers);

  UPDATE public.reservations SET
    table_ids = p_table_numbers,
    reservation_merge_group_id = v_merged_group_id,
    updated_at = NOW()
  WHERE id = p_reservation_id;

  DELETE FROM public.reservation_tables 
  WHERE reservation_id = p_reservation_id 
    AND table_number != p_table_numbers[1];

  INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
  SELECT p_reservation_id, tn, NOW()
  FROM unnest(p_table_numbers) AS tn
  ON CONFLICT (reservation_id, table_number) DO NOTHING;

  PERFORM public.log_reservation_operation(
    p_reservation_id,
    'merge_reservation_tables',
    jsonb_build_object('table_ids', v_old_table_ids),
    jsonb_build_object('table_ids', p_table_numbers, 'merged_group_id', v_merged_group_id),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'merged_group_id', v_merged_group_id);
END;
$$;


--
-- Name: merge_table_to_reservation(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_table_to_reservation(p_reservation_id uuid, p_new_table_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_target_status TEXT;
  v_target_table_number INTEGER;
BEGIN
  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_reservation.status NOT IN ('pending', 'confirmed') THEN
    RAISE EXCEPTION 'RESERVATION_NOT_MOVABLE' USING ERRCODE = 'P0001';
  END IF;

  SELECT status, table_number INTO v_target_status, v_target_table_number
  FROM table_floors WHERE id = p_new_table_id FOR UPDATE;

  IF v_target_status IS NULL THEN
    RAISE EXCEPTION 'TARGET_TABLE_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_target_status != 'empty' THEN
    RAISE EXCEPTION 'TARGET_TABLE_NOT_EMPTY' USING ERRCODE = 'P0001';
  END IF;

  UPDATE table_floors SET
    status = 'reserved',
    reservation_id = p_reservation_id,
    reservation_name = v_reservation.name || v_reservation.customer_name,
    reservation_phone = v_reservation.phone,
    reservation_time = v_reservation.time,
    guest_count = v_reservation.guests
  WHERE id = p_new_table_id;

  UPDATE reservations SET
    table_ids = COALESCE(table_ids, '[]'::jsonb) || jsonb_build_array(p_new_table_id::text),
    updated_at = now()
  WHERE id = p_reservation_id;

  RETURN jsonb_build_object(
    'success', true,
    'new_table', v_target_table_number,
    'reservation_id', p_reservation_id
  );
END;
$$;


--
-- Name: merge_tables_atomic(text, integer, integer[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_tables_atomic(p_token text, p_parent_table_number integer, p_child_table_numbers integer[], p_performed_by uuid, p_performed_by_terminal_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_parent        table_floors;
  v_child         table_floors;
  v_parent_order  orders;
  v_child_order   orders;
  v_children      int[];
  v_parent_kind   text;
  v_child_kind    text;
  v_mode          text;
  v_group         text;
  v_resv_id       uuid;
  v_resv_name     text;
  v_resv_phone    text;
  v_resv_time     text;
  v_parent_order_id uuid;
  v_canonical_from  int;      -- table that currently hosts the group's canonical order
  v_resv_bound    int;
  v_resv_unbound  int;
  v_resv_distinct int;
  v_occ_count     int;
  v_r             int;
  v_paid          int;
  v_merged        int := 0;
  v_children_summary jsonb := '[]'::jsonb;
  v_children_lineage jsonb := '[]'::jsonb;
  v_old_state     jsonb;
BEGIN
  PERFORM public.set_session_staff(p_token);
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  PERFORM public.validate_actor(p_performed_by);

  IF p_parent_table_number = ANY(p_child_table_numbers) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_PARENT_IN_CHILD');
  END IF;
  v_children := (SELECT array_agg(tn ORDER BY tn) FROM (SELECT DISTINCT unnest(p_child_table_numbers) AS tn) x);
  IF v_children IS NULL OR array_length(v_children, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_NO_CHILDREN');
  END IF;

  SELECT * INTO v_parent FROM public.table_floors
   WHERE table_number = p_parent_table_number AND (v_sess_loc IS NULL OR location_id = v_sess_loc) FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  IF NOT has_location_access(v_parent.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE table_number = ANY(v_children) AND location_id <> v_parent.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE table_number = ANY(v_children) AND NOT has_location_access(location_id)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF v_parent.merged_into_table IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_PARENT_ALREADY_MERGED');
  END IF;

  -- lock children deterministically after parent
  FOR v_child IN SELECT * FROM public.table_floors
                 WHERE table_number = ANY(v_children) ORDER BY table_number FOR UPDATE LOOP
    NULL;
  END LOOP;
  IF (SELECT count(*) FROM public.table_floors WHERE table_number = ANY(v_children)) <> array_length(v_children, 1) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_CHILD_NOT_FOUND');
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE table_number = ANY(v_children)
             AND (location_id IS DISTINCT FROM v_parent.location_id
                  OR organization_id IS DISTINCT FROM v_parent.organization_id)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_LOCATION_MISMATCH');
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE table_number = ANY(v_children)
             AND merged_into_table IS NOT NULL) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_CHILD_ALREADY_MERGED');
  END IF;

  -- ---- classify parent + children by status ----
  v_parent_kind := CASE v_parent.status WHEN 'occupied' THEN 'occupied'
                                        WHEN 'reserved' THEN 'reserved'
                                        WHEN 'empty'    THEN 'empty' ELSE 'other' END;
  IF v_parent_kind = 'other' THEN
    RETURN jsonb_build_object('success', false, 'error',
      'G_MERGE_TABLE_STATE_INVALID (parent=' || p_parent_table_number || ')');
  END IF;

  SELECT
    count(*) FILTER (WHERE status = 'occupied') AS occ_c,
    count(*) FILTER (WHERE status = 'reserved') AS res_c
  INTO v_occ_count, v_resv_bound
  FROM public.table_floors
  WHERE table_number = p_parent_table_number OR table_number = ANY(v_children);

  -- cases 8/9: any reserved + any occupied in the same group is forbidden
  IF v_resv_bound > 0 AND v_occ_count > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_RESERVED_WITH_OCCUPIED');
  END IF;

  -- case 7 / multi-reserved: all reserved tables must share ONE reservation
  SELECT
    count(*) FILTER (WHERE reservation_id IS NOT NULL) AS bound,
    count(*) FILTER (WHERE reservation_id IS NULL)     AS unbound
  INTO v_resv_bound, v_resv_unbound
  FROM public.table_floors
  WHERE (table_number = p_parent_table_number OR table_number = ANY(v_children))
    AND status = 'reserved';
  SELECT count(DISTINCT reservation_id) INTO v_resv_distinct
  FROM public.table_floors
  WHERE (table_number = p_parent_table_number OR table_number = ANY(v_children))
    AND status = 'reserved' AND reservation_id IS NOT NULL;
  IF v_resv_distinct > 1 OR (v_resv_bound > 0 AND v_resv_unbound > 0) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_RESERVATION_MISMATCH');
  END IF;

  -- canonical reservation (only one may exist once validated)
  v_resv_id := NULL;
  SELECT reservation_id, reservation_name, reservation_phone, reservation_time INTO v_resv_id, v_resv_name, v_resv_phone, v_resv_time
  FROM public.table_floors
  WHERE (table_number = p_parent_table_number OR table_number = ANY(v_children))
    AND status = 'reserved' AND reservation_id IS NOT NULL
  LIMIT 1;

  -- ---- per-table order validation ----
  -- parent (occupied): exactly one open unmerged order
  IF v_parent_kind = 'occupied' THEN
    SELECT count(*) INTO v_r FROM public.orders
     WHERE table_number = p_parent_table_number
       AND merged_into IS NULL
       AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided');
    IF v_r = 0 THEN
      RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_PARENT_NO_ORDER');
    END IF;
    IF v_r > 1 THEN
      RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_PARENT_MULTIPLE');
    END IF;
    SELECT * INTO v_parent_order FROM public.orders
     WHERE table_number = p_parent_table_number
       AND merged_into IS NULL
       AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
     ORDER BY created_at ASC LIMIT 1;
    v_parent_order_id := v_parent_order.id;
  END IF;

  FOR v_child IN SELECT * FROM public.table_floors
                 WHERE table_number = ANY(v_children) ORDER BY table_number LOOP
    v_child_kind := CASE v_child.status WHEN 'occupied' THEN 'occupied'
                                         WHEN 'reserved' THEN 'reserved'
                                         WHEN 'empty'    THEN 'empty' ELSE 'other' END;
    IF v_child_kind = 'other' THEN
      RETURN jsonb_build_object('success', false, 'error',
        'G_MERGE_TABLE_STATE_INVALID (child=' || v_child.table_number || ')');
    END IF;
    SELECT count(*) INTO v_r FROM public.orders
     WHERE table_number = v_child.table_number
       AND merged_into IS NULL
       AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided');
    IF v_child_kind = 'occupied' THEN
      IF v_r = 0 THEN
        RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_CHILD_NO_ORDER (child=' || v_child.table_number || ')');
      END IF;
      IF v_r > 1 THEN
        RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_CHILD_MULTIPLE (child=' || v_child.table_number || ')');
      END IF;
    ELSIF v_r > 0 THEN
      -- a reserved/empty table must not carry an open order (inconsistent state)
      RETURN jsonb_build_object('success', false, 'error',
        'G_MERGE_TABLE_STATE_INVALID (child=' || v_child.table_number || ' has open order)');
    END IF;
  END LOOP;

  -- ---- payment guard on every open order in the group ----
  IF EXISTS (SELECT 1 FROM public.orders o
             JOIN public.payments p ON p.order_id = o.id
             WHERE (o.table_number = p_parent_table_number OR o.table_number = ANY(v_children))
               AND o.status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
               AND p.status IN ('captured','pending')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_MERGE_ORDER_PAID');
  END IF;

  -- ---- decide mode + canonical order host ----
  v_canonical_from := p_parent_table_number;
  IF v_resv_id IS NOT NULL THEN
    v_mode := 'reservation-aware';
    v_parent_order_id := NULL;          -- reserved tables carry no open order
  ELSIF v_occ_count > 0 THEN
    v_mode := 'bill-merge';
  ELSE
    v_mode := 'group-empty';
    v_parent_order_id := NULL;
  END IF;

  v_old_state := jsonb_build_object('parent_status', v_parent.status,
    'parent_order_id', v_parent_order_id, 'parent_reservation_id', v_resv_id,
    'children', v_children);
  v_group := 'group-' || p_parent_table_number;

  -- ========================================================================
  -- APPLY per child
  -- ========================================================================
  FOR v_child IN SELECT * FROM public.table_floors
                 WHERE table_number = ANY(v_children) ORDER BY table_number LOOP
    v_child_kind := CASE v_child.status WHEN 'occupied' THEN 'occupied'
                                         WHEN 'reserved' THEN 'reserved'
                                         WHEN 'empty'    THEN 'empty' ELSE 'other' END;

    IF v_child_kind = 'occupied' THEN
      SELECT * INTO v_child_order FROM public.orders
       WHERE table_number = v_child.table_number
         AND merged_into IS NULL
         AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
       ORDER BY created_at ASC LIMIT 1;

      IF v_parent_kind = 'occupied' THEN
        -- case 4: child order merges INTO parent order (child lineage preserved)
        UPDATE public.orders SET
          merged_into = v_parent_order_id,
          merged_from_table = v_child.table_number,
          table_number = p_parent_table_number,
          updated_at = now(),
          version = COALESCE(version,0) + 1,
          updated_by_terminal_id = p_performed_by_terminal_id
        WHERE id = v_child_order.id;

        UPDATE public.kitchen_schedule SET
          table_number = p_parent_table_number, updated_at = now()
        WHERE order_id = v_child_order.id;

        v_children_lineage := v_children_lineage || jsonb_build_array(jsonb_build_object(
          'table', v_child.table_number, 'kind', 'occupied', 'order_id', v_child_order.id));
      ELSIF v_parent_order_id IS NULL THEN
        -- case 2: FIRST occupied child's order BECOMES canonical on (formerly empty) parent
        UPDATE public.orders SET
          table_number = p_parent_table_number,
          merged_from_table = v_child.table_number,
          merged_into = NULL,
          updated_at = now(),
          version = COALESCE(version,0) + 1,
          updated_by_terminal_id = p_performed_by_terminal_id
        WHERE id = v_child_order.id;

        UPDATE public.kitchen_schedule SET
          table_number = p_parent_table_number, updated_at = now()
        WHERE order_id = v_child_order.id;

        v_parent_order_id := v_child_order.id;
        v_canonical_from  := v_child.table_number;

        v_children_lineage := v_children_lineage || jsonb_build_array(jsonb_build_object(
          'table', v_child.table_number, 'kind', 'occupied', 'order_id', v_child_order.id));
      ELSE
        -- additional occupied child: merge its order into the established canonical
        UPDATE public.orders SET
          merged_into = v_parent_order_id,
          merged_from_table = v_child.table_number,
          table_number = p_parent_table_number,
          updated_at = now(),
          version = COALESCE(version,0) + 1,
          updated_by_terminal_id = p_performed_by_terminal_id
        WHERE id = v_child_order.id;

        UPDATE public.kitchen_schedule SET
          table_number = p_parent_table_number, updated_at = now()
        WHERE order_id = v_child_order.id;

        v_children_lineage := v_children_lineage || jsonb_build_array(jsonb_build_object(
          'table', v_child.table_number, 'kind', 'occupied', 'order_id', v_child_order.id));
      END IF;

      -- child floor -> merged / hidden
      UPDATE public.table_floors SET
        status = 'merged',
        current_order_id = NULL,
        merged_into_table = p_parent_table_number,
        kitchen_status = NULL,
        guest_count = NULL,
        total_amount = 0,
        order_count = 0,
        has_pending = false,
        oldest_pending_at = NULL,
        bill_requested = false,
        reservation_id = NULL,
        reservation_name = NULL,
        reservation_phone = NULL,
        reservation_time = NULL,
        metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
          jsonb_build_object('mode', v_mode, 'kind', 'occupied',
            'order_id', v_child_order.id, 'parent_order_id', v_parent_order_id,
            'parent_reservation_id', v_resv_id, 'canonical_order_from', v_canonical_from)),
        updated_at = now(),
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = v_child.table_number;

      v_children_summary := v_children_summary || jsonb_build_array(jsonb_build_object(
        'child_table', v_child.table_number, 'kind', 'occupied',
        'order_id', v_child_order.id, 'total_amount', v_child_order.total_amount,
        'guest_count', v_child_order.guest_count));
      v_merged := v_merged + 1;
      CONTINUE;
    END IF;

    IF v_child_kind = 'reserved' THEN
      -- case 7: child reserved, same reservation as parent -> hide child in group
      UPDATE public.table_floors SET
        status = 'merged',
        current_order_id = NULL,
        merged_into_table = p_parent_table_number,
        kitchen_status = NULL,
        guest_count = NULL,
        has_pending = false,
        oldest_pending_at = NULL,
        bill_requested = false,
        -- keep reservation denormalized so unmerge can restore
        reservation_id = v_resv_id,
        reservation_name = v_resv_name,
        reservation_phone = v_resv_phone,
        reservation_time = v_resv_time,
        metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
          jsonb_build_object('mode', v_mode, 'kind', 'reserved',
            'order_id', NULL, 'parent_order_id', NULL,
            'parent_reservation_id', v_resv_id, 'canonical_order_from', v_canonical_from)),
        updated_at = now(),
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = v_child.table_number;

      v_children_lineage := v_children_lineage || jsonb_build_array(jsonb_build_object(
        'table', v_child.table_number, 'kind', 'reserved', 'order_id', NULL));
      v_children_summary := v_children_summary || jsonb_build_array(jsonb_build_object(
        'child_table', v_child.table_number, 'kind', 'reserved'));
      v_merged := v_merged + 1;
      CONTINUE;
    END IF;

    -- child_kind = 'empty'
    IF v_mode = 'reservation-aware' AND v_resv_id IS NOT NULL THEN
      -- case 5/6: empty table joins the group reservation
      UPDATE public.table_floors SET
        status = 'merged',
        current_order_id = NULL,
        merged_into_table = p_parent_table_number,
        kitchen_status = NULL,
        guest_count = NULL,
        total_amount = 0,
        order_count = 0,
        has_pending = false,
        oldest_pending_at = NULL,
        bill_requested = false,
        reservation_id = v_resv_id,
        reservation_name = v_resv_name,
        reservation_phone = v_resv_phone,
        reservation_time = v_resv_time,
        metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
          jsonb_build_object('mode', v_mode, 'kind', 'empty',
            'order_id', NULL, 'parent_order_id', v_parent_order_id,
            'parent_reservation_id', v_resv_id, 'canonical_order_from', v_canonical_from)),
        updated_at = now(),
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = v_child.table_number;

      -- attach the empty table to the reservation (trigger syncs reservations.table_ids)
      INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
      VALUES (v_resv_id, v_child.table_number, now())
      ON CONFLICT (reservation_id, table_number) DO NOTHING;
    ELSE
      -- case 1 (group-empty) or case 3 (occupied parent + empty child): plain group
      UPDATE public.table_floors SET
        status = 'merged',
        current_order_id = NULL,
        merged_into_table = p_parent_table_number,
        kitchen_status = NULL,
        guest_count = NULL,
        total_amount = 0,
        order_count = 0,
        has_pending = false,
        oldest_pending_at = NULL,
        bill_requested = false,
        reservation_id = NULL,
        reservation_name = NULL,
        reservation_phone = NULL,
        reservation_time = NULL,
        metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
          jsonb_build_object('mode', v_mode, 'kind', 'empty',
            'order_id', NULL, 'parent_order_id', v_parent_order_id,
            'parent_reservation_id', v_resv_id, 'canonical_order_from', v_canonical_from)),
        updated_at = now(),
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = v_child.table_number;
    END IF;

    v_children_lineage := v_children_lineage || jsonb_build_array(jsonb_build_object(
      'table', v_child.table_number, 'kind', 'empty', 'order_id', NULL));
    v_children_summary := v_children_summary || jsonb_build_array(jsonb_build_object(
      'child_table', v_child.table_number, 'kind', 'empty'));
    v_merged := v_merged + 1;
  END LOOP;

  -- ========================================================================
  -- APPLY parent (final floor state)
  -- ========================================================================
  IF v_parent_kind = 'occupied' THEN
    -- case 3 / 4: parent keeps its own order (or case 2 parent became occupied via move)
    UPDATE public.table_floors SET
      status = 'occupied',
      current_order_id = v_parent_order_id,
      merged_into_table = NULL,
      metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
        jsonb_build_object('mode', v_mode, 'parent_kind', 'occupied',
          'children', v_children_lineage, 'parent_order_id', v_parent_order_id,
          'parent_reservation_id', v_resv_id, 'canonical_order_from', v_canonical_from)),
      updated_at = now(),
      updated_by_terminal_id = p_performed_by_terminal_id
    WHERE table_number = p_parent_table_number;
    PERFORM public.sync_table_order_aggregates(p_parent_table_number);
  ELSIF v_parent_kind = 'reserved' THEN
    -- case 5 / 7: parent was reserved -> stays reserved; keep its existing reservation
    -- denormalized fields (already reflect the canonical display name/phone/time).
    UPDATE public.table_floors SET
      status = 'reserved',
      current_order_id = NULL,
      merged_into_table = NULL,
      metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
        jsonb_build_object('mode', v_mode, 'parent_kind', 'reserved',
          'children', v_children_lineage, 'parent_order_id', NULL,
          'parent_reservation_id', v_resv_id, 'canonical_order_from', v_canonical_from)),
      updated_at = now(),
      updated_by_terminal_id = p_performed_by_terminal_id
    WHERE table_number = p_parent_table_number;
  ELSIF v_parent_kind = 'empty' AND v_resv_id IS NOT NULL THEN
    -- case 6: parent was empty, now carries the group reservation
    UPDATE public.table_floors SET
      status = 'reserved',
      current_order_id = NULL,
      merged_into_table = NULL,
      reservation_id = v_resv_id,
      reservation_name = v_resv_name,
      reservation_phone = v_resv_phone,
      reservation_time = v_resv_time,
      metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
        jsonb_build_object('mode', v_mode, 'parent_kind', 'empty',
          'children', v_children_lineage, 'parent_order_id', NULL,
          'parent_reservation_id', v_resv_id, 'canonical_order_from', v_canonical_from)),
      updated_at = now(),
      updated_by_terminal_id = p_performed_by_terminal_id
    WHERE table_number = p_parent_table_number;
    -- parent (formerly empty) joins the reservation group
    INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
    VALUES (v_resv_id, p_parent_table_number, now())
    ON CONFLICT (reservation_id, table_number) DO NOTHING;
  ELSE
    -- case 1 (group-empty) / case 2 (parent empty, order moved in)
    IF v_mode = 'bill-merge' THEN
      -- case 2: parent was empty, child order now lives here -> occupied
      UPDATE public.table_floors SET
        status = 'occupied',
        current_order_id = v_parent_order_id,
        merged_into_table = NULL,
        metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
          jsonb_build_object('mode', v_mode, 'parent_kind', 'empty',
            'children', v_children_lineage, 'parent_order_id', v_parent_order_id,
            'parent_reservation_id', NULL, 'canonical_order_from', v_canonical_from)),
        updated_at = now(),
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = p_parent_table_number;
      PERFORM public.sync_table_order_aggregates(p_parent_table_number);
    ELSE
      -- case 1: parent was empty, stays empty
      UPDATE public.table_floors SET
        status = 'empty',
        current_order_id = NULL,
        merged_into_table = NULL,
        guest_count = NULL,
        total_amount = 0,
        order_count = 0,
        has_pending = false,
        oldest_pending_at = NULL,
        bill_requested = false,
        metadata = COALESCE(metadata,'{}'::jsonb) || jsonb_build_object('merge_lineage',
          jsonb_build_object('mode', v_mode, 'parent_kind', 'empty',
            'children', v_children_lineage, 'parent_order_id', NULL,
            'parent_reservation_id', NULL, 'canonical_order_from', v_canonical_from)),
        updated_at = now(),
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = p_parent_table_number;
    END IF;
  END IF;

  -- refresh aggregates on merged children (order_count -> 0)
  FOR v_child IN SELECT * FROM public.table_floors WHERE table_number = ANY(v_children) ORDER BY table_number LOOP
    PERFORM public.sync_table_order_aggregates(v_child.table_number);
  END LOOP;

  PERFORM public.g_table_audit(
    'merge_tables', 'table.merged',
    p_parent_table_number, v_parent.id, v_parent_order_id,
    v_old_state,
    jsonb_build_object('mode', v_mode, 'merged_group_id', v_group, 'children', v_children_summary),
    p_performed_by, p_performed_by_terminal_id,
    'contract-merge-v2:' || v_mode,
    p_parent_table_number, NULL, v_parent.location_id, v_parent.organization_id);

  RETURN jsonb_build_object('success', true,
    'mode', v_mode,
    'parent_order_id', v_parent_order_id,
    'parent_reservation_id', v_resv_id,
    'merged_group_id', v_group,
    'merged_children', v_merged, 'children', v_children_summary);
END;
$$;


--
-- Name: merge_tables_v3(integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_tables_v3(p_table_numbers integer[], p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_table INTEGER;
  v_rest_tables INTEGER[];
  v_primary_order_id UUID;
  v_source_order_ids UUID[];
  v_total_amount NUMERIC := 0;
  v_total_guests INTEGER := 0;
  v_order RECORD;
BEGIN
  v_target_table := p_table_numbers[1];
  v_rest_tables := p_table_numbers[2:array_length(p_table_numbers, 1)];

  -- Lock target table floor
  PERFORM 1 FROM table_floors WHERE table_number = v_target_table FOR UPDATE;
  
  -- Find or create primary order for target table
  SELECT id, guest_count, total_amount INTO v_primary_order_id, v_total_guests, v_total_amount 
  FROM orders 
  WHERE table_number = v_target_table AND status NOT IN ('paid', 'cancelled', 'closed')
  LIMIT 1 FOR UPDATE;

  IF v_primary_order_id IS NULL THEN
    INSERT INTO orders (table_number, total_amount, guest_count, status, kitchen_status)
    VALUES (v_target_table, 0, 1, 'confirmed', 'pending')
    RETURNING id INTO v_primary_order_id;
    v_total_guests := 1;
    v_total_amount := 0;
  END IF;

  -- Lock and collect source orders
  FOR v_order IN 
    SELECT id, total_amount, guest_count FROM orders 
    WHERE table_number = ANY(v_rest_tables) AND status NOT IN ('paid', 'cancelled', 'closed')
    FOR UPDATE
  LOOP
    v_source_order_ids := array_append(v_source_order_ids, v_order.id);
    v_total_amount := v_total_amount + COALESCE(v_order.total_amount, 0);
    v_total_guests := v_total_guests + COALESCE(v_order.guest_count, 0);
    
    -- Mark source order as merged
    UPDATE orders SET merged_into = v_primary_order_id, updated_at = now() WHERE id = v_order.id;
  END LOOP;

  -- Update primary order totals
  UPDATE orders SET 
    total_amount = v_total_amount, 
    guest_count = v_total_guests,
    updated_at = now() 
  WHERE id = v_primary_order_id;

  -- Update table floors (CRITICAL SSOT)
  UPDATE table_floors SET 
    status = 'merged', 
    merged_into_table = v_target_table,
    guest_count = NULL,
    total_amount = 0
  WHERE table_number = ANY(v_rest_tables);

  UPDATE table_floors SET 
    status = 'occupied',
    guest_count = v_total_guests,
    total_amount = v_total_amount
  WHERE table_number = v_target_table;

  RETURN jsonb_build_object(
    'success', true,
    'primary_order_id', v_primary_order_id,
    'total_amount', v_total_amount,
    'total_guests', v_total_guests
  );
END;
$$;


--
-- Name: merge_tables_v4(integer, integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.merge_tables_v4(p_primary_table integer, p_child_tables integer[], p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_group_id UUID;
  v_primary_order_id UUID;
  v_child_num INTEGER;
  v_log_id UUID;
BEGIN
  -- Lock primary floor
  PERFORM 1 FROM table_floors WHERE table_number = p_primary_table FOR UPDATE;

  -- Find primary order
  SELECT id, group_id INTO v_primary_order_id, v_group_id FROM orders 
  WHERE table_number = p_primary_table AND status = 'confirmed' LIMIT 1 FOR UPDATE;

  IF v_primary_order_id IS NULL THEN
    RAISE EXCEPTION 'PRIMARY_TABLE_EMPTY' USING ERRCODE = 'P0001';
  END IF;

  -- Reuse or Create Group
  IF v_group_id IS NULL THEN
    INSERT INTO dining_groups (primary_order_id) VALUES (v_primary_order_id) RETURNING id INTO v_group_id;
    UPDATE orders SET group_id = v_group_id WHERE id = v_primary_order_id;
  END IF;

  -- Merge Children
  FOREACH v_child_num IN ARRAY p_child_tables LOOP
    UPDATE orders SET group_id = v_group_id 
    WHERE table_number = v_child_num AND status = 'confirmed';
    
    UPDATE table_floors SET status = 'occupied', merged_into_table = p_primary_table 
    WHERE table_number = v_child_num;
  END LOOP;

  -- Audit
  INSERT INTO operation_logs (type, payload, inverse_payload, performed_by)
  VALUES ('MERGE', 
    jsonb_build_object('primary', p_primary_table, 'children', p_child_tables, 'group_id', v_group_id),
    jsonb_build_object('primary', p_primary_table, 'children', p_child_tables, 'group_id', v_group_id),
    p_performed_by
  ) RETURNING id INTO v_log_id;

  RETURN jsonb_build_object('success', true, 'group_id', v_group_id, 'log_id', v_log_id);
END;
$$;


--
-- Name: migrate_existing_campaigns(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.migrate_existing_campaigns() RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_campaign RECORD;
  v_rule_id UUID;
BEGIN
  FOR v_campaign IN SELECT * FROM campaigns WHERE deleted_at IS NULL LOOP
    IF v_campaign.type = 'PERCENTAGE' OR v_campaign.type = 'HAPPY_HOUR' THEN
      INSERT INTO campaign_rules (campaign_id, rule_type, percentage, start_time, end_time)
      VALUES (v_campaign.id, lower(v_campaign.type), COALESCE(v_campaign.discount_value, 0), v_campaign.start_time::TIME, v_campaign.end_time::TIME)
      RETURNING id INTO v_rule_id;
    ELSIF v_campaign.type = 'FIXED_AMOUNT' THEN
      INSERT INTO campaign_rules (campaign_id, rule_type, fixed_amount)
      VALUES (v_campaign.id, 'fixed_amount', COALESCE(v_campaign.discount_value, 0))
      RETURNING id INTO v_rule_id;
    ELSIF v_campaign.type = 'BOGO' THEN
      INSERT INTO campaign_rules (campaign_id, rule_type, buy_quantity, pay_quantity)
      VALUES (v_campaign.id, 'buy_x_pay_y', 1, 1)
      RETURNING id INTO v_rule_id;
    ELSIF v_campaign.type = 'BUY2GET1' THEN
      INSERT INTO campaign_rules (campaign_id, rule_type, buy_quantity, pay_quantity)
      VALUES (v_campaign.id, 'buy_x_pay_y', 2, 1)
      RETURNING id INTO v_rule_id;
    ELSIF v_campaign.type = 'FREE_DELIVERY' THEN
      INSERT INTO campaign_rules (campaign_id, rule_type, delivery_min_order)
      VALUES (v_campaign.id, 'free_delivery', COALESCE(v_campaign.min_purchase_amount, 0))
      RETURNING id INTO v_rule_id;
    END IF;

    IF v_campaign.target_type = 'product' AND v_campaign.target_id IS NOT NULL THEN
      INSERT INTO campaign_targets (campaign_id, target_type, target_id)
      VALUES (v_campaign.id, 'product', v_campaign.target_id);
    ELSIF v_campaign.target_type = 'category' AND v_campaign.target_id IS NOT NULL THEN
      INSERT INTO campaign_targets (campaign_id, target_type, target_id)
      VALUES (v_campaign.id, 'category', v_campaign.target_id);
    ELSIF v_campaign.target_type = 'all' THEN
      INSERT INTO campaign_targets (campaign_id, target_type, target_id)
      VALUES (v_campaign.id, 'whole_order', NULL);
    END IF;

    IF v_campaign.start_date IS NOT NULL OR v_campaign.end_date IS NOT NULL THEN
      INSERT INTO campaign_schedules (campaign_id, start_date, end_date, start_time, end_time)
      VALUES (v_campaign.id, v_campaign.start_date, v_campaign.end_date, v_campaign.start_time::TIME, v_campaign.end_time::TIME);
    END IF;
  END LOOP;
END;
$$;


--
-- Name: mirror_audit_log_to_audit_logs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.mirror_audit_log_to_audit_logs() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.audit_logs (
    action, table_name, record_id, old_data, new_data, performed_by, created_at,
    target_type, target_id, staff_id
  ) VALUES (
    NEW.action, NEW.table_name, NEW.record_id::text, NEW.old_data, NEW.new_data,
    NEW.performed_by, COALESCE(NEW.created_at, now()),
    NEW.table_name, NEW.record_id::text, NEW.performed_by
  );
  RETURN NEW;
END;
$$;


--
-- Name: move_reservation_table_atomic(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_reservation_table_atomic(p_reservation_id uuid, p_from_table integer, p_to_table integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_old_table_ids integer[];
BEGIN
  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;

  v_old_table_ids := v_reservation.table_ids;

  UPDATE public.table_floors SET
    status = 'empty',
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    updated_at = NOW()
  WHERE table_number = p_from_table;

  UPDATE public.table_floors SET
    status = 'reserved',
    reservation_id = p_reservation_id,
    reservation_name = v_reservation.name,
    reservation_phone = v_reservation.phone,
    updated_at = NOW()
  WHERE table_number = p_to_table;

  UPDATE public.reservations SET
    table_ids = array_replace(table_ids, p_from_table, p_to_table),
    updated_at = NOW()
  WHERE id = p_reservation_id;

  DELETE FROM public.reservation_tables WHERE reservation_id = p_reservation_id AND table_number = p_from_table;

  INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
  VALUES (p_reservation_id, p_to_table, NOW())
  ON CONFLICT (reservation_id, table_number) DO NOTHING;

  PERFORM public.log_reservation_operation(
    p_reservation_id,
    'move_reservation_table',
    jsonb_build_object('from_table', p_from_table, 'table_ids', v_old_table_ids),
    jsonb_build_object('to_table', p_to_table, 'table_ids', array_replace(v_old_table_ids, p_from_table, p_to_table)),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: move_reserved_table_atomic(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.move_reserved_table_atomic(p_reservation_id uuid, p_from_table_id uuid, p_to_table_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_target_status TEXT;
  v_target_table_number INTEGER;
  v_from_table_number INTEGER;
BEGIN
  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_reservation.status NOT IN ('pending', 'confirmed') THEN
    RAISE EXCEPTION 'RESERVATION_NOT_MOVABLE' USING ERRCODE = 'P0001';
  END IF;

  SELECT status, table_number INTO v_target_status, v_target_table_number
  FROM table_floors WHERE id = p_to_table_id FOR UPDATE;

  IF v_target_status IS NULL THEN
    RAISE EXCEPTION 'TARGET_TABLE_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_target_status != 'empty' THEN
    RAISE EXCEPTION 'TARGET_TABLE_NOT_EMPTY' USING ERRCODE = 'P0001';
  END IF;

  SELECT table_number INTO v_from_table_number FROM table_floors WHERE id = p_from_table_id;

  -- Free source table
  UPDATE table_floors SET
    status = 'empty',
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    guest_count = NULL
  WHERE id = p_from_table_id;

  -- Reserve target table
  UPDATE table_floors SET
    status = 'reserved',
    reservation_id = p_reservation_id,
    reservation_name = v_reservation.name || v_reservation.customer_name,
    reservation_phone = v_reservation.phone,
    reservation_time = v_reservation.time,
    guest_count = v_reservation.guests
  WHERE id = p_to_table_id;

  -- Update reservation table_ids (replace from UUID with to UUID)
  UPDATE reservations SET
    table_ids = (
      SELECT jsonb_agg(elem)
      FROM jsonb_array_elements(table_ids) AS elem
      WHERE elem <> p_from_table_id::text
    ) || jsonb_build_array(p_to_table_id::text),
    updated_at = now()
  WHERE id = p_reservation_id;

  RETURN jsonb_build_object(
    'success', true,
    'from_table', v_from_table_number,
    'to_table', v_target_table_number,
    'reservation_id', p_reservation_id
  );
END;
$$;


--
-- Name: normalize_role(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_role(p_role text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    AS $$
DECLARE v_lower text := LOWER(TRIM(p_role));
BEGIN
  IF v_lower IN ('superadmin', 'super admin') THEN RETURN 'superadmin';
  ELSIF v_lower IN ('admin', 'administrator') THEN RETURN 'admin';
  ELSIF v_lower IN ('menecer', 'manager') THEN RETURN 'manager';
  ELSIF v_lower IN ('kassir', 'cashier', 'kassa') THEN RETURN 'cashier';
  ELSIF v_lower IN ('ofisiant', 'waiter', 'baş ofisiant', 'head waiter') THEN RETURN 'waiter';
  ELSIF v_lower IN ('barmen', 'bartender') THEN RETURN 'bartender';
  ELSIF v_lower IN ('aşpaz', 'ashpaz', 'chef', 'kitchen') THEN RETURN 'kitchen';
  ELSIF v_lower IN ('host', 'hostess') THEN RETURN 'host';
  ELSIF v_lower IN ('stock', 'anbarçı') THEN RETURN 'stock';
  ELSIF v_lower IN ('accountant', 'mühasib') THEN RETURN 'accountant';
  ELSIF v_lower IN ('owner', 'sahibkar') THEN RETURN 'owner';
  ELSE RETURN v_lower;
  END IF;
END;
$$;


--
-- Name: normalize_table_after_reservation_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.normalize_table_after_reservation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF new.status IN ('cancelled', 'expired', 'archived', 'no_show') THEN
    UPDATE public.table_floors
      SET status = 'empty',
          reservation_id = NULL,
          reservation_name = NULL,
          reservation_phone = NULL,
          reservation_time = NULL,
          guest_count = NULL,
          reservation_status_snapshot = new.status,
          reservation_updated_at = now(),
          updated_at = now()
    WHERE reservation_id = new.id;
  END IF;
  IF new.status = 'confirmed' THEN
    UPDATE public.table_floors
      SET status = 'reserved',
          reservation_status_snapshot = new.status,
          reservation_updated_at = now(),
          updated_at = now()
    WHERE reservation_id = new.id
      AND status NOT IN ('occupied', 'dirty', 'cleaning');
  END IF;
  IF new.status = 'checked_in' THEN
    UPDATE public.table_floors
      SET status = 'occupied',
          reservation_status_snapshot = new.status,
          reservation_updated_at = now(),
          updated_at = now()
    WHERE reservation_id = new.id;
  END IF;
  IF new.status = 'completed' THEN
    UPDATE public.table_floors
      SET status = 'empty',
          reservation_status_snapshot = new.status,
          reservation_updated_at = now(),
          updated_at = now()
    WHERE reservation_id = new.id;
  END IF;
  RETURN new;
END;
$$;


--
-- Name: open_cash_register(text, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_cash_register(p_token text, p_opening_balance numeric, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_opener uuid;
  v_org uuid;
  v_loc uuid;
  v_shift shifts%ROWTYPE;
  v_session_id uuid;
BEGIN
  PERFORM set_session_staff(p_token);
  v_opener := current_staff_id();
  v_org := current_org_id();
  v_loc := nullif(current_setting('app.current_location_id'), '')::uuid;

  -- Q5: opener must have an ACTIVE session with a location/org
  IF v_org IS NULL OR v_loc IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active location in session');
  END IF;

  -- bind to the opener's single open shift (1:1). FOR UPDATE makes concurrent
  -- binds on the same shift serialize; the second gets ALREADY_BOUND via the
  -- unique open-drawer check below.
  SELECT * INTO v_shift FROM shifts
  WHERE staff_id = v_opener AND closed_at IS NULL
  FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'OPEN_SHIFT_REQUIRED');
  END IF;

  IF EXISTS (SELECT 1 FROM cash_drawer_sessions
             WHERE shift_id = v_shift.id AND status = 'open') THEN
    RETURN jsonb_build_object('success', false, 'error', 'DRAWER_ALREADY_BOUND');
  END IF;

  -- Atomic 1:1 (Q10): the unique index cash_drawer_open_shift_1to1 is the
  -- backstop for the TOCTOU race — two concurrent opens serialize on the shift
  -- FOR UPDATE; the loser gets a clean DRAWER_ALREADY_BOUND, not a raw 500.
  BEGIN
    INSERT INTO cash_drawer_sessions
      (opening_balance, status, notes, opened_by, organization_id, location_id, shift_id)
    VALUES (p_opening_balance, 'open', p_notes, v_opener, v_org, v_loc, v_shift.id)
    RETURNING id INTO v_session_id;
  EXCEPTION WHEN unique_violation THEN
    RETURN jsonb_build_object('success', false, 'error', 'DRAWER_ALREADY_BOUND');
  END;

  -- propagate opening cash to the shift (expected_cash derived later at close)
  UPDATE shifts SET starting_cash = p_opening_balance WHERE id = v_shift.id;

  INSERT INTO cash_drawer_log (session_id, type, amount, description, created_by)
  VALUES (v_session_id, 'open', p_opening_balance, COALESCE(p_notes, 'Kassa açıldı'), v_opener);

  PERFORM log_audit(
    'cash_register_opened'::text, 'cash_drawer_session'::text, v_session_id::text,
    v_opener, NULL::text, NULL::jsonb,
    jsonb_build_object('opening_balance', p_opening_balance, 'shift_id', v_shift.id,
                       'location_id', v_loc, 'organization_id', v_org),
    NULL::jsonb, NULL::text
  );

  RETURN jsonb_build_object('success', true, 'id', v_session_id,
                            'opening_balance', p_opening_balance, 'shift_id', v_shift.id);
END;
$$;


--
-- Name: open_shift(text, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.open_shift(p_token text, p_starting_cash numeric DEFAULT 0) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid;
    v_org_id uuid;
    v_loc_id uuid;
    v_shift_id uuid;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    v_org_id := current_org_id();
    
    -- GATE R1: serialize per-staff open-shift creation
    PERFORM pg_advisory_xact_lock(hashtext(v_staff_id::text));
v_loc_id := nullif(current_setting('app.current_location_id'), '')::uuid;

    IF v_loc_id IS NULL THEN
        RAISE EXCEPTION 'No active location';
    END IF;

    INSERT INTO shifts (staff_id, report_date, opened_at, starting_cash, expected_cash, actual_cash, difference, location_id, organization_id)
    VALUES (v_staff_id, public.local_day(now(), v_loc_id), now(), p_starting_cash, 0, 0, 0, v_loc_id, v_org_id)
    RETURNING id INTO v_shift_id;

    INSERT INTO operation_logs (entity_type, entity_id, operation, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('shift', v_shift_id, 'shift.opened',
            jsonb_build_object('staff_id', v_staff_id, 'starting_cash', p_starting_cash),
            v_staff_id, gen_random_uuid(), v_loc_id, v_org_id);

    RETURN jsonb_build_object('shift_id', v_shift_id, 'status', 'OPEN', 'started_at', now()::text,
                              'report_date', public.local_day(now(), v_loc_id));
END;
$$;


--
-- Name: operation_logs_normalize(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.operation_logs_normalize() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.operation IS NULL THEN
    NEW.operation := COALESCE(NEW.action, NEW.type, NEW.table_name, 'log');
  END IF;

  IF NEW.source_table_number IS NULL THEN
    NEW.source_table_number := NEW.table_number;
  END IF;

  -- old_state/new_state have NOT NULL DEFAULT '{}'; only override when they
  -- still carry the empty default and a legacy value was actually provided.
  IF NEW.old_state = '{}'::jsonb AND NEW.old_values IS NOT NULL THEN
    NEW.old_state := NEW.old_values;
  ELSIF NEW.old_state = '{}'::jsonb AND NEW.old_data IS NOT NULL THEN
    NEW.old_state := NEW.old_data;
  END IF;

  IF NEW.new_state = '{}'::jsonb AND NEW.new_values IS NOT NULL THEN
    NEW.new_state := NEW.new_values;
  ELSIF NEW.new_state = '{}'::jsonb AND NEW.new_data IS NOT NULL THEN
    NEW.new_state := NEW.new_data;
  END IF;

  IF NEW.undo_payload IS NULL THEN
    NEW.undo_payload := NEW.payload;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: order_table_archive_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.order_table_archive_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_arch boolean;
BEGIN
  IF NEW.table_number IS NOT NULL THEN
    SELECT is_archived INTO v_arch FROM public.table_floors
     WHERE table_number = NEW.table_number AND location_id = NEW.location_id;
    IF v_arch THEN
      RAISE EXCEPTION 'TABLE_ARCHIVED: cannot create an order for archived table %', NEW.table_number;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: outbox_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.outbox_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    aggregate_type character varying(100) NOT NULL,
    aggregate_id uuid NOT NULL,
    event_type character varying(100) NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    metadata jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    retry_count integer DEFAULT 0 NOT NULL,
    max_retries integer DEFAULT 5 NOT NULL,
    next_retry_at timestamp with time zone,
    processed_at timestamp with time zone,
    error_message text,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    CONSTRAINT outbox_events_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'processing'::character varying, 'completed'::character varying, 'failed'::character varying, 'dead'::character varying])::text[])))
);


--
-- Name: TABLE outbox_events; Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON TABLE public.outbox_events IS 'Outbox pattern per 0.1.24. DB mutation + outbox insert in same transaction.';


--
-- Name: outbox_dispatch(public.outbox_events); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_dispatch(p_ev public.outbox_events) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_p jsonb;
  v_order RECORD;
  v_ingredient RECORD;
  v_recent INT;
BEGIN
  BEGIN
    v_p := p_ev.payload::jsonb;
  EXCEPTION WHEN others THEN
    RAISE 'malformed payload (permanent failure): %', left(coalesce(SQLERRM,'unknown'), 300);
  END;

  -- NOOP types (realtime already covers POS/KDS via supabase_realtime publication;
  -- kept for future consumers via outbox).
  IF p_ev.event_type LIKE 'table.%'
     OR p_ev.event_type LIKE 'kds.%'
     OR p_ev.event_type LIKE 'location.%'
     OR p_ev.event_type LIKE 'staff.%'
  THEN
    RETURN;
  END IF;

  IF p_ev.event_type = 'order.status_changed' THEN
    SELECT o.id, o.order_number, o.status, o.location_id, o.organization_id
    INTO v_order
    FROM orders o
    WHERE o.id = p_ev.aggregate_id;
    IF v_order.id IS NULL THEN
      RETURN;
    END IF;
    IF v_order.status = 'paid' THEN
      INSERT INTO notifications (type, title, body, data)
      VALUES (
        'order',
        'Order paid: ' || coalesce(v_order.order_number::text, ''),
        'Order ' || coalesce(v_order.order_number::text, '') || ' payment complete',
        jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'status', 'paid')
      );
    ELSIF v_order.status IN ('cancelled', 'voided') THEN
      INSERT INTO notifications (type, title, body, data)
      VALUES (
        'order_cancelled',
        'Order cancelled: ' || coalesce(v_order.order_number::text, ''),
        coalesce(v_p->>'reason', 'Order cancelled'),
        jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'status', v_order.status, 'reason', v_p->>'reason')
      );
    END IF;
    RETURN;
  END IF;

  IF p_ev.event_type = 'payment.failed' THEN
    SELECT o.id, o.status, o.order_number, o.location_id, o.organization_id
    INTO v_order
    FROM orders o
    WHERE o.id = p_ev.aggregate_id
      AND o.status NOT IN ('closed', 'cancelled', 'voided');
    IF v_order.id IS NULL THEN
      RETURN;
    END IF;
    SELECT count(*) INTO v_recent
    FROM payment_attempts pa
    JOIN payments pm ON pm.id = pa.payment_id
    WHERE pm.order_id = v_order.id
      AND pa.status = 'failed'
      AND (pa.completed_at IS NULL OR pa.completed_at >= now() - interval '15 minutes');
    IF v_recent > 0 THEN
      INSERT INTO notifications (type, title, body, data)
      VALUES (
        'payment',
        'Payment failed: ' || coalesce(v_order.order_number::text, ''),
        'A payment attempt failed for order ' || coalesce(v_order.order_number::text, '') || ' — retry or use another method',
        jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'failed_attempts', v_recent)
      );
    END IF;
    RETURN;
  END IF;

  IF p_ev.event_type = 'payment.refunded'
     OR p_ev.event_type LIKE 'order.refund.%'
  THEN
    SELECT o.id, o.order_number, o.location_id, o.organization_id, pr.amount, pr.performed_by_name
    INTO v_order
    FROM payment_refunds pr
    JOIN orders o ON o.id = pr.order_id
    WHERE pr.order_id = p_ev.aggregate_id
      AND pr.status = 'completed'
      AND pr.created_at >= now() - interval '1 hour'
    ORDER BY pr.created_at DESC
    LIMIT 1;
    IF v_order.id IS NULL THEN
      RETURN;
    END IF;
    INSERT INTO notifications (type, title, body, data)
    VALUES (
      'payment',
      'Refund: ' || coalesce(v_order.order_number::text, ''),
      coalesce(v_order.performed_by_name, 'System') || ' processed a refund of ' || coalesce(v_order.amount::text, '') || ' for order ' || coalesce(v_order.order_number::text, ''),
      jsonb_build_object('order_id', v_order.id, 'order_number', v_order.order_number, 'amount', v_order.amount, 'performed_by', v_order.performed_by_name)
    );
    RETURN;
  END IF;

  IF p_ev.event_type = 'inventory.stock_changed' THEN
    SELECT i.id, i.name, i.unit, i.current_stock, i.critical_limit
    INTO v_ingredient
    FROM ingredients i
    WHERE i.id = p_ev.aggregate_id;
    IF v_ingredient.id IS NULL OR v_ingredient.critical_limit IS NULL OR v_ingredient.critical_limit <= 0 THEN
      RETURN;
    END IF;
    IF v_ingredient.current_stock <= v_ingredient.critical_limit THEN
      SELECT count(*) INTO v_recent
      FROM notifications
      WHERE type = 'stock'
        AND title = 'Ehtiyat azalıb: ' || v_ingredient.name
        AND created_at >= now() - interval '4 hours';
      IF v_recent = 0 THEN
        INSERT INTO notifications (type, title, body, data)
        VALUES (
          'stock',
          'Ehtiyat azalıb: ' || v_ingredient.name,
          v_ingredient.name || ': ' || v_ingredient.current_stock::text || ' ' || coalesce(v_ingredient.unit, '') || ' (threshold: ' || v_ingredient.critical_limit::text || ')',
          jsonb_build_object('ingredient_id', v_ingredient.id, 'name', v_ingredient.name, 'current_stock', v_ingredient.current_stock, 'critical_limit', v_ingredient.critical_limit)
        );
      END IF;
    END IF;
    RETURN;
  END IF;

  -- Unknown event type: no-op (forward compatible).
  RETURN;
END;
$$;


--
-- Name: outbox_pump(integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.outbox_pump(p_batch_size integer DEFAULT 200) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_batch outbox_events%ROWTYPE;
  v_done INT := 0;
  v_failed INT := 0;
  v_noop INT := 0;
BEGIN
  FOR v_batch IN
    SELECT * FROM outbox_events
    WHERE status IN ('pending','processing')
      AND (next_retry_at IS NULL OR next_retry_at <= now())
    ORDER BY created_at ASC
    LIMIT GREATEST(1, COALESCE(p_batch_size, 200))
    FOR UPDATE SKIP LOCKED
  LOOP
    BEGIN
      PERFORM public.outbox_dispatch(v_batch);
      -- allowed status values (outbox_events_status_check):
      --   pending, processing, completed, failed, dead
      -- success → 'completed'; transient → 'pending'+backoff; perma → 'dead'
      UPDATE outbox_events
      SET status = 'completed',
          processed_at = now(),
          next_retry_at = NULL,
          error_message = NULL
      WHERE id = v_batch.id;
      v_done := v_done + 1;
    EXCEPTION
      WHEN others THEN
        IF v_batch.retry_count + 1 < v_batch.max_retries THEN
          UPDATE outbox_events
          SET status = 'pending',
              retry_count = retry_count + 1,
              next_retry_at = now() + make_interval(secs => (retry_count + 1) * 60),
              error_message = left(coalesce(SQLERRM, 'unknown'), 500)
          WHERE id = v_batch.id;
        ELSE
          UPDATE outbox_events
          SET status = 'dead',
              retry_count = retry_count + 1,
              error_message = left(coalesce(SQLERRM, 'unknown'), 500)
          WHERE id = v_batch.id;
          v_failed := v_failed + 1;
        END IF;
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'processed', v_done,
    'failed', v_failed,
    'remaining', (SELECT count(*) FROM outbox_events WHERE status IN ('pending','processing') AND (next_retry_at IS NULL OR next_retry_at <= now()))
  );
END;
$$;


--
-- Name: p1_actor_allowed_at_location(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.p1_actor_allowed_at_location(p_actor_id uuid, p_location_id uuid) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM staff s
    WHERE s.id = p_actor_id
      AND (
        EXISTS (SELECT 1 FROM staff_locations sl
                WHERE sl.staff_id = p_actor_id
                  AND sl.location_id = p_location_id
                  AND sl.active = true)
        OR (SELECT r.name FROM roles r WHERE r.id = s.role_id) IN ('superadmin', 'owner')
        OR (
          (SELECT count(DISTINCT o.location_id) FROM orders o WHERE o.location_id IS NOT NULL) = 1
          AND EXISTS (SELECT 1 FROM orders o WHERE o.location_id = p_location_id)
        )
      )
  );
$$;


--
-- Name: FUNCTION p1_actor_allowed_at_location(p_actor_id uuid, p_location_id uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.p1_actor_allowed_at_location(p_actor_id uuid, p_location_id uuid) IS 'P-1 M2: location-scope assertion for financial writes (fail-closed). P1_AUTHZ_CONTRACT_FREEZE_2026-09-12.md §8/M2.';


--
-- Name: payment_reconciliation(date, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_reconciliation(p_date date DEFAULT CURRENT_DATE, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result jsonb;
  v_performer_name TEXT;
BEGIN
  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  SELECT jsonb_build_object(
    'date', p_date,
    'summary', (
      SELECT jsonb_build_object(
        'total_payments', COALESCE(SUM(amount), 0),
        'total_tips', COALESCE(SUM(tip_amount), 0),
        'by_method', (
          SELECT jsonb_object_agg(payment_method, method_total)
          FROM (
            SELECT payment_method, jsonb_build_object('count', COUNT(*), 'total', SUM(amount)) as method_total
            FROM public.payments
            WHERE DATE(created_at) = p_date AND status IN ('captured', 'authorized', 'settled') AND is_refund = false
            GROUP BY payment_method
          ) sub
        ),
        'total_refunds', COALESCE((SELECT SUM(ABS(amount)) FROM public.payments WHERE DATE(created_at) = p_date AND is_refund = true AND status = 'refunded'), 0),
        'refund_count', (SELECT COUNT(*) FROM public.payments WHERE DATE(created_at) = p_date AND is_refund = true),
        'failed_count', (SELECT COUNT(*) FROM public.payments WHERE DATE(created_at) = p_date AND status IN ('failed', 'declined')),
        'pending_count', (SELECT COUNT(*) FROM public.payments WHERE DATE(created_at) = p_date AND status IN ('pending', 'processing', 'unknown')),
        'void_count', (SELECT COUNT(*) FROM public.payments WHERE DATE(created_at) = p_date AND status = 'voided')
      )
      FROM public.payments
      WHERE DATE(created_at) = p_date AND is_refund = false
    )
  ) INTO v_result;

  PERFORM public.log_audit(
    'payment_reconciliation', 'system', p_date::text,
    p_performed_by, v_performer_name,
    NULL, v_result, NULL, NULL
  );

  RETURN v_result;
END;
$$;


--
-- Name: payment_reports(date, date); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.payment_reports(p_from date DEFAULT (CURRENT_DATE - '7 days'::interval), p_to date DEFAULT CURRENT_DATE) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  RETURN jsonb_build_object(
    'period', jsonb_build_object('from', p_from, 'to', p_to),
    'totals', (
      SELECT jsonb_build_object(
        'total_payments', COALESCE(SUM(amount), 0),
        'total_tips', COALESCE(SUM(tip_amount), 0),
        'total_refunds', COALESCE((SELECT SUM(ABS(amount)) FROM public.payments WHERE DATE(created_at) BETWEEN p_from AND p_to AND is_refund = true), 0),
        'net_revenue', COALESCE(SUM(amount), 0) - COALESCE((SELECT SUM(ABS(amount)) FROM public.payments WHERE DATE(created_at) BETWEEN p_from AND p_to AND is_refund = true), 0)
      )
      FROM public.payments
      WHERE DATE(created_at) BETWEEN p_from AND p_to AND is_refund = false AND status IN ('captured', 'authorized', 'settled')
    ),
    'by_method', (
      SELECT jsonb_object_agg(payment_method, method_data)
      FROM (
        SELECT payment_method,
          jsonb_build_object(
            'count', COUNT(*),
            'total', SUM(amount),
            'tips', COALESCE(SUM(tip_amount), 0),
            'refunds', COALESCE((SELECT SUM(ABS(amount)) FROM public.payments r WHERE r.payment_method = p.payment_method AND DATE(r.created_at) BETWEEN p_from AND p_to AND r.is_refund = true), 0)
          ) as method_data
        FROM public.payments p
        WHERE DATE(created_at) BETWEEN p_from AND p_to AND is_refund = false AND status IN ('captured', 'authorized', 'settled')
        GROUP BY payment_method
      ) sub
    ),
    'by_day', (
      SELECT jsonb_object_agg(day, day_data)
      FROM (
        SELECT DATE(created_at) as day,
          jsonb_build_object(
            'total', SUM(amount),
            'tips', COALESCE(SUM(tip_amount), 0),
            'count', COUNT(*)
          ) as day_data
        FROM public.payments
        WHERE DATE(created_at) BETWEEN p_from AND p_to AND is_refund = false AND status IN ('captured', 'authorized', 'settled')
        GROUP BY DATE(created_at)
      ) sub
    ),
    'status_breakdown', (
      SELECT jsonb_object_agg(status, status_count)
      FROM (
        SELECT status, COUNT(*) as status_count
        FROM public.payments
        WHERE DATE(created_at) BETWEEN p_from AND p_to
        GROUP BY status
      ) sub
    )
  );
END;
$$;


--
-- Name: perform_stock_audit(uuid, numeric, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.perform_stock_audit(p_ingredient_id uuid, p_actual_qty numeric, p_reason text DEFAULT 'physical_count'::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_ingredient RECORD;
  v_variance   NUMERIC;
  v_variance_pct NUMERIC;
  v_alert_id   UUID;
  v_loc        UUID;
  v_org        UUID;
  v_corr       UUID := gen_random_uuid();
  v_key        TEXT;
  v_id         UUID;
  v_dup        BOOLEAN := false;
BEGIN
  IF p_performed_by IS NOT NULL THEN
    PERFORM public.validate_actor(p_performed_by);
    -- Soft session anchor: capture location/org context if an active session exists.
    SELECT s.active_location_id, s.organization_id
      INTO v_loc, v_org
      FROM public.sessions s
     WHERE s.user_id = p_performed_by
       AND s.revoked_at IS NULL
       AND s.expires_at > now()
     ORDER BY s.last_activity_at DESC
     LIMIT 1;
  END IF;

  SELECT * INTO v_ingredient FROM public.ingredients WHERE id = p_ingredient_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'INGREDIENT_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  v_variance := p_actual_qty - COALESCE(v_ingredient.current_stock, 0);
  v_variance_pct := CASE
    WHEN COALESCE(v_ingredient.current_stock, 0) > 0
    THEN ABS(v_variance) / v_ingredient.current_stock * 100
    ELSE 0
  END;

  v_key := 'stock_audit:' || p_ingredient_id::text
        || ':' || COALESCE(p_performed_by::text, 'svc')
        || ':' || REPLACE(p_actual_qty::text, '.', '_')
        || ':' || SUBSTR(md5(COALESCE(p_reason, 'physical_count')), 1, 8);

  INSERT INTO public.inventory_logs (
    ingredient_id, type, quantity, cost_per_unit, reason,
    reference_type, reference_id,
    correlation_id, idempotency_key, performed_by, location_id, organization_id
  ) VALUES (
    p_ingredient_id, 'adjustment', v_variance, v_ingredient.average_cost_per_unit,
    'Audit: ' || COALESCE(p_reason, 'physical_count'),
    'audit', p_ingredient_id,
    v_corr, v_key, p_performed_by, v_loc, v_org
  )
  ON CONFLICT DO NOTHING
  RETURNING id INTO v_id;

  IF v_id IS NULL THEN
    -- Idempotent retry of the same logical audit: no second movement, no emit.
    v_dup := true;
  END IF;

  UPDATE public.ingredients
     SET theoretical_stock = GREATEST(0, p_actual_qty),
         updated_at = now()
   WHERE id = p_ingredient_id;

  IF NOT v_dup THEN
    PERFORM public.emit_outbox_event('inventory', p_ingredient_id, 'inventory.transaction.created',
      jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', p_ingredient_id,
                         'quantity', v_variance, 'type', 'adjustment'),
      jsonb_build_object('correlation_id', v_corr, 'operation', 'stock_audit',
                         'performed_by', p_performed_by, 'location_id', v_loc,
                         'organization_id', v_org));
    PERFORM public.emit_outbox_event('inventory', p_ingredient_id, 'inventory.stock_changed',
      jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', p_ingredient_id,
                         'quantity', v_variance, 'type', 'adjustment'),
      jsonb_build_object('correlation_id', v_corr, 'operation', 'stock_audit',
                         'performed_by', p_performed_by, 'location_id', v_loc,
                         'organization_id', v_org));

    IF v_variance_pct > 10 THEN
      INSERT INTO public.notifications (type, title, body, data, created_at)
      VALUES (
        'alert',
        'Böyük stok fərqi',
        v_ingredient.name || ' — fərq: ' || ROUND(ABS(v_variance), 2) || ' (' || ROUND(v_variance_pct, 1) || '%)',
        jsonb_build_object('ingredient_id', p_ingredient_id, 'variance', v_variance,
                           'variance_pct', v_variance_pct, 'correlation_id', v_corr),
        now()
      )
      RETURNING id INTO v_alert_id;
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'ingredient_id', p_ingredient_id,
    'variance', v_variance,
    'variance_pct', v_variance_pct,
    'new_stock', GREATEST(0, p_actual_qty),
    'alert_id', v_alert_id,
    'inventory_log_id', v_id,
    'correlation_id', v_corr,
    'duplicate', v_dup
  );
END;
$$;


--
-- Name: prepare_order_items(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prepare_order_items(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated INTEGER;
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- K3-6 (044): finalized-order guard (ORDER_FINALIZED).
  IF v_order.status IN ('paid','cancelled','closed') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_FINALIZED',
      'order_id', p_order_id, 'order_status', v_order.status);
  END IF;

  UPDATE order_items
  SET kitchen_status = 'preparing'
  WHERE order_id = p_order_id
    AND kitchen_status IN ('pending', 'accepted', 'reserved');

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  IF v_updated > 0 THEN
    UPDATE orders SET
      kitchen_status = 'preparing',
      kitchen_accepted_at = now()
    WHERE id = p_order_id
      AND kitchen_status IS DISTINCT FROM 'preparing';
  END IF;

  -- (b) REMOVED: the table status SET 'in_kitchen'. The table stays
  --     'occupied' (decision A); kitchen progression is table.kitchen_status.

  RETURN jsonb_build_object('success', true, 'updated_items', v_updated);
END;
$$;


--
-- Name: prevent_audit_mutation(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prevent_audit_mutation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'Audit records cannot be updated or deleted (0.1.23)';
END;
$$;


--
-- Name: process_due_kitchen_schedules(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_due_kitchen_schedules() RETURNS TABLE(schedule_id uuid, reservation_id uuid, table_number integer)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_due RECORD;
BEGIN
  FOR v_due IN
    UPDATE kitchen_schedule ks
    SET status = 'started'
    WHERE ks.status = 'pending'
      AND ks.scheduled_at <= now()
    RETURNING ks.id, ks.reservation_id, ks.table_number
  LOOP
    UPDATE reservations r
    SET kitchen_scheduled_at = now()
    WHERE r.id = v_due.reservation_id;

    UPDATE orders o
    SET kitchen_status = 'pending',
        kitchen_accepted_at = now()
    WHERE o.reservation_id = v_due.reservation_id
      AND o.kitchen_status = 'reserved';

    UPDATE order_items oi
    SET kitchen_status = 'pending'
    FROM orders o
    WHERE oi.order_id = o.id
      AND o.reservation_id = v_due.reservation_id
      AND oi.kitchen_status = 'reserved';

    INSERT INTO notifications (type, title, body, data, created_at)
    VALUES (
      'kitchen',
      'Mətbəxə hazırlıq göndərildi',
      'Masa ' || v_due.table_number || ' — hazırlığa başlanıldı',
      jsonb_build_object('schedule_id', v_due.id, 'reservation_id', v_due.reservation_id, 'table_number', v_due.table_number),
      now()
    );

    schedule_id := v_due.id;
    reservation_id := v_due.reservation_id;
    table_number := v_due.table_number;
    RETURN NEXT;
  END LOOP;
END;
$$;


--
-- Name: process_expired_reservations_atomic(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_expired_reservations_atomic() RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_r RECORD;
  v_no_show INT := 0;
  v_cancelled INT := 0;
  v_skipped INT := 0;
  v_skip_reasons JSONB := '[]'::jsonb;
BEGIN
  FOR v_r IN
    SELECT * FROM reservations
    WHERE (status = 'confirmed' AND date < CURRENT_DATE - interval '15 days')
       OR (status = 'pending' AND date < CURRENT_DATE - interval '1 hour')
    ORDER BY date ASC
    FOR UPDATE
  LOOP
    BEGIN
      IF v_r.status = 'confirmed' THEN
        UPDATE reservations SET status = 'no_show', no_show_at = now(), updated_at = now()
        WHERE id = v_r.id;
        v_no_show := v_no_show + 1;
        INSERT INTO notifications (type, title, body, data)
        VALUES (
        'reservation',
        'No-show: ' || coalesce(v_r.name, ''),
          coalesce(v_r.name, '') || ' — ' || v_r.date::text || ' ' || coalesce(v_r.time::text, '') || ' reservation marked no-show (expired)',
          jsonb_build_object('reservation_id', v_r.id, 'name', v_r.name, 'date', v_r.date, 'time', v_r.time, 'new_status', 'no_show')
        );
      ELSE
        UPDATE reservations SET status = 'cancelled', cancelled_at = now(), cancelled_reason = 'auto_expired_reservation', updated_at = now()
        WHERE id = v_r.id;
        v_cancelled := v_cancelled + 1;
      END IF;

      INSERT INTO operation_logs (operation, old_state, new_state)
      VALUES (
        'process_expired_reservation',
        jsonb_build_object('status', v_r.status, 'date', v_r.date),
        jsonb_build_object('status', CASE WHEN v_r.status = 'confirmed' THEN 'no_show' ELSE 'cancelled' END)
      );
    EXCEPTION
      WHEN OTHERS THEN
        -- trigger (trg_cleanup_reservation_draft_orders) was blocked by
        -- table_release_guard → reservation stays untouched, flag for manual review
        v_skipped := v_skipped + 1;
        v_skip_reasons := v_skip_reasons || jsonb_build_array(
          v_r.name || ' (' || v_r.status || ' ' || v_r.date::text || '): ' || left(coalesce(SQLERRM,'unknown'), 300)
        );
    END;
  END LOOP;

  RETURN jsonb_build_object(
    'success', true,
    'no_show', v_no_show,
    'cancelled', v_cancelled,
    'skipped', v_skipped,
    'skip_reasons', v_skip_reasons
  );
END;
$$;


--
-- Name: process_order_payment(uuid, text, numeric, numeric, uuid, numeric, text, uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_order_payment(p_order_id uuid, p_payment_method text DEFAULT 'card'::text, p_paid_amount numeric DEFAULT NULL::numeric, p_tip_amount numeric DEFAULT 0, p_campaign_id uuid DEFAULT NULL::uuid, p_discount_amount numeric DEFAULT 0, p_discount_type text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_cash_amount numeric DEFAULT NULL::numeric, p_card_amount numeric DEFAULT NULL::numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
  v_order RECORD;
  v_new_paid numeric;
  v_total_paid numeric;
  v_profit numeric;
  v_cogs numeric := 0;
  v_fully_paid boolean;
  v_result jsonb;
  v_now timestamptz := now();
  v_ingredient RECORD;
  v_already_deducted boolean := false;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Order % not found', p_order_id;
  END IF;
  IF v_order.status = 'paid' THEN
    SELECT COALESCE(SUM(amount), 0) INTO v_total_paid FROM order_payments WHERE order_id = p_order_id;
    RETURN jsonb_build_object('success', false, 'duplicate', true, 'message', 'Order already paid', 'total_paid', v_total_paid, 'cogs', 0, 'profit', 0, 'fully_paid', true);
  END IF;
  v_new_paid := COALESCE(p_paid_amount, 0);
  v_total_paid := v_new_paid;
  v_total_paid := LEAST(v_total_paid, v_order.total_amount);
  IF v_new_paid > v_order.total_amount THEN
    RAISE EXCEPTION 'OVERPAYMENT: paid % exceeds total %', v_new_paid, v_order.total_amount;
  END IF;
  SELECT EXISTS (SELECT 1 FROM inventory_logs WHERE type = 'order_consumption' AND order_id = p_order_id) INTO v_already_deducted;
  IF v_already_deducted THEN
    SELECT COALESCE(SUM(quantity * unit_cost), 0) INTO v_cogs FROM inventory_logs WHERE type = 'order_consumption' AND order_id = p_order_id;
  ELSE
    FOR v_ingredient IN
      SELECT oi.product_id, oi.quantity, r.ingredient_id,
             COALESCE(r.quantity_brutto, r.quantity_required) AS ingred_qty,
             i.average_cost_per_unit, i.current_stock, i.unit
      FROM order_items oi
      JOIN recipes r ON r.menu_item_id = oi.product_id
      JOIN ingredients i ON i.id = r.ingredient_id
      WHERE oi.order_id = p_order_id
    LOOP
      INSERT INTO inventory_logs (ingredient_id, quantity, type, unit_cost, reference_type, reference_id, created_at)
      VALUES (v_ingredient.ingredient_id, -(v_ingredient.ingred_qty * v_ingredient.quantity), 'order_consumption'::inventory_log_type, v_ingredient.average_cost_per_unit, 'order', p_order_id, v_now);
      v_cogs := v_cogs + (v_ingredient.average_cost_per_unit * v_ingredient.ingred_qty * v_ingredient.quantity);
    END LOOP;
  END IF;
  v_profit := v_total_paid - v_cogs;
  IF p_cash_amount IS NOT NULL AND p_cash_amount > 0 THEN
    INSERT INTO order_payments (order_id, payment_method, amount, created_at) VALUES (p_order_id, 'cash', p_cash_amount, v_now);
  END IF;
  IF p_card_amount IS NOT NULL AND p_card_amount > 0 THEN
    INSERT INTO order_payments (order_id, payment_method, amount, created_at) VALUES (p_order_id, 'card', p_card_amount, v_now);
  END IF;
  IF p_cash_amount IS NULL AND p_card_amount IS NULL THEN
    INSERT INTO order_payments (order_id, payment_method, amount, created_at) VALUES (p_order_id, p_payment_method, v_new_paid, v_now);
  END IF;
  UPDATE orders SET status = 'paid', paid_amount = v_total_paid, payment_method = p_payment_method, tip_amount = COALESCE(p_tip_amount, 0), cash_amount = COALESCE(p_cash_amount, 0), card_amount = COALESCE(p_card_amount, 0), cogs = v_cogs, profit = v_profit, paid_at = v_now, inventory_deducted = true, discount_amount = COALESCE(p_discount_amount, 0), discount_type = p_discount_type, campaign_id = p_campaign_id, updated_at = v_now WHERE id = p_order_id;
  IF COALESCE(v_order.order_source, 'dine_in') = 'dine_in' AND v_order.table_number IS NOT NULL THEN
    UPDATE table_floors SET status = 'dirty', total_amount = 0, guest_count = NULL, order_count = 0, bill_requested = false WHERE table_number = v_order.table_number;
  END IF;
  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, performed_by) VALUES ('orders', p_order_id, 'payment', jsonb_build_object('status', v_order.status), jsonb_build_object('status', 'paid', 'amount', v_total_paid, 'cogs', v_cogs, 'profit', v_profit, 'method', p_payment_method, 'discount_type', p_discount_type, 'discount_amount', p_discount_amount, 'tip', p_tip_amount, 'total_paid', v_total_paid), p_performed_by);
  INSERT INTO notifications (title, body, type, created_at) VALUES ('Ödəniş qəbul edildi', CASE WHEN v_order.table_number IS NOT NULL THEN 'Masa ' || v_order.table_number || ' - ' || v_total_paid || ' AZN (cogs: ' || v_cogs || ', profit: ' || v_profit || ')' ELSE v_total_paid || ' AZN ödəniş qəbul edildi' END, 'payment', v_now);
  SELECT jsonb_build_object('success', true, 'cogs', v_cogs, 'profit', v_profit, 'fully_paid', v_total_paid >= v_order.total_amount, 'paid_amount', v_new_paid, 'total_paid', v_total_paid, 'duplicate', false) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: process_stock_in(uuid, numeric, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_stock_in(p_ingredient_id uuid, p_quantity numeric, p_unit_cost numeric DEFAULT NULL::numeric, p_reason text DEFAULT 'stock_in'::text, p_reference_type text DEFAULT NULL::text, p_reference_id uuid DEFAULT NULL::uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_old_stock NUMERIC;
  v_ingredient RECORD;
  v_id uuid;
  v_corr uuid := gen_random_uuid();
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_ingredient FROM ingredients WHERE id = p_ingredient_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'INGREDIENT_NOT_FOUND' USING ERRCODE = 'P0001'; END IF;

  v_old_stock := COALESCE(v_ingredient.current_stock, 0);

  INSERT INTO inventory_logs (ingredient_id, type, quantity, cost_per_unit, reason, reference_type, reference_id, notes, created_at)
  VALUES (p_ingredient_id, 'stock_in', p_quantity, p_unit_cost, p_reason,
    p_reference_type, p_reference_id,
    'Stock in: +' || p_quantity || ' @ ' || COALESCE(p_unit_cost::TEXT, '0'), now())
  RETURNING id INTO v_id;

  IF v_id IS NOT NULL THEN
    PERFORM public.emit_outbox_event('inventory', p_ingredient_id, 'inventory.transaction.created',
      jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', p_ingredient_id, 'quantity', p_quantity, 'type', 'stock_in'),
      jsonb_build_object('correlation_id', v_corr, 'operation', 'stock_in', 'performed_by', p_performed_by));
    PERFORM public.emit_outbox_event('inventory', p_ingredient_id, 'inventory.stock_changed',
      jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', p_ingredient_id, 'quantity', p_quantity, 'type', 'stock_in'),
      jsonb_build_object('correlation_id', v_corr, 'operation', 'stock_in', 'performed_by', p_performed_by));
  END IF;

  RETURN jsonb_build_object('success', true, 'ingredient_id', p_ingredient_id,
    'previous_stock', v_old_stock, 'new_stock', v_old_stock + p_quantity,
    'new_avg_cost', (SELECT average_cost_per_unit FROM ingredients WHERE id = p_ingredient_id),
    'purchase_price', (SELECT purchase_price FROM ingredients WHERE id = p_ingredient_id));
END;
$$;


--
-- Name: process_supplier_return(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.process_supplier_return(p_return_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_return RECORD;
  v_item RECORD;
  v_total NUMERIC(12,2) := 0;
  v_id uuid;
  v_corr uuid := gen_random_uuid();
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_return FROM supplier_returns WHERE id = p_return_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'RETURN_NOT_FOUND' USING ERRCODE = 'P0001'; END IF;
  IF v_return.status != 'draft' THEN RAISE EXCEPTION 'RETURN_ALREADY_PROCESSED' USING ERRCODE = 'P0001'; END IF;

  FOR v_item IN
    SELECT sri.*, i.name, i.current_stock
    FROM supplier_return_items sri
    JOIN ingredients i ON i.id = sri.ingredient_id
    WHERE sri.supplier_return_id = p_return_id
    FOR UPDATE
  LOOP
    -- Log-only with positive quantity: 'waste' type signs -q in the effect
    -- trigger (one correct stock reduction). No direct current_stock UPDATE.
    INSERT INTO inventory_logs (ingredient_id, type, quantity, cost_per_unit, reason, reference_type, reference_id, notes, created_at)
    VALUES (v_item.ingredient_id, 'waste', v_item.quantity, v_item.unit_cost,
      'return_to_supplier', 'supplier_return', p_return_id,
      'Returned to supplier: ' || v_item.quantity || ' x ' || COALESCE(v_item.unit_cost, 0), now())
    RETURNING id INTO v_id;

    IF v_id IS NOT NULL THEN
      PERFORM public.emit_outbox_event('inventory', v_item.ingredient_id, 'inventory.transaction.created',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', v_item.ingredient_id, 'quantity', v_item.quantity, 'type', 'waste'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'supplier_return', 'performed_by', p_performed_by));
      PERFORM public.emit_outbox_event('inventory', v_item.ingredient_id, 'inventory.stock_changed',
        jsonb_build_object('inventory_log_id', v_id, 'ingredient_id', v_item.ingredient_id, 'quantity', v_item.quantity, 'type', 'waste'),
        jsonb_build_object('correlation_id', v_corr, 'operation', 'supplier_return', 'performed_by', p_performed_by));
    END IF;

    v_total := v_total + v_item.total_cost;
  END LOOP;

  UPDATE supplier_returns SET status = 'completed', total_amount = v_total, returned_at = now(), updated_at = now()
  WHERE id = p_return_id;

  INSERT INTO notifications (type, title, body, data, created_at)
  VALUES ('stock', 'Təchizatçıya geri qaytarılma',
    v_return.return_number || ' — ' || v_total || ' AZN',
    jsonb_build_object('return_id', p_return_id, 'supplier_id', v_return.supplier_id, 'total_amount', v_total), now());

  RETURN jsonb_build_object('success', true, 'return_id', p_return_id, 'total_amount', v_total, 'return_number', v_return.return_number);
END;
$$;


--
-- Name: prune_expired_idempotency_keys(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.prune_expired_idempotency_keys() RETURNS integer
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_pruned integer := 0;
BEGIN
  -- advisory lock: concurrent callers (pay/refund routes, best-effort) serialize
  IF NOT pg_try_advisory_lock(41000001) THEN
    RETURN 0;
  END IF;
  BEGIN
    DELETE FROM payment_idempotency_keys WHERE expires_at IS NOT NULL AND expires_at < now();
    GET DIAGNOSTICS v_pruned = ROW_COUNT;
  EXCEPTION WHEN OTHERS THEN
    PERFORM pg_advisory_unlock(41000001);
    RETURN 0;
  END;
  PERFORM pg_advisory_unlock(41000001);
  RETURN v_pruned;
END;
$$;


--
-- Name: push_reservation_to_kitchen(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.push_reservation_to_kitchen(p_order_id uuid, p_schedule_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_updated int := 0;
BEGIN
  UPDATE public.orders
  SET    kitchen_status = 'pending',
         kitchen_accepted_at = v_now,
         updated_at = v_now
  WHERE  id = p_order_id;

  UPDATE public.order_items
  SET    kitchen_status = 'pending',
         updated_at = v_now
  WHERE  order_id = p_order_id
  AND    kitchen_status = 'reserved';

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  UPDATE public.kitchen_schedule
  SET    status = 'started'
  WHERE  id = p_schedule_id;

  PERFORM public.log_audit(
    'reservation_pushed_to_kitchen', p_order_id, NULL, p_performed_by,
    NULL, NULL, NULL, NULL,
    jsonb_build_object('items_activated', v_updated, 'schedule_id', p_schedule_id),
    NULL, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'items_activated', v_updated);
END;
$$;


