--
-- Name: recalculate_cash_session(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_cash_session(p_session_id uuid) RETURNS numeric
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_session cash_drawer_sessions%ROWTYPE;
  v_expected NUMERIC;
BEGIN
  SELECT * INTO v_session FROM cash_drawer_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RETURN NULL; END IF;
  SELECT COALESCE(SUM(CASE WHEN type IN ('payment','cash_in','card_payment','open') THEN amount ELSE 0 END), 0)
         - COALESCE(SUM(CASE WHEN type IN ('cash_out') THEN amount ELSE 0 END), 0)
    INTO v_expected
    FROM cash_drawer_log
    WHERE session_id = p_session_id;
  UPDATE cash_drawer_sessions SET expected_balance = v_expected WHERE id = p_session_id;
  RETURN v_expected;
END;
$$;


--
-- Name: recalculate_cost_for_recipe(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_cost_for_recipe() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product_id uuid;
  v_total_cost numeric;
  v_price numeric;
  v_margin numeric;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_product_id := OLD.menu_item_id;
  ELSE
    v_product_id := NEW.menu_item_id;
  END IF;

  SELECT price INTO v_price FROM products WHERE id = v_product_id;

  -- quantity_brutto istifadə et (cold waste daxil)
  SELECT COALESCE(SUM(COALESCE(r.quantity_brutto, r.quantity_required) * i.average_cost_per_unit), 0)
  INTO v_total_cost
  FROM recipes r
  JOIN ingredients i ON i.id = r.ingredient_id
  WHERE r.menu_item_id = v_product_id AND r.is_ai_suggested = false;

  IF v_price > 0 THEN
    v_margin := ((v_price - v_total_cost) / v_price) * 100;
  ELSE
    v_margin := 0;
  END IF;

  UPDATE products
  SET cost_price = ROUND(v_total_cost, 2),
      profit_margin = ROUND(v_margin, 1)
  WHERE id = v_product_id;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: recalculate_order_payment_state(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_order_payment_state(p_order_id uuid) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_paid     NUMERIC := 0;
  v_cash     NUMERIC := 0;
  v_refund   NUMERIC := 0;
  v_order    RECORD;
  v_payable  NUMERIC;
  v_method   TEXT;
  v_status   TEXT;
BEGIN
  -- B1: 'captured' (canonical) is now counted as paid. Legacy statuses kept.
  SELECT COALESCE(SUM(amount), 0)
    INTO v_paid
    FROM order_payments
   WHERE order_id = p_order_id
     AND COALESCE(status, 'success') IN ('success','paid','authorized','captured')
     AND COALESCE(is_refund, false) = false;

  SELECT COALESCE(SUM(amount), 0)
    INTO v_cash
    FROM order_payments
   WHERE order_id = p_order_id
     AND COALESCE(status, 'success') IN ('success','paid','authorized','captured')
     AND COALESCE(is_refund, false) = false
     AND payment_method IN ('cash','nağd');

  SELECT COALESCE(SUM(amount), 0)
    INTO v_refund
    FROM order_payments
   WHERE order_id = p_order_id
     AND COALESCE(is_refund, false) = true;

  SELECT * INTO v_order FROM orders WHERE id = p_order_id;
  IF NOT FOUND THEN RETURN; END IF;

  v_payable := COALESCE(v_order.total_amount, 0) - COALESCE(v_order.discount_amount, 0);
  v_method  := v_order.payment_method;
  IF v_paid > 0 THEN
    IF v_cash > 0 AND (v_paid - v_cash) > 0 THEN v_method := 'split';
    ELSIF (v_paid - v_cash) > 0 THEN v_method := 'card';
    ELSE v_method := 'cash';
    END IF;
  END IF;

  IF v_paid > 0 AND v_refund >= v_paid THEN
    v_status := 'refunded';
  ELSIF v_refund > 0 THEN
    v_status := 'partially_refunded';
  ELSIF v_payable > 0 AND v_paid >= v_payable THEN
    v_status := 'paid';
  ELSE
    v_status := v_order.status;
  END IF;

  UPDATE orders SET
    paid_amount   = v_paid,
    cash_amount   = v_cash,
    card_amount   = (v_paid - v_cash),
    refund_amount = v_refund,
    payment_method = CASE WHEN v_paid > 0 THEN v_method ELSE v_order.payment_method END,
    status = v_status,
    paid_at = CASE
                 WHEN v_payable > 0 AND v_paid >= v_payable AND v_order.paid_at IS NULL THEN NOW()
                 ELSE v_order.paid_at
               END,
    version   = COALESCE(v_order.version, 0) + 1,
    updated_at = NOW()
  WHERE id = p_order_id;
END;
$$;


--
-- Name: recalculate_product_costs(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recalculate_product_costs() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_product RECORD;
  v_total_cost numeric;
  v_margin numeric;
BEGIN
  FOR v_product IN
    SELECT DISTINCT p.id, p.price
    FROM products p
    JOIN recipes r ON r.menu_item_id = p.id
    WHERE r.ingredient_id = NEW.id AND r.is_ai_suggested = false
  LOOP
    -- Maya dəyəri = Σ(quantity_brutto × average_cost_per_unit)
    -- quantity_brutto cold waste-i əhatə edir
    SELECT COALESCE(SUM(COALESCE(r2.quantity_brutto, r2.quantity_required) * i2.average_cost_per_unit), 0)
    INTO v_total_cost
    FROM recipes r2
    JOIN ingredients i2 ON i2.id = r2.ingredient_id
    WHERE r2.menu_item_id = v_product.id AND r2.is_ai_suggested = false;

    IF v_product.price > 0 THEN
      v_margin := ((v_product.price - v_total_cost) / v_product.price) * 100;
    ELSE
      v_margin := 0;
    END IF;

    UPDATE products
    SET cost_price = ROUND(v_total_cost, 2),
        profit_margin = ROUND(v_margin, 1)
    WHERE id = v_product.id;
  END LOOP;

  RETURN NEW;
END;
$$;


--
-- Name: recall_order_items(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_order_items(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated INTEGER := 0;
BEGIN
  UPDATE order_items
  SET kitchen_status = 'preparing'
  WHERE order_id = p_order_id
    AND kitchen_status = 'ready';

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'order_items',
    p_order_id,
    'recall',
    jsonb_build_object('order_id', p_order_id),
    jsonb_build_object('recalled_items', v_updated),
    p_performed_by,
    now()
  );

  RETURN jsonb_build_object('success', true, 'recalled_items', v_updated);
END;
$$;


--
-- Name: recall_ticket_atomic(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.recall_ticket_atomic(p_order_id uuid, p_reason text DEFAULT 'recall'::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status NOT IN ('accepted', 'preparing', 'ready', 'served') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order cannot be recalled from current status');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'pending',
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  UPDATE public.order_items SET
    kitchen_status = 'pending',
    updated_at = NOW()
  WHERE order_id = p_order_id AND kitchen_status IN ('accepted', 'preparing', 'ready', 'served');

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'pending',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'recall_ticket',
    jsonb_build_object('kitchen_status', v_order.kitchen_status),
    jsonb_build_object('kitchen_status', 'pending', 'reason', p_reason),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: reconcile_table_aggregates(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reconcile_table_aggregates(p_min_table_number integer DEFAULT NULL::integer, p_max_table_number integer DEFAULT NULL::integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_scanned int := 0;
  v_fixed   int := 0;
  v_first   int;
  v_last    int;
  v_fixed_tables int[];
  v_floor   public.table_floors;
BEGIN
  PERFORM public.validate_actor(p_performed_by);

  FOR v_floor IN
    SELECT * FROM public.table_floors
     WHERE (p_min_table_number IS NULL OR table_number >= p_min_table_number)
       AND (p_max_table_number IS NULL OR table_number <= p_max_table_number)
     ORDER BY table_number
  LOOP
    v_scanned := v_scanned + 1;
    PERFORM public.sync_table_order_aggregates(v_floor.table_number);
    -- detect whether the floor actually moved (no-op sync changed nothing)
    IF (SELECT version FROM public.table_floors WHERE table_number = v_floor.table_number)
       <> v_floor.version THEN
      v_fixed := v_fixed + 1;
      IF v_first IS NULL THEN v_first := v_floor.table_number; END IF;
      v_last := v_floor.table_number;
      v_fixed_tables := array_append(v_fixed_tables, v_floor.table_number);
    END IF;
  END LOOP;

  -- Audit ONLY when a repair actually happened, and OPLOG-ONLY (p_event NULL →
  -- no synthetic outbox event the frontend does not understand). A silent
  -- no-op run leaves no trace (correct: nothing changed).
  IF v_fixed > 0 THEN
    PERFORM public.g_table_audit(
      'reconcile_aggregates', NULL,
      v_first, NULL, NULL,
      jsonb_build_object('scanned', v_scanned),
      jsonb_build_object('fixed', v_fixed, 'tables', v_fixed_tables),
      p_performed_by, 'reconciler', 'order-agg-reconciler:v1',
      v_first, NULL, NULL, NULL);
  END IF;

  RETURN jsonb_build_object('scanned', v_scanned, 'fixed', v_fixed,
    'first_table', v_first, 'last_table', v_last, 'tables', v_fixed_tables);
END;
$$;


