--
-- Name: record_item_waste(uuid, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_item_waste(p_order_item_id uuid, p_quantity integer DEFAULT NULL::integer, p_reason text DEFAULT 'waste'::text, p_reason_text text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_oi RECORD;
  v_order RECORD;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
  v_waste_qty INT;
  v_new_qty INT;
  v_valid_reasons text[] := ARRAY['customer_return','kitchen_error','burned','spilled','wrong_item','expired','spoilage','other'];
  v_product RECORD;
  v_rec RECORD;
  v_corr uuid := gen_random_uuid();
  v_key text;
  v_id uuid;
  v_wasted INT := 0;
  v_prod_found boolean := false;
BEGIN
  SELECT * INTO v_oi FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order item not found');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_oi.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_oi.kitchen_status NOT IN ('ready', 'completed', 'served') THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Cannot waste item in state: ' || COALESCE(v_oi.kitchen_status, 'pending') || '. Use void for DRAFT/SENT/PREPARING.',
      'current_state', COALESCE(v_oi.kitchen_status, 'pending')
    );
  END IF;

  IF p_reason IS NULL OR NOT (p_reason = ANY(v_valid_reasons)) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Invalid reason. Valid reasons: ' || array_to_string(v_valid_reasons, ', '),
      'valid_reasons', to_jsonb(v_valid_reasons)
    );
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  v_waste_qty := COALESCE(p_quantity, v_oi.quantity);
  IF v_waste_qty <= 0 OR v_waste_qty > v_oi.quantity THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid waste quantity');
  END IF;

  INSERT INTO public.cancelled_orders (order_id, reason, reason_text, items, total_amount, created_at)
  VALUES (
    v_oi.order_id,
    CASE
      WHEN p_reason = 'customer_return' THEN 'customer_refused'
      WHEN p_reason = 'wrong_item' THEN 'wrong_order'
      WHEN p_reason = 'other' THEN 'other'
      ELSE 'waste'
    END,
    COALESCE(p_reason_text, 'İtki: ' || COALESCE(v_oi.product_name, 'Məhsul')),
    jsonb_build_array(jsonb_build_object(
      'order_item_id', v_oi.id,
      'product_id', v_oi.product_id,
      'product_name', v_oi.product_name,
      'quantity', v_waste_qty,
      'unit_price', v_oi.unit_price,
      'kitchen_status', v_oi.kitchen_status,
      'reason', p_reason
    )),
    v_oi.unit_price * v_waste_qty,
    v_now
  );

  -- H8: consumed (ready/served/completed) => write canonical waste ledger rows.
  IF NOT EXISTS (
    SELECT 1 FROM public.inventory_logs l WHERE l.order_item_id = p_order_item_id AND l.type = 'waste'
  ) THEN
    SELECT * INTO v_product FROM public.products WHERE id = v_oi.product_id;
    IF FOUND THEN
      v_prod_found := true;
    END IF;

    IF v_prod_found AND v_product.is_ready_product AND v_product.direct_ingredient_id IS NOT NULL THEN
      v_key := 'waste:' || p_order_item_id::text || ':' || v_product.direct_ingredient_id::text;
      INSERT INTO public.inventory_logs (
        ingredient_id, type, quantity, unit, order_id, order_item_id, item_quantity,
        reference_type, reference_id, correlation_id, idempotency_key, performed_by,
        reason, created_at, location_id, organization_id
      ) VALUES (
        v_product.direct_ingredient_id, 'waste', v_waste_qty,
        (SELECT COALESCE(unit, 'gram') FROM public.ingredients WHERE id = v_product.direct_ingredient_id),
        v_oi.order_id, p_order_item_id, v_waste_qty, 'order', v_oi.order_id, v_corr, v_key,
        p_performed_by, COALESCE(p_reason_text, 'İtki: ' || COALESCE(v_oi.product_name, 'Məhsul')),
        v_now, v_order.location_id, v_order.organization_id
      )
      ON CONFLICT DO NOTHING RETURNING id INTO v_id;
      IF v_id IS NOT NULL THEN v_wasted := 1; END IF;

    ELSIF v_prod_found THEN
      FOR v_rec IN
        SELECT r.ingredient_id, r.quantity_required, r.quantity_brutto,
               COALESCE(i.unit, 'gram') AS unit
        FROM public.recipes r
        JOIN public.ingredients i ON i.id = r.ingredient_id
        WHERE r.menu_item_id = v_oi.product_id AND r.is_ai_suggested = false
      LOOP
        v_key := 'waste:' || p_order_item_id::text || ':' || v_rec.ingredient_id::text;
        INSERT INTO public.inventory_logs (
          ingredient_id, type, quantity, unit, order_id, order_item_id, item_quantity,
          reference_type, reference_id, correlation_id, idempotency_key, performed_by,
          reason, created_at, location_id, organization_id
        ) VALUES (
          v_rec.ingredient_id, 'waste',
          COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_waste_qty,
          v_rec.unit, v_oi.order_id, p_order_item_id, v_waste_qty, 'order', v_oi.order_id,
          v_corr, v_key, p_performed_by,
          COALESCE(p_reason_text, 'İtki: ' || COALESCE(v_oi.product_name, 'Məhsul')),
          v_now, v_order.location_id, v_order.organization_id
        )
        ON CONFLICT DO NOTHING RETURNING id INTO v_id;
        IF v_id IS NOT NULL THEN v_wasted := 1; END IF;
      END LOOP;
    END IF;

    IF v_wasted > 0 THEN
      PERFORM public.emit_outbox_event('inventory', v_oi.product_id, 'inventory.transaction.created',
        jsonb_build_object('order_item_id', p_order_item_id, 'product_id', v_oi.product_id, 'quantity', v_waste_qty, 'type', 'waste'),
        jsonb_build_object('correlation_id', v_corr));
    END IF;
  END IF;

  IF v_waste_qty >= v_oi.quantity THEN
    UPDATE public.order_items SET kitchen_status = 'voided', total_price = 0 WHERE id = v_oi.id;
  ELSE
    v_new_qty := v_oi.quantity - v_waste_qty;
    UPDATE public.order_items SET quantity = v_new_qty, total_price = COALESCE(unit_price, 0) * v_new_qty WHERE id = v_oi.id;
  END IF;

  UPDATE public.orders SET
    total_amount = GREATEST(0, (SELECT COALESCE(SUM(total_price), 0) FROM public.order_items WHERE order_id = v_oi.order_id AND kitchen_status != 'voided'))
  WHERE id = v_oi.order_id;

  IF NOT EXISTS (SELECT 1 FROM public.order_items WHERE order_id = v_oi.order_id AND kitchen_status != 'voided') THEN
    UPDATE public.orders SET status = 'cancelled', kitchen_status = 'cancelled', cancelled_at = v_now WHERE id = v_oi.order_id;
  END IF;

  PERFORM public.log_audit(
    'item_waste', 'order_item', p_order_item_id::text,
    p_performed_by, v_performer_name, NULL,
    jsonb_build_object(
      'product_name', v_oi.product_name,
      'quantity', v_waste_qty,
      'reason', p_reason,
      'reason_text', p_reason_text,
      'kitchen_status', v_oi.kitchen_status
    ),
    jsonb_build_object('order_id', v_oi.order_id, 'order_item_id', p_order_item_id),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true, 'action', 'waste',
    'product_name', v_oi.product_name,
    'quantity_wasted', v_waste_qty,
    'reason', p_reason,
    'order_id', v_oi.order_id, 'timestamp', v_now
  );
END;
$$;


--
-- Name: record_login_attempt(text, text, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_login_attempt(p_identifier text, p_ip text DEFAULT NULL::text, p_success boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  INSERT INTO public.login_attempts (identifier, ip_address, success)
  VALUES (p_identifier, p_ip, p_success);

  -- Cleanup old records (>24 hours)
  DELETE FROM public.login_attempts WHERE created_at < NOW() - interval '24 hours';
END;
$$;


--
-- Name: record_login_attempt(uuid, boolean, text, inet, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_login_attempt(p_staff_id uuid, p_success boolean, p_failure_reason text DEFAULT NULL::text, p_ip_address inet DEFAULT NULL::inet, p_user_agent text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    INSERT INTO login_attempts (staff_id, success, failure_reason, ip_address, user_agent)
    VALUES (p_staff_id, p_success, p_failure_reason, p_ip_address, p_user_agent);

    -- Update staff on failed attempt
    IF NOT p_success THEN
        UPDATE staff
        SET failed_login_attempts = failed_login_attempts + 1,
            locked_until = CASE
                WHEN failed_login_attempts + 1 >= 5
                THEN now() + interval '15 minutes'
                ELSE locked_until
            END
        WHERE id = p_staff_id;
    END IF;

    -- Reset on success
    IF p_success THEN
        UPDATE staff
        SET failed_login_attempts = 0,
            locked_until = NULL,
            last_login_at = now()
        WHERE id = p_staff_id;
    END IF;
END;
$$;


--
-- Name: record_payment_attempt(uuid, text, numeric, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.record_payment_attempt(p_payment_id uuid, p_status text, p_amount numeric, p_provider_response jsonb DEFAULT NULL::jsonb, p_provider_error text DEFAULT NULL::text, p_terminal_id text DEFAULT NULL::text) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_next_attempt int;
  v_attempt_id uuid;
BEGIN
  SELECT COALESCE(MAX(attempt_number), 0) + 1 INTO v_next_attempt
  FROM public.payment_attempts WHERE payment_id = p_payment_id;

  INSERT INTO public.payment_attempts (payment_id, attempt_number, status, provider_response, provider_error, amount, terminal_id, completed_at)
  VALUES (p_payment_id, v_next_attempt, p_status, p_provider_response, p_provider_error, p_amount, p_terminal_id, NOW())
  RETURNING id INTO v_attempt_id;

  -- Update payment status if terminal response
  IF p_status IN ('authorized', 'captured', 'failed', 'declined') THEN
    UPDATE public.payments SET status = p_status, updated_at = NOW() WHERE id = p_payment_id;
  END IF;

  RETURN v_attempt_id;
END;
$$;


--
-- Name: refund_payment_atomic(uuid, numeric, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_payment_atomic(p_order_id uuid, p_amount numeric, p_method text DEFAULT 'cash'::text, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_cash_drawer_session_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_refund_id UUID;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_NOT_FOUND');
  END IF;

  INSERT INTO order_payments (
    order_id, payment_method, method, amount, status, is_refund, created_by
  ) VALUES (
    p_order_id, p_method, p_method, p_amount, 'success', true, p_performed_by
  ) RETURNING id INTO v_refund_id;

  PERFORM public.log_audit(
    'refund', 'order', p_order_id::text,
    p_performed_by, NULL,
    jsonb_build_object('amount', v_order.paid_amount),
    jsonb_build_object('amount', v_order.paid_amount - p_amount, 'refund', p_amount),
    jsonb_build_object('payment_id', v_refund_id, 'reason', p_reason),
    NULL
  );

  RETURN jsonb_build_object('success', true, 'refund_id', v_refund_id, 'refund_amount', p_amount);
END;
$$;


--
-- Name: refund_with_inventory(uuid, uuid, integer, numeric, text, text, text, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_with_inventory(p_order_id uuid, p_order_item_id uuid, p_quantity integer, p_amount numeric, p_method text DEFAULT 'cash'::text, p_item_fate text DEFAULT 'waste'::text, p_reason text DEFAULT NULL::text, p_reason_text text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_oi RECORD;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
  v_refund_qty INT;
  v_refund_amount NUMERIC;
  v_new_refund NUMERIC;
  v_product RECORD;
  v_rec RECORD;
  v_stock_returned INT := 0;
  v_waste_recorded INT := 0;
  v_corr uuid := gen_random_uuid();
  v_key text;
  v_id uuid;
  v_paid_after NUMERIC;
  v_refund_after NUMERIC;
  v_status_after TEXT;
  v_prod_found boolean := false;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;
  -- ═══ P-1 M2: LOCATION ASSERTION (fail-closed, D-5; ratified 2026-09-12) ═══
  IF p_location_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'LOCATION_CONTEXT_MISSING');
  END IF;
  IF v_order.location_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_LOCATION_NULL');
  END IF;
  IF v_order.location_id IS DISTINCT FROM p_location_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'LOCATION_MISMATCH');
  END IF;
  IF p_performed_by IS NOT NULL
     AND NOT public.p1_actor_allowed_at_location(p_performed_by, p_location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'LOCATION_ACCESS_DENIED');
  END IF;
  IF v_order.status NOT IN ('paid', 'partially_refunded') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only refund paid or partially_refunded orders. Current: ' || v_order.status);
  END IF;

  SELECT * INTO v_oi FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order item not found');
  END IF;
  IF v_oi.order_id != p_order_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item does not belong to this order');
  END IF;
  IF v_oi.kitchen_status NOT IN ('ready', 'completed', 'served') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot refund item in state: ' || COALESCE(v_oi.kitchen_status, 'pending'));
  END IF;

  v_refund_qty := COALESCE(p_quantity, 1);
  IF v_refund_qty <= 0 OR v_refund_qty > v_oi.quantity THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid refund quantity. Max: ' || v_oi.quantity);
  END IF;

  v_refund_amount := COALESCE(p_amount, v_oi.unit_price * v_refund_qty);
  IF v_refund_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid refund amount');
  END IF;

  -- H10.1: refundable = paid_amount - refund_amount. paid_amount is NEVER
  -- decremented; cumulative refunds are compared against the original paid.
  v_new_refund := COALESCE(v_order.refund_amount, 0) + v_refund_amount;
  IF v_new_refund > COALESCE(v_order.paid_amount, 0) THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Refund (' || v_refund_amount || ') exceeds remaining refundable (' ||
      ROUND(COALESCE(v_order.paid_amount, 0) - COALESCE(v_order.refund_amount, 0), 2) || ')');
  END IF;

  IF p_item_fate NOT IN ('return_to_stock', 'waste') THEN
    RETURN jsonb_build_object('success', false, 'error', 'item_fate must be return_to_stock or waste');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  SELECT * INTO v_product FROM public.products WHERE id = v_oi.product_id;
  IF FOUND THEN
    v_prod_found := true;
  END IF;

  -- H10.1: fate idempotency guards run BEFORE any money write so a duplicate
  -- refund can never record money and then fail.
  IF p_item_fate = 'return_to_stock' THEN
    IF EXISTS (
      SELECT 1 FROM public.inventory_logs
      WHERE order_item_id = p_order_item_id AND type IN ('reversal', 'stock_return')
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Stock already returned for this item');
    END IF;
  ELSIF p_item_fate = 'waste' THEN
    IF EXISTS (
      SELECT 1 FROM public.cancelled_orders
      WHERE order_id = p_order_id
        AND reason IN ('waste', 'refund_waste')
        AND items @> jsonb_build_array(jsonb_build_object('order_item_id', p_order_item_id))
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Waste already recorded for this item');
    END IF;
  END IF;

  -- ===== Financial record =====
  -- Legacy compatibility/reporting mirror (negative refund convention).
  INSERT INTO public.payments (
    order_id, payment_method, amount, status, is_refund,
    performed_by, performed_by_name, notes, metadata, idempotency_key
  ) VALUES (
    p_order_id, p_method, -ABS(v_refund_amount), 'refunded', true,
    p_performed_by, v_performer_name, p_reason_text,
    jsonb_build_object(
      'reason', p_reason,
      'reason_text', p_reason_text,
      'item_fate', p_item_fate,
      'order_item_id', p_order_item_id,
      'quantity', v_refund_qty
    ),
    'refund:' || p_order_item_id::text || ':' || v_corr::text
  );

  -- Canonical financial SSOT refund row (amount > 0, is_refund = true,
  -- status = 'captured').
  INSERT INTO public.order_payments (
    order_id, amount, payment_method, method, currency, status,
    is_refund, reference, performed_by, created_by,
    idempotency_key, correlation_id
  ) VALUES (
    p_order_id, v_refund_amount, p_method, p_method, 'AZN',
    'captured', true, p_reason_text,
    p_performed_by, p_performed_by,
    'refund:' || p_order_item_id::text || ':' || v_corr::text,
    v_corr
  );

  -- orders financial state derived through the canonical recalculator.
  UPDATE public.orders SET
    refund_reason = p_reason_text,
    refunded_at   = v_now
  WHERE id = p_order_id;

  PERFORM public.recalculate_order_payment_state(p_order_id);

  SELECT COALESCE(paid_amount, 0), COALESCE(refund_amount, 0), status
    INTO v_paid_after, v_refund_after, v_status_after
  FROM public.orders WHERE id = p_order_id;

  -- ===== Inventory fate =====
  IF p_item_fate = 'return_to_stock' THEN
    IF v_prod_found AND v_product.is_ready_product AND v_product.direct_ingredient_id IS NOT NULL THEN
      v_key := 'refund:' || p_order_item_id::text || ':' || v_product.direct_ingredient_id::text;
      INSERT INTO public.inventory_logs (
        ingredient_id, type, quantity, unit, order_id, order_item_id,
        item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
        performed_by, reason, created_at, location_id, organization_id
      ) VALUES (
        v_product.direct_ingredient_id, 'reversal', v_refund_qty,
        (SELECT COALESCE(unit, 'gram') FROM public.ingredients WHERE id = v_product.direct_ingredient_id),
        p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
        v_corr, v_key, p_performed_by,
        'Refund — return to stock: ' || COALESCE(v_oi.product_name, 'Məhsul'),
        v_now, v_order.location_id, v_order.organization_id
      )
      ON CONFLICT DO NOTHING RETURNING id INTO v_id;
      IF v_id IS NOT NULL THEN
        v_stock_returned := 1;
        PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.transaction.created',
          jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_refund_qty, 'type', 'reversal'),
          jsonb_build_object('correlation_id', v_corr));
        PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.stock_changed',
          jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_refund_qty),
          jsonb_build_object('correlation_id', v_corr));
      END IF;

    ELSIF v_prod_found THEN
      FOR v_rec IN
        SELECT r.ingredient_id, r.quantity_required, r.quantity_brutto,
               COALESCE(i.unit, 'gram') AS unit
        FROM public.recipes r
        JOIN public.ingredients i ON i.id = r.ingredient_id
        WHERE r.menu_item_id = v_oi.product_id AND r.is_ai_suggested = false
      LOOP
        v_key := 'refund:' || p_order_item_id::text || ':' || v_rec.ingredient_id::text;
        INSERT INTO public.inventory_logs (
          ingredient_id, type, quantity, unit, order_id, order_item_id,
          item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
          performed_by, reason, created_at, location_id, organization_id
        ) VALUES (
          v_rec.ingredient_id, 'reversal',
          COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty,
          v_rec.unit, p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
          v_corr, v_key, p_performed_by,
          'Refund — return to stock: ' || COALESCE(v_oi.product_name, 'Məhsul'),
          v_now, v_order.location_id, v_order.organization_id
        )
        ON CONFLICT DO NOTHING RETURNING id INTO v_id;
        IF v_id IS NOT NULL THEN
          v_stock_returned := 1;
          PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.transaction.created',
            jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty, 'type', 'reversal'),
            jsonb_build_object('correlation_id', v_corr));
          PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.stock_changed',
            jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty),
            jsonb_build_object('correlation_id', v_corr));
        END IF;
      END LOOP;
    END IF;

  ELSIF p_item_fate = 'waste' THEN
    INSERT INTO public.cancelled_orders (
      order_id, reason, reason_text, items, total_amount, created_at
    ) VALUES (
      p_order_id, 'waste',
      COALESCE(p_reason_text, 'Refund + waste: ' || COALESCE(v_oi.product_name, 'Məhsul')),
      jsonb_build_array(jsonb_build_object(
        'order_item_id', p_order_item_id,
        'product_name', v_oi.product_name,
        'quantity', v_refund_qty,
        'unit_price', v_oi.unit_price,
        'kitchen_status', v_oi.kitchen_status,
        'reason', p_reason
      )),
      v_refund_amount,
      v_now
    );

    -- H8: waste fate writes canonical waste ledger rows for the refunded
    -- quantity. Per H10.1/M1 these rows are order-context waste => zero stock
    -- effect (stock was already deducted by the READY consumption), so only
    -- inventory.transaction.created is emitted (no stock_changed).
    IF v_prod_found AND v_product.is_ready_product AND v_product.direct_ingredient_id IS NOT NULL THEN
      v_key := 'refund_waste:' || p_order_item_id::text || ':' || v_product.direct_ingredient_id::text;
      INSERT INTO public.inventory_logs (
        ingredient_id, type, quantity, unit, order_id, order_item_id,
        item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
        performed_by, reason, created_at, location_id, organization_id
      ) VALUES (
        v_product.direct_ingredient_id, 'waste', v_refund_qty,
        (SELECT COALESCE(unit, 'gram') FROM public.ingredients WHERE id = v_product.direct_ingredient_id),
        p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
        v_corr, v_key, p_performed_by,
        'Refund — waste: ' || COALESCE(v_oi.product_name, 'Məhsul'),
        v_now, v_order.location_id, v_order.organization_id
      )
      ON CONFLICT DO NOTHING RETURNING id INTO v_id;
      IF v_id IS NOT NULL THEN
        v_waste_recorded := 1;
        PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.transaction.created',
          jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_refund_qty, 'type', 'waste'),
          jsonb_build_object('correlation_id', v_corr));
      END IF;

    ELSIF v_prod_found THEN
      FOR v_rec IN
        SELECT r.ingredient_id, r.quantity_required, r.quantity_brutto,
               COALESCE(i.unit, 'gram') AS unit
        FROM public.recipes r
        JOIN public.ingredients i ON i.id = r.ingredient_id
        WHERE r.menu_item_id = v_oi.product_id AND r.is_ai_suggested = false
      LOOP
        v_key := 'refund_waste:' || p_order_item_id::text || ':' || v_rec.ingredient_id::text;
        INSERT INTO public.inventory_logs (
          ingredient_id, type, quantity, unit, order_id, order_item_id,
          item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
          performed_by, reason, created_at, location_id, organization_id
        ) VALUES (
          v_rec.ingredient_id, 'waste',
          COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty,
          v_rec.unit, p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
          v_corr, v_key, p_performed_by,
          'Refund — waste: ' || COALESCE(v_oi.product_name, 'Məhsul'),
          v_now, v_order.location_id, v_order.organization_id
        )
        ON CONFLICT DO NOTHING RETURNING id INTO v_id;
        IF v_id IS NOT NULL THEN
          v_waste_recorded := 1;
          PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.transaction.created',
            jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty, 'type', 'waste'),
            jsonb_build_object('correlation_id', v_corr));
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ===== Item state transition (unchanged; total_amount NOT recomputed) =====
  IF v_refund_qty >= v_oi.quantity THEN
    UPDATE public.order_items SET kitchen_status = 'voided', total_price = 0 WHERE id = p_order_item_id;
  ELSE
    UPDATE public.order_items SET
      quantity = v_oi.quantity - v_refund_qty,
      total_price = COALESCE(unit_price, 0) * (v_oi.quantity - v_refund_qty)
    WHERE id = p_order_item_id;
  END IF;

  -- ===== Audit (before/after from derived state) =====
  PERFORM public.log_audit(
    'refund_with_inventory', 'order', p_order_id::text,
    p_performed_by, v_performer_name,
    jsonb_build_object('paid_amount', v_order.paid_amount, 'status', v_order.status),
    jsonb_build_object(
      'refund_amount', v_refund_after,
      'refund_qty', v_refund_qty,
      'item_fate', p_item_fate,
      'product_name', v_oi.product_name,
      'stock_returned', v_stock_returned,
      'waste_recorded', v_waste_recorded,
      'new_paid_amount', v_paid_after
    ),
    jsonb_build_object('order_id', p_order_id, 'order_item_id', p_order_item_id),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', 'refund_with_inventory',
    'refund_amount', v_refund_after,
    'quantity_refunded', v_refund_qty,
    'item_fate', p_item_fate,
    'stock_returned', v_stock_returned > 0,
    'waste_recorded', v_waste_recorded > 0,
    'new_paid_amount', v_paid_after,
    'new_status', v_status_after,
    'order_id', p_order_id,
    'timestamp', v_now
  );
END;
$$;


--
-- Name: refund_with_inventory(uuid, uuid, integer, numeric, text, text, text, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.refund_with_inventory(p_order_id uuid, p_order_item_id uuid, p_quantity integer, p_amount numeric, p_method text DEFAULT 'cash'::text, p_item_fate text DEFAULT 'waste'::text, p_reason text DEFAULT NULL::text, p_reason_text text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_location_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_oi RECORD;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
  v_refund_qty INT;
  v_refund_amount NUMERIC;
  v_new_refund NUMERIC;
  v_product RECORD;
  v_rec RECORD;
  v_stock_returned INT := 0;
  v_waste_recorded INT := 0;
  v_corr uuid := gen_random_uuid();
  v_key text;
  v_id uuid;
  v_paid_after NUMERIC;
  v_refund_after NUMERIC;
  v_status_after TEXT;
  v_prod_found boolean := false;
  v_idem_result JSONB;
  v_idem_order UUID;
  v_idem_amount NUMERIC;
  v_refund_effect NUMERIC;
  v_result JSONB;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;
  -- ═══ P-1 M2: LOCATION ASSERTION (fail-closed, D-5; ratified 2026-09-12) ═══
  IF p_location_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'LOCATION_CONTEXT_MISSING');
  END IF;
  IF v_order.location_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_LOCATION_NULL');
  END IF;
  IF v_order.location_id IS DISTINCT FROM p_location_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'LOCATION_MISMATCH');
  END IF;
  IF p_performed_by IS NOT NULL
     AND NOT public.p1_actor_allowed_at_location(p_performed_by, p_location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'LOCATION_ACCESS_DENIED');
  END IF;
  IF v_order.status NOT IN ('paid', 'partially_refunded') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Can only refund paid or partially_refunded orders. Current: ' || v_order.status);
  END IF;

  SELECT * INTO v_oi FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order item not found');
  END IF;
  IF v_oi.order_id != p_order_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item does not belong to this order');
  END IF;
  IF v_oi.kitchen_status NOT IN ('ready', 'completed', 'served') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot refund item in state: ' || COALESCE(v_oi.kitchen_status, 'pending'));
  END IF;

  v_refund_qty := COALESCE(p_quantity, 1);
  IF v_refund_qty <= 0 OR v_refund_qty > v_oi.quantity THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid refund quantity. Max: ' || v_oi.quantity);
  END IF;

  v_refund_amount := COALESCE(p_amount, v_oi.unit_price * v_refund_qty);
  IF v_refund_amount <= 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid refund amount');
  END IF;

  -- ═══ P-4 C-3/C-5: IDEMPOTENCY DEDUPE (namespace='refund'; ratified D-4) ═══
  -- AFTER the order FOR UPDATE (section 1) + amount resolution, BEFORE the
  -- refund-cap / item-fate guards, so a retry replays the stored success
  -- instead of tripping "exceeds remaining refundable" / fate double-guard.
  v_refund_effect := v_refund_amount;
  IF p_idempotency_key IS NOT NULL THEN
    SELECT order_id, amount, result INTO v_idem_order, v_idem_amount, v_idem_result
    FROM payment_idempotency_keys
    WHERE namespace = 'refund' AND key = p_idempotency_key;
    IF FOUND THEN
      IF v_idem_order IS DISTINCT FROM p_order_id
         OR v_idem_amount IS DISTINCT FROM v_refund_effect THEN
        RAISE EXCEPTION 'IDEMPOTENCY_CONFLICT: key % is bound to a different operation (order %, amount %); request was (order %, amount %)',
          p_idempotency_key, v_idem_order, v_idem_amount, p_order_id, v_refund_effect;
      END IF;
      RETURN (COALESCE(v_idem_result, jsonb_build_object('success', false, 'error', 'IDEMPOTENCY_DATA_MISSING')))
        || jsonb_build_object('idempotent', true, 'duplicate', true,
             'original', COALESCE(v_idem_result, '{}'::jsonb),
             'current', jsonb_build_object(
               'status', v_order.status,
               'paid_amount', v_order.paid_amount,
               'refund_amount', COALESCE(v_order.refund_amount, 0),
               'remaining', GREATEST(0, COALESCE(v_order.paid_amount, 0) - COALESCE(v_order.refund_amount, 0)),
               'replayed_at', v_now));
    END IF;
  END IF;

  -- H10.1: refundable = paid_amount - refund_amount. paid_amount is NEVER
  -- decremented; cumulative refunds are compared against the original paid.
  v_new_refund := COALESCE(v_order.refund_amount, 0) + v_refund_amount;
  IF v_new_refund > COALESCE(v_order.paid_amount, 0) THEN
    RETURN jsonb_build_object('success', false, 'error',
      'Refund (' || v_refund_amount || ') exceeds remaining refundable (' ||
      ROUND(COALESCE(v_order.paid_amount, 0) - COALESCE(v_order.refund_amount, 0), 2) || ')');
  END IF;

  IF p_item_fate NOT IN ('return_to_stock', 'waste') THEN
    RETURN jsonb_build_object('success', false, 'error', 'item_fate must be return_to_stock or waste');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  SELECT * INTO v_product FROM public.products WHERE id = v_oi.product_id;
  IF FOUND THEN
    v_prod_found := true;
  END IF;

  -- H10.1: fate idempotency guards run BEFORE any money write so a duplicate
  -- refund can never record money and then fail.
  IF p_item_fate = 'return_to_stock' THEN
    IF EXISTS (
      SELECT 1 FROM public.inventory_logs
      WHERE order_item_id = p_order_item_id AND type IN ('reversal', 'stock_return')
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Stock already returned for this item');
    END IF;
  ELSIF p_item_fate = 'waste' THEN
    IF EXISTS (
      SELECT 1 FROM public.cancelled_orders
      WHERE order_id = p_order_id
        AND reason IN ('waste', 'refund_waste')
        AND items @> jsonb_build_array(jsonb_build_object('order_item_id', p_order_item_id))
    ) THEN
      RETURN jsonb_build_object('success', false, 'error', 'Waste already recorded for this item');
    END IF;
  END IF;

  -- ===== Financial record =====
  -- Legacy compatibility/reporting mirror (negative refund convention).
  INSERT INTO public.payments (
    order_id, payment_method, amount, status, is_refund,
    performed_by, performed_by_name, notes, metadata, idempotency_key
  ) VALUES (
    p_order_id, p_method, -ABS(v_refund_amount), 'refunded', true,
    p_performed_by, v_performer_name, p_reason_text,
    jsonb_build_object(
      'reason', p_reason,
      'reason_text', p_reason_text,
      'item_fate', p_item_fate,
      'order_item_id', p_order_item_id,
      'quantity', v_refund_qty
    ),
    'refund:' || p_order_item_id::text || ':' || v_corr::text
  );

  -- Canonical financial SSOT refund row (amount > 0, is_refund = true,
  -- status = 'captured').
  INSERT INTO public.order_payments (
    order_id, amount, payment_method, method, currency, status,
    is_refund, reference, performed_by, created_by,
    idempotency_key, correlation_id
  ) VALUES (
    p_order_id, v_refund_amount, p_method, p_method, 'AZN',
    'captured', true, p_reason_text,
    p_performed_by, p_performed_by,
    'refund:' || p_order_item_id::text || ':' || v_corr::text,
    v_corr
  );

  -- orders financial state derived through the canonical recalculator.
  UPDATE public.orders SET
    refund_reason = p_reason_text,
    refunded_at   = v_now
  WHERE id = p_order_id;

  PERFORM public.recalculate_order_payment_state(p_order_id);

  SELECT COALESCE(paid_amount, 0), COALESCE(refund_amount, 0), status
    INTO v_paid_after, v_refund_after, v_status_after
  FROM public.orders WHERE id = p_order_id;

  -- ===== Inventory fate =====
  IF p_item_fate = 'return_to_stock' THEN
    IF v_prod_found AND v_product.is_ready_product AND v_product.direct_ingredient_id IS NOT NULL THEN
      v_key := 'refund:' || p_order_item_id::text || ':' || v_product.direct_ingredient_id::text;
      INSERT INTO public.inventory_logs (
        ingredient_id, type, quantity, unit, order_id, order_item_id,
        item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
        performed_by, reason, created_at, location_id, organization_id
      ) VALUES (
        v_product.direct_ingredient_id, 'reversal', v_refund_qty,
        (SELECT COALESCE(unit, 'gram') FROM public.ingredients WHERE id = v_product.direct_ingredient_id),
        p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
        v_corr, v_key, p_performed_by,
        'Refund — return to stock: ' || COALESCE(v_oi.product_name, 'Məhsul'),
        v_now, v_order.location_id, v_order.organization_id
      )
      ON CONFLICT DO NOTHING RETURNING id INTO v_id;
      IF v_id IS NOT NULL THEN
        v_stock_returned := 1;
        PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.transaction.created',
          jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_refund_qty, 'type', 'reversal'),
          jsonb_build_object('correlation_id', v_corr));
        PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.stock_changed',
          jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_refund_qty),
          jsonb_build_object('correlation_id', v_corr));
      END IF;

    ELSIF v_prod_found THEN
      FOR v_rec IN
        SELECT r.ingredient_id, r.quantity_required, r.quantity_brutto,
               COALESCE(i.unit, 'gram') AS unit
        FROM public.recipes r
        JOIN public.ingredients i ON i.id = r.ingredient_id
        WHERE r.menu_item_id = v_oi.product_id AND r.is_ai_suggested = false
      LOOP
        v_key := 'refund:' || p_order_item_id::text || ':' || v_rec.ingredient_id::text;
        INSERT INTO public.inventory_logs (
          ingredient_id, type, quantity, unit, order_id, order_item_id,
          item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
          performed_by, reason, created_at, location_id, organization_id
        ) VALUES (
          v_rec.ingredient_id, 'reversal',
          COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty,
          v_rec.unit, p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
          v_corr, v_key, p_performed_by,
          'Refund — return to stock: ' || COALESCE(v_oi.product_name, 'Məhsul'),
          v_now, v_order.location_id, v_order.organization_id
        )
        ON CONFLICT DO NOTHING RETURNING id INTO v_id;
        IF v_id IS NOT NULL THEN
          v_stock_returned := 1;
          PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.transaction.created',
            jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty, 'type', 'reversal'),
            jsonb_build_object('correlation_id', v_corr));
          PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.stock_changed',
            jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty),
            jsonb_build_object('correlation_id', v_corr));
        END IF;
      END LOOP;
    END IF;

  ELSIF p_item_fate = 'waste' THEN
    INSERT INTO public.cancelled_orders (
      order_id, reason, reason_text, items, total_amount, created_at
    ) VALUES (
      p_order_id, 'waste',
      COALESCE(p_reason_text, 'Refund + waste: ' || COALESCE(v_oi.product_name, 'Məhsul')),
      jsonb_build_array(jsonb_build_object(
        'order_item_id', p_order_item_id,
        'product_name', v_oi.product_name,
        'quantity', v_refund_qty,
        'unit_price', v_oi.unit_price,
        'kitchen_status', v_oi.kitchen_status,
        'reason', p_reason
      )),
      v_refund_amount,
      v_now
    );

    -- H8: waste fate writes canonical waste ledger rows for the refunded
    -- quantity. Per H10.1/M1 these rows are order-context waste => zero stock
    -- effect (stock was already deducted by the READY consumption), so only
    -- inventory.transaction.created is emitted (no stock_changed).
    IF v_prod_found AND v_product.is_ready_product AND v_product.direct_ingredient_id IS NOT NULL THEN
      v_key := 'refund_waste:' || p_order_item_id::text || ':' || v_product.direct_ingredient_id::text;
      INSERT INTO public.inventory_logs (
        ingredient_id, type, quantity, unit, order_id, order_item_id,
        item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
        performed_by, reason, created_at, location_id, organization_id
      ) VALUES (
        v_product.direct_ingredient_id, 'waste', v_refund_qty,
        (SELECT COALESCE(unit, 'gram') FROM public.ingredients WHERE id = v_product.direct_ingredient_id),
        p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
        v_corr, v_key, p_performed_by,
        'Refund — waste: ' || COALESCE(v_oi.product_name, 'Məhsul'),
        v_now, v_order.location_id, v_order.organization_id
      )
      ON CONFLICT DO NOTHING RETURNING id INTO v_id;
      IF v_id IS NOT NULL THEN
        v_waste_recorded := 1;
        PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.transaction.created',
          jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_refund_qty, 'type', 'waste'),
          jsonb_build_object('correlation_id', v_corr));
      END IF;

    ELSIF v_prod_found THEN
      FOR v_rec IN
        SELECT r.ingredient_id, r.quantity_required, r.quantity_brutto,
               COALESCE(i.unit, 'gram') AS unit
        FROM public.recipes r
        JOIN public.ingredients i ON i.id = r.ingredient_id
        WHERE r.menu_item_id = v_oi.product_id AND r.is_ai_suggested = false
      LOOP
        v_key := 'refund_waste:' || p_order_item_id::text || ':' || v_rec.ingredient_id::text;
        INSERT INTO public.inventory_logs (
          ingredient_id, type, quantity, unit, order_id, order_item_id,
          item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
          performed_by, reason, created_at, location_id, organization_id
        ) VALUES (
          v_rec.ingredient_id, 'waste',
          COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty,
          v_rec.unit, p_order_id, p_order_item_id, v_refund_qty, 'order', p_order_id,
          v_corr, v_key, p_performed_by,
          'Refund — waste: ' || COALESCE(v_oi.product_name, 'Məhsul'),
          v_now, v_order.location_id, v_order.organization_id
        )
        ON CONFLICT DO NOTHING RETURNING id INTO v_id;
        IF v_id IS NOT NULL THEN
          v_waste_recorded := 1;
          PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.transaction.created',
            jsonb_build_object('order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_refund_qty, 'type', 'waste'),
            jsonb_build_object('correlation_id', v_corr));
        END IF;
      END LOOP;
    END IF;
  END IF;

  -- ===== Item state transition (unchanged; total_amount NOT recomputed) =====
  IF v_refund_qty >= v_oi.quantity THEN
    UPDATE public.order_items SET kitchen_status = 'voided', total_price = 0 WHERE id = p_order_item_id;
  ELSE
    UPDATE public.order_items SET
      quantity = v_oi.quantity - v_refund_qty,
      total_price = COALESCE(unit_price, 0) * (v_oi.quantity - v_refund_qty)
    WHERE id = p_order_item_id;
  END IF;

  -- ===== Audit (before/after from derived state) =====
  PERFORM public.log_audit(
    'refund_with_inventory', 'order', p_order_id::text,
    p_performed_by, v_performer_name,
    jsonb_build_object('paid_amount', v_order.paid_amount, 'status', v_order.status),
    jsonb_build_object(
      'refund_amount', v_refund_after,
      'refund_qty', v_refund_qty,
      'item_fate', p_item_fate,
      'product_name', v_oi.product_name,
      'stock_returned', v_stock_returned,
      'waste_recorded', v_waste_recorded,
      'new_paid_amount', v_paid_after
    ),
    jsonb_build_object('order_id', p_order_id, 'order_item_id', p_order_item_id),
    NULL
  );

  v_result := jsonb_build_object(
    'success', true,
    'action', 'refund_with_inventory',
    'refund_amount', v_refund_after,
    'quantity_refunded', v_refund_qty,
    'item_fate', p_item_fate,
    'stock_returned', v_stock_returned > 0,
    'waste_recorded', v_waste_recorded > 0,
    'new_paid_amount', v_paid_after,
    'new_status', v_status_after,
    'order_id', p_order_id,
    'timestamp', v_now
  );

  -- ═══ P-4 C-2/C-4/C-6: STORE IDEMPOTENCY KEY + RESULT (atomic, namespace='refund', TTL 30d) ═══
  IF p_idempotency_key IS NOT NULL THEN
    INSERT INTO payment_idempotency_keys (namespace, key, order_id, amount, status, result, expires_at)
    VALUES ('refund', p_idempotency_key, p_order_id, v_refund_effect, 'completed', v_result,
            now() + interval '30 days');
  END IF;

  RETURN v_result;
END;
$$;


--
-- Name: release_item_hold(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_item_hold(p_order_item_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item RECORD;
BEGIN
  SELECT * INTO v_item FROM order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  UPDATE order_items
  SET hold_until = NULL
  WHERE id = p_order_item_id;

  RETURN jsonb_build_object('success', true, 'order_item_id', p_order_item_id);
END;
$$;


--
-- Name: release_paid_table_atomic(text, integer, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.release_paid_table_atomic(p_token text, p_table_number integer, p_final_status text, p_performed_by uuid, p_terminal_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_table RECORD;
  v_open  int;
  v_paid  int;
  v_old_state jsonb;
BEGIN
  PERFORM public.set_session_staff(p_token);
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    PERFORM public.validate_actor(p_performed_by);
  END IF;
  IF p_final_status NOT IN ('empty','cleaning') THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_DISMISS_INVALID_FINAL');
  END IF;

  SELECT * INTO v_table FROM public.table_floors
   WHERE table_number = p_table_number AND (v_sess_loc IS NULL OR location_id = v_sess_loc) FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  IF NOT has_location_access(v_table.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF v_table.reservation_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TABLE_RESERVED');
  END IF;
  IF v_table.merged_into_table IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TABLE_MERGED');
  END IF;

  -- Any non-terminal order? Refuse — those must be voided/wasted via dismiss.
  SELECT count(*) INTO v_open FROM public.orders
   WHERE table_number = p_table_number AND location_id = v_table.location_id
     AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided');
  IF v_open > 0 THEN
    RETURN jsonb_build_object('success', false,
      'error', 'G_TABLE_HAS_ACTIVE_ORDERS', 'open_orders', v_open);
  END IF;

  -- Paid orders still to close (paid, or partially_refunded with a paid part
  -- already settled — both transition to closed legally).
  SELECT count(*) INTO v_paid FROM public.orders
   WHERE table_number = p_table_number
     AND status IN ('paid','partially_refunded');
  IF v_paid = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_NO_PAID_ORDER');
  END IF;

  v_old_state := jsonb_build_object(
    'status', v_table.status,
    'order_id', v_table.current_order_id,
    'paid_orders', v_paid);

  -- paid/partially_refunded -> closed (registered edge; guard stamps closed_at)
  UPDATE public.orders SET
    status = 'closed',
    version = COALESCE(version, 0) + 1,
    updated_by_terminal_id = p_terminal_id
  WHERE table_number = p_table_number
    AND status IN ('paid','partially_refunded');

  -- release the table (mirrors dismiss_table_atomic's release block)
  UPDATE public.table_floors SET
    status = p_final_status,
    guest_count = NULL,
    total_amount = 0,
    order_count = 0,
    current_order_id = NULL,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    has_pending = false,
    oldest_pending_at = NULL,
    bill_requested = false,
    updated_at = now(),
    updated_by_terminal_id = p_terminal_id
  WHERE table_number = p_table_number;

  PERFORM public.sync_table_order_aggregates(p_table_number);

  PERFORM public.g_table_audit(
    'release_paid_table', 'table.released_after_payment',
    p_table_number, v_table.id, v_table.current_order_id,
    v_old_state,
    jsonb_build_object('status', p_final_status, 'orders_closed', v_paid),
    p_performed_by, p_terminal_id, NULL,
    p_table_number, NULL, v_table.location_id, v_table.organization_id);

  RETURN jsonb_build_object('success', true,
    'table_status', p_final_status, 'orders_closed', v_paid);
END;
$$;


--
-- Name: remove_service_charge(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_service_charge(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  UPDATE orders SET
    service_charge_pct = 0,
    service_charge_amount = 0,
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  PERFORM log_order_event(
    p_order_id, 'service_charge_removed',
    jsonb_build_object('old_pct', v_order.service_charge_pct, 'old_amount', v_order.service_charge_amount),
    jsonb_build_object('pct', 0, 'amount', 0),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: remove_table_from_reservation(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.remove_table_from_reservation(p_reservation_id uuid, p_table_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table_number INTEGER;
BEGIN
  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_reservation.status NOT IN ('pending', 'confirmed') THEN
    RAISE EXCEPTION 'RESERVATION_NOT_MOVABLE' USING ERRCODE = 'P0001';
  END IF;

  SELECT table_number INTO v_table_number FROM table_floors WHERE id = p_table_id;

  IF v_table_number IS NULL THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- Free the table
  UPDATE table_floors SET
    status = 'empty',
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    guest_count = NULL
  WHERE id = p_table_id;

  -- Remove from reservation table_ids
  UPDATE reservations SET
    table_ids = (
      SELECT jsonb_agg(elem)
      FROM jsonb_array_elements(table_ids) AS elem
      WHERE elem <> p_table_id::text
    ),
    updated_at = now()
  WHERE id = p_reservation_id;

  RETURN jsonb_build_object(
    'success', true,
    'removed_table', v_table_number,
    'reservation_id', p_reservation_id
  );
END;
$$;


--
-- Name: reopen_cash_register(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_cash_register(p_session_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_session cash_drawer_sessions%ROWTYPE;
BEGIN
  IF NOT has_permission(p_performed_by, 'cash.reopen') THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  SELECT * INTO v_session FROM cash_drawer_sessions WHERE id = p_session_id FOR UPDATE;
  IF NOT FOUND THEN RETURN jsonb_build_object('success', false, 'error', 'NOT_FOUND'); END IF;
  IF v_session.status <> 'closed' THEN RETURN jsonb_build_object('success', false, 'error', 'NOT_CLOSED'); END IF;

  UPDATE cash_drawer_sessions SET
    status = 'open', closed_at = NULL, closed_by = NULL, approved_by = NULL, approval_note = NULL,
    notes = COALESCE(notes, '') || ' | reopened: ' || COALESCE(p_reason, '')
  WHERE id = p_session_id;

  INSERT INTO cash_drawer_log (session_id, type, amount, description, created_by)
  VALUES (p_session_id, 'open', COALESCE(v_session.opening_balance, 0), 'Reopened: ' || COALESCE(p_reason, ''), p_performed_by);

  PERFORM log_audit('cash_register_reopen', 'cash_register', p_session_id::text, p_performed_by,
    jsonb_build_object('previous_close', v_session.closed_at),
    jsonb_build_object('reason', p_reason), NULL, NULL, NULL);

  RETURN jsonb_build_object('success', true, 'session_id', p_session_id, 'status', 'open');
END;
$$;


--
-- Name: reopen_kitchen_ticket_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_kitchen_ticket_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status NOT IN ('ready', 'served', 'cancelled') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order cannot be reopened');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'pending',
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  UPDATE public.order_items SET
    kitchen_status = 'pending',
    updated_at = NOW()
  WHERE order_id = p_order_id AND kitchen_status IN ('ready', 'served', 'cancelled');

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'pending',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'reopen_kitchen_ticket',
    jsonb_build_object('kitchen_status', v_order.kitchen_status),
    jsonb_build_object('kitchen_status', 'pending'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: reopen_order(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_order(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status != 'paid' THEN
    RAISE EXCEPTION 'ORDER_NOT_PAID' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.paid_at IS NULL OR now() - v_order.paid_at > INTERVAL '24 hours' THEN
    RAISE EXCEPTION 'REOPEN_WINDOW_EXPIRED' USING ERRCODE = 'P0001';
  END IF;

  UPDATE orders
  SET status = 'confirmed',
      paid_at = NULL,
      paid_amount = 0,
      version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'orders',
    p_order_id,
    'reopen',
    jsonb_build_object('status', 'paid', 'paid_at', v_order.paid_at),
    jsonb_build_object('status', 'confirmed', 'reopened_at', now()),
    p_performed_by,
    now()
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: reopen_order_atomic(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_order_atomic(p_order_id uuid, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_order RECORD;
  v_item  RECORD;
  v_rev   jsonb;
  v_reversed integer := 0;
BEGIN
  -- P-3: this is the single trusted path allowed to remove an order's payment
  -- records (full authorized reversal). Transaction-scoped flag read by
  -- trg_order_payment_immutable; external callers cannot forge it.
  PERFORM set_config('app.payment_ledger_reopen', 'on', true);

  PERFORM public.validate_actor(p_performed_by);

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status NOT IN ('paid','completed','partially_refunded','refunded') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order is not paid/completed/refunded');
  END IF;

  FOR v_item IN
    SELECT oi.id FROM public.order_items oi
    WHERE oi.order_id = p_order_id
  LOOP
    v_rev := public._inventory_reverse_item(v_item.id, 'reopen', p_performed_by);
    IF (v_rev->>'reversed')::int > 0 THEN
      v_reversed := v_reversed + (v_rev->>'reversed')::int;
    END IF;
  END LOOP;

  DELETE FROM public.order_payments WHERE order_id = p_order_id;

  UPDATE public.orders SET
    status = 'new',
    paid_amount = 0,
    cash_amount = 0,
    card_amount = 0,
    tip_amount = 0,
    paid_at = NULL,
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id,
    updated_at = NOW()
  WHERE id = p_order_id;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'reopen_order',
    jsonb_build_object('status', v_order.status),
    jsonb_build_object('status', 'new', 'reason', p_reason),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'reversed', v_reversed);
END;
$$;


--
-- Name: reopen_order_atomic(text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reopen_order_atomic(p_token text, p_order_id uuid, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_order RECORD;
  v_item  RECORD;
  v_rev   jsonb;
  v_reversed integer := 0;
  v_auth     jsonb;
  v_actor_id text;
  v_has_over boolean := false;
BEGIN
  -- P-3: this is the single trusted path allowed to remove an order's payment
  -- records (full authorized reversal). Transaction-scoped flag read by
  -- trg_order_payment_immutable; external callers cannot forge it.
  PERFORM set_config('app.payment_ledger_reopen', 'on', true);

  PERFORM public.validate_actor(p_performed_by);

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status NOT IN ('paid','completed','partially_refunded','refunded') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order is not paid/completed/refunded');
  END IF;

  -- ═══ P-6 D-1 (ratified 2026-09-13): server-side reopen authorization ═══
  -- Reopen is a FULL financial reversal (it DELETEs every order_payments row).
  -- The route passes the SESSION TOKEN; identity is re-derived from the session
  -- (never the caller-supplied p_performed_by — O-01 lesson). Requires
  -- orders.edit (registry) + location access (P-1) + MANAGER OVERRIDE
  -- (refund.approve OR void.approve OR an approved manager_overrides row;
  --  registry ovr=true for paid→new / refunded→new / closed→new / partial→new).
  v_auth := public.authorize(p_token, 'orders.edit', v_order.location_id);
  IF NOT (v_auth->>'allowed')::boolean THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED: reopen requires orders.edit at the order location (reason: ' || coalesce(v_auth->>'reason','?') || ')');
  END IF;
  v_actor_id := v_auth->>'staff_id';
  IF v_actor_id IS NOT NULL AND p_performed_by IS NOT NULL
     AND (v_actor_id::uuid IS DISTINCT FROM p_performed_by) THEN
    RETURN jsonb_build_object('success', false, 'error', 'IDENTITY_MISMATCH: p_performed_by must match the session staff (identity comes from the session)');
  END IF;
  IF v_actor_id IS NOT NULL THEN
    v_has_over := COALESCE((SELECT has_permission(v_actor_id::uuid, 'refund.approve')), false)
               OR COALESCE((SELECT has_permission(v_actor_id::uuid, 'void.approve')), false)
               OR COALESCE((SELECT EXISTS(
                    SELECT 1 FROM manager_overrides mo
                    WHERE mo.requested_by = v_actor_id::uuid
                      AND mo.permission IN ('orders.edit','refund.approve','void.approve')
                      AND (mo.location_id = v_order.location_id OR mo.location_id IS NULL)
                      AND mo.status = 'APPROVED' AND mo.expires_at > now())), false);
    IF NOT v_has_over THEN
      RETURN jsonb_build_object('success', false, 'error', 'MANAGER_OVERRIDE_REQUIRED: reopening a ' || v_order.status || ' order requires refund.approve / void.approve / an approved manager override (reason: reopen reverses the full payment)');
    END IF;
  END IF;

  FOR v_item IN
    SELECT oi.id FROM public.order_items oi
    WHERE oi.order_id = p_order_id
  LOOP
    v_rev := public._inventory_reverse_item(v_item.id, 'reopen', p_performed_by);
    IF (v_rev->>'reversed')::int > 0 THEN
      v_reversed := v_reversed + (v_rev->>'reversed')::int;
    END IF;
  END LOOP;

  DELETE FROM public.order_payments WHERE order_id = p_order_id;

  UPDATE public.orders SET
    status = 'new',
    paid_amount = 0,
    cash_amount = 0,
    card_amount = 0,
    tip_amount = 0,
    paid_at = NULL,
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id,
    updated_at = NOW()
  WHERE id = p_order_id;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'reopen_order',
    jsonb_build_object('status', v_order.status),
    jsonb_build_object('status', 'new', 'reason', p_reason),
    p_performed_by
  );

  -- ═══ P-6 D-2 (ratified 2026-09-13): canonical audit + order outbox for the
  -- full reversal (previously operation_logs only — no audit, no client resync). ═══
  PERFORM public.log_audit(
    'reopen_order', 'order', p_order_id::text,
    p_performed_by,
    (SELECT name FROM public.staff WHERE id = p_performed_by),
    jsonb_build_object('status', v_order.status, 'paid_amount', v_order.paid_amount,
      'refund_amount', v_order.refund_amount),
    jsonb_build_object('status', 'new', 'reason', p_reason, 'reversed_items', v_reversed),
    jsonb_build_object('order_id', p_order_id), NULL
  );
  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order', p_order_id, 'order.status_changed',
    jsonb_build_object('old_status', v_order.status, 'new_status', 'new',
                       'reason', p_reason, 'performed_by', p_performed_by,
                       'reopened', true),
    'pending');

  RETURN jsonb_build_object('success', true, 'reversed', v_reversed);
END;
$$;


--
-- Name: request_override(text, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_override(p_token text, p_permission text, p_reason text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid;
    v_org_id uuid;
    v_override_id uuid;
BEGIN
    -- Auth check
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    v_org_id := current_org_id();

    -- Insert override request
    INSERT INTO manager_overrides (requested_by, permission, reason, location_id, organization_id)
    VALUES (v_staff_id, p_permission, p_reason, p_location_id, v_org_id)
    RETURNING id INTO v_override_id;

    -- Audit
    INSERT INTO operation_logs (entity_type, entity_id, operation, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('manager_override', v_override_id, 'override.requested',
            jsonb_build_object('permission', p_permission, 'reason', p_reason, 'staff_id', v_staff_id),
            v_staff_id, gen_random_uuid(), p_location_id, v_org_id);

    RETURN jsonb_build_object('override_id', v_override_id, 'status', 'PENDING', 'expires_at', (now() + interval '5 minutes')::text);
END;
$$;


--
-- Name: request_shift_swap(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.request_shift_swap(p_requester_shift_id uuid, p_target_staff_id uuid, p_target_shift_id uuid, p_requested_by uuid, p_message text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_swap_id UUID;
BEGIN
  INSERT INTO shift_swap_requests (requester_shift_id, target_staff_id, target_shift_id, requested_by, message)
  VALUES (p_requester_shift_id, p_target_staff_id, p_target_shift_id, p_requested_by, p_message)
  RETURNING id INTO v_swap_id;

  RETURN json_build_object('success', true, 'swap_id', v_swap_id);
END;
$$;


--
-- Name: reserve_table_atomic(uuid, uuid[], integer, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reserve_table_atomic(p_reservation_id uuid, p_table_ids uuid[], p_guest_count integer DEFAULT NULL::integer, p_pre_order_items jsonb DEFAULT '[]'::jsonb, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table_number INTEGER;
  v_order_id UUID;
  v_customer_id UUID;
  v_total_amount NUMERIC;
  v_item JSONB;
  v_draft_order_ids UUID[] := '{}'::UUID[];
  v_now TIMESTAMPTZ := now();
  v_result jsonb;
BEGIN
  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;

  IF v_reservation.status NOT IN ('pending') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation is not pending');
  END IF;

  UPDATE reservations SET
    status = 'confirmed',
    table_ids = ARRAY(SELECT unnest(p_table_ids)::integer),
    guest_count = COALESCE(p_guest_count, guest_count),
    updated_at = NOW()
  WHERE id = p_reservation_id;

  DELETE FROM public.reservation_tables 
  WHERE reservation_id = p_reservation_id;

  FOR v_table_number IN SELECT unnest(p_table_ids)::integer LOOP
    INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
    VALUES (p_reservation_id, v_table_number, NOW())
    ON CONFLICT (reservation_id, table_number) DO NOTHING;

    UPDATE public.table_floors SET
      status = 'reserved',
      reservation_id = p_reservation_id,
      reservation_name = v_reservation.name,
      reservation_phone = v_reservation.phone,
      reserved_at = NOW(),
      reserved_until = v_reservation.date + v_reservation.time,
      updated_at = NOW()
    WHERE table_number = v_table_number;
  END LOOP;

  IF p_pre_order_items IS NOT NULL AND jsonb_array_length(p_pre_order_items) > 0 THEN
    DELETE FROM public.reservation_preorder_items WHERE reservation_id = p_reservation_id;

    FOR v_item IN SELECT * FROM jsonb_array_elements(p_pre_order_items) LOOP
      INSERT INTO public.reservation_preorder_items (
        reservation_id, product_id, product_name, quantity, unit_price, modifiers, special_notes, course, combo_id, created_at
      ) VALUES (
        p_reservation_id,
        (v_item->>'product_id')::uuid,
        v_item->>'product_name',
        (v_item->>'quantity')::integer,
        (v_item->>'unit_price')::numeric,
        v_item->'modifiers',
        v_item->>'special_notes',
        v_item->>'course',
        (v_item->>'combo_id')::uuid,
        NOW()
      );
    END LOOP;
  END IF;

  PERFORM public.log_reservation_operation(
    p_reservation_id,
    'reserve_table',
    jsonb_build_object('status', 'pending', 'table_ids', v_reservation.table_ids),
    jsonb_build_object('status', 'confirmed', 'table_ids', ARRAY(SELECT unnest(p_table_ids)::integer)),
    p_user_id
  );

  v_result := jsonb_build_object('success', true, 'reservation_id', p_reservation_id);
  RETURN v_result;
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: reset_staff_pin(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reset_staff_pin(p_staff_id uuid, p_new_pin text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_pin text;
  v_staff staff%ROWTYPE;
BEGIN
  SELECT * INTO v_staff FROM staff WHERE id = p_staff_id;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'STAFF_NOT_FOUND');
  END IF;

  -- Generate random 4-digit PIN if not provided
  v_pin := COALESCE(p_new_pin, LPAD(FLOOR(RANDOM() * 10000)::text, 4, '0'));

  -- Validate PIN format
  IF LENGTH(v_pin) < 4 OR LENGTH(v_pin) > 6 OR v_pin !~ '^\d+$' THEN
    RETURN jsonb_build_object('success', false, 'error', 'INVALID_PIN_FORMAT');
  END IF;

  -- Update PIN (hashed)
  UPDATE staff SET pin_hash = crypt(v_pin, gen_salt('bf')) WHERE id = p_staff_id;

  -- Audit
  PERFORM log_audit(
    'pin_reset', 'staff', p_staff_id::text, p_performed_by,
    NULL, jsonb_build_object('pin_length', LENGTH(v_pin)), NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'staff_id', p_staff_id,
    'new_pin', v_pin,
    'message', 'PIN has been reset. Share securely with staff member.'
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$_$;


--
-- Name: resolve_staff_location(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resolve_staff_location(p_staff uuid, p_session_location uuid DEFAULT NULL::uuid, p_session_org uuid DEFAULT NULL::uuid) RETURNS TABLE(resolved_location_id uuid, resolved_organization_id uuid)
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_loc uuid;
  v_org uuid;
  v_distinct int;
BEGIN
  -- 1) Session active location is authoritative (set via /api/locations/switch)
  IF p_session_location IS NOT NULL THEN
    RETURN QUERY SELECT p_session_location, p_session_org;
    RETURN;
  END IF;

  IF p_staff IS NULL THEN
    RETURN;  -- no staff context -> NULL (caller -> 400)
  END IF;

  -- 2) Staff's PRIMARY active location
  SELECT sl.location_id, sl.organization_id INTO v_loc, v_org
  FROM staff_locations sl
  WHERE sl.staff_id = p_staff AND sl.active AND sl.is_primary
  LIMIT 1;
  IF FOUND THEN
    RETURN QUERY SELECT v_loc, v_org;
    RETURN;
  END IF;

  -- 3) Exactly ONE distinct active location -> use it
  SELECT count(DISTINCT sl.location_id) INTO v_distinct
  FROM staff_locations sl
  WHERE sl.staff_id = p_staff AND sl.active;
  IF v_distinct = 1 THEN
    SELECT sl.location_id, sl.organization_id INTO v_loc, v_org
    FROM staff_locations sl
    WHERE sl.staff_id = p_staff AND sl.active
    LIMIT 1;
    IF v_loc IS NOT NULL THEN
      RETURN QUERY SELECT v_loc, v_org;
      RETURN;
    END IF;
  END IF;

  -- 4) Ambiguous (multiple active, no primary) or none -> NULL (caller -> 400)
  RETURN;
END;
$$;


--
-- Name: FUNCTION resolve_staff_location(p_staff uuid, p_session_location uuid, p_session_org uuid); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.resolve_staff_location(p_staff uuid, p_session_location uuid, p_session_org uuid) IS 'D-5 location resolution: session active -> staff primary -> single active -> NULL (NO_LOCATION_CONTEXT). Never defaults or picks arbitrarily. Returns (resolved_location_id, resolved_organization_id).';


--
-- Name: respond_shift_swap(uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.respond_shift_swap(p_swap_id uuid, p_approved boolean, p_responded_by uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_swap RECORD;
BEGIN
  SELECT * INTO v_swap FROM shift_swap_requests WHERE id = p_swap_id;

  IF v_swap.status != 'pending' THEN
    RETURN json_build_object('success', false, 'error', 'Swap request already processed');
  END IF;

  IF p_approved THEN
    -- Swap the schedules
    UPDATE schedule SET staff_id = v_swap.target_staff_id WHERE id = v_swap.requester_shift_id;
    UPDATE schedule SET staff_id = (SELECT staff_id FROM schedule WHERE id = v_swap.requester_shift_id) WHERE id = v_swap.target_shift_id;

    UPDATE shift_swap_requests SET status = 'accepted', approved_by = p_responded_by, updated_at = NOW() WHERE id = p_swap_id;
  ELSE
    UPDATE shift_swap_requests SET status = 'rejected', approved_by = p_responded_by, updated_at = NOW() WHERE id = p_swap_id;
  END IF;

  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: restore_item_atomic(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.restore_item_atomic(p_token text, p_item_id uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_item RECORD;
  v_order RECORD;
  v_rule jsonb;
  v_allowed jsonb;
  v_restore_total numeric;
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  SELECT * INTO v_item FROM order_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE = 'P0001'; END IF;
  IF v_item.kitchen_status NOT IN ('voided','cancelled') THEN
    RAISE EXCEPTION 'ITEM_NOT_VOIDED: item is % — only voided/cancelled items are restorable', v_item.kitchen_status USING ERRCODE='P0001';
  END IF;

  SELECT * INTO v_order FROM orders WHERE id = v_item.order_id FOR UPDATE;
  IF v_order.status IN ('paid','closed','refunded','partially_refunded') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED' USING ERRCODE='P0001';
  END IF;

  v_rule := validate_transition('item', v_item.kitchen_status, 'pending');
  IF NOT (v_rule->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_ITEM_TRANSITION: %', v_rule->>'error' USING ERRCODE='P0001';
  END IF;

  v_allowed := authorize(p_token, COALESCE(v_rule->>'requires_permission','orders.edit'), v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: % at % (reason: %)',
      COALESCE(v_rule->>'requires_permission','orders.edit'), v_order.location_id,
      v_allowed->>'reason' USING ERRCODE='P0001';
  END IF;

  IF COALESCE(v_rule->>'requires_manager_override','false')::boolean THEN
    PERFORM ensure_manager_override(v_staff_id,
      COALESCE(v_rule->>'requires_permission','orders.edit'),
      v_order.location_id, v_item.kitchen_status, 'pending');
  END IF;

  v_restore_total := v_item.unit_price * v_item.quantity;

  UPDATE order_items SET
    kitchen_status = 'pending',
    total_price = v_restore_total,
    updated_at = now()
  WHERE id = p_item_id;

  UPDATE orders SET
    total_amount = COALESCE(total_amount, 0) + v_restore_total,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = v_order.id;

  PERFORM log_order_event(v_order.id, 'kitchen_status_changed',
    jsonb_build_object('item', p_item_id, 'status_before', v_item.kitchen_status),
    jsonb_build_object('status', 'pending', 'total', v_restore_total, 'reason', p_reason),
    '{}'::jsonb, v_staff_id, NULL, NULL, NULL);

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', p_item_id, 'order_item.restored',
    jsonb_build_object('order_id', v_order.id, 'total', v_restore_total,
      'reason', p_reason, 'performed_by', v_staff_id), 'pending');

  RETURN jsonb_build_object('success', true, 'order_item_id', p_item_id,
    'restored_total', v_restore_total, 'item_status', 'pending');
END;
$$;


--
-- Name: resv_table_loc_fill(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.resv_table_loc_fill() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.location_id IS NULL THEN
    SELECT location_id INTO NEW.location_id FROM reservations WHERE id = NEW.reservation_id;
  END IF;
  IF NEW.location_id IS NULL THEN
    RAISE EXCEPTION 'reservation_tables.location_id unresolvable (reservation missing location)';
  END IF;
  RETURN NEW;
END; $$;


--
-- Name: return_to_stock(uuid, integer, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.return_to_stock(p_order_item_id uuid, p_quantity integer DEFAULT NULL::integer, p_reason text DEFAULT 'return_to_stock'::text, p_reason_text text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_oi RECORD;
  v_order RECORD;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
  v_return_qty INT;
  v_product RECORD;
  v_rec RECORD;
  v_returned INT := 0;
  v_corr uuid := gen_random_uuid();
  v_key text;
  v_id uuid;
  v_prod_found boolean := false;
  v_meta jsonb;
BEGIN
  SELECT * INTO v_oi FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order item not found');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_oi.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_oi.kitchen_status NOT IN ('ready', 'completed', 'served') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot return item in state: ' || COALESCE(v_oi.kitchen_status, 'pending'));
  END IF;

  -- Idempotent (covers reversal + legacy stock_return rows)
  IF EXISTS (
    SELECT 1 FROM public.inventory_logs
    WHERE order_item_id = p_order_item_id AND type IN ('reversal', 'stock_return')
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Stock already returned for this item');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  v_return_qty := COALESCE(p_quantity, v_oi.quantity);
  IF v_return_qty <= 0 OR v_return_qty > v_oi.quantity THEN
    RETURN jsonb_build_object('success', false, 'error', 'Invalid return quantity');
  END IF;

  SELECT * INTO v_product FROM public.products WHERE id = v_oi.product_id;
  IF FOUND THEN
    v_prod_found := true;
  END IF;

  v_meta := jsonb_build_object('correlation_id', v_corr, 'operation', 'return_to_stock',
    'location_id', v_order.location_id, 'organization_id', v_order.organization_id,
    'performed_by', p_performed_by);

  IF v_prod_found AND v_product.is_ready_product AND v_product.direct_ingredient_id IS NOT NULL THEN
    v_key := 'return:' || p_order_item_id::text || ':' || v_product.direct_ingredient_id::text;
    INSERT INTO public.inventory_logs (
      ingredient_id, type, quantity, unit, order_id, order_item_id,
      item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
      performed_by, reason, created_at, location_id, organization_id
    ) VALUES (
      v_product.direct_ingredient_id, 'reversal', v_return_qty,
      (SELECT COALESCE(unit, 'gram') FROM public.ingredients WHERE id = v_product.direct_ingredient_id),
      v_oi.order_id, p_order_item_id, v_return_qty,
      'order', v_oi.order_id, v_corr, v_key, p_performed_by,
      COALESCE(p_reason_text, 'Return to stock: ' || COALESCE(v_oi.product_name, 'Məhsul')),
      v_now, v_order.location_id, v_order.organization_id
    )
    ON CONFLICT DO NOTHING
    RETURNING id INTO v_id;
    IF v_id IS NOT NULL THEN
      v_returned := 1;
      PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.transaction.created',
        jsonb_build_object('inventory_log_id', v_id, 'order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_return_qty, 'type', 'reversal'),
        v_meta);
      PERFORM public.emit_outbox_event('inventory', v_product.direct_ingredient_id, 'inventory.stock_changed',
        jsonb_build_object('inventory_log_id', v_id, 'order_item_id', p_order_item_id, 'ingredient_id', v_product.direct_ingredient_id, 'quantity', v_return_qty, 'type', 'reversal'),
        v_meta);
    END IF;

  ELSIF v_prod_found THEN
    FOR v_rec IN
      SELECT r.ingredient_id, r.quantity_required, r.quantity_brutto,
             COALESCE(i.unit, 'gram') AS unit
      FROM public.recipes r
      JOIN public.ingredients i ON i.id = r.ingredient_id
      WHERE r.menu_item_id = v_oi.product_id AND r.is_ai_suggested = false
    LOOP
      v_key := 'return:' || p_order_item_id::text || ':' || v_rec.ingredient_id::text;
      INSERT INTO public.inventory_logs (
        ingredient_id, type, quantity, unit, order_id, order_item_id,
        item_quantity, reference_type, reference_id, correlation_id, idempotency_key,
        performed_by, reason, created_at, location_id, organization_id
      ) VALUES (
        v_rec.ingredient_id, 'reversal',
        COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_return_qty,
        v_rec.unit, v_oi.order_id, p_order_item_id, v_return_qty,
        'order', v_oi.order_id, v_corr, v_key, p_performed_by,
        COALESCE(p_reason_text, 'Return to stock: ' || COALESCE(v_oi.product_name, 'Məhsul')),
        v_now, v_order.location_id, v_order.organization_id
      )
      ON CONFLICT DO NOTHING
      RETURNING id INTO v_id;
      IF v_id IS NOT NULL THEN
        v_returned := 1;
        PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.transaction.created',
          jsonb_build_object('inventory_log_id', v_id, 'order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_return_qty, 'type', 'reversal'),
          v_meta);
        PERFORM public.emit_outbox_event('inventory', v_rec.ingredient_id, 'inventory.stock_changed',
          jsonb_build_object('inventory_log_id', v_id, 'order_item_id', p_order_item_id, 'ingredient_id', v_rec.ingredient_id, 'quantity', COALESCE(v_rec.quantity_brutto, v_rec.quantity_required) * v_return_qty, 'type', 'reversal'),
          v_meta);
      END IF;
    END LOOP;
  END IF;

  PERFORM public.log_audit(
    'return_to_stock', 'order_item', p_order_item_id::text,
    p_performed_by, v_performer_name, NULL,
    jsonb_build_object(
      'product_name', v_oi.product_name,
      'quantity', v_return_qty,
      'reason', p_reason,
      'returned_entries', v_returned
    ),
    jsonb_build_object('order_id', v_oi.order_id, 'order_item_id', p_order_item_id),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', 'return_to_stock',
    'product_name', v_oi.product_name,
    'quantity_returned', v_return_qty,
    'entries_created', v_returned,
    'order_id', v_oi.order_id,
    'timestamp', v_now
  );
END;
$$;


--
-- Name: reverse_stock_for_items(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.reverse_stock_for_items(p_items text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_items jsonb;
  v_item jsonb;
  v_corr uuid := gen_random_uuid();
  v_res jsonb;
  v_reversed int := 0;
BEGIN
  IF p_items IS NULL THEN
    RETURN jsonb_build_object('success', true, 'result', 'no_items', 'reversed', 0);
  END IF;

  v_items := p_items::jsonb;
  IF jsonb_typeof(v_items) <> 'array' OR jsonb_array_length(v_items) = 0 THEN
    RETURN jsonb_build_object('success', true, 'result', 'no_items', 'reversed', 0);
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(v_items)
  LOOP
    IF NOT (v_item ? 'order_item_id') THEN CONTINUE; END IF;
    v_res := public._inventory_reverse_item_qty(
      (v_item->>'order_item_id')::uuid,
      COALESCE((v_item->>'reverse_qty')::int, 0),
      'cancel', NULL, v_corr
    );
    v_reversed := v_reversed + COALESCE((v_res->>'reversed')::int, 0);
  END LOOP;

  RETURN jsonb_build_object('success', true, 'result', 'reversed', 'reversed', v_reversed, 'correlation_id', v_corr);
END;
$$;


--
-- Name: revoke_session(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.revoke_session(p_token text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
    UPDATE sessions
    SET revoked_at = now(), status = 'REVOKED'
    WHERE token = p_token AND status = 'ACTIVE';

    RETURN FOUND;
END;
$$;


--
-- Name: route_kitchen_order(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.route_kitchen_order(p_order_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_result JSONB := '{}'::JSONB;
BEGIN
  SELECT jsonb_object_agg(
    COALESCE(printer_route, 'default'),
    jsonb_agg(
      jsonb_build_object(
        'id', id,
        'product_name', product_name,
        'quantity', quantity,
        'kitchen_status', kitchen_status,
        'course', course,
        'hold_until', hold_until
      )
    )
  ) INTO v_result
  FROM order_items
  WHERE order_id = p_order_id
    AND kitchen_status IS DISTINCT FROM 'cancelled';

  RETURN jsonb_build_object('success', true, 'routes', v_result);
END;
$$;


--
-- Name: saito_dismiss_table(integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saito_dismiss_table(p_table_number integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_ids UUID[];
  v_count INTEGER := 0;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  PERFORM 1 FROM table_floors WHERE table_number = p_table_number FOR UPDATE;

  SELECT array_agg(id)
  INTO v_order_ids
  FROM orders
  WHERE table_number = p_table_number
    AND status NOT IN ('paid', 'cancelled', 'closed')
  FOR UPDATE;

  IF v_order_ids IS NOT NULL AND array_length(v_order_ids, 1) IS NOT NULL THEN
    UPDATE orders
    SET
      status = 'cancelled',
      updated_at = now()
    WHERE id = ANY(v_order_ids);
  END IF;

  UPDATE table_floors
  SET
    status = 'empty',
    total_amount = 0,
    guest_count = NULL,
    order_count = 0,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    updated_at = now()
  WHERE table_number = p_table_number;

  GET DIAGNOSTICS v_count = ROW_COUNT;

  RETURN jsonb_build_object(
    'success', true,
    'table_number', p_table_number,
    'cancelled_orders', array_length(v_order_ids, 1),
    'updated_tables', v_count
  );
END;
$$;


--
-- Name: saito_merge_tables(integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saito_merge_tables(p_table_numbers integer[], p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$ DECLARE v_primary_table INTEGER; v_child_tables INTEGER[]; v_primary_order_id UUID; v_child_order_ids UUID[]; v_child_total NUMERIC := 0; v_child_guests INTEGER := 0; v_merged_count INTEGER := 0; BEGIN IF array_length(p_table_numbers, 1) < 2 THEN RAISE EXCEPTION 'At least 2 tables required for merge' USING ERRCODE = 'P0002'; END IF; v_primary_table := p_table_numbers[1]; v_child_tables := p_table_numbers[2:]; SELECT id INTO v_primary_order_id FROM orders WHERE table_number = v_primary_table AND status NOT IN ('paid', 'cancelled', 'closed') LIMIT 1; IF v_primary_order_id IS NULL THEN INSERT INTO orders (table_number, status, order_type, guest_count, total_amount) VALUES (v_primary_table, 'new', 'dine_in', 0, 0) RETURNING id INTO v_primary_order_id; END IF; SELECT array_agg(id), COALESCE(SUM(total_amount), 0), COALESCE(SUM(guest_count), 0) INTO v_child_order_ids, v_child_total, v_child_guests FROM orders WHERE table_number = ANY(v_child_tables) AND status NOT IN ('paid', 'cancelled', 'closed'); IF v_child_order_ids IS NOT NULL AND array_length(v_child_order_ids, 1) > 0 THEN UPDATE orders SET merged_into = v_primary_order_id, version = COALESCE(version, 0) + 1 WHERE id = ANY(v_child_order_ids); UPDATE orders SET total_amount = COALESCE(total_amount, 0) + v_child_total, guest_count = COALESCE(guest_count, 0) + v_child_guests, version = COALESCE(version, 0) + 1 WHERE id = v_primary_order_id; v_merged_count := array_length(v_child_order_ids, 1); END IF; UPDATE table_floors SET status = 'merged', merged_into_table = v_primary_table, guest_count = 0, total_amount = 0, opened_at = NULL, last_activity_at = now() WHERE table_number = ANY(v_child_tables); UPDATE table_floors SET status = CASE WHEN status = 'empty' THEN 'ordering' ELSE status END, guest_count = COALESCE(guest_count, 0) + v_child_guests, last_activity_at = now() WHERE table_number = v_primary_table; INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at) VALUES ('orders', v_primary_order_id, 'merge', jsonb_build_object('child_tables', v_child_tables), jsonb_build_object('merged_count', v_merged_count, 'child_total', v_child_total, 'child_guests', v_child_guests), p_performed_by, now()); RETURN jsonb_build_object('success', true, 'primary_table', v_primary_table, 'primary_order_id', v_primary_order_id, 'merged_count', v_merged_count, 'child_tables', v_child_tables, 'child_order_ids', v_child_order_ids, 'new_total', (SELECT COALESCE(total_amount, 0) FROM orders WHERE id = v_primary_order_id)); END; $$;


--
-- Name: saito_reverse_payment(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saito_reverse_payment(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
  DECLARE
  v_order RECORD;
  v_total_deductions NUMERIC;
  v_inventory_count INTEGER;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.status != 'paid' THEN
    RAISE EXCEPTION 'ORDER_NOT_PAID' USING ERRCODE = 'P0001';
  END IF;

  -- Get inventory deductions for reversal
  SELECT COUNT(*) INTO v_inventory_count FROM inventory_logs
  WHERE reference_type = 'order' AND reference_id = p_order_id;

  -- Reverse stock: insert opposite entries
  INSERT INTO inventory_logs (ingredient_id, type, quantity, unit_cost, reference_type, reference_id, order_id, notes, created_at)
  SELECT
    il.ingredient_id, 'order_consumption'::inventory_log_type,
    -il.quantity, COALESCE(il.unit_cost, 0),
    'reversal', p_order_id, p_order_id,
    'Reversal: Payment ' || p_order_id, now()
  FROM inventory_logs il
  WHERE il.reference_type = 'order' AND il.reference_id = p_order_id AND il.quantity > 0;

  -- Reset order to confirmed state
  UPDATE orders SET
    status = 'confirmed',
    paid_at = NULL,
    paid_amount = 0,
    tip_amount = 0,
    payment_method = NULL,
    cogs = 0,
    profit = 0,
    kitchen_status = 'pending',
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  -- Restore table
  UPDATE table_floors SET status = 'occupied', guest_count = COALESCE(v_order.guest_count, 1)
  WHERE table_number = v_order.table_number;

  -- Mark order_payments as reversed (soft delete via updating payment_method)
  UPDATE order_payments SET payment_method = 'reversed'
  WHERE order_id = p_order_id AND payment_method != 'reversed';

  -- Un-complete kitchen items
  UPDATE order_items SET kitchen_status = 'pending'
  WHERE order_id = p_order_id AND kitchen_status = 'completed';

  -- Audit log
  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'orders', p_order_id, 'payment_reversal',
    jsonb_build_object('status', 'paid', 'paid_amount', v_order.paid_amount, 'cogs', v_order.cogs),
    jsonb_build_object('status', 'confirmed', 'reversed_inventory', v_inventory_count),
    p_performed_by, now()
  );

  -- Notification
  INSERT INTO notifications (type, title, body, data, created_at)
  VALUES (
    'payment_reversal', 'Ödəniş ləğv edildi',
    'Masa ' || v_order.table_number || ' — ' || v_order.paid_amount || ' AZN ödəniş ləğv edildi',
    jsonb_build_object('order_id', p_order_id, 'table_number', v_order.table_number, 'reversed_amount', v_order.paid_amount),
    now()
  );

  RETURN jsonb_build_object(
    'success', true, 'order_id', p_order_id,
    'reversed_amount', v_order.paid_amount,
    'reversed_inventory', v_inventory_count
  );
END;
$$;


--
-- Name: saito_split_orders(integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saito_split_orders(p_table_numbers integer[], p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_primary_table int;
  v_child_tables int[];
  v_split_orders uuid[];
  v_order RECORD;
  v_now timestamptz := now();
  v_result jsonb;
  v_subtract_total numeric := 0;
  v_subtract_guests int := 0;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  IF array_length(p_table_numbers, 1) < 2 THEN
    RAISE EXCEPTION 'Need at least 2 tables to split';
  END IF;

  v_primary_table := p_table_numbers[1];

  FOR i IN 2 .. array_length(p_table_numbers, 1) LOOP
    SELECT id, total_amount, guest_count INTO v_order
    FROM orders
    WHERE table_number = p_table_numbers[i] AND status NOT IN ('paid', 'cancelled')
    LIMIT 1;

    IF NOT FOUND THEN
      INSERT INTO orders (table_number, status, total_amount, guest_count, order_type, created_at, updated_at)
      VALUES (p_table_numbers[i], 'confirmed', 0, 0, 'dine_in', v_now, v_now)
      RETURNING id, total_amount, guest_count INTO v_order;
    END IF;

    -- Clear any merged_into reference
    UPDATE orders
    SET merged_into = NULL, updated_at = v_now
    WHERE id = v_order.id;

    v_subtract_total := v_subtract_total + v_order.total_amount;
    v_subtract_guests := v_subtract_guests + v_order.guest_count;
  END LOOP;

  -- Subtract split amounts from the primary order
  UPDATE orders
  SET total_amount = GREATEST(total_amount - v_subtract_total, 0),
      guest_count = GREATEST(guest_count - v_subtract_guests, 0),
      updated_at = v_now
  WHERE table_number = v_primary_table AND status NOT IN ('paid', 'cancelled');

  -- Refresh table floor totals
  FOR i IN 1 .. array_length(p_table_numbers, 1) LOOP
    UPDATE table_floors
    SET total_amount = (SELECT COALESCE(SUM(total_amount), 0)
        FROM orders WHERE table_number = p_table_numbers[i] AND status NOT IN ('paid', 'cancelled')),
        guest_count = (SELECT COALESCE(SUM(guest_count), 0)
        FROM orders WHERE table_number = p_table_numbers[i] AND status NOT IN ('paid', 'cancelled'))
    WHERE table_number = p_table_numbers[i];
  END LOOP;

  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, changed_by)
  VALUES ('orders'::text, v_primary_table::text, 'split'::text, '{}'::jsonb,
    jsonb_build_object('tables', p_table_numbers, 'subtract_total', v_subtract_total),
    p_performed_by);

  SELECT jsonb_build_object('split_count', array_length(p_table_numbers, 1)) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: saito_transfer_table(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saito_transfer_table(p_from_table integer, p_to_table integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_target_order_id uuid;
  v_undo_data jsonb;
  v_now timestamptz := now();
  v_result jsonb;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  -- Check source has active orders
  SELECT id, table_number, total_amount, guest_count INTO v_order
  FROM orders
  WHERE table_number = p_from_table AND status NOT IN ('paid', 'cancelled')
  LIMIT 1;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'NO_ACTIVE_ORDERS';
  END IF;

  -- If target has active orders, merge
  SELECT id INTO v_target_order_id
  FROM orders
  WHERE table_number = p_to_table AND status NOT IN ('paid', 'cancelled')
  LIMIT 1;

  IF FOUND THEN
    -- Merge source into target
    UPDATE orders
    SET merged_into = v_target_order_id::text,
        table_number = p_to_table,
        updated_at = v_now
    WHERE id = v_order.id;

    v_undo_data := jsonb_build_object(
      'action', 'transfer',
      'order_id', v_order.id,
      'from_table', p_from_table,
      'to_table', p_to_table,
      'merged', true,
      'target_order_id', v_target_order_id
    );

    UPDATE table_floors
    SET status = 'empty', total_amount = 0, guest_count = NULL, order_count = 0
    WHERE table_number = p_from_table;
  ELSE
    -- Just move order to target table
    UPDATE orders
    SET table_number = p_to_table, updated_at = v_now
    WHERE id = v_order.id;

    v_undo_data := jsonb_build_object(
      'action', 'transfer',
      'order_id', v_order.id,
      'from_table', p_from_table,
      'to_table', p_to_table,
      'merged', false
    );

    UPDATE table_floors
    SET status = 'empty', total_amount = 0, guest_count = NULL, order_count = 0
    WHERE table_number = p_from_table;
  END IF;

  -- Refresh target table totals
  UPDATE table_floors
  SET status = 'occupied',
      total_amount = (SELECT COALESCE(SUM(total_amount), 0)
        FROM orders WHERE table_number = p_to_table AND status NOT IN ('paid', 'cancelled')),
      guest_count = (SELECT COALESCE(SUM(guest_count), 0)
        FROM orders WHERE table_number = p_to_table AND status NOT IN ('paid', 'cancelled'))
  WHERE table_number = p_to_table;

  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, changed_by)
  VALUES ('orders'::text, v_order.id, 'transfer'::text, '{}'::jsonb,
    jsonb_build_object('from_table', p_from_table, 'to_table', p_to_table),
    p_performed_by);

  SELECT jsonb_build_object('moved_orders', 1, 'undo', v_undo_data) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: saito_transfer_tables(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saito_transfer_tables(p_from_table integer, p_to_table integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_ids UUID[];
  v_total_amount NUMERIC := 0;
  v_total_guests INTEGER := 0;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  PERFORM 1 FROM table_floors WHERE table_number = p_from_table FOR UPDATE;
  PERFORM 1 FROM table_floors WHERE table_number = p_to_table FOR UPDATE;

  SELECT array_agg(id), COALESCE(SUM(total_amount), 0), COALESCE(SUM(guest_count), 0)
  INTO v_order_ids, v_total_amount, v_total_guests
  FROM orders
  WHERE table_number = p_from_table
    AND status NOT IN ('paid', 'cancelled', 'closed')
  FOR UPDATE;

  IF v_order_ids IS NULL OR array_length(v_order_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'NO_ACTIVE_ORDERS' USING ERRCODE = 'P0001';
  END IF;

  UPDATE orders
  SET
    table_number = p_to_table,
    version = COALESCE(version, 0) + 1
  WHERE id = ANY(v_order_ids);

  UPDATE table_floors
  SET
    status = 'occupied',
    total_amount = v_total_amount,
    guest_count = v_total_guests,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL
  WHERE table_number = p_to_table;

  UPDATE table_floors
  SET
    status = 'empty',
    total_amount = 0,
    guest_count = NULL,
    order_count = 0,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL
  WHERE table_number = p_from_table;

  RETURN jsonb_build_object(
    'success', true,
    'from_table', p_from_table,
    'to_table', p_to_table,
    'order_ids', v_order_ids,
    'total_amount', v_total_amount,
    'total_guests', v_total_guests
  );
END;
$$;


--
-- Name: saito_undo_table_operation(text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.saito_undo_table_operation(p_action text, p_data jsonb, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_now timestamptz := now();
  v_result jsonb;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  CASE p_action
    WHEN 'merge' THEN
      UPDATE orders
      SET merged_into = NULL,
          table_number = (p_data->>'table_number')::int,
          updated_at = v_now
      WHERE id = (p_data->>'order_id')::uuid;

      UPDATE table_floors
      SET status = 'occupied',
          total_amount = (SELECT COALESCE(SUM(total_amount), 0)
            FROM orders WHERE table_number = (p_data->>'table_number')::int AND status NOT IN ('paid', 'cancelled')),
          guest_count = (SELECT COALESCE(SUM(guest_count), 0)
            FROM orders WHERE table_number = (p_data->>'table_number')::int AND status NOT IN ('paid', 'cancelled'))
      WHERE table_number = (p_data->>'table_number')::int;

      -- Recalculate primary table
      UPDATE table_floors
      SET total_amount = (SELECT COALESCE(SUM(total_amount), 0)
          FROM orders WHERE table_number = (p_data->>'table_number')::int AND status NOT IN ('paid', 'cancelled')),
          guest_count = (SELECT COALESCE(SUM(guest_count), 0)
          FROM orders WHERE table_number = (p_data->>'table_number')::int AND status NOT IN ('paid', 'cancelled'))
      WHERE table_number = (SELECT table_number FROM orders WHERE id = ((p_data->>'merged_into')::uuid));

    WHEN 'transfer' THEN
      UPDATE orders
      SET table_number = (p_data->>'from_table')::int,
          merged_into = CASE WHEN (p_data->>'merged')::bool THEN (p_data->>'target_order_id')::uuid::text ELSE NULL END,
          updated_at = v_now
      WHERE id = (p_data->>'order_id')::uuid;

      UPDATE table_floors
      SET status = 'occupied', total_amount = (p_data->>'total_amount')::numeric, guest_count = (p_data->>'guest_count')::int
      WHERE table_number = (p_data->>'from_table')::int;

    WHEN 'split' THEN
      UPDATE orders
      SET total_amount = (p_data->>'total_amount')::numeric,
          guest_count = (p_data->>'guest_count')::int,
          updated_at = v_now
      WHERE id = (p_data->>'order_id')::uuid;

    ELSE
      RAISE EXCEPTION 'Unknown undo action: %', p_action;
  END CASE;

  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, changed_by)
  VALUES ('table_floors', p_data->>'table_number', 'undo_' || p_action, p_data, '{}'::jsonb, p_performed_by);

  SELECT jsonb_build_object('success', true) INTO v_result;
  RETURN v_result;
END;
$$;


--
-- Name: seat_guests_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.seat_guests_atomic(p_reservation_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table RECORD;
  v_order_id uuid;
  v_order_ids uuid[] := '{}';
  v_item RECORD;
  v_now timestamptz := now();
  v_scheduled_for timestamptz;
  v_result jsonb;
  v_capacity int := 0;
  v_table_count int := 0;
  v_split int;
  v_k int := 0;
  v_old_state jsonb;
BEGIN
  PERFORM public.validate_actor(p_performed_by);

  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;
  IF v_reservation.status NOT IN ('pending','confirmed','waiting') THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_SEAT_RESERVATION_STATE');
  END IF;

  -- lock the reserved tables deterministically
  FOR v_table IN
    SELECT t.table_number, t.id AS table_id, t.capacity
    FROM public.reservation_tables rt
    JOIN public.table_floors t ON t.table_number = rt.table_number
    WHERE rt.reservation_id = p_reservation_id
      AND t.status = ANY (ARRAY['reserved','waiting'])
    ORDER BY t.table_number
    FOR UPDATE OF t
  LOOP
    NULL;
  END LOOP;

  v_scheduled_for := COALESCE(v_reservation.kitchen_scheduled_for,
    (v_reservation.date::timestamp + v_reservation.time::time)
      - interval '1 minute' * COALESCE(v_reservation.kitchen_prep_time_minutes, 20));

  -- capacity guard: sum of known capacities must cover guests (0/unknown skipped)
  SELECT COALESCE(sum(capacity), 0) INTO v_capacity
   FROM public.table_floors t
   JOIN public.reservation_tables rt ON rt.table_number = t.table_number
   WHERE rt.reservation_id = p_reservation_id
     AND t.status = ANY (ARRAY['reserved','waiting'])
     AND t.capacity > 0;
  IF v_capacity > 0 AND v_reservation.guests > v_capacity THEN
    RETURN jsonb_build_object('success', false, 'error',
      'G_SEAT_CAPACITY_EXCEEDED (guests=' || v_reservation.guests || ', capacity=' || v_capacity || ')');
  END IF;

  -- per-table seat minimum: every seated table gets >=1 guest (orders store
  -- guest_count > 0); the remainder lands on the primary table so the group
  -- total always matches the reservation's guest count.
  SELECT count(*) INTO v_table_count
   FROM public.reservation_tables rt
   JOIN public.table_floors t ON t.table_number = rt.table_number
   WHERE rt.reservation_id = p_reservation_id
     AND t.status = ANY (ARRAY['reserved','waiting']);

  -- deterministic per-table seat
  FOR v_table IN
    SELECT t.table_number, t.id AS table_id, t.capacity
    FROM public.reservation_tables rt
    JOIN public.table_floors t ON t.table_number = rt.table_number
    WHERE rt.reservation_id = p_reservation_id
      AND t.status = ANY (ARRAY['reserved','waiting'])
    ORDER BY t.table_number
  LOOP
    v_k := v_k + 1;
    IF v_k = 1 THEN
      v_split := COALESCE(v_reservation.guests, 1) - (v_table_count - 1);
      IF v_split < 1 THEN v_split := 1; END IF;
    ELSE
      v_split := 1; -- every seated table hosts at least one guest
    END IF;

    SELECT id INTO v_order_id FROM public.orders
     WHERE reservation_id = p_reservation_id
       AND table_number = v_table.table_number
       AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
     ORDER BY created_at DESC LIMIT 1;

    IF v_order_id IS NULL THEN
      INSERT INTO public.orders (
        table_number, status, total_amount, guest_count,
        order_source, reservation_id, created_at, updated_at,
        created_by, is_draft, kitchen_status, kitchen_scheduled_for,
        location_id, organization_id
      ) VALUES (
        v_table.table_number, 'confirmed', 0, v_split,
        'dine_in', p_reservation_id, v_now, v_now,
        p_performed_by, false, 'pending', v_scheduled_for,
        v_reservation.location_id, v_reservation.organization_id
      ) RETURNING id INTO v_order_id;
    ELSE
      UPDATE public.orders SET
        status = 'confirmed',
        guest_count = v_split,
        kitchen_status = 'pending',
        kitchen_scheduled_for = v_scheduled_for,
        version = COALESCE(version,0) + 1,
        updated_at = v_now
      WHERE id = v_order_id;
    END IF;

    -- pre-order items land on the primary table's order only (reservation-level
    -- preorders have no per-table plan; single canonical carrier keeps totals exact)
    IF v_k = 1 THEN
      FOR v_item IN
        SELECT * FROM public.reservation_preorder_items WHERE reservation_id = p_reservation_id
      LOOP
        INSERT INTO public.order_items (
          order_id, product_id, combo_group_id, product_name, quantity,
          unit_price, total_price, modifiers, special_notes,
          course, kitchen_status, prepared_quantity, tax_rate, tax_amount, created_at
        ) VALUES (
          v_order_id, v_item.product_id, v_item.combo_id, v_item.product_name, v_item.quantity,
          v_item.unit_price, (v_item.quantity * v_item.unit_price), v_item.modifiers, v_item.special_notes,
          v_item.course, 'reserved', 0, 0, 0, v_now
        );
      END LOOP;
    END IF;

    UPDATE public.table_floors SET
      status = 'occupied',
      current_order_id = v_order_id,
      guest_count = v_split,
      last_activity_at = v_now,
      opened_at = COALESCE(opened_at, v_now),
      updated_at = v_now
    WHERE id = v_table.table_id;

    PERFORM public.sync_table_order_aggregates(v_table.table_number);

    v_old_state := jsonb_build_object('reservation_status', v_reservation.status,
      'guests', v_reservation.guests, 'table_number', v_table.table_number, 'capacity', v_table.capacity);

    PERFORM public.g_table_audit(
      'seat_guests', 'table.guests_seated',
      v_table.table_number, v_table.table_id, v_order_id,
      v_old_state,
      jsonb_build_object('status','occupied','order_id',v_order_id,'guests',v_split,
        'reservation_id', p_reservation_id, 'kitchen_scheduled_for', v_scheduled_for),
      p_performed_by, NULL, 'contract-seat',
      v_table.table_number, NULL, v_reservation.location_id, v_reservation.organization_id);

    v_order_ids := array_append(v_order_ids, v_order_id);
  END LOOP;

  IF array_length(v_order_ids, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_SEAT_NO_TABLES');
  END IF;

  UPDATE public.reservations SET
    status = 'checked_in',
    checked_in_at = v_now,
    pre_order_items = '[]'::jsonb,
    pre_order_total = NULL,
    updated_at = v_now
  WHERE id = p_reservation_id;

  DELETE FROM public.reservation_preorder_items WHERE reservation_id = p_reservation_id;

  v_result := jsonb_build_object('success', true, 'order_ids', v_order_ids, 'seated_at', v_now, 'tables', v_k);
  RETURN v_result;
END;
$$;


--
-- Name: send_item_atomic(text, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_item_atomic(p_token text, p_item_id uuid, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_correlation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT item_kitchen_step(p_token, p_item_id, 'sent', p_reason, p_metadata, p_correlation_id)
$$;


--
-- Name: send_message(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_message(p_from_staff_id uuid, p_to_staff_id uuid, p_location_id uuid, p_type text, p_subject text, p_content text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_message_id UUID;
BEGIN
  INSERT INTO staff_messages (from_staff_id, to_staff_id, location_id, message_type, subject, content)
  VALUES (p_from_staff_id, p_to_staff_id, p_location_id, p_type, p_subject, p_content)
  RETURNING id INTO v_message_id;

  RETURN json_build_object('success', true, 'message_id', v_message_id);
END;
$$;


--
-- Name: send_to_kitchen_atomic(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_to_kitchen_atomic(p_reservation_id uuid, p_user_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
BEGIN
  PERFORM public.validate_actor(p_user_id);
  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;

  INSERT INTO public.operation_logs (
    reservation_id, action, new_values, performed_by
  ) VALUES (
    p_reservation_id, 'send_to_kitchen',
    jsonb_build_object('reservation_id', p_reservation_id),
    p_user_id
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: send_to_kitchen_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.send_to_kitchen_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  DECLARE
  v_order RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status IN ('pending', 'accepted', 'preparing', 'ready', 'served') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order already sent to kitchen');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'pending',
    is_draft = false,
    kitchen_accepted_at = NOW(),
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  UPDATE public.order_items SET
    kitchen_status = 'pending',
    updated_at = NOW()
  WHERE order_id = p_order_id AND kitchen_status = 'reserved';

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'pending',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'send_to_kitchen',
    jsonb_build_object('kitchen_status', v_order.kitchen_status),
    jsonb_build_object('kitchen_status', 'pending'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: separate_tables_v1(integer, integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.separate_tables_v1(p_primary_table integer, p_child_tables integer[], p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$ DECLARE v_primary_order RECORD; v_child_order RECORD; v_removed_amount numeric := 0; v_removed_guests integer := 0; v_now timestamptz := now(); v_result jsonb; BEGIN SELECT id, total_amount, guest_count INTO v_primary_order FROM orders WHERE table_number = p_primary_table AND status NOT IN ('paid', 'cancelled', 'closed') AND merged_into IS NULL ORDER BY created_at DESC LIMIT 1; IF NOT FOUND THEN RAISE EXCEPTION 'PRIMARY_ORDER_NOT_FOUND' USING ERRCODE = 'P0001'; END IF; FOR i IN 1..array_length(p_child_tables, 1) LOOP SELECT id, total_amount, guest_count INTO v_child_order FROM orders WHERE table_number = p_child_tables[i] AND status NOT IN ('paid', 'cancelled', 'closed') AND merged_into = v_primary_order.id LIMIT 1; IF FOUND THEN v_removed_amount := v_removed_amount + COALESCE(v_child_order.total_amount, 0); v_removed_guests := v_removed_guests + COALESCE(v_child_order.guest_count, 0); UPDATE orders SET merged_into = NULL, table_number = p_child_tables[i], updated_at = v_now WHERE id = v_child_order.id; END IF; UPDATE table_floors SET status = CASE WHEN v_child_order.id IS NOT NULL THEN 'occupied' ELSE 'empty' END, guest_count = CASE WHEN v_child_order.id IS NOT NULL THEN v_child_order.guest_count ELSE NULL END, total_amount = CASE WHEN v_child_order.id IS NOT NULL THEN v_child_order.total_amount ELSE 0 END, merged_into_table = NULL WHERE table_number = p_child_tables[i]; END LOOP; UPDATE orders SET total_amount = GREATEST(COALESCE(v_primary_order.total_amount, 0) - v_removed_amount, 0), guest_count = GREATEST(COALESCE(v_primary_order.guest_count, 1) - v_removed_guests, 1), updated_at = v_now WHERE id = v_primary_order.id; UPDATE table_floors SET total_amount = GREATEST(COALESCE(v_primary_order.total_amount, 0) - v_removed_amount, 0), guest_count = GREATEST(COALESCE(v_primary_order.guest_count, 1) - v_removed_guests, 1), last_activity_at = v_now WHERE table_number = p_primary_table; INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, changed_by) VALUES ('orders', v_primary_order.id::text, 'unmerge', jsonb_build_object('primary_table', p_primary_table, 'child_tables', p_child_tables), jsonb_build_object('removed_amount', v_removed_amount, 'removed_guests', v_removed_guests), p_performed_by); INSERT INTO notifications (title, body, type, data, created_at) VALUES ('Masalar ayrıldı', 'Masa ' || p_primary_table || ' — ' || array_length(p_child_tables, 1) || ' masa ayrıldı', 'order', jsonb_build_object('primary_table', p_primary_table, 'child_tables', p_child_tables), v_now); SELECT jsonb_build_object('success', true, 'primary_table', p_primary_table, 'child_tables', p_child_tables, 'removed_amount', v_removed_amount, 'removed_guests', v_removed_guests) INTO v_result; RETURN v_result; END; $$;


--
-- Name: separate_tables_v1(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.separate_tables_v1(p_primary_table_id uuid, p_separated_table_id uuid, p_order_ids uuid[]) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE orders
  SET table_number = p_separated_table_id
  WHERE id = ANY(p_order_ids);

  UPDATE table_floors
  SET status = 'occupied'
  WHERE id = p_separated_table_id;

  IF NOT EXISTS (
    SELECT 1 FROM orders
    WHERE table_number = p_primary_table_id
      AND status = 'active'
  ) THEN
    UPDATE table_floors
    SET status = 'available'
    WHERE id = p_primary_table_id;
  END IF;
END;
$$;


--
