--
-- Name: set_session_staff(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.set_session_staff(p_token text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_session RECORD;
BEGIN
    SELECT s.user_id, s.role, s.expires_at, s.active_location_id, s.organization_id, s.status
    INTO v_session
    FROM sessions s
    WHERE s.token = p_token;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Invalid or expired session';
    END IF;

    IF v_session.expires_at <= now() THEN
        UPDATE sessions SET status = 'EXPIRED' WHERE token = p_token;
        RAISE EXCEPTION 'Session expired';
    END IF;

    IF v_session.status = 'REVOKED' THEN
        RAISE EXCEPTION 'Session revoked';
    END IF;

    -- Auto-expire if status is wrong
    IF v_session.status != 'ACTIVE' THEN
        RAISE EXCEPTION 'Session is %', v_session.status;
    END IF;

    PERFORM set_config('app.current_staff_id', v_session.user_id::text, false);
    PERFORM set_config('app.current_role', v_session.role, false);
    PERFORM set_config('app.current_location_id', COALESCE(v_session.active_location_id::text, ''), false);
    PERFORM set_config('app.current_org_id', COALESCE(v_session.organization_id::text, ''), false);

    -- Update last_activity_at
    UPDATE sessions SET last_activity_at = now() WHERE token = p_token;
END;
$$;


