--
-- Name: split_by_seat(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_by_seat(p_order_id uuid, p_seat_number integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_original RECORD;
  v_new_order_id UUID;
  v_new_total NUMERIC := 0;
  v_item_count INTEGER := 0;
BEGIN
  SELECT * INTO v_original FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_original.status = 'paid' THEN
    RAISE EXCEPTION 'ORDER_ALREADY_PAID' USING ERRCODE = 'P0001';
  END IF;

  -- Create new order for the split (INHERITS parent location/org — D-2 fix)
  INSERT INTO orders (
    table_number, order_source, status, guest_count,
    total_amount, is_split, merged_into, version, created_at,
    location_id, organization_id
  ) VALUES (
    v_original.table_number, v_original.order_source, 'confirmed', 1,
    0, true, p_order_id, 1, now(),
    v_original.location_id, v_original.organization_id
  )
  RETURNING id INTO v_new_order_id;

  -- Move seat items to new order
  INSERT INTO order_items (
    order_id, product_id, product_name, quantity, unit_price, total_price,
    modifiers, special_notes, combo_group_id, variant_id,
    kitchen_status, seat_number, course, price_snapshot
  )
  SELECT
    v_new_order_id, product_id, product_name, quantity, unit_price, total_price,
    modifiers, special_notes, combo_group_id, variant_id,
    kitchen_status, seat_number, course, price_snapshot
  FROM order_items
  WHERE order_id = p_order_id
    AND seat_number = p_seat_number
    AND kitchen_status NOT IN ('cancelled');

  GET DIAGNOSTICS v_item_count = ROW_COUNT;

  -- Calculate new total
  SELECT COALESCE(SUM(total_price), 0) INTO v_new_total
  FROM order_items WHERE order_id = v_new_order_id;

  UPDATE orders SET total_amount = v_new_total WHERE id = v_new_order_id;

  -- Update original order total
  UPDATE orders SET
    total_amount = GREATEST(0, COALESCE(total_amount, 0) - v_new_total),
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  -- Log events
  PERFORM log_order_event(
    p_order_id, 'bill_split',
    jsonb_build_object('total_amount', v_original.total_amount),
    jsonb_build_object('split_to', v_new_order_id, 'seat', p_seat_number, 'amount', v_new_total),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  PERFORM log_operation(
    'split_bill', p_order_id,
    v_original.table_number, NULL,
    jsonb_build_object('total_amount', v_original.total_amount, 'seat', p_seat_number),
    jsonb_build_object('new_order_id', v_new_order_id, 'new_total', v_new_total),
    jsonb_build_object('undo_action', 'merge', 'order_id', v_new_order_id),
    p_performed_by, NULL, NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'new_order_id', v_new_order_id,
    'seat_number', p_seat_number,
    'items_moved', v_item_count,
    'new_total', v_new_total,
    'remaining_total', GREATEST(0, COALESCE(v_original.total_amount, 0) - v_new_total)
  );
END;
$$;


--
-- Name: split_equal(uuid, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_equal(p_order_id uuid, p_split_count integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_original RECORD;
  v_split_total NUMERIC;
  v_remainder NUMERIC;
  v_new_order_id UUID;
  v_split_amount NUMERIC;
  v_i INTEGER;
BEGIN
  SELECT * INTO v_original FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_original.status = 'paid' THEN
    RAISE EXCEPTION 'ORDER_ALREADY_PAID' USING ERRCODE = 'P0001';
  END IF;
  IF p_split_count < 2 OR p_split_count > 12 THEN
    RAISE EXCEPTION 'INVALID_SPLIT_COUNT' USING ERRCODE = 'P0001';
  END IF;

  v_split_total := COALESCE(v_original.total_amount, 0);
  v_split_amount := floor(v_split_total / p_split_count * 100) / 100;
  v_remainder := v_split_total - (v_split_amount * (p_split_count - 1));

  -- Create N-1 split orders (last one keeps the original)
  FOR v_i IN 1..(p_split_count - 1)
  LOOP
    INSERT INTO orders (
      table_number, order_source, status, guest_count,
      total_amount, is_split, merged_into, version, created_at
    ) VALUES (
      v_original.table_number, v_original.order_source, 'confirmed', 1,
      v_split_amount, true, p_order_id, 1, now()
    )
    RETURNING id INTO v_new_order_id;
  END LOOP;

  -- Update original with remainder
  UPDATE orders SET
    total_amount = v_remainder,
    is_split = true,
    version = COALESCE(version, 0) + 1
  WHERE id = p_order_id;

  PERFORM log_order_event(
    p_order_id, 'bill_split',
    jsonb_build_object('total_amount', v_split_total, 'split_count', p_split_count),
    jsonb_build_object('split_amount', v_split_amount, 'remainder', v_remainder),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'split_count', p_split_count,
    'split_amount', v_split_amount,
    'remainder', v_remainder,
    'original_order_id', p_order_id
  );
END;
$$;


--
-- Name: split_order_atomic(uuid, jsonb, numeric, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_order_atomic(p_original_order_id uuid, p_split_items jsonb, p_split_total numeric, p_new_guest_count integer DEFAULT 1, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_original RECORD;
  v_new_order_id UUID;
  v_item RECORD;
BEGIN
  -- Lock original order
  SELECT * INTO v_original FROM orders WHERE id = p_original_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_original.status = 'paid' THEN
    RAISE EXCEPTION 'ORDER_ALREADY_PAID' USING ERRCODE = 'P0001';
  END IF;

  -- Create new split order (INHERITS parent location/org — D-2 fix)
  INSERT INTO orders (
    table_number, total_amount, guest_count, status, kitchen_status,
    merged_into, is_split, version, created_at,
    location_id, organization_id
  ) VALUES (
    v_original.table_number, p_split_total, p_new_guest_count,
    'confirmed', 'pending',
    p_original_order_id, true, 1, now(),
    v_original.location_id, v_original.organization_id
  )
  RETURNING id INTO v_new_order_id;

  -- Move items from original to split order
  FOR v_item IN SELECT * FROM jsonb_to_recordset(p_split_items) AS x(
    id UUID, product_id UUID, product_name TEXT, quantity INTEGER,
    unit_price NUMERIC, total_price NUMERIC, modifiers TEXT,
    special_notes TEXT, combo_group_id UUID, variant_id UUID
  )
  LOOP
    -- Insert into new order
    -- NOTE: v_item.modifiers is TEXT (from jsonb_to_recordset); the column is
    -- jsonb. The live route stringifies modifiers (JSON.stringify), so cast it
    -- safely (empty/NULL -> '[]') — fixes a pre-existing type mismatch that
    -- surfaced when modifiers was a non-empty string.
    INSERT INTO order_items (
      order_id, product_id, product_name, quantity, unit_price,
      total_price, modifiers, special_notes, combo_group_id, variant_id,
      kitchen_status
    ) VALUES (
      v_new_order_id, v_item.product_id, v_item.product_name,
      v_item.quantity, v_item.unit_price, v_item.total_price,
      COALESCE(NULLIF(trim(COALESCE(v_item.modifiers, '')), ''), '[]')::jsonb,
      v_item.special_notes, v_item.combo_group_id,
      v_item.variant_id, 'ready'
    );

    -- Reduce or delete from original order
    UPDATE order_items
    SET quantity = quantity - v_item.quantity,
        total_price = GREATEST(0, total_price - v_item.total_price)
    WHERE id = v_item.id AND quantity > v_item.quantity;

    DELETE FROM order_items
    WHERE id = v_item.id AND quantity <= v_item.quantity;
  END LOOP;

  -- Update original order total
  UPDATE orders
  SET total_amount = GREATEST(0, COALESCE(v_original.total_amount, 0) - p_split_total),
      version = COALESCE(v_original.version, 0) + 1
  WHERE id = p_original_order_id;

  RETURN jsonb_build_object(
    'success', true,
    'original_order_id', p_original_order_id,
    'new_order_id', v_new_order_id,
    'new_total', GREATEST(0, COALESCE(v_original.total_amount, 0) - p_split_total)
  );
END;
$$;


--
-- Name: split_order_by_items_atomic(uuid, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.split_order_by_items_atomic(p_original_order_id uuid, p_splits jsonb, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_original RECORD;
  v_split JSONB;
  v_new_order_id UUID;
  v_new_total NUMERIC := 0;
BEGIN
  SELECT * INTO v_original FROM orders WHERE id = p_original_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_original.status = 'paid' THEN
    RAISE EXCEPTION 'ORDER_ALREADY_PAID' USING ERRCODE = 'P0001';
  END IF;

  FOR v_split IN SELECT * FROM jsonb_array_elements(p_splits)
  LOOP
    INSERT INTO orders (
      table_number, total_amount, guest_count, status, kitchen_status,
      merged_into, version, created_at
    ) VALUES (
      v_original.table_number,
      0, 1, 'confirmed', 'pending',
      p_original_order_id, 1, now()
    )
    RETURNING id INTO v_new_order_id;

    INSERT INTO order_items (
      order_id, product_id, product_name, quantity, unit_price, total_price,
      modifiers, special_notes, combo_group_id, variant_id, kitchen_status, seat_number
    )
    SELECT
      v_new_order_id,
      (i->>'product_id')::UUID,
      i->>'product_name',
      (i->>'quantity')::INTEGER,
      (i->>'unit_price')::NUMERIC,
      (i->>'unit_price')::NUMERIC * (i->>'quantity')::INTEGER,
      i->>'modifiers',
      i->>'special_notes',
      (i->>'combo_group_id')::UUID,
      (i->>'variant_id')::UUID,
      'ready',
      (i->>'seat_number')::INTEGER
    FROM jsonb_array_elements(v_split->'items') AS i;

    SELECT COALESCE(SUM((i->>'unit_price')::NUMERIC * (i->>'quantity')::INTEGER), 0)
    INTO v_new_total
    FROM jsonb_array_elements(v_split->'items') AS i;

    UPDATE orders SET total_amount = v_new_total WHERE id = v_new_order_id;
  END LOOP;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: start_break_token(text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_break_token(p_token text, p_target_id uuid, p_break_type text DEFAULT 'unpaid'::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_actor uuid;
  v_override boolean;
  v_shift RECORD;
  v_active_break RECORD;
  v_break_id uuid;
BEGIN
  PERFORM set_session_staff(p_token);
  v_actor := current_staff_id();
  v_override := (p_target_id IS DISTINCT FROM v_actor)
                AND coalesce(has_permission(v_actor, 'timeclock.override'), false);
  IF p_target_id IS DISTINCT FROM v_actor AND NOT v_override THEN
    INSERT INTO security_events (staff_id, event_type, success, metadata)
    VALUES (v_actor, 'permission_denied', false,
      jsonb_build_object('action', 'start_break', 'target', p_target_id));
    RETURN json_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  SELECT * INTO v_shift FROM shifts
  WHERE staff_id = p_target_id AND closed_at IS NULL
  ORDER BY opened_at DESC LIMIT 1;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'No active shift');
  END IF;

  SELECT * INTO v_active_break FROM shift_breaks
  WHERE shift_id = v_shift.id AND ended_at IS NULL;
  IF FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Break already in progress');
  END IF;

  -- G-1: staff_id is NOT NULL on shift_breaks (was missing → every break failed)
  -- G-3: shift_breaks.id is gen_random_uuid() (NO sequence) → currval() always
  --      crashed. Capture the id via RETURNING.
  INSERT INTO shift_breaks (staff_id, shift_id, break_type, started_at)
  VALUES (p_target_id, v_shift.id, p_break_type, NOW())
  RETURNING id INTO v_break_id;

  INSERT INTO time_clock_entries (staff_id, entry_type, source, timestamp)
  VALUES (p_target_id, 'break_start', 'pos_terminal', NOW());

  INSERT INTO time_clock_audit (action, performed_by, details)
  VALUES ('break_start', p_target_id, jsonb_build_object('break_type', p_break_type, 'actor', v_actor, 'override', v_override));

  RETURN json_build_object(
    'success', true, 'break_id', v_break_id,
    'override', v_override, 'started_at', NOW()
  );
END;
$$;


--
-- Name: start_item_atomic(text, uuid, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_item_atomic(p_token text, p_item_id uuid, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_correlation_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
  SELECT item_kitchen_step(p_token, p_item_id, 'preparing', p_reason, p_metadata, p_correlation_id)
$$;


--
-- Name: start_onboarding(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_onboarding(p_staff_id uuid, p_role_id uuid) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_workflow_id UUID;
BEGIN
  INSERT INTO onboarding_workflows (staff_id, role_id, status)
  VALUES (p_staff_id, p_role_id, 'in_progress')
  RETURNING id INTO v_workflow_id;

  -- Create default tasks
  INSERT INTO onboarding_tasks (workflow_id, task_type, title, description, sort_order)
  VALUES
    (v_workflow_id, 'setup', 'Account Setup', 'Complete account setup', 1),
    (v_workflow_id, 'training', 'POS Training', 'Learn POS system basics', 2),
    (v_workflow_id, 'training', 'Safety Training', 'Complete safety training', 3),
    (v_workflow_id, 'documents', 'Submit Documents', 'Upload required documents', 4),
    (v_workflow_id, 'review', 'Manager Review', 'Complete manager review', 5);

  RETURN json_build_object('success', true, 'workflow_id', v_workflow_id);
END;
$$;


--
-- Name: start_preparing_atomic(uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.start_preparing_atomic(p_order_id uuid, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.kitchen_status NOT IN ('accepted', 'pending') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order cannot start preparing');
  END IF;

  UPDATE public.orders SET
    kitchen_status = 'preparing',
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  IF v_order.table_number IS NOT NULL THEN
    UPDATE public.table_floors SET
      kitchen_status = 'preparing',
      updated_at = NOW()
    WHERE table_number = v_order.table_number;
  END IF;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'start_preparing',
    jsonb_build_object('kitchen_status', v_order.kitchen_status),
    jsonb_build_object('kitchen_status', 'preparing'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true);
END;
$$;


