--
-- Name: submit_shift_review(uuid, uuid, numeric, numeric, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.submit_shift_review(p_shift_id uuid, p_staff_id uuid, p_declared_cash_tips numeric DEFAULT 0, p_declared_tip_out numeric DEFAULT 0, p_declared_notes text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_review_id UUID;
BEGIN
  INSERT INTO shift_reviews (
    shift_id, staff_id, review_status,
    declared_cash_tips, declared_tip_out, declared_notes
  ) VALUES (
    p_shift_id, p_staff_id, 'submitted',
    p_declared_cash_tips, p_declared_tip_out, p_declared_notes
  )
  ON CONFLICT (shift_id) WHERE review_status = 'pending'
  DO UPDATE SET
    declared_cash_tips = EXCLUDED.declared_cash_tips,
    declared_tip_out = EXCLUDED.declared_tip_out,
    declared_notes = EXCLUDED.declared_notes,
    review_status = 'submitted',
    updated_at = NOW()
  RETURNING id INTO v_review_id;

  RETURN json_build_object('success', true, 'review_id', v_review_id);
END;
$$;


--
-- Name: switch_location_atomic(text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.switch_location_atomic(p_token text, p_target_location_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
    v_staff_id uuid;
    v_org_id uuid;
    v_loc RECORD;
    v_membership RECORD;
    v_corr uuid;
    v_result jsonb;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    v_org_id := current_org_id();

    -- 1. Target location exists?
    SELECT * INTO v_loc FROM locations WHERE id = p_target_location_id;
    IF NOT FOUND THEN
        RAISE EXCEPTION 'Location not found: %', p_target_location_id;
    END IF;

    -- 2. Same organization?
    IF v_loc.organization_id != v_org_id THEN
        RAISE EXCEPTION 'Cannot switch to location in another organization';
    END IF;

    -- 3. Location ACTIVE?
    IF v_loc.status != 'ACTIVE' THEN
        RAISE EXCEPTION 'Cannot switch to % location (status: %)', v_loc.name, v_loc.status;
    END IF;

    -- 4. Staff has active membership?
    SELECT * INTO v_membership
    FROM staff_locations sl
    WHERE sl.staff_id = v_staff_id
      AND sl.location_id = p_target_location_id
      AND sl.active = true;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'Staff not assigned to location: %', v_loc.name;
    END IF;

    -- 5. Update session active_location_id
    UPDATE sessions SET active_location_id = p_target_location_id
    WHERE token = p_token AND expires_at > now() AND revoked_at IS NULL;

    -- 6. Update GUC
    PERFORM set_config('app.current_location_id', p_target_location_id::text, false);

    v_corr := gen_random_uuid();

    -- 7. Audit
    INSERT INTO operation_logs (entity_type, entity_id, operation, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('session', v_staff_id, 'location.switched',
            jsonb_build_object('location_id', p_target_location_id, 'location_name', v_loc.name, 'staff_id', v_staff_id),
            v_staff_id, v_corr, p_target_location_id, v_org_id);

    -- 8. Outbox
    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, metadata, status)
    VALUES ('session', v_staff_id, 'location.switched',
            jsonb_build_object('location_id', p_target_location_id, 'location_name', v_loc.name),
            jsonb_build_object('organization_id', v_org_id, 'actor_staff_id', v_staff_id, 'correlation_id', v_corr),
            'pending');

    -- 9. Return new context
    v_result := jsonb_build_object(
        'staff_id', v_staff_id,
        'organization_id', v_org_id,
        'active_location_id', p_target_location_id,
        'active_location_name', v_loc.name,
        'accessible_locations', (
            SELECT COALESCE(jsonb_agg(jsonb_build_object('id', l.id, 'name', l.name, 'code', l.code, 'status', l.status)), '[]'::jsonb)
            FROM staff_locations sl
            JOIN locations l ON l.id = sl.location_id
            WHERE sl.staff_id = v_staff_id AND sl.active = true AND l.organization_id = v_org_id
        )
    );

    RETURN v_result;
END;
$$;


--
-- Name: sync_operation(text, text, text, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_operation(p_client_id text, p_operation_id text, p_op_type text, p_payload jsonb, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_existing RECORD;
  v_result JSONB;
  v_performer_name TEXT;
BEGIN
  SELECT * INTO v_existing FROM public.operation_tracking
  WHERE client_id = p_client_id AND operation_id = p_operation_id;

  IF FOUND THEN
    IF v_existing.status = 'applied' THEN
      RETURN jsonb_build_object(
        'success', true, 'idempotent', true, 'status', 'applied',
        'result', v_existing.result, 'applied_at', v_existing.applied_at
      );
    ELSIF v_existing.status = 'rejected' THEN
      RETURN jsonb_build_object(
        'success', false, 'idempotent', true, 'status', 'rejected',
        'error', v_existing.error_message
      );
    ELSIF v_existing.status = 'conflict' THEN
      RETURN jsonb_build_object(
        'success', false, 'idempotent', true, 'status', 'conflict',
        'error', 'Operation conflicts with server state'
      );
    END IF;
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  CASE p_op_type
    WHEN 'add_to_cart' THEN
      v_result := jsonb_build_object('success', true, 'message', 'Client-side operation');

    WHEN 'update_cart' THEN
      v_result := jsonb_build_object('success', true, 'message', 'Client-side operation');

    WHEN 'payment' THEN
      IF p_payload IS NULL OR NOT (p_payload ? 'order_id') THEN
        v_result := jsonb_build_object('success', false, 'error', 'Missing order_id in payload');
        INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, error_message, performed_by)
        VALUES (p_client_id, p_operation_id, p_op_type, 'rejected', 'Missing order_id', p_performed_by)
        ON CONFLICT (client_id, operation_id) DO UPDATE SET status = 'rejected', error_message = 'Missing order_id';
        RETURN v_result;
      END IF;

      SELECT public.complete_payment_atomic(
        (p_payload->>'order_id')::uuid,
        COALESCE(p_payload->'payments', '[]'::jsonb),
        COALESCE(p_payload->>'payment_method', 'cash'),
        COALESCE((p_payload->>'cash_amount')::numeric, 0),
        COALESCE((p_payload->>'card_amount')::numeric, 0),
        COALESCE((p_payload->>'tip_amount')::numeric, 0),
        COALESCE((p_payload->>'discount_amount')::numeric, 0),
        (p_payload->>'discount_type')::text,
        p_performed_by,
        (p_payload->>'terminal_id')::text,
        (p_payload->>'cash_drawer_session_id')::uuid
      ) INTO v_result;

      INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, result, performed_by, applied_at)
      VALUES (p_client_id, p_operation_id, p_op_type,
        CASE WHEN (v_result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        v_result, p_performed_by, NOW())
      ON CONFLICT (client_id, operation_id) DO UPDATE SET
        status = CASE WHEN (EXCLUDED.result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        result = EXCLUDED.result,
        applied_at = NOW();

    WHEN 'refund' THEN
      IF p_payload IS NULL OR NOT (p_payload ? 'order_id') THEN
        v_result := jsonb_build_object('success', false, 'error', 'Missing order_id');
        INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, error_message, performed_by)
        VALUES (p_client_id, p_operation_id, p_op_type, 'rejected', 'Missing order_id', p_performed_by)
        ON CONFLICT (client_id, operation_id) DO UPDATE SET status = 'rejected', error_message = 'Missing order_id';
        RETURN v_result;
      END IF;

      SELECT public.complete_payment_atomic(
        (p_payload->>'order_id')::uuid,
        COALESCE(p_payload->'payments', '[]'::jsonb),
        COALESCE(p_payload->>'payment_method', 'cash'),
        0, 0, 0, 0, NULL,
        p_performed_by, NULL, NULL
      ) INTO v_result;

      INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, result, performed_by, applied_at)
      VALUES (p_client_id, p_operation_id, p_op_type,
        CASE WHEN (v_result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        v_result, p_performed_by, NOW())
      ON CONFLICT (client_id, operation_id) DO UPDATE SET
        status = CASE WHEN (EXCLUDED.result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        result = EXCLUDED.result,
        applied_at = NOW();

    WHEN 'cash_close' THEN
      IF p_payload IS NULL OR NOT (p_payload ? 'session_id') THEN
        v_result := jsonb_build_object('success', false, 'error', 'Missing session_id');
        INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, error_message, performed_by)
        VALUES (p_client_id, p_operation_id, p_op_type, 'rejected', 'Missing session_id', p_performed_by)
        ON CONFLICT (client_id, operation_id) DO UPDATE SET status = 'rejected', error_message = 'Missing session_id';
        RETURN v_result;
      END IF;

      SELECT public.close_cash_register_v2(
        (p_payload->>'session_id')::uuid,
        COALESCE((p_payload->>'actual_cash')::numeric, 0),
        (p_payload->>'notes')::text,
        (p_payload->>'manager_id')::uuid,
        p_performed_by
      ) INTO v_result;

      INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, result, performed_by, applied_at)
      VALUES (p_client_id, p_operation_id, p_op_type,
        CASE WHEN (v_result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        v_result, p_performed_by, NOW())
      ON CONFLICT (client_id, operation_id) DO UPDATE SET
        status = CASE WHEN (EXCLUDED.result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        result = EXCLUDED.result,
        applied_at = NOW();

    WHEN 'void' THEN
      IF p_payload IS NULL OR NOT (p_payload ? 'order_id') THEN
        v_result := jsonb_build_object('success', false, 'error', 'Missing order_id');
        INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, error_message, performed_by)
        VALUES (p_client_id, p_operation_id, p_op_type, 'rejected', 'Missing order_id', p_performed_by)
        ON CONFLICT (client_id, operation_id) DO UPDATE SET status = 'rejected', error_message = 'Missing order_id';
        RETURN v_result;
      END IF;

      UPDATE public.orders SET status = 'cancelled', updated_at = NOW()
      WHERE id = (p_payload->>'order_id')::uuid AND status NOT IN ('paid', 'cancelled');

      v_result := jsonb_build_object('success', true, 'order_id', p_payload->>'order_id');

      INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, result, performed_by, applied_at)
      VALUES (p_client_id, p_operation_id, p_op_type, 'applied', v_result, p_performed_by, NOW())
      ON CONFLICT (client_id, operation_id) DO UPDATE SET status = 'applied', result = EXCLUDED.result, applied_at = NOW();

    WHEN 'seat_table' THEN
      IF p_payload IS NULL OR NOT (p_payload ? 'table_number') THEN
        v_result := jsonb_build_object('success', false, 'error', 'Missing table_number');
        INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, error_message, performed_by)
        VALUES (p_client_id, p_operation_id, p_op_type, 'rejected', 'Missing table_number', p_performed_by)
        ON CONFLICT (client_id, operation_id) DO UPDATE SET status = 'rejected', error_message = 'Missing table_number';
        RETURN v_result;
      END IF;

      SELECT public.walkin_atomic(
        (p_payload->>'table_number')::integer,
        COALESCE((p_payload->>'guests')::integer, 1),
        (p_payload->>'name')::text,
        (p_payload->>'phone')::text,
        COALESCE((p_payload->>'order_type')::text, 'dine_in'),
        (p_payload->>'notes')::text,
        p_performed_by
      ) INTO v_result;

      INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, result, performed_by, applied_at)
      VALUES (p_client_id, p_operation_id, p_op_type,
        CASE WHEN (v_result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        v_result, p_performed_by, NOW())
      ON CONFLICT (client_id, operation_id) DO UPDATE SET
        status = CASE WHEN (EXCLUDED.result->>'success')::boolean THEN 'applied' ELSE 'rejected' END,
        result = EXCLUDED.result,
        applied_at = NOW();

    ELSE
      v_result := jsonb_build_object('success', false, 'error', 'Unknown operation type: ' || p_op_type);
      INSERT INTO public.operation_tracking (client_id, operation_id, op_type, status, error_message, performed_by)
      VALUES (p_client_id, p_operation_id, p_op_type, 'rejected', 'Unknown operation type', p_performed_by)
      ON CONFLICT (client_id, operation_id) DO UPDATE SET status = 'rejected', error_message = 'Unknown operation type';
  END CASE;

  PERFORM public.log_audit(
    'sync_' || p_op_type, 'operation', p_operation_id,
    p_performed_by, v_performer_name, NULL, v_result,
    jsonb_build_object('client_id', p_client_id, 'op_type', p_op_type), NULL
  );

  RETURN v_result;
END;
$$;


--
-- Name: sync_order_kitchen_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_order_kitchen_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_id UUID;
  v_new_status TEXT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    SELECT order_id INTO v_order_id FROM order_items WHERE id = OLD.id;
  ELSE
    v_order_id := NEW.order_id;
  END IF;
  IF v_order_id IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  WITH agg AS (
    SELECT
      count(*) FILTER (WHERE kitchen_status NOT IN ('cancelled','comped','wasted','recalled','voided')) AS active,
      count(*) FILTER (WHERE kitchen_status = 'served') AS served,
      count(*) FILTER (WHERE kitchen_status IN ('preparing','cooking','hot','bar','sushi')) AS production,
      count(*) FILTER (WHERE kitchen_status = 'ready')  AS ready,
      count(*) FILTER (WHERE kitchen_status IN ('pending','sent','reserved','accepted')) AS pre_cook,
      count(*) FILTER (WHERE kitchen_status = 'accepted') AS accepted,
      count(*) FILTER (WHERE kitchen_status = 'sent')     AS sent,
      count(*) FILTER (WHERE kitchen_status = 'pending')  AS pending,
      count(*) FILTER (WHERE kitchen_status = 'reserved') AS reserved,
      count(*) FILTER (WHERE kitchen_status = 'completed') AS completed
    FROM order_items
    WHERE order_id = v_order_id
  )
  SELECT CASE
    WHEN active = 0 THEN 'cancelled'
    WHEN served > 0 THEN 'served'
    WHEN ready > 0 AND (production > 0 OR pre_cook > 0) THEN 'partially_ready'
    WHEN production > 0 THEN 'preparing'
    WHEN ready > 0 THEN 'ready'
    WHEN accepted > 0 THEN 'accepted'
    WHEN sent > 0 THEN 'sent'
    WHEN pending > 0 THEN 'pending'
    WHEN reserved > 0 THEN 'reserved'
    WHEN completed = active THEN 'completed'
    ELSE 'cancelled'
  END
  INTO v_new_status
  FROM agg;

  UPDATE orders
  SET kitchen_status = v_new_status
  WHERE id = v_order_id
    AND status NOT IN ('paid', 'cancelled', 'closed');

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_table_floors_on_order_change(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_table_floors_on_order_change() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_new_table  int;
  v_old_table  int;
  v_terminal   text;
BEGIN
  IF TG_OP = 'INSERT' THEN
    v_new_table := NEW.table_number;
    v_old_table := NULL;
    v_terminal  := NEW.updated_by_terminal_id;
  ELSIF TG_OP = 'DELETE' THEN
    v_new_table := NULL;
    v_old_table := OLD.table_number;
    v_terminal  := OLD.updated_by_terminal_id;
  ELSE
    v_new_table := NEW.table_number;
    v_old_table := OLD.table_number;
    v_terminal  := COALESCE(NEW.updated_by_terminal_id, OLD.updated_by_terminal_id);
  END IF;

  IF v_new_table IS NULL AND v_old_table IS NULL THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  IF TG_OP = 'INSERT' OR TG_OP = 'DELETE' THEN
    IF v_new_table IS NOT NULL THEN PERFORM public.sync_table_order_aggregates(v_new_table, v_terminal); END IF;
    IF v_old_table IS NOT NULL AND v_old_table IS DISTINCT FROM v_new_table THEN
      PERFORM public.sync_table_order_aggregates(v_old_table, v_terminal);
    END IF;
  ELSE
    IF (NEW.status        IS DISTINCT FROM OLD.status)
       OR (NEW.total_amount  IS DISTINCT FROM OLD.total_amount)
       OR (NEW.guest_count   IS DISTINCT FROM OLD.guest_count)
       OR (NEW.table_number  IS DISTINCT FROM OLD.table_number)
       OR (NEW.merged_into   IS DISTINCT FROM OLD.merged_into)
       OR (NEW.kitchen_status IS DISTINCT FROM OLD.kitchen_status)
    THEN
      IF v_new_table IS NOT NULL THEN PERFORM public.sync_table_order_aggregates(v_new_table, v_terminal); END IF;
      IF v_new_table IS DISTINCT FROM v_old_table AND v_old_table IS NOT NULL THEN
        PERFORM public.sync_table_order_aggregates(v_old_table, v_terminal);
      END IF;
    END IF;
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_table_kitchen_status(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_table_kitchen_status() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order_id UUID;
  v_table_number INT;
  v_new_status TEXT;
  v_old_status TEXT;
  v_updated boolean;
BEGIN
  -- fire points: orders INSERT/UPDATE/DELETE (after cancel of broken item trigger)
  IF TG_TABLE_NAME = 'orders' THEN
    IF TG_OP = 'DELETE' THEN
      v_order_id := OLD.id;
      v_table_number := OLD.table_number;  -- row is gone; read directly from OLD
    ELSE
      v_order_id := NEW.id;
      v_table_number := NEW.table_number;
    END IF;
  ELSE
    v_order_id := COALESCE(NEW.order_id, OLD.order_id);
    IF v_order_id IS NULL THEN
      RETURN COALESCE(NEW, OLD);
    END IF;
    SELECT table_number INTO v_table_number FROM orders WHERE id = v_order_id;
  END IF;
  IF v_table_number IS NULL OR v_table_number <= 0 THEN
    RETURN COALESCE(NEW, OLD);
  END IF;

  SELECT kitchen_status INTO v_old_status
  FROM table_floors WHERE table_number = v_table_number;

  WITH oagg AS (
    SELECT
      count(*) AS active_order,
      count(*) FILTER (WHERE kitchen_status = 'served')        AS served,
      count(*) FILTER (WHERE kitchen_status = 'partially_ready') AS partially,
      count(*) FILTER (WHERE kitchen_status IN ('preparing','cooking')) AS prod,
      count(*) FILTER (WHERE kitchen_status = 'ready')         AS ready,
      count(*) FILTER (WHERE kitchen_status = 'accepted')      AS accepted,
      count(*) FILTER (WHERE kitchen_status = 'sent')          AS sent,
      count(*) FILTER (WHERE kitchen_status = 'pending')       AS pending,
      count(*) FILTER (WHERE kitchen_status = 'reserved')      AS reserved,
      count(*) FILTER (WHERE kitchen_status = 'completed')     AS completed
    FROM orders
    WHERE table_number = v_table_number
      AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
  )
  SELECT CASE
    WHEN active_order = 0 THEN 'completed'
    WHEN served > 0 THEN 'served'
    WHEN partially > 0 THEN 'partially_ready'
    WHEN ready > 0 AND (prod > 0 OR accepted+sent+pending > 0) THEN 'partially_ready'
    WHEN prod > 0 THEN 'preparing'
    WHEN ready > 0 THEN 'ready'
    WHEN accepted > 0 THEN 'accepted'
    WHEN sent > 0 THEN 'sent'
    WHEN pending > 0 THEN 'pending'
    WHEN reserved > 0 THEN 'reserved'
    WHEN completed = active_order THEN 'completed'
    ELSE 'pending'
  END
  INTO v_new_status
  FROM oagg;

  v_updated := false;
  IF NEW IS NOT NULL AND TG_TABLE_NAME = 'orders' THEN
    IF TG_OP = 'INSERT' THEN
      v_updated := true;
    ELSE
      SELECT EXISTS (SELECT 1 FROM orders o WHERE o.id = v_order_id)
        AND NOT EXISTS (SELECT 1 FROM orders o WHERE o.id = v_order_id AND o.kitchen_status = NEW.kitchen_status)
        INTO v_updated;
      -- orders UPDATE: refresh whenever any column the aggregation consumes changed
      IF NOT v_updated THEN
        v_updated := true; -- orders row updated → recompute table (cheap, idempotent)
      END IF;
    END IF;
  END IF;

  UPDATE table_floors
  SET kitchen_status = v_new_status,
      last_activity_at = now(),
      updated_at = now()
  WHERE table_number = v_table_number;

  -- E7: addproducer — table level event (consumers dedupe by outbox id)
  IF v_new_status IS DISTINCT FROM v_old_status THEN
    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
    VALUES ('table', gen_random_uuid(), 'table.kitchen_changed',
      jsonb_build_object('table_number', v_table_number,
        'kitchen_status', v_new_status,
        'previous_status', v_old_status,
        'location_id', (SELECT location_id FROM orders WHERE id = v_order_id),
        'order_ids', (SELECT COALESCE(jsonb_agg(id), '[]'::jsonb) FROM orders
                      WHERE table_number = v_table_number
                        AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided'))),
      'pending');
  END IF;

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: sync_table_order_aggregates(integer, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.sync_table_order_aggregates(p_table_number integer, p_updated_by_terminal_id text DEFAULT NULL::text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_d_total numeric;
  v_d_guest numeric;
  v_d_count int;
  v_d_pending boolean;
  v_d_oldest  timestamptz;
  v_cur       public.table_floors;
  v_agg_changed boolean;
  v_terminal_changed boolean;
  v_ptr uuid;
  v_ptr_to_write uuid;
  v_ptr_changed boolean;
BEGIN
  IF p_table_number IS NULL THEN
    RETURN;
  END IF;

  SELECT
    COALESCE(SUM(total_amount) FILTER (WHERE status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')), 0),
    COALESCE(SUM(guest_count)  FILTER (WHERE status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')), 0),
    COUNT(*) FILTER (WHERE status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')),
    EXISTS (SELECT 1 FROM public.orders
             WHERE table_number = p_table_number
               AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
               AND kitchen_status IN ('pending','reserved','sent','accepted','preparing','cooking','ready','partially_ready','served')),
    (SELECT MIN(updated_at) FROM public.orders
      WHERE table_number = p_table_number
        AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
        AND kitchen_status IN ('pending','reserved','sent','accepted','preparing','cooking','ready','partially_ready','served'))
  INTO v_d_total, v_d_guest, v_d_count, v_d_pending, v_d_oldest
  FROM public.orders
  WHERE table_number = p_table_number;

  SELECT * INTO v_cur FROM public.table_floors WHERE table_number = p_table_number FOR UPDATE;
  IF NOT FOUND THEN
    RETURN;
  END IF;

  -- F-05 (frozen): canonical pointer = latest OPEN order on (table, location);
  -- a stale/cancelled pointer never shadows a live open order; NULL if none.
  SELECT o.id INTO v_ptr FROM public.orders o
   WHERE o.table_number = p_table_number AND o.location_id = v_cur.location_id
     AND o.status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
   ORDER BY o.updated_at DESC, o.id DESC LIMIT 1;
  -- Guard-safe write: clearing to NULL is always allowed; setting a LIVE pointer
  -- is only allowed when the table is NOT in a released state (empty/cleaning) —
  -- table_release_guard (BEFORE trigger) forbids an active pointer on a released
  -- table. In the (rare) inconsistent case (released table + open order) we leave
  -- the pointer untouched and let the state machine reconcile it.
  IF v_ptr IS NULL THEN
    v_ptr_to_write := NULL;
  ELSIF v_cur.status IN ('empty','cleaning') THEN
    v_ptr_to_write := v_cur.current_order_id;
  ELSE
    v_ptr_to_write := v_ptr;
  END IF;
  v_ptr_changed := v_cur.current_order_id IS DISTINCT FROM v_ptr_to_write;

  v_agg_changed :=
       v_cur.total_amount        IS DISTINCT FROM v_d_total
    OR v_cur.guest_count         IS DISTINCT FROM v_d_guest
    OR v_cur.order_count         IS DISTINCT FROM v_d_count
    OR v_cur.has_pending         IS DISTINCT FROM v_d_pending
    OR v_cur.oldest_pending_at   IS DISTINCT FROM v_d_oldest;

  -- F-2: terminal provenance — write only when a concrete terminal is provided and
  -- differs from the current value. NULL never overwrites.
  v_terminal_changed :=
       p_updated_by_terminal_id IS NOT NULL
    AND v_cur.updated_by_terminal_id IS DISTINCT FROM p_updated_by_terminal_id;

  IF NOT v_agg_changed AND NOT v_terminal_changed AND NOT v_ptr_changed THEN
    RETURN;  -- no-op rule: no UPDATE, no version churn
  END IF;

  UPDATE public.table_floors SET
    current_order_id  = v_ptr_to_write,
    total_amount      = v_d_total,
    guest_count       = v_d_guest,
    order_count       = v_d_count,
    has_pending       = v_d_pending,
    oldest_pending_at = v_d_oldest,
    updated_at        = now(),
    updated_by_terminal_id = CASE
      WHEN p_updated_by_terminal_id IS NULL THEN updated_by_terminal_id
      ELSE p_updated_by_terminal_id
    END
  WHERE table_number = p_table_number;
END;
$$;


--
-- Name: table_archive_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.table_archive_guard() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE v_num int;
BEGIN
  v_num := OLD.table_number;
  RAISE EXCEPTION 'TABLE_ARCHIVE_ONLY: table % cannot be deleted; archive it instead (F-04)', v_num;
END;
$$;


--
-- Name: table_archived_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.table_archived_immutable() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  -- Block USE of an archived table (status/reservation/order-pointer/merge).
  -- The archive flag itself may flip (archive <-> unarchive, the floor editor's
  -- "re-add to plan" path); only using an archived table is forbidden.
  IF OLD.is_archived AND NOT (NEW.is_archived IS DISTINCT FROM OLD.is_archived) AND (
       NEW.status IS DISTINCT FROM OLD.status
    OR NEW.reservation_id IS DISTINCT FROM OLD.reservation_id
    OR NEW.current_order_id IS DISTINCT FROM OLD.current_order_id
    OR NEW.merged_into_table IS DISTINCT FROM OLD.merged_into_table
  ) THEN
    RAISE EXCEPTION 'TABLE_ARCHIVED: table % is archived and cannot be used (F-04)', OLD.table_number;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: table_release_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.table_release_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status IN ('empty','cleaning') THEN
    IF NEW.current_order_id IS NOT NULL THEN
      RAISE EXCEPTION 'TABLE_ORDER_POINTER_ACTIVE: table % cannot be released while it still points order %',
        NEW.table_number, NEW.current_order_id USING ERRCODE = 'P0001';
    END IF;
    IF EXISTS (
      SELECT 1 FROM public.orders o
      WHERE o.table_number = NEW.table_number
        AND o.status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
    ) THEN
      RAISE EXCEPTION 'TABLE_OPEN_ORDERS: table % cannot be empty while open orders exist; close/dismiss them first',
        NEW.table_number USING ERRCODE = 'P0001';
    END IF;
    NEW.kitchen_status := NULL;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: toggle_item_hold(uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_item_hold(p_item_id uuid, p_is_hold boolean, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item record;
BEGIN
  SELECT * INTO v_item FROM public.order_items WHERE id = p_item_id FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item not found');
  END IF;

  UPDATE public.order_items
  SET    is_hold = p_is_hold,
         hold_until = CASE WHEN p_is_hold THEN now() ELSE NULL END,
         updated_at = now()
  WHERE  id = p_item_id;

  PERFORM public.log_audit(
    'item_hold_toggled', v_item.order_id, p_item_id, p_performed_by,
    NULL, NULL, NULL, NULL,
    jsonb_build_object('is_hold', p_is_hold),
    NULL, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'item_id', p_item_id, 'is_hold', p_is_hold);
END;
$$;


--
-- Name: toggle_rush(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_rush(order_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE orders SET is_rush = NOT is_rush WHERE id = order_id;
END;
$$;


--
-- Name: toggle_staff_active(uuid, boolean, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.toggle_staff_active(p_staff_id uuid, p_is_active boolean, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff staff%ROWTYPE;
BEGIN
  SELECT * INTO v_staff FROM staff WHERE id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'STAFF_NOT_FOUND');
  END IF;

  UPDATE staff SET is_active = p_is_active WHERE id = p_staff_id;

  IF NOT p_is_active THEN
    UPDATE sessions SET revoked_at = now() WHERE user_id = p_staff_id AND revoked_at IS NULL;
  END IF;

  PERFORM log_audit(
    CASE WHEN p_is_active THEN 'staff_enabled' ELSE 'staff_disabled' END,
    'staff', p_staff_id::text, p_performed_by,
    jsonb_build_object('is_active', v_staff.is_active),
    jsonb_build_object('is_active', p_is_active),
    NULL, NULL, NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'staff_id', p_staff_id,
    'is_active', p_is_active
  );
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: touch_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.touch_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
begin
  new.updated_at = now();
  return new;
end;
$$;


--
-- Name: transfer_orders_atomic(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_orders_atomic(p_from_table integer, p_to_table integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_floor RECORD;
  v_orders RECORD;
  v_order_ids UUID[];
  v_moved_count INTEGER := 0;
BEGIN
  -- Lock target table floor (prevent race on "is it empty?")
  SELECT * INTO v_target_floor
  FROM table_floors
  WHERE table_number = p_to_table
  FOR UPDATE;

  IF v_target_floor.status = 'reserved' THEN
    RAISE EXCEPTION 'TARGET_TABLE_RESERVED' USING ERRCODE = 'P0001';
  END IF;
  IF v_target_floor.status = 'occupied' THEN
    RAISE EXCEPTION 'TARGET_TABLE_OCCUPIED' USING ERRCODE = 'P0001';
  END IF;

  -- Lock all source orders
  FOR v_orders IN
    SELECT id, guest_count FROM orders
    WHERE table_number = p_from_table AND status NOT IN ('paid', 'cancelled', 'closed')
    FOR UPDATE
  LOOP
    v_order_ids := array_append(v_order_ids, v_orders.id);
  END LOOP;

  IF array_length(v_order_ids, 1) IS NULL THEN
    RAISE EXCEPTION 'NO_ACTIVE_ORDERS' USING ERRCODE = 'P0001';
  END IF;

  -- Move orders to new table
  UPDATE orders
  SET table_number = p_to_table, version = COALESCE(version, 0) + 1, updated_at = now()
  WHERE id = ANY(v_order_ids);

  v_moved_count := array_length(v_order_ids, 1);

  -- Clear source table floor
  UPDATE table_floors
  SET
    status = 'empty',
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    guest_count = NULL,
    merged_into_table = NULL
  WHERE table_number = p_from_table;

  -- Transfer reservation data to target table floor
  UPDATE table_floors
  SET
    status = 'occupied',
    guest_count = (SELECT COALESCE(SUM(guest_count), 0) FROM orders WHERE id = ANY(v_order_ids))
  WHERE table_number = p_to_table;

  -- Audit
  INSERT INTO audit_log (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'orders',
    v_order_ids[1],
    'transfer',
    jsonb_build_object('from', p_from_table, 'to', p_to_table),
    jsonb_build_object('order_ids', v_order_ids, 'moved_count', v_moved_count),
    p_performed_by,
    now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'from_table', p_from_table,
    'to_table', p_to_table,
    'moved_count', v_moved_count,
    'order_ids', v_order_ids
  );
END;
$$;


--
-- Name: transfer_seat_items(uuid, integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_seat_items(p_order_id uuid, p_from_seat integer, p_to_seat integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_updated INTEGER := 0;
BEGIN
  UPDATE order_items
  SET seat_number = p_to_seat
  WHERE order_id = p_order_id
    AND seat_number = p_from_seat
    AND kitchen_status NOT IN ('cancelled', 'served');

  GET DIAGNOSTICS v_updated = ROW_COUNT;

  PERFORM log_order_event(
    p_order_id, 'seat_changed',
    jsonb_build_object('from_seat', p_from_seat),
    jsonb_build_object('to_seat', p_to_seat, 'items_moved', v_updated),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'items_moved', v_updated);
END;
$$;


--
-- Name: transfer_table_atomic(text, integer, integer, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_table_atomic(p_token text, p_from_table integer, p_to_table integer, p_performed_by uuid, p_performed_by_terminal_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_from   RECORD;
  v_to     RECORD;
  v_order  orders;
  v_first  int;
  v_second int;
  v_lock   RECORD;
  v_active int;
  v_paid   int;
  v_total  numeric;
  v_guests int;
  v_old_state jsonb;
BEGIN
  PERFORM public.set_session_staff(p_token);
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  PERFORM public.validate_actor(p_performed_by);
  IF p_from_table = p_to_table THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_SAME_TABLE');
  END IF;

  -- Q4: lock both floors in deterministic (ascending) order — crossed
  -- transfers X->Y and Y->X now serialize instead of deadlocking.
  IF p_from_table < p_to_table THEN
    v_first := p_from_table; v_second := p_to_table;
  ELSE
    v_first := p_to_table;   v_second := p_from_table;
  END IF;
  FOR v_lock IN SELECT * FROM public.table_floors
                WHERE table_number IN (v_first, v_second)
                ORDER BY table_number FOR UPDATE LOOP
    NULL;
  END LOOP;
  IF (SELECT count(*) FROM public.table_floors
      WHERE table_number IN (p_from_table, p_to_table)) <> 2 THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  SELECT * INTO v_from FROM public.table_floors WHERE table_number = p_from_table AND (v_sess_loc IS NULL OR location_id = v_sess_loc);
  SELECT * INTO v_to   FROM public.table_floors WHERE table_number = p_to_table AND (v_sess_loc IS NULL OR location_id = v_sess_loc);
  IF NOT (has_location_access(v_from.location_id) AND has_location_access(v_to.location_id)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;

  IF v_from.location_id IS DISTINCT FROM v_to.location_id
     OR v_from.organization_id IS DISTINCT FROM v_to.organization_id THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_LOCATION_MISMATCH');
  END IF;

  -- Q2: a table that is a merge PARENT cannot transfer its order away
  -- (would leave the merged children + stale lineage dangling — T-2)
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE merged_into_table = p_from_table) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_SOURCE_HAS_MERGED_CHILDREN');
  END IF;
  -- Q3: cannot transfer into a merge PARENT (children would dangle on an
  -- occupied table — T-3)
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE merged_into_table = p_to_table) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_TARGET_HAS_MERGED_CHILDREN');
  END IF;

  IF v_from.merged_into_table IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_SOURCE_MERGED');
  END IF;
  IF v_from.reservation_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_SOURCE_RESERVED');
  END IF;
  IF v_to.status NOT IN ('empty','dirty') OR v_to.current_order_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_TARGET_OCCUPIED');
  END IF;
  IF v_to.reservation_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_TARGET_RESERVED');
  END IF;

  SELECT count(*) INTO v_active FROM public.orders
   WHERE table_number = p_from_table AND location_id = v_from.location_id
     AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided');
  IF v_active = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_NO_ACTIVE_ORDER');
  END IF;
  IF v_active > 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_MULTIPLE_ORDERS');
  END IF;

  SELECT * INTO v_order FROM public.orders
   WHERE table_number = p_from_table
     AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
   ORDER BY created_at ASC LIMIT 1;

  SELECT count(*) INTO v_paid FROM public.payments
   WHERE order_id = v_order.id AND status IN ('captured','pending');
  IF v_paid > 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_TRANSFER_ORDER_PAID');
  END IF;

  SELECT COALESCE(sum(total_amount),0), COALESCE(sum(guest_count),0)
    INTO v_total, v_guests
   FROM public.orders
   WHERE table_number = p_from_table
     AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided');

  v_old_state := jsonb_build_object('status', v_from.status, 'order_status', v_order.status,
    'guest_count', v_order.guest_count, 'total_amount', v_order.total_amount);

  -- order ownership moves first (orders.table_number is SSOT);
  -- clear_stale_table_order_pointer auto-clears the source floor pointer.
  UPDATE public.orders SET
    table_number = p_to_table,
    updated_at = now(),
    version = COALESCE(version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = v_order.id;

  -- Q5: kitchen schedule parity (merge/unmerge already keep it in sync)
  UPDATE public.kitchen_schedule SET
    table_number = p_to_table, updated_at = now()
  WHERE order_id = v_order.id;

  UPDATE public.table_floors SET
    status = 'occupied',
    current_order_id = v_order.id,
    guest_count = v_guests,
    total_amount = v_total,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    bill_requested = false,
    updated_at = now(),
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE table_number = p_to_table;

  UPDATE public.table_floors SET
    status = 'empty',
    current_order_id = NULL,
    guest_count = NULL,
    total_amount = 0,
    order_count = 0,
    has_pending = false,
    oldest_pending_at = NULL,
    bill_requested = false,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    updated_at = now(),
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE table_number = p_from_table;

  PERFORM public.sync_table_order_aggregates(p_to_table);
  PERFORM public.sync_table_order_aggregates(p_from_table);

  PERFORM public.g_table_audit(
    'transfer_table', 'table.order_transferred',
    p_from_table, v_from.id, v_order.id,
    v_old_state,
    jsonb_build_object('status','occupied','order_id',v_order.id,'guest_count',v_guests,'total_amount',v_total),
    p_performed_by, p_performed_by_terminal_id, 'contract-transfer-v2',
    p_from_table, p_to_table, v_from.location_id, v_from.organization_id);

  RETURN jsonb_build_object('success', true, 'order_id', v_order.id, 'to_table', p_to_table);
END;
$$;


--
-- Name: transfer_table_session(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_table_session(p_from_table_number integer, p_to_table_number integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from_table RECORD;
  v_to_table RECORD;
  v_order RECORD;
  v_result JSONB;
BEGIN
  -- Lock both tables
  SELECT * INTO v_from_table FROM table_floors WHERE table_number = p_from_table_number FOR UPDATE;
  SELECT * INTO v_to_table FROM table_floors WHERE table_number = p_to_table_number FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'FROM_TABLE_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TO_TABLE_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- Move active orders from source to target
  UPDATE orders
  SET table_number = p_to_table_number,
      updated_at = now()
  WHERE table_number = p_from_table_number
    AND status NOT IN ('paid', 'cancelled');

  -- Merge cart items from from-table into to-table (if to-table has existing order)
  -- If to-table has no active order, create draft order from from-table's data

  -- Mark source table as empty
  UPDATE table_floors
  SET status = 'empty',
      reservation_id = NULL,
      reservation_name = NULL,
      reservation_phone = NULL,
      reservation_time = NULL,
      guest_count = NULL,
      total_amount = 0,
      order_count = 0,
      order_ids = '{}'::TEXT[],
      has_pending = false,
      oldest_pending_at = NULL,
      opened_at = NULL,
      merged_into_table = NULL,
      merged_orders = '[]'::JSONB,
      updated_at = now()
  WHERE table_number = p_from_table_number;

  -- Update target table to occupied if not already
  UPDATE table_floors
  SET status = 'occupied',
      updated_at = now()
  WHERE table_number = p_to_table_number
    AND status = 'empty';

  v_result := jsonb_build_object(
    'success', true,
    'from_table', p_from_table_number,
    'to_table', p_to_table_number
  );

  RETURN v_result;
END;
$$;


--
-- Name: transfer_table_v4(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_table_v4(p_from_table integer, p_to_table integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_status TEXT;
BEGIN
  -- Validate target
  SELECT status INTO v_target_status FROM table_floors WHERE table_number = p_to_table FOR UPDATE;
  IF v_target_status != 'empty' THEN
    RAISE EXCEPTION 'TARGET_TABLE_NOT_EMPTY' USING ERRCODE = 'P0001';
  END IF;

  -- Move Orders
  UPDATE orders SET table_number = p_to_table 
  WHERE table_number = p_from_table AND status = 'confirmed';

  -- Sync Floors
  UPDATE table_floors SET status = 'empty', merged_into_table = NULL WHERE table_number = p_from_table;
  UPDATE table_floors SET status = 'occupied' WHERE table_number = p_to_table;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: transfer_tables_v3(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transfer_tables_v3(p_from_table integer, p_to_table integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_target_status TEXT;
  v_order_ids UUID[];
  v_total_amount NUMERIC := 0;
  v_total_guests INTEGER := 0;
BEGIN
  -- Validate target
  SELECT status INTO v_target_status FROM table_floors WHERE table_number = p_to_table FOR UPDATE;
  IF v_target_status != 'empty' THEN
    RAISE EXCEPTION 'TARGET_TABLE_NOT_EMPTY' USING ERRCODE = 'P0001';
  END IF;

  -- Collect orders
  SELECT array_agg(id), SUM(total_amount), SUM(guest_count) 
  INTO v_order_ids, v_total_amount, v_total_guests
  FROM orders 
  WHERE table_number = p_from_table AND status NOT IN ('paid', 'cancelled', 'closed')
  FOR UPDATE;

  IF v_order_ids IS NULL THEN
    RAISE EXCEPTION 'SOURCE_TABLE_EMPTY' USING ERRCODE = 'P0001';
  END IF;

  -- Update orders
  UPDATE orders SET table_number = p_to_table, updated_at = now() WHERE id = ANY(v_order_ids);

  -- Update floors
  UPDATE table_floors SET 
    status = 'empty', guest_count = NULL, total_amount = 0, merged_into_table = NULL 
  WHERE table_number = p_from_table;

  UPDATE table_floors SET 
    status = 'occupied', guest_count = v_total_guests, total_amount = v_total_amount 
  WHERE table_number = p_to_table;

  RETURN jsonb_build_object('success', true, 'order_ids', v_order_ids);
END;
$$;


--
-- Name: transition_delivery_status(text, uuid, text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_delivery_status(p_token text, p_order_id uuid, p_new_status text, p_courier_id uuid, p_courier_name text, p_performed_by_terminal_id text, p_metadata jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_validation jsonb;
  v_old_delivery_status TEXT;
  v_staff_id uuid;
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();
  IF v_staff_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  v_old_delivery_status := COALESCE(v_order.delivery_status, 'pending');

  v_validation := validate_transition('delivery', v_old_delivery_status, p_new_status);
  IF NOT (v_validation->>'valid')::BOOLEAN THEN
    RETURN jsonb_build_object('success', false, 'error', v_validation->>'error');
  END IF;

  UPDATE public.orders SET
    delivery_status = p_new_status,
    delivered_at = CASE WHEN p_new_status = 'delivered' THEN NOW() ELSE delivered_at END,
    courier_id = p_courier_id,
    courier_name = p_courier_name,
    updated_at = NOW(),
    version = COALESCE(v_order.version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = p_order_id;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, p_order_id, 'transition_delivery_status',
    jsonb_build_object('delivery_status', v_old_delivery_status, 'courier_id', v_order.courier_id, 'courier_name', v_order.courier_name),
    jsonb_build_object('delivery_status', p_new_status, 'courier_id', p_courier_id, 'courier_name', p_courier_name),
    v_staff_id
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'old_delivery_status', v_old_delivery_status,
    'new_delivery_status', p_new_status
  );
END;
$$;


--
-- Name: transition_order_atomic(text, uuid, text, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_order_atomic(p_token text, p_order_id uuid, p_new_status text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_allowed jsonb;
  v_rule jsonb;
  v_order RECORD;
  v_old_status text;
  v_old_kitchen text;
  v_staff_id uuid;
  v_table_number int;
  v_current_table_status text;
  v_approver_key text;
  v_has_approver boolean := false;
  v_overr boolean := false;
BEGIN
  -- 1. AUTH (identity ONLY from the session token)
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  -- 2. Lock order
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE='P0001';
  END IF;
  -- P-5 (D-1a, ratified 2026-09-13): payment-state targets are owned by the
  -- payment RPCs (complete_payment_atomic_v2 / refund_with_inventory), which
  -- atomically create the order_payments record. A generic transition to a
  -- payment state would leave the order paid/refunded with NO payment record.
  IF p_new_status IN ('paid','refunded','partially_refunded')
     AND p_new_status IS DISTINCT FROM v_order.status THEN
    RAISE EXCEPTION 'PAYMENT_STATE_FORBIDDEN: % -> % must go through the payment RPCs (complete_payment_atomic_v2 / refund_with_inventory); this path creates no order_payments record [order=%]', v_order.status, p_new_status, p_order_id USING ERRCODE='P0001';
  END IF;

  v_old_status  := v_order.status;
  v_old_kitchen := v_order.kitchen_status;
  v_table_number := v_order.table_number;

  IF v_old_status IS DISTINCT FROM p_new_status THEN
    -- 3. TRANSITION VALIDATION (registry = source of truth)
    v_rule := validate_transition('order', v_old_status, p_new_status);
    IF NOT (v_rule->>'valid')::boolean THEN
      RAISE EXCEPTION 'INVALID_TRANSITION: %', v_rule->>'error' USING ERRCODE='P0001';
    END IF;

    -- 4. AUTHORIZATION (session + staff + org + location-scope permission)
    v_allowed := authorize(
      p_token,
      COALESCE(v_rule->>'requires_permission', 'orders.edit'),
      v_order.location_id
    );
    IF NOT (v_allowed->>'allowed')::boolean THEN
      RAISE EXCEPTION 'PERMISSION_DENIED: % → % requires [%] at location % (reason: %)',
        v_old_status, p_new_status,
        COALESCE(v_rule->>'requires_permission','orders.edit'),
        v_order.location_id, v_allowed->>'reason' USING ERRCODE='P0001';
    END IF;

    -- 5. MANAGER OVERRIDE GATE
    IF COALESCE(v_rule->>'requires_manager_override','false')::boolean THEN
      v_approver_key := CASE WHEN COALESCE(v_rule->>'requires_permission','') LIKE '%refund%'
                             THEN 'refund.approve' ELSE 'void.approve' END;
      v_has_approver := COALESCE((SELECT has_permission(v_staff_id, v_approver_key)), false);
      IF NOT v_has_approver THEN
        SELECT EXISTS(
          SELECT 1 FROM manager_overrides mo
          WHERE mo.requested_by = v_staff_id
            AND mo.permission = COALESCE(v_rule->>'requires_permission','orders.edit')
            AND mo.location_id = v_order.location_id
            AND mo.status = 'APPROVED'
            AND mo.expires_at > now()
        ) INTO v_overr;
        IF NOT v_overr THEN
          RAISE EXCEPTION 'MANAGER_OVERRIDE_REQUIRED: % → % (approver perm [%])',
            v_old_status, p_new_status, v_approver_key USING ERRCODE='P0001';
        END IF;
      END IF;
    END IF;

    -- 6. ATOMIC UPDATE (guard trigger re-validates + sets canonical timestamps)
    UPDATE orders SET
      status = p_new_status,
      version = COALESCE(version, 0) + 1,
      updated_at = now()
    WHERE id = p_order_id;

    -- 6a. kitchen_status sync (parity with the pre-G1 live path)
    CASE p_new_status
      WHEN 'in_kitchen' THEN
        UPDATE orders SET kitchen_status = 'preparing' WHERE id = p_order_id AND kitchen_status IS DISTINCT FROM 'preparing';
      WHEN 'ready' THEN
        UPDATE orders SET kitchen_status = 'ready' WHERE id = p_order_id;
      WHEN 'served' THEN
        UPDATE orders SET kitchen_status = 'completed' WHERE id = p_order_id;
      WHEN 'paid','closed' THEN
        UPDATE orders SET kitchen_status = 'completed' WHERE id = p_order_id AND kitchen_status NOT IN ('completed','cancelled');
      WHEN 'cancelled' THEN
        UPDATE orders SET kitchen_status = 'cancelled' WHERE id = p_order_id AND kitchen_status IS DISTINCT FROM 'cancelled';
      ELSE NULL;
    END CASE;

    -- 6b. kitchen_schedule parity
    IF p_new_status IN ('paid','closed','cancelled') THEN
      DELETE FROM public.kitchen_schedule WHERE order_id = p_order_id;
    ELSIF p_new_status = 'in_kitchen' THEN
      INSERT INTO public.kitchen_schedule (order_id, table_number, status, created_at, updated_at)
      SELECT p_order_id, v_table_number, 'preparing', NOW(), NOW()
      WHERE v_table_number IS NOT NULL
        AND NOT EXISTS (SELECT 1 FROM public.kitchen_schedule WHERE order_id = p_order_id);
    END IF;

    -- 6c. floor sync (L5/A, 2026-09-12, ratified): the table lifecycle is
    --     exactly empty / occupied / reserved. An active meal — including
    --     paid — KEEPS the table occupied (PAID+OCCUPIED is valid; kitchen/
    --     service progress lives in orders/order_items.kitchen_status +
    --     table.kitchen_status, never table.status). The ONLY transition this
    --     block performs is terminal cancellation freeing the table, and only
    --     when no other open order remains on this (table, location).
    --     'closed' is released by release_paid_table_atomic (explicit UI
    --     departure action) — never auto-emptied here.
    IF v_table_number IS NOT NULL AND v_table_number > 0 THEN
      IF p_new_status = 'cancelled' THEN
        SELECT status INTO v_current_table_status FROM table_floors
         WHERE table_number = v_table_number AND location_id = v_order.location_id FOR UPDATE;
        IF v_current_table_status = 'occupied'
           AND NOT EXISTS (SELECT 1 FROM orders o2
                           WHERE o2.table_number = v_table_number
                             AND o2.location_id = v_order.location_id
                             AND o2.status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided'))
        THEN
          -- Guarded: table_release_guard (BEFORE trigger on table_floors)
          -- re-validates no-active-pointer / no-open-orders for the empty state.
          UPDATE table_floors SET
            status = 'empty',
            current_order_id = NULL,
            total_amount = 0,
            guest_count = NULL,
            order_count = 0,
            has_pending = false,
            oldest_pending_at = NULL,
            bill_requested = false,
            updated_at = now()
          WHERE table_number = v_table_number AND location_id = v_order.location_id;
          PERFORM public.sync_table_order_aggregates(v_table_number);
        END IF;
      END IF;
    END IF;
  END IF;

  -- 7. AUDIT + 8. OUTBOX (only when status actually changed)
  IF v_old_status IS DISTINCT FROM p_new_status THEN
    PERFORM log_order_event(
      p_order_id, 'status_changed',
      jsonb_build_object('status', v_old_status, 'kitchen_status', v_old_kitchen),
      jsonb_build_object('status', p_new_status, 'kitchen_status',
        (SELECT kitchen_status FROM orders WHERE id = p_order_id),
        'reason', p_reason),
      COALESCE(p_metadata, '{}'::jsonb),
      v_staff_id, NULL, NULL, NULL
    );

    INSERT INTO audit_logs (table_name, record_id, action, old_data, new_data, performed_by, created_at)
    VALUES ('orders', p_order_id, 'order.transition',
      jsonb_build_object('status', v_old_status),
      jsonb_build_object('status', p_new_status, 'reason', p_reason),
      v_staff_id, now());

    INSERT INTO operation_logs (operation, order_id, performed_by, reason, old_state, new_state,
                                location_id, organization_id, metadata)
    VALUES ('order.transition', p_order_id, v_staff_id, p_reason,
      jsonb_build_object('status', v_old_status),
      jsonb_build_object('status', p_new_status),
      v_order.location_id, v_order.organization_id,
      jsonb_build_object('reopened', p_new_status IN ('new','open','confirmed','in_kitchen') AND v_old_status NOT IN ('new','open','confirmed','in_kitchen')));

    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
    VALUES ('order', p_order_id, 'order.status_changed',
      jsonb_build_object('old_status', v_old_status, 'new_status', p_new_status,
                         'reason', p_reason, 'performed_by', v_staff_id),
      'pending');
  END IF;

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'old_status', v_old_status,
    'new_status', p_new_status,
    'kitchen_status', (SELECT kitchen_status FROM orders WHERE id = p_order_id)
  );
END;
$$;


--
-- Name: transition_order_status_validated(uuid, text, uuid, text, text, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_order_status_validated(p_order_id uuid, p_new_status text, p_performed_by uuid DEFAULT NULL::uuid, p_employee_name text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_ip_address text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_validation JSONB;
  v_old_status TEXT;
  v_old_kitchen_status TEXT;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  IF v_order.order_source IS NOT NULL AND v_order.order_source NOT IN ('dine_in', 'takeaway', 'delivery') THEN
    RAISE EXCEPTION 'INVALID_ORDER_SOURCE: %', v_order.order_source USING ERRCODE = 'P0001';
  END IF;

  v_old_status := v_order.status;
  v_old_kitchen_status := v_order.kitchen_status;

  v_validation := validate_transition('order', v_old_status, p_new_status);
  IF NOT (v_validation->>'valid')::BOOLEAN THEN
    RAISE EXCEPTION 'INVALID_TRANSITION: %', v_validation->>'error' USING ERRCODE = 'P0001';
  END IF;

  UPDATE orders SET
    status = p_new_status,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  CASE p_new_status
    WHEN 'in_kitchen' THEN
      UPDATE orders SET kitchen_status = 'preparing' WHERE id = p_order_id AND kitchen_status IS DISTINCT FROM 'preparing';
    WHEN 'ready' THEN
      UPDATE orders SET kitchen_status = 'ready' WHERE id = p_order_id;
    WHEN 'served' THEN
      UPDATE orders SET kitchen_status = 'completed' WHERE id = p_order_id;
    WHEN 'paid', 'closed' THEN
      UPDATE orders SET kitchen_status = 'completed' WHERE id = p_order_id
        AND kitchen_status NOT IN ('completed', 'cancelled');
    WHEN 'cancelled' THEN
      UPDATE orders SET kitchen_status = 'cancelled' WHERE id = p_order_id
        AND kitchen_status NOT IN ('cancelled');
    ELSE NULL;
  END CASE;

  IF p_new_status IN ('paid', 'closed', 'cancelled') THEN
    DELETE FROM public.kitchen_schedule WHERE order_id = p_order_id;
  ELSIF p_new_status = 'in_kitchen' THEN
    INSERT INTO public.kitchen_schedule (order_id, table_number, status, created_at, updated_at)
    SELECT p_order_id, v_order.table_number, 'preparing', NOW(), NOW()
    WHERE NOT EXISTS (SELECT 1 FROM public.kitchen_schedule WHERE order_id = p_order_id);
  END IF;

  PERFORM log_order_event(
    p_order_id,
    'status_changed',
    jsonb_build_object('status', v_old_status, 'kitchen_status', v_old_kitchen_status),
    jsonb_build_object('status', p_new_status, 'kitchen_status', (SELECT kitchen_status FROM orders WHERE id = p_order_id)),
    p_metadata,
    p_performed_by,
    p_employee_name,
    p_ip_address,
    p_device_id
  );

  INSERT INTO audit_logs (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'orders', p_order_id, 'status_change',
    jsonb_build_object('status', v_old_status),
    jsonb_build_object('status', p_new_status, 'reason', p_reason),
    p_performed_by, now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'order_id', p_order_id,
    'old_status', v_old_status,
    'new_status', p_new_status,
    'kitchen_status', (SELECT kitchen_status FROM orders WHERE id = p_order_id)
  );
END;
$$;


--
-- Name: transition_table_status(integer, text, uuid, text, text, jsonb, jsonb, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.transition_table_status(p_table_number integer, p_new_status text, p_performed_by uuid DEFAULT NULL::uuid, p_employee_name text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb, p_undo_payload jsonb DEFAULT NULL::jsonb, p_ip_address text DEFAULT NULL::text, p_device_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table RECORD;
  v_validation JSONB;
  v_old_status TEXT;
BEGIN
  -- 1. Lock and fetch table
  SELECT * INTO v_table FROM table_floors WHERE table_number = p_table_number FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  v_old_status := v_table.status;

  -- 2. Validate transition
  v_validation := validate_transition('table', v_old_status, p_new_status);
  IF NOT (v_validation->>'valid')::BOOLEAN THEN
    RAISE EXCEPTION 'INVALID_TRANSITION: %', v_validation->>'error' USING ERRCODE = 'P0001';
  END IF;

  -- 3. Apply transition
  UPDATE table_floors SET
    status = p_new_status,
    updated_at = now()
  WHERE table_number = p_table_number;

  -- 4. Clear reservation data when table becomes empty
  IF p_new_status = 'empty' THEN
    UPDATE table_floors SET
      reservation_id = NULL,
      reservation_name = NULL,
      reservation_phone = NULL,
      reservation_time = NULL,
      bill_requested = false
    WHERE table_number = p_table_number;
  END IF;

  -- 5. Log operation
  PERFORM log_operation(
    'status_change',
    NULL,
    p_table_number,
    NULL,
    jsonb_build_object('status', v_old_status),
    jsonb_build_object('status', p_new_status, 'reason', p_reason),
    p_undo_payload,
    p_performed_by,
    p_employee_name,
    p_reason,
    p_ip_address,
    p_device_id
  );

  -- 6. Audit log
  INSERT INTO audit_logs (table_name, record_id, action, old_data, new_data, performed_by, created_at)
  VALUES (
    'table_floors', v_table.id, 'status_change',
    jsonb_build_object('status', v_old_status, 'table_number', p_table_number),
    jsonb_build_object('status', p_new_status, 'reason', p_reason),
    p_performed_by, now()
  );

  RETURN jsonb_build_object(
    'success', true,
    'table_number', p_table_number,
    'old_status', v_old_status,
    'new_status', p_new_status
  );
END;
$$;


--
-- Name: trg_apply_inventory_effect(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_apply_inventory_effect() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_signed_qty numeric;
  v_fate_waste boolean := false;
BEGIN
  -- H10.1 (P0-1): an order-context 'waste' row is a fate/status record for
  -- stock that was ALREADY deducted by order_consumption at READY.
  -- It must not move stock a second time. Supplier-return / standalone waste
  -- rows (order_item_id IS NULL) keep their -quantity effect.
  v_fate_waste := (NEW.type = 'waste' AND NEW.order_item_id IS NOT NULL);

  IF v_fate_waste THEN
    v_signed_qty := NULL;
  ELSIF NEW.type = 'stock_in' THEN
    v_signed_qty := NEW.quantity;
  ELSIF NEW.type IN ('order_consumption', 'waste') THEN
    v_signed_qty := -NEW.quantity;
  ELSIF NEW.type IN ('reversal', 'stock_return', 'order_restore') THEN
    v_signed_qty := NEW.quantity;
  ELSIF NEW.type = 'adjustment' THEN
    v_signed_qty := NEW.quantity;
  ELSIF NEW.type = 'historical_repair' THEN
    v_signed_qty := NEW.quantity;
  ELSE
    v_signed_qty := NULL;
  END IF;

  IF v_signed_qty IS NOT NULL THEN
    UPDATE ingredients
    SET current_stock = COALESCE(current_stock, 0) + v_signed_qty,
        updated_at    = now()
    WHERE id = NEW.ingredient_id;
  END IF;

  -- theoretical_stock: adjustment is set by the audit/stock-count function
  -- (counted actual), never here. historical_repair does NOT move
  -- theoretical_stock — it is the reconciliation target.
  -- Order-context waste (fate record, v_fate_waste) must not move it either.
  IF NOT v_fate_waste AND NEW.type IN ('stock_in','order_consumption','waste','reversal',
                  'stock_return','order_restore') THEN
    UPDATE ingredients
    SET theoretical_stock = COALESCE(theoretical_stock, 0) + v_signed_qty,
        updated_at        = now()
    WHERE id = NEW.ingredient_id;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_inventory_logs_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_inventory_logs_immutable() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'public'
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' THEN
    RAISE EXCEPTION 'inventory_logs is immutable: UPDATE forbidden (ledger id %)', OLD.id;
  ELSIF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'inventory_logs is immutable: DELETE forbidden (ledger id %)', OLD.id;
  END IF;
  RETURN NULL;
END;
$$;


--
-- Name: trg_item_money_lock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_item_money_lock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_locked boolean;
BEGIN
  v_locked := COALESCE(NEW.kitchen_status, OLD.kitchen_status) IN
              ('sent','accepted','preparing','ready','served','completed');

  -- void/cancel/waste/comp zeroing in same UPDATE is legal
  IF OLD.kitchen_status IS DISTINCT FROM NEW.kitchen_status
     AND NEW.kitchen_status IN ('voided','cancelled','wasted','comped') THEN
    RETURN NEW;
  END IF;

  IF NOT v_locked THEN
    RETURN NEW;
  END IF;

  IF COALESCE(current_setting('app.order_item_money_bypass', true), '') = 'true' THEN
    RETURN NEW;
  END IF;

  IF NEW.unit_price IS DISTINCT FROM OLD.unit_price THEN
    RAISE EXCEPTION 'ITEM_PRICE_FROZEN: cannot change unit_price in state % (use void + re-add)',
      COALESCE(NEW.kitchen_status, '') USING ERRCODE = 'P0001';
  END IF;
  IF NEW.price_snapshot IS DISTINCT FROM OLD.price_snapshot THEN
    RAISE EXCEPTION 'ITEM_SNAPSHOT_FROZEN: price_snapshot immutable in state %',
      COALESCE(NEW.kitchen_status, '') USING ERRCODE = 'P0001';
  END IF;
  IF NEW.tax_rate IS DISTINCT FROM OLD.tax_rate OR NEW.tax_amount IS DISTINCT FROM OLD.tax_amount THEN
    RAISE EXCEPTION 'ITEM_TAX_FROZEN: tax snapshot immutable in state %',
      COALESCE(NEW.kitchen_status, '') USING ERRCODE = 'P0001';
  END IF;
  IF NEW.station_id IS DISTINCT FROM OLD.station_id THEN
    RAISE EXCEPTION 'ITEM_STATION_FROZEN: station routing immutable in state %',
      COALESCE(NEW.kitchen_status, '') USING ERRCODE = 'P0001';
  END IF;
  -- total_price allowed only as exact quantity rescale
  IF NEW.total_price IS DISTINCT FROM OLD.total_price
     AND GREATEST(NEW.total_price, 0) != GREATEST(NEW.unit_price * NEW.quantity, 0) THEN
    RAISE EXCEPTION 'ITEM_TOTAL_FROZEN: total_price must equal unit_price × quantity (state %)',
      COALESCE(NEW.kitchen_status, '') USING ERRCODE = 'P0001';
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_item_seat_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_item_seat_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.seat_number IS NOT NULL AND NEW.seat_number < 1 THEN
    RAISE EXCEPTION 'INVALID_SEAT: seat_number must be ≥ 1 (got %)', NEW.seat_number
      USING ERRCODE = 'P0001';
  END IF;
  IF NEW.course IS NOT NULL AND NEW.course NOT IN ('main','appetizer','dessert','drink','side','combo') THEN
    RAISE EXCEPTION 'INVALID_COURSE: % (allowed main/appetizer/dessert/drink/side/combo)', NEW.course
      USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: trg_item_state_machine_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_item_state_machine_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valid jsonb;
BEGIN
  IF OLD.kitchen_status IS NOT DISTINCT FROM NEW.kitchen_status THEN
    RETURN NEW;
  END IF;

  v_valid := validate_transition('item', OLD.kitchen_status, NEW.kitchen_status);
  IF NOT (v_valid->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_ITEM_TRANSITION [% → %]: % (item %)',
      OLD.kitchen_status, NEW.kitchen_status, v_valid->>'error', NEW.id
      USING ERRCODE = 'P0001';
  END IF;

  IF NEW.kitchen_status = 'sent' AND OLD.kitchen_status IS DISTINCT FROM 'sent'
     AND NEW.sent_at IS NULL THEN
    NEW.sent_at := now();
  END IF;
  IF NEW.kitchen_status = 'accepted' AND OLD.kitchen_status IS DISTINCT FROM 'accepted'
     AND NEW.accepted_at IS NULL THEN
    NEW.accepted_at := now();
  END IF;
  IF NEW.kitchen_status = 'preparing' AND OLD.kitchen_status IS DISTINCT FROM 'preparing'
     AND NEW.started_at IS NULL THEN
    NEW.started_at := now();
  END IF;
  IF NEW.kitchen_status = 'ready' AND OLD.kitchen_status IS DISTINCT FROM 'ready'
     AND NEW.ready_at IS NULL THEN
    NEW.ready_at := now();
  END IF;
  IF NEW.kitchen_status = 'completed' AND OLD.kitchen_status IS DISTINCT FROM 'completed'
     AND NEW.completed_at IS NULL THEN
    NEW.completed_at := now();
  END IF;

  IF NEW.kitchen_status = 'served' AND NEW.served_at IS NULL THEN
    NEW.served_at := now();
  END IF;
  IF NEW.kitchen_status IN ('voided','cancelled','comped','wasted') THEN
    NEW.served_at := NULL;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_order_payment_immutable(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_order_payment_immutable() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    -- Trusted exception: reopen_order_atomic's authorized, actor-validated,
    -- audited FULL order reversal (order -> new, paid_amount -> 0, inventory
    -- reversed). It is transaction-scoped (set_config ... , true) and set only
    -- inside that SECURITY DEFINER fn, so external callers cannot forge it.
    IF coalesce(current_setting('app.payment_ledger_reopen', true), 'off') <> 'on' THEN
      RAISE EXCEPTION 'PAYMENT_RECORD_IMMUTABLE: order_payments rows cannot be deleted (corrections are new refund/reverse rows) [order=%]', OLD.order_id USING ERRCODE = 'P0001';
    END IF;
    RETURN OLD;
  END IF;
  -- UPDATE: the financial identity is immutable; status is handled by the
  -- separate P-2 state-machine guard (trg_payment_state_machine_guard).
  IF (OLD.amount   IS DISTINCT FROM NEW.amount)
     OR (OLD.method IS DISTINCT FROM NEW.method)
     OR (OLD.is_refund IS DISTINCT FROM NEW.is_refund)
     OR (OLD.order_id IS DISTINCT FROM NEW.order_id) THEN
    RAISE EXCEPTION 'PAYMENT_RECORD_IMMUTABLE: amount/method/is_refund/order_id are immutable (P-5 D-3: a payment record cannot be re-attached to a different order) [payment=%, order=% -> %]', NEW.id, OLD.order_id, NEW.order_id USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trg_order_payment_immutable(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trg_order_payment_immutable() IS 'P-3: order_payments financial identity (amount/method/is_refund) is immutable; rows are append-only. DELETE only via the trusted reopen_order_atomic full-reversal flag. status transitions remain P-2''s trg_payment_state_machine_guard.';


--
-- Name: trg_order_payment_state_machine_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_order_payment_state_machine_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valid jsonb;
BEGIN
  IF TG_OP <> 'UPDATE' OR (OLD.status IS NOT DISTINCT FROM NEW.status) THEN
    RETURN NEW;
  END IF;
  IF OLD.status IS NULL THEN
    -- first set of an unset (legacy NULL) status: allowed
    RETURN NEW;
  END IF;
  IF NEW.status IS NULL THEN
    RAISE EXCEPTION 'INVALID_PAYMENT_TRANSITION [payment status cannot be unset: % -> NULL]', OLD.status USING ERRCODE='P0001';
  END IF;
  v_valid := validate_transition('payment', OLD.status, NEW.status);
  IF NOT (v_valid->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_PAYMENT_TRANSITION [% -> %]: % (payment %)', OLD.status, NEW.status, v_valid->>'error', OLD.id USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trg_order_payment_state_machine_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trg_order_payment_state_machine_guard() IS 'P-2: order_payments.status is transition-validated against state_transitions entity=''payment'' (single SSOT). NULL init allowed; unset rejected; X->Y must exist in registry.';


--
-- Name: trg_order_state_machine_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_order_state_machine_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_valid jsonb;
BEGIN
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  -- (a) Registry is the only source of truth for transitions
  v_valid := validate_transition('order', OLD.status, NEW.status);
  IF NOT (v_valid->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_TRANSITION [% → %]: % (order %)',
      OLD.status, NEW.status, v_valid->>'error', NEW.id USING ERRCODE='P0001';
  END IF;

  -- (b) Canonical timestamps (first time only)
  IF NEW.status = 'paid'          AND NEW.paid_at IS NULL      THEN NEW.paid_at      := now(); END IF;
  IF NEW.status = 'closed'        AND NEW.closed_at IS NULL    THEN NEW.closed_at    := now(); END IF;
  IF NEW.status = 'cancelled'     AND NEW.cancelled_at IS NULL THEN NEW.cancelled_at := now(); END IF;
  IF NEW.status IN ('refunded','partially_refunded') AND NEW.refunded_at IS NULL THEN NEW.refunded_at := now(); END IF;
  IF NEW.status IN ('new','open','confirmed','in_kitchen')
     AND OLD.status IN ('paid','closed','cancelled','refunded','partially_refunded','voided')
  THEN
    NEW.reopened_at := now();
  END IF;

  -- (c) Coarse kitchen_status sync per contract
  IF NEW.status IN ('paid','closed','refunded','partially_refunded')
     AND COALESCE(NEW.kitchen_status,'') NOT IN ('completed','cancelled')
  THEN
    NEW.kitchen_status := 'completed';
  END IF;
  IF NEW.status = 'cancelled' THEN NEW.kitchen_status := 'cancelled'; END IF;

  RETURN NEW;
END;
$$;


--
-- Name: trg_order_underpayment_guard(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_order_underpayment_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status IN ('paid','closed')
     AND COALESCE(NEW.paid_amount, 0) > 0
     AND COALESCE(NEW.paid_amount, 0) < COALESCE(NEW.total_amount, 0) - 0.01 THEN
    RAISE EXCEPTION 'PAYMENT_INCOMPLETE: order cannot be % with paid_amount % < total_amount % (partial pay; keep the order open or void it)', NEW.status, NEW.paid_amount, NEW.total_amount USING ERRCODE = 'P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: FUNCTION trg_order_underpayment_guard(); Type: COMMENT; Schema: public; Owner: -
--

COMMENT ON FUNCTION public.trg_order_underpayment_guard() IS 'P-3 (P3-F4b): an order may not enter paid/closed while partially paid (0 < paid_amount < total_amount). Full-amount and zero-amount (void) closes are unaffected. Legacy underpaid-closed rows are untouched (UPDATE-only guard).';


--
-- Name: trg_permission_prevent_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_permission_prevent_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count integer;
BEGIN
    SELECT count(*) INTO v_count FROM role_permissions WHERE permission_key = OLD.key;
    IF v_count > 0 THEN
        RAISE EXCEPTION 'Cannot delete permission: assigned to % roles', v_count;
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: trg_role_prevent_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_role_prevent_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count integer;
BEGIN
    SELECT count(*) INTO v_count FROM staff WHERE role_id = OLD.id;
    IF v_count > 0 THEN
        RAISE EXCEPTION 'Cannot delete role: % staff members still assigned', v_count;
    END IF;
    RETURN OLD;
END;
$$;


--
-- Name: trg_roles_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_roles_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
