    RETURN NEW;
END;
$$;


--
-- Name: trg_session_expiry_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_session_expiry_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Auto-expire on access if expired
    IF NEW.expires_at <= now() AND NEW.status = 'ACTIVE' THEN
        NEW.status := 'EXPIRED';
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_session_staff_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_session_staff_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_staff_org uuid;
BEGIN
    SELECT organization_id INTO v_staff_org FROM staff WHERE id = NEW.user_id;
    IF v_staff_org IS NULL THEN
        RAISE EXCEPTION 'Staff not found for session: %', NEW.user_id;
    END IF;

    -- Set organization_id from staff
    NEW.organization_id := v_staff_org;

    RETURN NEW;
END;
$$;


--
-- Name: trg_shift_active_staff(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_shift_active_staff() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status staff_status;
BEGIN
    SELECT status INTO v_status FROM staff WHERE id = NEW.staff_id;
    IF v_status != 'ACTIVE' THEN
        RAISE EXCEPTION 'Cannot open shift for % staff (status: %)', v_status, v_status;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_shift_no_overlap(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_shift_no_overlap() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count integer;
BEGIN
    IF NEW.status = 'OPEN' OR NEW.closed_at IS NULL THEN
        SELECT count(*) INTO v_count
        FROM shifts
        WHERE staff_id = NEW.staff_id
        AND id != NEW.id
        AND (closed_at IS NULL OR status = 'OPEN');

        IF v_count > 0 THEN
            RAISE EXCEPTION 'Staff already has an open shift. Close it first.';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_deactivate_cascade(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_deactivate_cascade() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- When staff becomes INACTIVE or SUSPENDED, deactivate all staff_locations
    IF NEW.status IN ('INACTIVE', 'SUSPENDED') AND OLD.status = 'ACTIVE' THEN
        UPDATE staff_locations
        SET active = false
        WHERE staff_id = NEW.id AND active = true;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_location_org_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_location_org_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_staff_org uuid;
    v_loc_org uuid;
BEGIN
    -- Get staff's organization
    SELECT organization_id INTO v_staff_org FROM staff WHERE id = NEW.staff_id;
    IF v_staff_org IS NULL THEN
        RAISE EXCEPTION 'Staff not found: %', NEW.staff_id;
    END IF;

    -- Get location's organization
    SELECT organization_id INTO v_loc_org FROM locations WHERE id = NEW.location_id;
    IF v_loc_org IS NULL THEN
        RAISE EXCEPTION 'Location not found: %', NEW.location_id;
    END IF;

    -- Organization match
    IF v_staff_org != v_loc_org THEN
        RAISE EXCEPTION 'Staff org (%) != Location org (%)', v_staff_org, v_loc_org;
    END IF;

    -- Store organization_id
    NEW.organization_id := v_staff_org;

    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_locations_active_check(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_locations_active_check() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_status staff_status;
BEGIN
    IF NEW.active = true THEN
        SELECT status INTO v_status FROM staff WHERE id = NEW.staff_id;
        IF v_status != 'ACTIVE' THEN
            RAISE EXCEPTION 'Cannot assign location to % staff (status: %)', v_status, v_status;
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_locations_single_primary(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_locations_single_primary() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
    v_count integer;
BEGIN
    IF NEW.is_primary = true THEN
        SELECT count(*) INTO v_count
        FROM staff_locations
        WHERE staff_id = NEW.staff_id AND is_primary = true AND id != NEW.id;

        IF v_count > 0 THEN
            RAISE EXCEPTION 'Staff already has a primary location. Unset it first.';
        END IF;
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_locations_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_locations_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_outbox(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_outbox() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    IF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
        INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, metadata, status)
        VALUES ('staff', NEW.id, 'staff.' || LOWER(NEW.status::text),
                jsonb_build_object('staff_id', NEW.id, 'name', NEW.name, 'old_status', OLD.status, 'new_status', NEW.status),
                jsonb_build_object('organization_id', NEW.organization_id, 'actor_staff_id', NEW.id),
                'pending');
    END IF;
    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_prevent_delete(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_prevent_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    RAISE EXCEPTION 'Cannot DELETE staff. Use status = INACTIVE instead.';
    RETURN NULL;
END;
$$;


--
-- Name: trg_staff_role_consistency(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_role_consistency() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    -- Role must exist and be active
    IF NOT EXISTS (SELECT 1 FROM roles WHERE id = NEW.role_id) THEN
        RAISE EXCEPTION 'Invalid role_id: %', NEW.role_id;
    END IF;

    -- Staff must have organization_id
    IF NEW.organization_id IS NULL THEN
        RAISE EXCEPTION 'Staff must have an organization_id';
    END IF;

    -- Organization must exist and be active
    IF NOT EXISTS (SELECT 1 FROM organizations WHERE id = NEW.organization_id AND status = 'ACTIVE') THEN
        RAISE EXCEPTION 'Invalid or inactive organization: %', NEW.organization_id;
    END IF;

    RETURN NEW;
END;
$$;


--
-- Name: trg_staff_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.trg_staff_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$;


--
-- Name: undo_operation(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_operation(p_operation_log_id uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log RECORD;
BEGIN
  SELECT * INTO v_log FROM operation_logs WHERE id = p_operation_log_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'OPERATION_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_log.is_undone THEN
    RAISE EXCEPTION 'ALREADY_UNDONE' USING ERRCODE = 'P0001';
  END IF;
  IF v_log.undo_payload IS NULL THEN
    RAISE EXCEPTION 'NO_UNDO_PAYLOAD' USING ERRCODE = 'P0001';
  END IF;

  UPDATE operation_logs
  SET is_undone = true, undone_at = now(), undone_by = p_performed_by
  WHERE id = p_operation_log_id;

  RETURN jsonb_build_object(
    'success', true,
    'operation', v_log.operation,
    'undo_payload', v_log.undo_payload
  );
END;
$$;


--
-- Name: undo_operation_v4(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_operation_v4(p_log_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_log RECORD;
BEGIN
  -- Check time limit (5 mins)
  SELECT * INTO v_log FROM operation_logs WHERE id = p_log_id AND created_at > now() - interval '5 minutes';
  
  IF v_log IS NULL THEN
    RAISE EXCEPTION 'UNDO_TIMEOUT_OR_NOT_FOUND' USING ERRCODE = 'P0002';
  END IF;

  -- Inverse Logic based on Type
  IF v_log.type = 'MERGE' THEN
    -- Restore relations (detach children)
    UPDATE orders SET group_id = NULL 
    WHERE table_number = ANY(ARRAY(SELECT jsonb_array_elements_text(v_log.payload->'children'))::integer[])
    AND group_id = (v_log.payload->>'group_id')::uuid;
    
    UPDATE table_floors SET merged_into_table = NULL 
    WHERE table_number = ANY(ARRAY(SELECT jsonb_array_elements_text(v_log.payload->'children'))::integer[]);
    
  ELSIF v_log.type = 'TRANSFER' THEN
    -- Inverse transfer
    UPDATE orders SET table_number = (v_log.payload->>'from')::integer 
    WHERE table_number = (v_log.payload->>'to')::integer AND status = 'confirmed';
    
    UPDATE table_floors SET status = 'empty' WHERE table_number = (v_log.payload->>'to')::integer;
    UPDATE table_floors SET status = 'occupied' WHERE table_number = (v_log.payload->>'from')::integer;
  END IF;

  -- Remove log after successful undo
  DELETE FROM operation_logs WHERE id = p_log_id;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: undo_transfer_atomic(integer, integer, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.undo_transfer_atomic(p_from_table integer, p_to_table integer, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_from RECORD;
  v_to RECORD;
  v_order RECORD;
  v_total_guests INT := 0;
  v_total_amount NUMERIC := 0;
BEGIN
  IF p_from_table = p_to_table THEN
    RETURN jsonb_build_object('success', false, 'error', 'Source and target are the same');
  END IF;

  SELECT * INTO v_from FROM public.table_floors WHERE table_number = p_from_table FOR UPDATE;
  SELECT * INTO v_to FROM public.table_floors WHERE table_number = p_to_table FOR UPDATE;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Table not found');
  END IF;

  SELECT * INTO v_order FROM public.orders
    WHERE table_number = p_to_table
      AND status NOT IN ('paid', 'cancelled', 'closed', 'completed')
    ORDER BY created_at ASC LIMIT 1;

  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active order on target table to revert');
  END IF;

  v_total_guests := COALESCE(v_order.guest_count, 0);
  v_total_amount := COALESCE(v_order.total_amount, 0);

  UPDATE public.orders SET
    table_number = p_from_table,
    updated_at = NOW()
  WHERE table_number = p_to_table
    AND status NOT IN ('paid', 'cancelled', 'closed', 'completed');

  UPDATE public.table_floors SET
    status = 'occupied',
    guest_count = v_total_guests,
    total_amount = v_total_amount,
    current_order_id = v_order.id,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    updated_at = NOW()
  WHERE table_number = p_from_table;

  UPDATE public.table_floors SET
    status = 'empty',
    guest_count = NULL,
    total_amount = 0,
    current_order_id = NULL,
    merged_into_table = NULL,
    reservation_id = NULL,
    reservation_name = NULL,
    reservation_phone = NULL,
    reservation_time = NULL,
    updated_at = NOW()
  WHERE table_number = p_to_table;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    p_from_table,
    v_order.id,
    'undo_transfer',
    jsonb_build_object('from_table', p_from_table, 'to_table', p_to_table),
    jsonb_build_object('from_table', p_from_table, 'to_table', p_to_table, 'reverted', true),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'order_id', v_order.id);
END;
$$;


--
-- Name: unmerge_tables_atomic(text, integer, integer[], uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unmerge_tables_atomic(p_token text, p_parent_table_number integer, p_child_table_numbers integer[], p_performed_by uuid, p_performed_by_terminal_id text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_sess_loc uuid;
  v_parent          table_floors;
  v_child           table_floors;
  v_children        int[];
  v_plineage        jsonb;
  v_clineage        jsonb;
  v_mode            text;
  v_parent_kind     text;
  v_child_kind      text;
  v_resv_id         uuid;
  v_canonical_order uuid;
  v_canonical_from  int;
  v_child_order_id  uuid;
  v_resv_name       text;
  v_resv_phone      text;
  v_resv_time       text;
  v_resv_active     boolean;
  v_unmerged        int := 0;
  v_children_summary jsonb := '[]'::jsonb;
  -- P-1 (legacy lineage-less recovery)
  v_legacy_candidate_orders int := 0;
  v_p1_recovered            int := 0;
BEGIN
  PERFORM public.set_session_staff(p_token);
  v_sess_loc := nullif(current_setting('app.current_location_id', true), '')::uuid;
  IF current_staff_id() IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN');
  END IF;
  IF NOT coalesce(has_permission(current_staff_id(), 'floor.manage'), false) THEN
    RETURN jsonb_build_object('success', false, 'error', 'PERMISSION_DENIED');
  END IF;

  PERFORM public.validate_actor(p_performed_by);

  IF p_parent_table_number = ANY(p_child_table_numbers) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_PARENT_IN_CHILD');
  END IF;
  v_children := (SELECT array_agg(tn ORDER BY tn) FROM (SELECT DISTINCT unnest(p_child_table_numbers) AS tn) x);
  IF v_children IS NULL OR array_length(v_children, 1) IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_NO_CHILDREN');
  END IF;

  SELECT * INTO v_parent FROM public.table_floors
   WHERE table_number = p_parent_table_number AND (v_sess_loc IS NULL OR location_id = v_sess_loc) FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;
  IF NOT has_location_access(v_parent.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE table_number = ANY(v_children) AND location_id <> v_parent.location_id) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  IF EXISTS (SELECT 1 FROM public.table_floors WHERE table_number = ANY(v_children) AND NOT has_location_access(location_id)) THEN
    RETURN jsonb_build_object('success', false, 'error', 'FORBIDDEN_LOCATION');
  END IF;
  FOR v_child IN SELECT * FROM public.table_floors
                 WHERE table_number = ANY(v_children) ORDER BY table_number FOR UPDATE LOOP
    NULL;
  END LOOP;
  IF (SELECT count(*) FROM public.table_floors WHERE table_number = ANY(v_children)) <> array_length(v_children, 1) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_CHILD_NOT_FOUND');
  END IF;

  -- the group must actually be merged under this parent
  IF NOT EXISTS (SELECT 1 FROM public.table_floors
                 WHERE table_number = ANY(v_children)
                   AND merged_into_table = p_parent_table_number) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_NO_MERGED_CHILDREN');
  END IF;

  -- ---- read parent lineage (fallback: infer from current state) ----
  v_plineage := v_parent.metadata;
  v_mode           := (v_plineage->'merge_lineage')->>'mode';
  v_parent_kind    := (v_plineage->'merge_lineage')->>'parent_kind';
  v_resv_id        := ((v_plineage->'merge_lineage')->>'parent_reservation_id')::uuid;
  v_canonical_order:= ((v_plineage->'merge_lineage')->>'parent_order_id')::uuid;
  v_canonical_from := ((v_plineage->'merge_lineage')->>'canonical_order_from')::int;

  IF v_mode IS NULL THEN
    -- reservation is checked BEFORE the pointer: a LEGACY checked-in group has a
    -- reserved parent that still carries a pointer (e.g. real table 6) — it must
    -- restore as 'reserved' keeping that pointer, not as 'occupied'. A bill-merge
    -- parent never has a reservation_id, so this ordering is safe both ways.
    IF v_parent.reservation_id IS NOT NULL THEN
      v_mode := 'reservation-aware'; v_parent_kind := 'reserved'; v_resv_id := v_parent.reservation_id;
    ELSIF EXISTS (SELECT 1 FROM public.table_floors
                  WHERE table_number = ANY(v_children) AND reservation_id IS NOT NULL) THEN
      -- legacy reservation group: child still carries the reservation binding
      v_mode := 'reservation-aware'; v_parent_kind := 'reserved';
      SELECT reservation_id INTO v_resv_id FROM public.table_floors
       WHERE table_number = ANY(v_children) AND reservation_id IS NOT NULL ORDER BY table_number LIMIT 1;
    ELSIF v_parent.status = 'reserved' THEN
      -- legacy checked-in / manual-reserved group: parent shows 'reserved' but has no
      -- reservation record (reservation_id NULL) — e.g. real tables 6/7
      v_mode := 'reservation-aware'; v_parent_kind := 'reserved';
      -- v_resv_id stays NULL
    ELSIF v_parent.current_order_id IS NOT NULL THEN
      v_mode := 'bill-merge'; v_parent_kind := 'occupied';
      v_canonical_order := v_parent.current_order_id; v_canonical_from := p_parent_table_number;
    ELSE
      v_mode := 'group-empty'; v_parent_kind := 'empty';
    END IF;
  END IF;
  IF v_canonical_from IS NULL THEN v_canonical_from := p_parent_table_number; END IF;

  v_resv_active := EXISTS (SELECT 1 FROM public.reservations r
                           WHERE r.id = v_resv_id
                             AND r.status IN ('pending','confirmed','checked_in','seated'));

  -- ---- guards: no kitchen activity / payment on any open order in the group ----
  IF EXISTS (SELECT 1 FROM public.orders
             WHERE (table_number = p_parent_table_number OR table_number = ANY(v_children))
               AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
               AND kitchen_status IN ('sent','accepted','preparing','cooking','ready','partially_ready','served')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_KITCHEN_ACTIVE');
  END IF;
  IF EXISTS (SELECT 1 FROM public.orders o JOIN public.payments p ON p.order_id = o.id
             WHERE (o.table_number = p_parent_table_number OR o.table_number = ANY(v_children))
               AND o.status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
               AND p.status IN ('captured','pending')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_ORDER_PAID');
  END IF;

  -- ========================================================================
  -- P-1 PREFLIGHT — lineage-less legacy bill-merge group: ambiguity fails loud
  -- ========================================================================
  IF v_mode = 'bill-merge' AND (v_plineage->'merge_lineage') IS NULL THEN
    IF EXISTS (SELECT 1 FROM public.orders
               WHERE table_number = p_parent_table_number
                 AND merged_from_table = ANY(v_children)
                 AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
               GROUP BY merged_from_table
               HAVING count(*) > 1) THEN
      RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_LEGACY_AMBIGUOUS',
        'detail', 'lineage-less bill-merge group: a child of parent table ' || p_parent_table_number ||
                  ' has multiple non-final orders at the parent claiming its merged_from_table; ' ||
                  'fix orders.merged_from_table manually and retry unmerge');
    END IF;
  END IF;

  -- ========================================================================
  -- PHASE 1 — parent first (move canonical order back, then set parent state)
  -- ========================================================================
  IF v_mode = 'bill-merge' AND v_canonical_order IS NOT NULL
     AND v_canonical_from <> p_parent_table_number AND v_canonical_from = ANY(v_children) THEN
    -- case 2 (or extra canonical): the group's canonical order belongs to a child -> move it back FIRST
    UPDATE public.orders SET
      table_number = v_canonical_from,
      merged_into = NULL,
      merged_from_table = NULL,
      updated_at = now(),
      version = COALESCE(version,0) + 1,
      updated_by_terminal_id = p_performed_by_terminal_id
    WHERE id = v_canonical_order;
    UPDATE public.kitchen_schedule SET table_number = v_canonical_from, updated_at = now()
    WHERE order_id = v_canonical_order;
    -- clear_stale_table_order_pointer now drops the parent's pointer to this order
  END IF;

  IF v_mode = 'bill-merge' THEN
    IF v_parent_kind = 'occupied' AND v_canonical_order IS NOT NULL THEN
      -- case 3 / 4: parent keeps the group's canonical order
      UPDATE public.table_floors SET
        status = 'occupied',
        current_order_id = v_canonical_order,
        merged_into_table = NULL,
        metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
        updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = p_parent_table_number;
      PERFORM public.sync_table_order_aggregates(p_parent_table_number);
    ELSE
      -- case 2: parent was empty (order already moved to the child) -> back to EMPTY
      UPDATE public.table_floors SET
        status = 'empty', current_order_id = NULL, merged_into_table = NULL,
        guest_count = NULL, total_amount = 0, order_count = 0, has_pending = false,
        oldest_pending_at = NULL, bill_requested = false,
        metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
        updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = p_parent_table_number;
    END IF;
  ELSIF v_mode = 'reservation-aware' THEN
    IF v_resv_id IS NOT NULL AND v_resv_active THEN
      SELECT name, phone, time::text INTO v_resv_name, v_resv_phone, v_resv_time
      FROM public.reservations WHERE id = v_resv_id;
    END IF;
    IF v_parent_kind = 'reserved' AND (v_resv_id IS NULL OR v_resv_active) THEN
      -- case 5 / 7 + legacy checked-in / manual-reserved group (e.g. real 6/7):
      -- parent restores to 'reserved'. current_order_id + reservation display fields
      -- are intentionally NOT touched (a legacy reserved parent keeps its pointer);
      -- reservation_id is kept as-is when the group has no reservation record.
      UPDATE public.table_floors SET
        status = 'reserved', merged_into_table = NULL,
        reservation_id = COALESCE(v_resv_id, reservation_id),
        metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
        updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = p_parent_table_number;
    ELSE
      -- case 6 (parent was empty) / reservation gone (id set but inactive) -> parent EMPTY;
      -- drop the reservation_tables binding the merge added
      IF v_resv_id IS NOT NULL THEN
        DELETE FROM public.reservation_tables
         WHERE reservation_id = v_resv_id AND table_number = p_parent_table_number;
      END IF;
      UPDATE public.table_floors SET
        status = 'empty', current_order_id = NULL, merged_into_table = NULL,
        guest_count = NULL, total_amount = 0, order_count = 0, has_pending = false,
        oldest_pending_at = NULL, bill_requested = false,
        reservation_id = NULL, reservation_name = NULL, reservation_phone = NULL, reservation_time = NULL,
        metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
        updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = p_parent_table_number;
    END IF;
  ELSE
    -- group-empty: parent was empty, stays empty
    UPDATE public.table_floors SET
      status = 'empty', current_order_id = NULL, merged_into_table = NULL,
      guest_count = NULL, total_amount = 0, order_count = 0, has_pending = false,
      oldest_pending_at = NULL, bill_requested = false,
      reservation_id = NULL, reservation_name = NULL, reservation_phone = NULL, reservation_time = NULL,
      metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
      updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
    WHERE table_number = p_parent_table_number;
  END IF;

  -- ========================================================================
  -- PHASE 2 — restore each child to its original state
  -- ========================================================================
  FOR v_child IN SELECT * FROM public.table_floors
                 WHERE table_number = ANY(v_children) ORDER BY table_number LOOP
    IF v_child.merged_into_table IS DISTINCT FROM p_parent_table_number THEN
      CONTINUE;  -- not part of this group
    END IF;

    v_clineage := v_child.metadata;
    v_child_kind := (v_clineage->'merge_lineage')->>'kind';
    IF v_child_kind IS NULL OR v_child_kind NOT IN ('occupied','reserved','empty') THEN
      IF v_child_kind IS NULL AND v_mode = 'bill-merge'
         AND (v_plineage->'merge_lineage') IS NULL
         AND v_child.reservation_id IS NULL AND v_child.current_order_id IS NULL THEN
        -- P-1: lineage-less legacy child in a lineage-less bill-merge group.
        -- Its order (if any) was moved to the parent by the legacy merge and is
        -- claimed via orders.merged_from_table = this child.
        SELECT count(*) INTO v_legacy_candidate_orders
          FROM public.orders
         WHERE table_number = p_parent_table_number
           AND merged_from_table = v_child.table_number
           AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided');
        -- count = 1 -> the child was OCCUPIED (order recovered below)
        -- count = 0 -> the child was genuinely EMPTY (legacy behavior preserved);
        -- count > 1 -> the preflight already failed loud (G_UNMERGE_LEGACY_AMBIGUOUS).
        IF v_legacy_candidate_orders = 1 THEN
          v_child_kind := 'occupied';
        ELSE
          v_child_kind := 'empty';
        END IF;
      ELSE
        v_child_kind := CASE WHEN v_child.reservation_id IS NOT NULL THEN 'reserved'
                             WHEN v_child.current_order_id IS NOT NULL THEN 'occupied'
                             WHEN v_mode = 'reservation-aware' THEN 'reserved'
                             ELSE 'empty' END;
      END IF;
    END IF;
    v_child_order_id := ((v_clineage->'merge_lineage')->>'order_id')::uuid;
    IF v_child_order_id IS NULL THEN v_child_order_id := v_child.current_order_id; END IF;
    -- P-1: a lineage-less legacy child classified 'occupied' above carries no pointer,
    -- so v_child_order_id is still NULL here -> recover the concrete order id.
    -- (kind='occupied' + order_id NULL can only arise from the P-1 branch above.)
    IF v_child_kind = 'occupied' AND v_child_order_id IS NULL
       AND v_mode = 'bill-merge' AND (v_plineage->'merge_lineage') IS NULL THEN
      SELECT id INTO v_child_order_id
        FROM public.orders
       WHERE table_number = p_parent_table_number
         AND merged_from_table = v_child.table_number
         AND status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')
       LIMIT 1;
      IF v_child_order_id IS NOT NULL THEN
        v_p1_recovered := 1;
      END IF;
    END IF;

    IF v_child_kind = 'occupied' AND v_child_order_id IS NOT NULL THEN
      -- child had its own order -> move it back to the child, child occupied
      -- (P-1: for a legacy lineage-less child this is the RECOVERED order)
      UPDATE public.orders SET
        table_number = v_child.table_number,
        merged_into = NULL, merged_from_table = NULL,
        updated_at = now(), version = COALESCE(version,0) + 1,
        updated_by_terminal_id = p_performed_by_terminal_id
      WHERE id = v_child_order_id;
      UPDATE public.kitchen_schedule SET table_number = v_child.table_number, updated_at = now()
      WHERE order_id = v_child_order_id;
      UPDATE public.table_floors SET
        status = 'occupied', current_order_id = v_child_order_id, merged_into_table = NULL,
        kitchen_status = NULL,
        reservation_id = NULL, reservation_name = NULL, reservation_phone = NULL, reservation_time = NULL,
        metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
        updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = v_child.table_number;
      v_children_summary := v_children_summary || jsonb_build_array(jsonb_build_object(
        'table', v_child.table_number, 'restored', 'occupied', 'order_id', v_child_order_id));
      v_unmerged := v_unmerged + 1;
      CONTINUE;
    END IF;

    IF v_child_kind = 'reserved' AND (v_resv_id IS NULL OR v_resv_active) THEN
      IF v_resv_id IS NOT NULL THEN
        -- case 5 / 7 + legacy groups with a reservation record -> reserved,
        -- denormalized reservation fields restored from the canonical reservation
        IF v_resv_name IS NULL THEN
          SELECT name, phone, time::text INTO v_resv_name, v_resv_phone, v_resv_time
          FROM public.reservations WHERE id = v_resv_id;
        END IF;
        UPDATE public.table_floors SET
          status = 'reserved', current_order_id = NULL, merged_into_table = NULL,
          kitchen_status = NULL,
          reservation_id = v_resv_id, reservation_name = v_resv_name,
          reservation_phone = v_resv_phone, reservation_time = v_resv_time,
          metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
          updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
        WHERE table_number = v_child.table_number;
      ELSE
        -- legacy no-record group (e.g. real 6/7): reserved, keep the child's
        -- existing reservation fields untouched
        UPDATE public.table_floors SET
          status = 'reserved', current_order_id = NULL, merged_into_table = NULL,
          kitchen_status = NULL,
          metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
          updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
        WHERE table_number = v_child.table_number;
      END IF;
      v_children_summary := v_children_summary || jsonb_build_array(jsonb_build_object(
        'table', v_child.table_number, 'restored', 'reserved', 'reservation_id', v_resv_id));
      v_unmerged := v_unmerged + 1;
      CONTINUE;
    END IF;

    -- child was empty (or reservation gone) -> EMPTY; drop the reservation binding merge added
    IF v_resv_id IS NOT NULL THEN
      DELETE FROM public.reservation_tables
       WHERE reservation_id = v_resv_id AND table_number = v_child.table_number;
    END IF;
    UPDATE public.table_floors SET
      status = 'empty', current_order_id = NULL, merged_into_table = NULL,
      kitchen_status = NULL, guest_count = NULL, total_amount = 0, order_count = 0,
      has_pending = false, oldest_pending_at = NULL, bill_requested = false,
      reservation_id = NULL, reservation_name = NULL, reservation_phone = NULL, reservation_time = NULL,
      metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
      updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
    WHERE table_number = v_child.table_number;
    v_children_summary := v_children_summary || jsonb_build_array(jsonb_build_object(
      'table', v_child.table_number, 'restored', 'empty'));
    v_unmerged := v_unmerged + 1;
  END LOOP;

  -- refresh aggregates on restored children
  FOR v_child IN SELECT * FROM public.table_floors
                 WHERE table_number = ANY(v_children) ORDER BY table_number LOOP
    PERFORM public.sync_table_order_aggregates(v_child.table_number);
  END LOOP;

  -- ========================================================================
  -- P-1 PARENT FIXUP — legacy lineage-less group only
  -- ========================================================================
  -- If the recovered order WAS the parent's pointer order (legacy case-2 shape),
  -- moving it to the child fired clear_stale_table_order_pointer and dropped the
  -- parent's current_order_id. An 'occupied' parent with no pointer is invalid:
  -- reset the parent to EMPTY. If the parent still holds other open orders the
  -- release guard makes this unmerge fail loud — never a silent pointer-less
  -- 'occupied' parent. If the parent kept its own pointer order, only re-sync.
  IF v_p1_recovered > 0 THEN
    IF NOT EXISTS (SELECT 1 FROM public.table_floors
                   WHERE table_number = p_parent_table_number AND current_order_id IS NOT NULL) THEN
      UPDATE public.table_floors SET
        status = 'empty', current_order_id = NULL, merged_into_table = NULL,
        guest_count = NULL, total_amount = 0, order_count = 0, has_pending = false,
        oldest_pending_at = NULL, bill_requested = false,
        metadata = COALESCE(metadata,'{}'::jsonb) - 'merge_lineage',
        updated_at = now(), updated_by_terminal_id = p_performed_by_terminal_id
      WHERE table_number = p_parent_table_number;
    END IF;
    PERFORM public.sync_table_order_aggregates(p_parent_table_number);
  END IF;

  IF v_unmerged = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_UNMERGE_NO_MERGED_CHILDREN');
  END IF;

  PERFORM public.g_table_audit(
    'unmerge_tables', 'table.unmerged',
    p_parent_table_number, v_parent.id, v_canonical_order,
    jsonb_build_object('mode', v_mode, 'children', v_children, 'parent_kind', v_parent_kind),
    jsonb_build_object('mode', v_mode, 'unmerged', v_children_summary, 'p1_recovered', v_p1_recovered > 0),
    p_performed_by, p_performed_by_terminal_id, 'contract-unmerge-v2:' || COALESCE(v_mode,'unknown'),
    p_parent_table_number, NULL, v_parent.location_id, v_parent.organization_id);

  RETURN jsonb_build_object('success', true, 'mode', v_mode,
    'parent_order_id', v_canonical_order, 'unmerged', v_children_summary, 'count', v_unmerged);
END;
$$;


--
-- Name: unmerge_tables_v3(integer, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unmerge_tables_v3(p_primary_table integer, p_child_tables integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_child INTEGER;
  v_primary_order_id UUID;
  v_child_order_id UUID;
BEGIN
  -- Find primary order
  SELECT id INTO v_primary_order_id FROM orders 
  WHERE table_number = p_primary_table AND status NOT IN ('paid', 'cancelled', 'closed') LIMIT 1;

  FOREACH v_child IN ARRAY p_child_tables
  LOOP
    -- Mark source order as NOT merged (point back to itself if needed, or just set null)
    UPDATE orders SET merged_into = NULL WHERE table_number = v_child AND merged_into = v_primary_order_id;
    
    -- Reset floor
    UPDATE table_floors SET status = 'occupied', merged_into_table = NULL WHERE table_number = v_child;
  END LOOP;

  -- Re-calculate primary table totals in DB
  UPDATE table_floors SET 
    total_amount = (SELECT COALESCE(SUM(total_amount), 0) FROM orders WHERE table_number = p_primary_table AND status NOT IN ('paid', 'cancelled', 'closed')),
    guest_count = (SELECT COALESCE(SUM(guest_count), 0) FROM orders WHERE table_number = p_primary_table AND status NOT IN ('paid', 'cancelled', 'closed'))
  WHERE table_number = p_primary_table;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: unmerge_tables_v3(integer, integer[], uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unmerge_tables_v3(p_primary_table_number integer, p_child_table_numbers integer[], p_performed_by uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  primary_order_id uuid;
  child_num integer;
  child_order record;
  child_amount numeric := 0;
  total_subtracted numeric := 0;
  result jsonb;
BEGIN
  SELECT o.id INTO primary_order_id
  FROM orders o
  WHERE o.table_number = p_primary_table_number
    AND o.status NOT IN ('paid', 'cancelled', 'closed')
  ORDER BY o.created_at DESC
  LIMIT 1;

  IF primary_order_id IS NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'Primary order not found');
  END IF;

  FOREACH child_num IN ARRAY p_child_table_numbers
  LOOP
    FOR child_order IN
      SELECT id, total_amount FROM orders
      WHERE merged_into = primary_order_id
        AND table_number = child_num
        AND status NOT IN ('paid', 'cancelled')
    LOOP
      child_amount := COALESCE(child_order.total_amount, 0);
      total_subtracted := total_subtracted + child_amount;
      UPDATE orders SET merged_into = NULL, updated_at = now() WHERE id = child_order.id;
    END LOOP;

    UPDATE table_floors
    SET status = 'occupied', merged_into_table = NULL
    WHERE table_number = child_num;
  END LOOP;

  UPDATE orders
  SET total_amount = GREATEST(0, COALESCE(total_amount, 0) - total_subtracted),
      updated_at = now()
  WHERE id = primary_order_id;

  result := jsonb_build_object(
    'success', true,
    'primary_table', p_primary_table_number,
    'children_unmerged', to_jsonb(p_child_table_numbers),
    'amount_subtracted', total_subtracted
  );
  RETURN result;
END;
$$;


--
-- Name: unmerge_tables_v4(integer, integer[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.unmerge_tables_v4(p_primary_table integer, p_tables_to_detach integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table_num INTEGER;
BEGIN
  FOREACH v_table_num IN ARRAY p_tables_to_detach LOOP
    UPDATE orders SET group_id = NULL 
    WHERE table_number = v_table_num AND status = 'confirmed';
    
    UPDATE table_floors SET merged_into_table = NULL 
    WHERE table_number = v_table_num;
  END LOOP;
  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: update_courier_location(uuid, numeric, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_courier_location(p_courier_id uuid, p_lat numeric, p_lng numeric) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE couriers SET
    last_location_lat = p_lat,
    last_location_lng = p_lng,
    last_location_at = now()
  WHERE id = p_courier_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'COURIER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  RETURN jsonb_build_object('success', true);
END;
$$;


--
-- Name: update_delivery_order(uuid, text, text, text, text, numeric, uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_delivery_order(p_order_id uuid, p_customer_phone text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_customer_note text DEFAULT NULL::text, p_delivery_address text DEFAULT NULL::text, p_delivery_fee numeric DEFAULT NULL::numeric, p_courier_id uuid DEFAULT NULL::uuid, p_estimated_delivery_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
  v_courier_name TEXT;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status IN ('paid', 'closed') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED' USING ERRCODE = 'P0001';
  END IF;

  -- Resolve courier name if courier_id provided
  IF p_courier_id IS NOT NULL THEN
    SELECT name INTO v_courier_name FROM couriers WHERE id = p_courier_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'COURIER_NOT_FOUND' USING ERRCODE = 'P0001';
    END IF;

    -- Free up previous courier if assigned
    IF v_order.courier_id IS NOT NULL AND v_order.courier_id != p_courier_id THEN
      UPDATE couriers SET current_order_id = NULL WHERE id = v_order.courier_id;
    END IF;

    -- Assign to new courier
    UPDATE couriers SET current_order_id = p_order_id WHERE id = p_courier_id;
  END IF;

  UPDATE orders SET
    customer_phone = COALESCE(p_customer_phone, customer_phone),
    customer_name = COALESCE(p_customer_name, customer_name),
    customer_note = COALESCE(p_customer_note, customer_note),
    delivery_address = COALESCE(p_delivery_address, delivery_address),
    delivery_fee = COALESCE(p_delivery_fee, delivery_fee),
    total_amount = COALESCE(total_amount, 0) - COALESCE(v_order.delivery_fee, 0) + COALESCE(p_delivery_fee, COALESCE(v_order.delivery_fee, 0)),
    courier_id = COALESCE(p_courier_id, courier_id),
    courier_name = COALESCE(v_courier_name, courier_name),
    estimated_delivery_time = COALESCE(p_estimated_delivery_time, estimated_delivery_time),
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id);
END;
$$;


--
-- Name: update_guest_count(integer, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_guest_count(p_table_number integer, p_guest_count integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_active_count INT;
BEGIN
  IF p_guest_count IS NULL OR p_guest_count < 1 THEN
    RETURN jsonb_build_object('success', false, 'error', 'Guest count must be at least 1');
  END IF;

  SELECT COUNT(*) INTO v_active_count
  FROM public.orders
  WHERE table_number = p_table_number
    AND status NOT IN ('paid', 'cancelled', 'closed', 'completed');

  IF v_active_count = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'No active order on this table');
  END IF;

  UPDATE public.orders SET
    guest_count = p_guest_count,
    updated_at = NOW()
  WHERE table_number = p_table_number
    AND status NOT IN ('paid', 'cancelled', 'closed', 'completed');

  UPDATE public.table_floors SET
    guest_count = p_guest_count,
    updated_at = NOW()
  WHERE table_number = p_table_number;

  RETURN jsonb_build_object('success', true, 'guest_count', p_guest_count);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


