-- Name: update_invoices_updated_at(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_invoices_updated_at() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  NEW.updated_at = now();
  RETURN NEW;
END;
$$;


--
-- Name: update_location_atomic(text, uuid, text, text, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_location_atomic(p_token text, p_location_id uuid, p_name text DEFAULT NULL::text, p_code text DEFAULT NULL::text, p_slug text DEFAULT NULL::text, p_timezone text DEFAULT NULL::text, p_currency text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
    v_staff_id uuid; v_loc RECORD; v_old jsonb; v_new jsonb; v_corr uuid;
BEGIN
    PERFORM set_session_staff(p_token);
    v_staff_id := current_staff_id();
    IF NOT has_permission('settings.admin') AND NOT is_superadmin() THEN
        RAISE EXCEPTION 'Permission denied: settings.admin required';
    END IF;
    SELECT * INTO v_loc FROM locations WHERE id = p_location_id FOR UPDATE;
    IF NOT FOUND THEN RAISE EXCEPTION 'Location not found'; END IF;
    IF NOT has_org_access(v_loc.organization_id) THEN RAISE EXCEPTION 'Cannot update location in another org'; END IF;
    IF v_loc.status != 'ACTIVE' THEN RAISE EXCEPTION 'Only ACTIVE locations can be updated'; END IF;
    v_old := row_to_json(v_loc)::jsonb; v_corr := gen_random_uuid();
    IF p_currency IS NOT NULL AND p_currency !~ '^[A-Z]{3}$' THEN RAISE EXCEPTION 'Invalid currency'; END IF;
    UPDATE locations SET name=COALESCE(p_name,name), code=COALESCE(p_code,code), slug=COALESCE(p_slug,slug),
        timezone=COALESCE(p_timezone,timezone), currency=COALESCE(p_currency,currency)
    WHERE id = p_location_id RETURNING row_to_json(locations.*)::jsonb INTO v_new;
    INSERT INTO operation_logs (entity_type, entity_id, operation, before_state, after_state, performed_by, correlation_id, location_id, organization_id)
    VALUES ('location', p_location_id, 'location.updated', v_old, v_new, v_staff_id, v_corr, p_location_id, v_loc.organization_id);
    INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, metadata, status)
    VALUES ('location', p_location_id, 'location.updated', v_new,
            jsonb_build_object('organization_id', v_loc.organization_id, 'actor_staff_id', v_staff_id, 'correlation_id', v_corr), 'pending');
    RETURN v_new;
END;
$_$;


--
-- Name: update_order_item_prepared(uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_order_item_prepared(p_order_item_id uuid, p_prepared_quantity integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item RECORD;
BEGIN
  SELECT * INTO v_item FROM order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  UPDATE order_items
  SET prepared_quantity = p_prepared_quantity
  WHERE id = p_order_item_id;

  RETURN jsonb_build_object('success', true, 'order_item_id', p_order_item_id, 'prepared_quantity', p_prepared_quantity);
END;
$$;


--
-- Name: update_order_item_quantity(uuid, integer, numeric); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_order_item_quantity(p_order_item_id uuid, p_quantity integer, p_unit_price numeric) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_item RECORD;
  v_res  jsonb;
BEGIN
  SELECT * INTO v_item FROM order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  UPDATE order_items
  SET
    quantity = p_quantity,
    total_price = p_unit_price * p_quantity,
    kitchen_status = 'pending'
  WHERE id = p_order_item_id;

  -- D-9: SSOT recompute (preserves the order's current vat/service flags).
  v_res := public.calculate_order_total_v3(
    v_item.order_id,
    (SELECT COALESCE(apply_vat, false) FROM public.orders WHERE id = v_item.order_id),
    (SELECT COALESCE(service_charge_pct, 0) > 0 FROM public.orders WHERE id = v_item.order_id)
  );

  RETURN jsonb_build_object('success', true,
    'order_item_id', p_order_item_id, 'quantity', p_quantity,
    'order_total', v_res->'total');
END;
$$;


--
-- Name: update_order_item_status(uuid, text, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_order_item_status(p_order_item_id uuid, p_status text, p_prepared_quantity integer DEFAULT NULL::integer) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item RECORD;
  v_order_status text;
BEGIN
  SELECT * INTO v_item FROM order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  -- K3-6 (044): finalized-order guard (parent order). An undo/status change on
  --   an item of a paid/cancelled/closed order is refused (ORDER_FINALIZED).
  SELECT status INTO v_order_status FROM orders WHERE id = v_item.order_id;
  IF v_order_status IN ('paid','cancelled','closed') THEN
    RETURN jsonb_build_object('success', false, 'error', 'ORDER_FINALIZED',
      'order_item_id', p_order_item_id, 'order_status', v_order_status);
  END IF;

  UPDATE order_items
  SET
    kitchen_status = p_status,
    prepared_quantity = COALESCE(p_prepared_quantity, prepared_quantity)
  WHERE id = p_order_item_id;

  RETURN jsonb_build_object('success', true, 'order_item_id', p_order_item_id, 'status', p_status);
END;
$$;


--
-- Name: update_payment_status(uuid, text, jsonb, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_payment_status(p_payment_id uuid, p_new_status text, p_provider_response jsonb DEFAULT NULL::jsonb, p_provider_transaction_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment RECORD;
  v_valid_transitions jsonb := '{
    "pending": ["processing", "cancelled"],
    "processing": ["authorized", "captured", "failed", "declined", "cancelled", "unknown"],
    "authorized": ["captured", "voided", "cancelled"],
    "captured": ["settled", "refunded", "partially_refunded"],
    "failed": ["pending", "processing"],
    "declined": ["pending", "processing"],
    "unknown": ["captured", "failed", "cancelled"],
    "refunded": [],
    "partially_refunded": ["refunded"],
    "voided": [],
    "cancelled": [],
    "settled": []
  }'::jsonb;
  v_allowed jsonb;
BEGIN
  SELECT * INTO v_payment FROM public.payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  v_allowed := v_valid_transitions->v_payment.status;
  IF v_allowed IS NULL OR NOT (v_allowed ? p_new_status) THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'Invalid transition: ' || v_payment.status || ' → ' || p_new_status,
      'current_status', v_payment.status,
      'allowed', v_allowed
    );
  END IF;

  UPDATE public.payments SET
    status = p_new_status,
    provider_transaction_id = COALESCE(p_provider_transaction_id, provider_transaction_id),
    updated_at = NOW()
  WHERE id = p_payment_id;

  -- Record attempt
  PERFORM public.record_payment_attempt(p_payment_id, p_new_status, v_payment.amount, p_provider_response, NULL, v_payment.terminal_id);

  RETURN jsonb_build_object(
    'success', true,
    'old_status', v_payment.status,
    'new_status', p_new_status,
    'payment_id', p_payment_id
  );
END;
$$;


--
-- Name: update_pickup_time(uuid, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_pickup_time(p_order_id uuid, p_pickup_time timestamp with time zone, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  UPDATE orders SET
    estimated_delivery_time = p_pickup_time,
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;

  PERFORM log_order_event(
    p_order_id, 'status_changed',
    NULL,
    jsonb_build_object('pickup_time', p_pickup_time),
    NULL, p_performed_by, NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id, 'pickup_time', p_pickup_time);
END;
$$;


--
-- Name: update_pre_order_cache(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_pre_order_cache() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_pre_order_items jsonb;
BEGIN
  IF TG_OP = 'DELETE' THEN
    IF TG_ARGV[0] = 'clear_all' THEN
      UPDATE public.reservations
      SET pre_order_items = '[]'::jsonb
      WHERE id = OLD.reservation_id;
    ELSE
      SELECT jsonb_agg(
        jsonb_build_object(
          'id', x.id,
          'product_id', x.product_id,
          'product_name', x.product_name,
          'quantity', x.quantity,
          'unit_price', x.unit_price,
          'modifiers', x.modifiers,
          'special_notes', x.special_notes,
          'course', x.course,
          'combo_id', x.combo_id
        )
      ) INTO v_pre_order_items
      FROM (
        SELECT id, product_id, product_name, quantity, unit_price, modifiers, special_notes, course, combo_id
        FROM public.reservation_preorder_items
        WHERE reservation_id = OLD.reservation_id
      ) AS x;
      
      UPDATE public.reservations
      SET pre_order_items = COALESCE(v_pre_order_items, '[]'::jsonb)
      WHERE id = OLD.reservation_id;
    END IF;
  ELSIF TG_OP = 'INSERT' OR TG_OP = 'UPDATE' THEN
    SELECT jsonb_agg(
      jsonb_build_object(
        'id', x.id,
        'product_id', x.product_id,
        'product_name', x.product_name,
        'quantity', x.quantity,
        'unit_price', x.unit_price,
        'modifiers', x.modifiers,
        'special_notes', x.special_notes,
        'course', x.course,
        'combo_id', x.combo_id
      )
    ) INTO v_pre_order_items
    FROM (
      SELECT id, product_id, product_name, quantity, unit_price, modifiers, special_notes, course, combo_id
      FROM public.reservation_preorder_items
      WHERE reservation_id = NEW.reservation_id
    ) AS x;
    
    UPDATE public.reservations
    SET pre_order_items = COALESCE(v_pre_order_items, '[]'::jsonb)
    WHERE id = NEW.reservation_id;
  END IF;
  
  RETURN NEW;
END;
$$;


--
-- Name: update_product_availability(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_product_availability() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  -- 1. HAZIR MƏHSULLAR: birbaşa direct_ingredient_id-dən stock yoxla
  UPDATE products p
  SET is_available = i.current_stock > 0
  FROM ingredients i
  WHERE p.direct_ingredient_id = i.id
    AND p.is_ready_product = true;

  -- 2. RESEPTLİ məhsullar (hazır deyil amma resepti var): stock-dan asılıdır
  UPDATE products p
  SET is_available = NOT EXISTS (
    SELECT 1
    FROM recipes r
    JOIN ingredients i ON i.id = r.ingredient_id
    WHERE r.menu_item_id = p.id
      AND i.current_stock < r.quantity_required
  )
  WHERE p.is_ready_product = false
    AND EXISTS (
      SELECT 1 FROM recipes r2 WHERE r2.menu_item_id = p.id
    );

  -- 3. NE RESEPTLİ NE HAZIR: həmişə available
  UPDATE products p
  SET is_available = true
  WHERE p.is_ready_product = false
    AND p.direct_ingredient_id IS NULL
    AND NOT EXISTS (
      SELECT 1 FROM recipes r WHERE r.menu_item_id = p.id
    );

  RETURN NULL;
END;
$$;


--
-- Name: update_reservation_atomic(uuid, text, text, integer, text, text, text, boolean, jsonb, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_reservation_atomic(p_reservation_id uuid, p_name text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_guests integer DEFAULT NULL::integer, p_date text DEFAULT NULL::text, p_time text DEFAULT NULL::text, p_notes text DEFAULT NULL::text, p_vip boolean DEFAULT NULL::boolean, p_table_ids jsonb DEFAULT NULL::jsonb, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table_id UUID;
  v_table_number INTEGER;
  v_new_ids UUID[] := '{}';
  v_new_nums INTEGER[] := '{}';
BEGIN
  SELECT * INTO v_reservation FROM reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'RESERVATION_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF p_table_ids IS NOT NULL AND jsonb_array_length(p_table_ids) > 0 THEN
    SELECT array_agg(x::UUID) INTO v_new_ids
    FROM jsonb_array_elements_text(p_table_ids) AS x;
  END IF;
  IF array_length(v_new_ids, 1) > 0 THEN
    SELECT COALESCE(array_agg(tf.table_number ORDER BY tf.table_number), '{}') INTO v_new_nums
    FROM table_floors tf
    WHERE tf.id = ANY(v_new_ids);
    DELETE FROM reservation_tables WHERE reservation_id = p_reservation_id;
    FOR v_table_id IN SELECT unnest(v_new_ids) LOOP
      SELECT table_number INTO v_table_number FROM table_floors WHERE id = v_table_id;
      IF v_table_number IS NOT NULL THEN
        INSERT INTO reservation_tables (reservation_id, table_number, created_at)
        VALUES (p_reservation_id, v_table_number, NOW())
        ON CONFLICT (reservation_id, table_number) DO NOTHING;
        UPDATE table_floors SET
          status = 'reserved',
          reservation_id = p_reservation_id,
          reservation_name = COALESCE(p_name, v_reservation.name),
          reservation_phone = COALESCE(p_phone, v_reservation.phone),
          reservation_time = COALESCE(p_time, v_reservation.time::text),
          guest_count = COALESCE(p_guests, v_reservation.guests),
          updated_at = NOW()
        WHERE id = v_table_id
          AND status IS DISTINCT FROM 'occupied';
      END IF;
    END LOOP;
  END IF;
  UPDATE reservations SET
    name = COALESCE(p_name, name),
    phone = COALESCE(p_phone, phone),
    guests = COALESCE(p_guests, guests),
    date = COALESCE(p_date::date, date),
    time = COALESCE(p_time::time without time zone, time),
    note = COALESCE(p_notes, note),
    is_vip = COALESCE(p_vip, is_vip),
    table_ids = v_new_nums,
    updated_at = now()
  WHERE id = p_reservation_id;
  RETURN jsonb_build_object(
    'success', true,
    'reservation_id', p_reservation_id
  );
END;
$$;


--
-- Name: update_reservation_status_atomic(uuid, text, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_reservation_status_atomic(p_reservation_id uuid, p_new_status text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text, p_notes text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_reservation RECORD;
  v_table RECORD;
  v_table_number INTEGER;
  v_order_id UUID;
  v_order_ids UUID[] := '{}';
  v_now TIMESTAMPTZ := NOW();
  v_old_status TEXT;
  v_undo jsonb;
BEGIN
  SELECT * INTO v_reservation FROM public.reservations WHERE id = p_reservation_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Reservation not found');
  END IF;
  v_old_status := v_reservation.status;
  IF v_old_status = p_new_status THEN
    RETURN jsonb_build_object('success', true, 'status', p_new_status, 'unchanged', true);
  END IF;
  IF p_new_status IN ('cancelled', 'no_show', 'expired') THEN
    UPDATE public.reservations SET
      status = p_new_status,
      notes = COALESCE(p_notes, notes),
      updated_at = NOW()
    WHERE id = p_reservation_id;
    IF v_reservation.table_ids IS NOT NULL THEN
      FOR v_table_number IN SELECT unnest(v_reservation.table_ids) LOOP
        UPDATE public.table_floors SET
          status = 'empty',
          reservation_id = NULL,
          reservation_name = NULL,
          reservation_phone = NULL,
          reservation_time = NULL,
          guest_count = NULL,
          current_order_id = NULL,
          merged_into_table = NULL,
          updated_at = NOW(),
          updated_by_terminal_id = p_performed_by_terminal_id
        WHERE table_number = v_table_number;
      END LOOP;
    END IF;
    PERFORM public.log_reservation_operation(
      p_reservation_id,
      'cancel_reservation',
      jsonb_build_object('status', v_old_status),
      jsonb_build_object('status', p_new_status, 'notes', p_notes),
      p_performed_by
    );
    RETURN jsonb_build_object('success', true, 'status', p_new_status);
  END IF;
  IF p_new_status IN ('waiting', 'checked_in', 'seated') THEN
    UPDATE public.reservations SET
      status = p_new_status,
      notes = COALESCE(p_notes, notes),
      updated_at = NOW()
    WHERE id = p_reservation_id;
    IF v_reservation.table_ids IS NOT NULL THEN
      FOR v_table_number IN SELECT unnest(v_reservation.table_ids) LOOP
        UPDATE public.table_floors SET
          status = CASE WHEN p_new_status = 'waiting' THEN 'waiting' ELSE 'occupied' END,
          reservation_id = NULL,
          reservation_name = NULL,
          reservation_phone = NULL,
          reservation_time = NULL,
          guest_count = v_reservation.guests,
          updated_at = NOW(),
          updated_by_terminal_id = p_performed_by_terminal_id
        WHERE table_number = v_table_number;
      END LOOP;
    END IF;
    PERFORM public.log_reservation_operation(
      p_reservation_id,
      'guest_arrived',
      jsonb_build_object('status', v_old_status),
      jsonb_build_object('status', p_new_status),
      p_performed_by
    );
    RETURN jsonb_build_object('success', true, 'status', p_new_status);
  END IF;
  IF p_new_status = 'confirmed' THEN
    UPDATE public.reservations SET
      status = 'confirmed',
      notes = COALESCE(p_notes, notes),
      updated_at = NOW()
    WHERE id = p_reservation_id;
    IF v_reservation.table_ids IS NOT NULL THEN
      FOR v_table_number IN SELECT unnest(v_reservation.table_ids) LOOP
        UPDATE public.table_floors SET
          status = 'reserved',
          reservation_id = p_reservation_id,
          reservation_name = v_reservation.name,
          reservation_phone = v_reservation.phone,
          reservation_time = v_reservation.time,
          updated_at = NOW(),
          updated_by_terminal_id = p_performed_by_terminal_id
        WHERE table_number = v_table_number;
      END LOOP;
    END IF;
    PERFORM public.log_reservation_operation(
      p_reservation_id,
      'confirm_reservation',
      jsonb_build_object('status', v_old_status),
      jsonb_build_object('status', p_new_status),
      p_performed_by
    );
    RETURN jsonb_build_object('success', true, 'status', p_new_status);
  END IF;
  UPDATE public.reservations SET
    status = p_new_status,
    notes = COALESCE(p_notes, notes),
    updated_at = NOW()
  WHERE id = p_reservation_id;
  PERFORM public.log_reservation_operation(
    p_reservation_id,
    'update_status',
    jsonb_build_object('status', v_old_status),
    jsonb_build_object('status', p_new_status),
    p_performed_by
  );
  RETURN jsonb_build_object('success', true, 'status', p_new_status);
END;
$$;


--
-- Name: update_reservation_table_ids(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_reservation_table_ids() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_table_ids integer[];
  v_reservation_id uuid;
BEGIN
  v_reservation_id := COALESCE(NEW.reservation_id, OLD.reservation_id);

  SELECT array_agg(table_number ORDER BY table_number) INTO v_table_ids
  FROM public.reservation_tables
  WHERE reservation_id = v_reservation_id;

  IF v_table_ids IS NULL THEN
    v_table_ids := ARRAY[]::integer[];
  END IF;

  UPDATE public.reservations
  SET table_ids = v_table_ids
  WHERE id = v_reservation_id
    AND (table_ids IS DISTINCT FROM v_table_ids);

  RETURN COALESCE(NEW, OLD);
END;
$$;


--
-- Name: update_schedule(uuid, time without time zone, time without time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_schedule(p_schedule_id uuid, p_start time without time zone, p_end time without time zone, p_notes text DEFAULT NULL::text) RETURNS json
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_row schedule%ROWTYPE;
  v_new_start time;
  v_new_end time;
BEGIN
  SELECT * INTO v_row FROM schedule WHERE id = p_schedule_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN json_build_object('success', false, 'error', 'Schedule not found');
  END IF;

  v_new_start := COALESCE(p_start, v_row.planned_start);
  v_new_end   := COALESCE(p_end, v_row.planned_end);

  IF v_new_start >= v_new_end THEN
    RETURN json_build_object('success', false, 'error', 'planned_start must be before planned_end');
  END IF;

  IF EXISTS (
    SELECT 1 FROM schedule
    WHERE staff_id = v_row.staff_id
      AND schedule_date = v_row.schedule_date
      AND id <> p_schedule_id
      AND (planned_start, planned_end) OVERLAPS (v_new_start, v_new_end)
  ) THEN
    RETURN json_build_object('success', false, 'error', 'Schedule conflict detected');
  END IF;

  BEGIN
    UPDATE schedule
    SET planned_start = v_new_start,
        planned_end = v_new_end,
        notes = COALESCE(p_notes, notes),
        updated_at = NOW()
    WHERE id = p_schedule_id;
  EXCEPTION WHEN exclusion_violation THEN
    RETURN json_build_object('success', false, 'error', 'Schedule conflict detected');
  END;

  RETURN json_build_object('success', true);
END;
$$;


--
-- Name: update_staff_atomic(uuid, text, text, text, text, uuid, text, numeric, text, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_staff_atomic(p_staff_id uuid, p_name text DEFAULT NULL::text, p_full_name text DEFAULT NULL::text, p_email text DEFAULT NULL::text, p_phone text DEFAULT NULL::text, p_role_id uuid DEFAULT NULL::uuid, p_pin_hash text DEFAULT NULL::text, p_hourly_rate numeric DEFAULT NULL::numeric, p_shift text DEFAULT NULL::text, p_station_id uuid DEFAULT NULL::uuid, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_old staff%ROWTYPE;
BEGIN
  SELECT * INTO v_old FROM staff WHERE id = p_staff_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'STAFF_NOT_FOUND');
  END IF;

  UPDATE staff SET
    name = COALESCE(p_name, name),
    full_name = COALESCE(p_full_name, full_name),
    email = COALESCE(p_email, email),
    phone = COALESCE(p_phone, phone),
    role_id = COALESCE(p_role_id, role_id),
    pin_hash = COALESCE(p_pin_hash, pin_hash),
    hourly_rate = COALESCE(p_hourly_rate, hourly_rate),
    shift = COALESCE(p_shift, shift),
    station_id = COALESCE(p_station_id, station_id)
  WHERE id = p_staff_id;

  PERFORM log_audit(
    'staff_updated', 'staff', p_staff_id::text, p_performed_by,
    jsonb_build_object(
      'name', v_old.name, 'role_id', v_old.role_id, 'is_active', v_old.is_active
    ),
    jsonb_build_object(
      'name', COALESCE(p_name, v_old.name),
      'role_id', COALESCE(p_role_id, v_old.role_id)
    ),
    NULL, NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'staff_id', p_staff_id);
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: update_takeaway_order(uuid, text, text, text, timestamp with time zone, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_takeaway_order(p_order_id uuid, p_customer_phone text DEFAULT NULL::text, p_customer_name text DEFAULT NULL::text, p_customer_note text DEFAULT NULL::text, p_estimated_pickup_time timestamp with time zone DEFAULT NULL::timestamp with time zone, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_order RECORD;
BEGIN
  SELECT * INTO v_order FROM orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'ORDER_NOT_FOUND' USING ERRCODE = 'P0001';
  END IF;
  IF v_order.status = 'paid' THEN
    RAISE EXCEPTION 'ORDER_ALREADY_PAID' USING ERRCODE = 'P0001';
  END IF;

  UPDATE orders SET
    customer_phone = COALESCE(p_customer_phone, customer_phone),
    customer_name = COALESCE(p_customer_name, customer_name),
    customer_note = COALESCE(p_customer_note, customer_note),
    estimated_delivery_time = COALESCE(p_estimated_pickup_time, estimated_delivery_time),
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = p_order_id;

  RETURN jsonb_build_object('success', true, 'order_id', p_order_id);
END;
$$;


--
-- Name: update_theoretical_stock(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_theoretical_stock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_delta numeric;
BEGIN
  IF NEW.type = 'stock_in' THEN
    v_delta := NEW.quantity;
  ELSIF NEW.type IN ('waste', 'order_consumption') THEN
    v_delta := -NEW.quantity;
  ELSIF NEW.type = 'adjustment' THEN
    v_delta := NEW.quantity;
  ELSE
    v_delta := 0;
  END IF;

  UPDATE ingredients
  SET theoretical_stock = GREATEST(0, COALESCE(theoretical_stock, 0) + v_delta),
      updated_at = now()
  WHERE id = NEW.ingredient_id;

  RETURN NEW;
END;
$$;


--
-- Name: update_timestamp(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.update_timestamp() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
