--
-- Name: upsert_courier(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_courier(p_id uuid DEFAULT NULL::uuid, p_name text DEFAULT ''::text, p_phone text DEFAULT NULL::text, p_vehicle_type text DEFAULT 'car'::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_id UUID;
BEGIN
  IF p_name = '' THEN
    RAISE EXCEPTION 'NAME_REQUIRED' USING ERRCODE = 'P0001';
  END IF;

  IF p_id IS NOT NULL THEN
    UPDATE couriers SET
      name = p_name,
      phone = COALESCE(p_phone, phone),
      vehicle_type = COALESCE(p_vehicle_type, vehicle_type),
      updated_at = now()
    WHERE id = p_id
    RETURNING id INTO v_id;

    IF v_id IS NULL THEN
      INSERT INTO couriers (name, phone, vehicle_type)
      VALUES (p_name, p_phone, p_vehicle_type)
      RETURNING id INTO v_id;
    END IF;
  ELSE
    INSERT INTO couriers (name, phone, vehicle_type)
    VALUES (p_name, p_phone, p_vehicle_type)
    RETURNING id INTO v_id;
  END IF;

  RETURN jsonb_build_object('success', true, 'courier_id', v_id);
END;
$$;


--
-- Name: upsert_popular_query(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_popular_query(q_text text, q_lang text) RETURNS void
    LANGUAGE plpgsql
    AS $$
begin
  insert into popular_queries (query_text, language, count, last_seen)
  values (q_text, q_lang, 1, now())
  on conflict (query_text, language)
  do update set count = popular_queries.count + 1, last_seen = now();
end;
$$;


--
-- Name: upsert_reservation_preorders(uuid, jsonb, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.upsert_reservation_preorders(p_reservation_id uuid, p_items jsonb, p_replace_all boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item jsonb;
  v_existing uuid;
  v_keep_ids uuid[];
  v_new_ids uuid[];
  v_new_insert_id uuid;
  v_result jsonb;
BEGIN
  IF p_reservation_id IS NULL OR p_items IS NULL OR jsonb_typeof(p_items) <> 'array' THEN
    RAISE EXCEPTION 'INVALID_PAYLOAD' USING ERRCODE = 'P0001';
  END IF;

  SELECT array_agg(id)
  INTO v_keep_ids
  FROM (
    SELECT (e->>'id')::uuid AS id
    FROM jsonb_array_elements(p_items) e
    WHERE e->>'id' IS NOT NULL
      AND EXISTS (SELECT 1 FROM public.reservation_preorder_items r WHERE r.id = (e->>'id')::uuid AND r.reservation_id = p_reservation_id)
  ) t;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    v_existing := NULLIF(v_item->>'id', '')::uuid;

    IF v_existing IS NOT NULL AND EXISTS (SELECT 1 FROM public.reservation_preorder_items WHERE id = v_existing AND reservation_id = p_reservation_id) THEN
      UPDATE public.reservation_preorder_items SET
        product_id = NULLIF(v_item->>'product_id', '')::uuid,
        product_name = COALESCE(v_item->>'product_name', product_name),
        quantity = GREATEST(1, COALESCE((v_item->>'quantity')::integer, 1)),
        unit_price = COALESCE((v_item->>'unit_price')::numeric, unit_price),
        modifiers = COALESCE(v_item->'modifiers', modifiers),
        special_notes = COALESCE(v_item->>'special_notes', special_notes),
        course = COALESCE(v_item->>'course', course)
      WHERE id = v_existing;
    ELSIF v_existing IS NULL THEN
      INSERT INTO public.reservation_preorder_items
        (reservation_id, product_id, product_name, quantity, unit_price, modifiers, special_notes, course)
      VALUES (
        p_reservation_id,
        NULLIF(v_item->>'product_id', '')::uuid,
        COALESCE(v_item->>'product_name', 'Məhsul'),
        GREATEST(1, COALESCE((v_item->>'quantity')::integer, 1)),
        COALESCE((v_item->>'unit_price')::numeric, 0),
        COALESCE(v_item->'modifiers', '[]'::jsonb),
        COALESCE(v_item->>'special_notes', ''),
        COALESCE(v_item->>'course', 'main')
      )
      RETURNING id INTO v_new_insert_id;
      v_new_ids := array_append(v_new_ids, v_new_insert_id);
    END IF;
  END LOOP;

  IF p_replace_all THEN
    DELETE FROM public.reservation_preorder_items
    WHERE reservation_id = p_reservation_id
      AND (v_keep_ids IS NULL OR id <> ALL (v_keep_ids))
      AND (v_new_ids IS NULL OR id <> ALL (v_new_ids));
  END IF;

  SELECT COALESCE(jsonb_agg(row_to_json(r)::jsonb), '[]'::jsonb)
  INTO v_result
  FROM (
    SELECT * FROM public.reservation_preorder_items
    WHERE reservation_id = p_reservation_id
    ORDER BY created_at
  ) r;

  RETURN v_result;
END;
$$;


--
-- Name: validate_actor(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_actor(p_actor_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
BEGIN
  IF p_actor_id IS NOT NULL THEN
    IF NOT EXISTS (SELECT 1 FROM staff WHERE id = p_actor_id AND is_active = true) THEN
      RAISE EXCEPTION 'Invalid actor: staff not found or inactive (id: %)', p_actor_id USING ERRCODE = 'P0001';
    END IF;
  END IF;
END;
$$;


--
-- Name: validate_order_item_price_snapshot(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_order_item_price_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.unit_price < 0 THEN
    RAISE EXCEPTION 'Order item unit_price cannot be negative (0.1.10)' USING ERRCODE='P0001';
  END IF;
  IF NEW.quantity <= 0 THEN
    RAISE EXCEPTION 'Order item quantity must be positive (0.1.36)' USING ERRCODE='P0001';
  END IF;
  IF NEW.total_price IS NOT NULL AND NEW.total_price != (NEW.unit_price * NEW.quantity)
     AND NOT (NEW.kitchen_status IN ('voided','cancelled','wasted','comped') AND NEW.total_price = 0)
  THEN
    RAISE EXCEPTION 'Order item total_price must equal unit_price * quantity (0.1.41) [void-exempt]'
      USING ERRCODE='P0001';
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_payment_order_balance(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_payment_order_balance() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_order_total NUMERIC;
  v_existing_payments NUMERIC;
  v_refund_amount NUMERIC;
BEGIN
  SELECT total_amount INTO v_order_total FROM orders WHERE id = NEW.order_id;

  -- B5: only NON-refund, non-failed/voided rows count as existing.
  SELECT COALESCE(SUM(amount), 0) INTO v_existing_payments
    FROM order_payments
   WHERE order_id = NEW.order_id
     AND id != NEW.id
     AND status NOT IN ('failed','voided')
     AND COALESCE(is_refund, false) = false;

  SELECT COALESCE(SUM(amount), 0) INTO v_refund_amount
    FROM order_payments
   WHERE order_id = NEW.order_id
     AND is_refund = true
     AND status = 'captured';

  IF NOT NEW.is_refund THEN
    IF (v_existing_payments + NEW.amount) > v_order_total THEN
      RAISE EXCEPTION 'Payment total cannot exceed order total (0.1.42). Order: %, Existing: %, New: %',
        v_order_total, v_existing_payments, NEW.amount;
    END IF;
  END IF;

  RETURN NEW;
END;
$$;


--
-- Name: validate_table_order_pointer(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_table_order_pointer() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_status text;
  v_table_number int;
  v_location_id uuid;
BEGIN
  IF NEW.current_order_id IS NULL THEN
    RETURN NEW;
  END IF;
  SELECT status, table_number, location_id
    INTO v_status, v_table_number, v_location_id
  FROM orders WHERE id = NEW.current_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'TABLE_ORDER_POINTER_INVALID: order % does not exist (table %)',
      NEW.current_order_id, NEW.table_number;
  END IF;
  IF v_status IN ('paid','cancelled','closed','refunded','partially_refunded','voided') THEN
    RAISE EXCEPTION 'TABLE_ORDER_POINTER_FINAL: order % is % (table %)',
      NEW.current_order_id, v_status, NEW.table_number;
  END IF;
  IF v_table_number IS DISTINCT FROM NEW.table_number THEN
    RAISE EXCEPTION 'TABLE_ORDER_POINTER_MISMATCH: order % lives at table %, not %',
      NEW.current_order_id, v_table_number, NEW.table_number;
  END IF;
  IF v_location_id IS DISTINCT FROM NEW.location_id THEN
    RAISE EXCEPTION 'TABLE_ORDER_POINTER_LOCATION_MISMATCH: order % is at location %, not %',
      NEW.current_order_id, v_location_id, NEW.location_id;
  END IF;
  RETURN NEW;
END;
$$;


--
-- Name: validate_transition(text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.validate_transition(p_entity text, p_from_status text, p_to_status text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_rule RECORD;
BEGIN
  SELECT * INTO v_rule
  FROM public.state_transitions
  WHERE entity = p_entity
    AND from_status = p_from_status
    AND to_status = p_to_status
    AND is_active = true;

  IF NOT FOUND THEN
    RETURN jsonb_build_object(
      'valid', false,
      'error', format('Invalid transition: %s → %s for %s', p_from_status, p_to_status, p_entity)
    );
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'requires_role', v_rule.requires_role,
    'requires_permission', v_rule.requires_permission,
    'requires_manager_override', v_rule.requires_manager_override,
    'description', v_rule.description
  );
END;
$$;


--
-- Name: verify_manager_pin(text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_manager_pin(p_pin text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $_$
DECLARE
  v_candidates jsonb;
BEGIN
  -- Return candidate staff records for app-side PBKDF2 verification
  -- The app will call verifyPin(pin, staff.pin_hash) for each candidate
  SELECT jsonb_agg(
    jsonb_build_object(
      'id', s.id,
      'name', s.name,
      'role', s.role,
      'role_id', s.role_id
    )
  ) INTO v_candidates
  FROM staff s
  WHERE s.pin_hash LIKE 'pbkdf2_sha256$%'
    AND s.role IN ('admin', 'superadmin')
    AND s.is_active = true
  LIMIT 10;

  IF v_candidates IS NULL OR jsonb_array_length(v_candidates) = 0 THEN
    RETURN jsonb_build_object('valid', false, 'error', 'Invalid manager PIN');
  END IF;

  RETURN jsonb_build_object(
    'valid', true,
    'candidates', v_candidates,
    'message', 'Verify PIN against candidates using PBKDF2 in application code'
  );
END;
$_$;


--
-- Name: verify_password(text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.verify_password(plain_password text, hashed_password text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $$
BEGIN
  RETURN hashed_password = crypt(plain_password, hashed_password);
END;
$$;


--
-- Name: void_item_atomic(text, uuid, text, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_item_atomic(p_token text, p_item_id uuid, p_reason text DEFAULT NULL::text, p_metadata jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_staff_id uuid;
  v_item RECORD;
  v_order RECORD;
  v_rule jsonb;
  v_allowed jsonb;
  v_void_total numeric;
  v_inv jsonb;
BEGIN
  PERFORM set_session_staff(p_token);
  v_staff_id := current_staff_id();

  SELECT * INTO v_item FROM order_items WHERE id = p_item_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ORDER_ITEM_NOT_FOUND' USING ERRCODE = 'P0001'; END IF;

  SELECT * INTO v_order FROM orders WHERE id = v_item.order_id FOR UPDATE;
  IF v_order.status IN ('paid','closed','refunded','partially_refunded') THEN
    RAISE EXCEPTION 'ORDER_FINALIZED: use refund/reversal workflow for paid orders' USING ERRCODE='P0001';
  END IF;

  v_rule := validate_transition('item', v_item.kitchen_status, 'voided');
  IF NOT (v_rule->>'valid')::boolean THEN
    RAISE EXCEPTION 'INVALID_ITEM_TRANSITION: %', v_rule->>'error' USING ERRCODE='P0001';
  END IF;

  v_allowed := authorize(p_token, COALESCE(v_rule->>'requires_permission', 'order.void'), v_order.location_id);
  IF NOT (v_allowed->>'allowed')::boolean THEN
    RAISE EXCEPTION 'PERMISSION_DENIED: % at % (reason: %)',
      COALESCE(v_rule->>'requires_permission','order.void'), v_order.location_id,
      v_allowed->>'reason' USING ERRCODE='P0001';
  END IF;

  IF COALESCE(v_rule->>'requires_manager_override','false')::boolean THEN
    PERFORM ensure_manager_override(v_staff_id,
      COALESCE(v_rule->>'requires_permission','order.void'),
      v_order.location_id, v_item.kitchen_status, 'voided');
  END IF;

  v_void_total := COALESCE(v_item.total_price, v_item.unit_price * v_item.quantity);

  -- H6: consumed items produce exactly one inventory reversal.
  IF v_item.kitchen_status IN ('ready','served','completed') THEN
    v_inv := public._inventory_reverse_item(p_item_id, COALESCE(p_reason, 'void'), v_staff_id);
  END IF;

  UPDATE order_items SET
    kitchen_status = 'voided',
    total_price = 0,
    served_at = NULL,
    updated_at = now()
  WHERE id = p_item_id;

  UPDATE orders SET
    total_amount = GREATEST(0, COALESCE(total_amount, 0) - v_void_total),
    version = COALESCE(version, 0) + 1,
    updated_at = now()
  WHERE id = v_order.id;

  PERFORM log_order_event(v_order.id, 'item_voided',
    jsonb_build_object('item', p_item_id, 'total', v_void_total),
    jsonb_build_object('total', 0, 'reason', p_reason),
    COALESCE(p_metadata, '{}'::jsonb), v_staff_id, NULL, NULL, NULL);

  INSERT INTO operation_logs (operation, order_id, performed_by, reason, old_state, new_state,
                              location_id, organization_id, metadata)
  VALUES ('order_item.void', v_order.id, v_staff_id, p_reason,
    jsonb_build_object('item', p_item_id, 'status', v_item.kitchen_status, 'total', v_void_total),
    jsonb_build_object('status', 'voided', 'total', 0),
    v_order.location_id, v_order.organization_id, COALESCE(p_metadata, '{}'::jsonb));

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('order_item', p_item_id, 'order_item.voided',
    jsonb_build_object('order_id', v_order.id, 'old_total', v_void_total,
      'new_total', 0, 'reason', p_reason, 'performed_by', v_staff_id), 'pending');

  RETURN jsonb_build_object('success', true, 'order_item_id', p_item_id,
    'voided_total', v_void_total, 'item_status', 'voided',
    'inventory', COALESCE(v_inv->>'result', 'n/a'));
END;
$$;


--
-- Name: void_items_state_aware(text, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_items_state_aware(p_order_id text, p_items jsonb, p_performed_by uuid DEFAULT NULL::uuid, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_oi RECORD;
  v_new_qty INT;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
  v_voided INT := 0;
  v_blocked TEXT[] := ARRAY[]::text[];
  v_order RECORD;
BEGIN
  IF p_order_id IS NULL OR p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_id and items required');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = p_order_id::uuid FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_order.status IN ('paid', 'closed', 'refunded') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Cannot void paid/closed/refunded orders');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT * INTO v_oi FROM public.order_items WHERE id = (v_item->>'order_item_id')::uuid FOR UPDATE;
    IF NOT FOUND THEN CONTINUE; END IF;

    IF v_oi.kitchen_status IN ('ready', 'completed', 'served') THEN
      v_blocked := array_append(v_blocked,
        v_oi.product_name || ' (status=' || COALESCE(v_oi.kitchen_status, 'pending') || ')'
      );
      CONTINUE;
    END IF;

    IF (v_item->>'quantity')::int >= v_oi.quantity THEN
      UPDATE public.order_items SET kitchen_status = 'voided', total_price = 0 WHERE id = v_oi.id;
    ELSE
      v_new_qty := v_oi.quantity - (v_item->>'quantity')::int;
      UPDATE public.order_items SET quantity = v_new_qty, total_price = COALESCE(unit_price, 0) * v_new_qty WHERE id = v_oi.id;
    END IF;

    v_voided := v_voided + 1;
  END LOOP;

  IF array_length(v_blocked, 1) > 0 AND v_voided = 0 THEN
    RETURN jsonb_build_object(
      'success', false,
      'error', 'All items are READY/SERVED — use waste workflow instead',
      'blocked_items', to_jsonb(v_blocked)
    );
  END IF;

  INSERT INTO public.cancelled_orders (order_id, reason, reason_text, items, created_at)
  VALUES (p_order_id::uuid, 'void', COALESCE(p_reason, 'Ləğv edildi'), p_items, v_now);

  UPDATE public.orders SET
    total_amount = GREATEST(0, (SELECT COALESCE(SUM(total_price), 0) FROM public.order_items WHERE order_id = p_order_id::uuid AND kitchen_status != 'voided'))
  WHERE id = p_order_id::uuid;

  IF NOT EXISTS (SELECT 1 FROM public.order_items WHERE order_id = p_order_id::uuid AND kitchen_status != 'voided') THEN
    UPDATE public.orders SET status = 'cancelled', kitchen_status = 'cancelled', cancelled_at = v_now WHERE id = p_order_id::uuid;
  END IF;

  PERFORM public.log_audit(
    'void_items', 'order', p_order_id,
    p_performed_by, v_performer_name, NULL,
    jsonb_build_object('items', p_items, 'reason', p_reason, 'voided', v_voided, 'blocked', array_length(v_blocked, 1)),
    jsonb_build_object('order_id', p_order_id), NULL
  );

  -- ═══ P-6 D-4 (ratified 2026-09-13): void is an order mutation — broadcast it. ═══
  IF v_voided > 0 THEN
    PERFORM public.emit_outbox_event(
      'order', p_order_id::uuid, 'order.status_changed',
      jsonb_build_object('old_status', v_order.status,
                         'new_status', (SELECT status FROM public.orders WHERE id = p_order_id::uuid),
                         'reason', 'void', 'voided_items', v_voided,
                         'performed_by', p_performed_by)
    );
  END IF;

  RETURN jsonb_build_object(
    'success', true, 'action', 'void',
    'voided_items', v_voided,
    'blocked_items', to_jsonb(v_blocked),
    'order_id', p_order_id, 'timestamp', v_now
  );
END;
$$;


--
-- Name: void_order_item_atomic(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_order_item_atomic(p_order_item_id uuid, p_reason text DEFAULT 'void'::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql
    AS $$
DECLARE
  v_item RECORD;
  v_order RECORD;
  v_inv jsonb;
  v_res jsonb;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order item not found');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_item.kitchen_status IN ('cancelled', 'voided') THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item already voided');
  END IF;

  v_inv := public._inventory_reverse_item(p_order_item_id, COALESCE(p_reason, 'void'), p_performed_by);

  UPDATE public.order_items SET
    kitchen_status = 'voided',
    updated_at = NOW()
  WHERE id = p_order_item_id;

  -- SSOT recompute (preserves current vat/service flags).
  v_res := public.calculate_order_total_v3(
    v_order.id,
    COALESCE(v_order.apply_vat, false),
    COALESCE(v_order.service_charge_pct, 0) > 0
  );

  UPDATE public.orders SET
    updated_by_terminal_id = p_performed_by_terminal_id
  WHERE id = v_order.id;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, v_order.id, 'void_order_item',
    jsonb_build_object('item_id', p_order_item_id, 'kitchen_status', v_item.kitchen_status, 'order_total', v_order.total_amount),
    jsonb_build_object('item_id', p_order_item_id, 'kitchen_status', 'voided', 'reason', p_reason, 'order_total', v_res->>'total'),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'new_order_total', v_res->>'total',
    'inventory', (v_inv->>'result'), 'inventory_reversed', (v_inv->>'reversed')::int);
END;
$$;


--
-- Name: void_payment_atomic(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_payment_atomic(p_payment_id uuid, p_reason text DEFAULT NULL::text, p_performed_by uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_payment RECORD;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_payment FROM order_payments WHERE id = p_payment_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Payment not found');
  END IF;

  UPDATE order_payments SET
    status = 'voided',
    updated_at = NOW()
  WHERE id = p_payment_id;

  PERFORM public.log_audit(
    'void_payment', 'order_payment', p_payment_id::text,
    p_performed_by, NULL,
    jsonb_build_object('status', v_payment.status),
    jsonb_build_object('status', 'voided', 'reason', p_reason),
    NULL, NULL
  );

  RETURN jsonb_build_object('success', true, 'payment_id', p_payment_id);
END;
$$;


--
-- Name: void_payment_atomic(text, jsonb, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_payment_atomic(p_order_id text, p_items jsonb, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
