--
-- Name: void_payment_atomic_v2(text, jsonb, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.void_payment_atomic_v2(p_order_id text, p_items jsonb, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item JSONB;
  v_oi RECORD;
  v_new_qty INT;
  v_performer_name TEXT;
  v_now TIMESTAMPTZ := NOW();
BEGIN
  IF p_order_id IS NULL OR p_items IS NULL OR jsonb_array_length(p_items) = 0 THEN
    RETURN jsonb_build_object('success', false, 'error', 'order_id and items required');
  END IF;

  IF NOT EXISTS (
    SELECT 1 FROM public.orders WHERE id = p_order_id::uuid AND status IN ('active', 'ready', 'confirmed')
  ) THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found or not in voidable status');
  END IF;

  IF p_performed_by IS NOT NULL THEN
    SELECT name INTO v_performer_name FROM public.staff WHERE id = p_performed_by;
  END IF;

  -- Delete/reduce items
  FOR v_item IN SELECT * FROM jsonb_array_elements(p_items)
  LOOP
    SELECT * INTO v_oi FROM public.order_items WHERE id = (v_item->>'order_item_id')::uuid;
    IF NOT FOUND THEN CONTINUE; END IF;

    IF (v_item->>'quantity')::int >= v_oi.quantity THEN
      -- Consumed items cannot be hard-deleted (immutable ledger FK);
      -- soft-cancel them instead (zeroed, terminal state).
      IF EXISTS (SELECT 1 FROM public.inventory_logs WHERE order_item_id = v_oi.id) THEN
        UPDATE public.order_items SET
          kitchen_status = 'cancelled',
          total_price = 0,
          served_at = NULL,
          updated_at = NOW()
        WHERE id = v_oi.id;
      ELSE
        DELETE FROM public.order_items WHERE id = (v_item->>'order_item_id')::uuid;
      END IF;
    ELSE
      v_new_qty := v_oi.quantity - (v_item->>'quantity')::int;
      UPDATE public.order_items SET quantity = v_new_qty, total_price = COALESCE(unit_price, 0) * v_new_qty
      WHERE id = (v_item->>'order_item_id')::uuid;
    END IF;
  END LOOP;

  -- Record in cancelled_orders
  INSERT INTO public.cancelled_orders (order_id, reason, reason_text, items, created_at)
  VALUES (p_order_id::uuid, 'void', COALESCE(p_reason, 'Kassir tərəfindən ləğv edildi (Void)'), p_items, v_now);

  -- Update order total
  UPDATE public.orders SET
    total_amount = GREATEST(0, (SELECT COALESCE(SUM(total_price), 0) FROM public.order_items WHERE order_id = p_order_id::uuid)),
    kitchen_status = 'pending'
  WHERE id = p_order_id::uuid;

  -- Audit
  PERFORM public.log_audit(
    'void_items', 'order', p_order_id,
    p_performed_by, v_performer_name,
    NULL,
    jsonb_build_object('items', p_items, 'terminal_id', p_performed_by_terminal_id, 'reason', p_reason),
    jsonb_build_object('order_id', p_order_id),
    NULL
  );

  RETURN jsonb_build_object(
    'success', true,
    'action', 'void',
    'voided_items', jsonb_array_length(p_items),
    'order_id', p_order_id,
    'timestamp', v_now
  );
END;
$$;


--
-- Name: walkin_atomic(integer, integer, text, text, text, text, uuid, boolean, text, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.walkin_atomic(p_table_number integer, p_guests integer, p_name text, p_phone text, p_order_type text, p_notes text, p_user_id uuid, p_pre_order boolean, p_scheduled_date text, p_scheduled_time text, p_location_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_table RECORD;
  v_reservation_id uuid;
  v_order_id uuid;
  v_result jsonb;
  v_sched_date date;
  v_sched_time time;
  v_hold boolean;
BEGIN
  -- G4: table_number resolves WITHIN the caller's active location only
  -- (p_location_id is server-resolved from the session — never client).
  SELECT * INTO v_table FROM public.table_floors
    WHERE table_number = p_table_number
      AND (p_location_id IS NULL OR location_id = p_location_id)
    FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_FOUND');
  END IF;

  v_hold := COALESCE(p_pre_order, false)
         OR p_scheduled_date IS NOT NULL
         OR p_scheduled_time IS NOT NULL;

  IF v_table.status NOT IN ('empty','dirty') THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_NOT_EMPTY');
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.orders o
    WHERE o.table_number = p_table_number
      AND o.location_id = v_table.location_id
      AND o.status NOT IN ('paid','cancelled','closed','refunded','partially_refunded','voided')) THEN
    RETURN jsonb_build_object('success', false, 'error', 'TABLE_ALREADY_HAS_OPEN_ORDER');
  END IF;
  IF v_hold AND v_table.reservation_id IS NOT NULL THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_WALKIN_TABLE_RESERVED');
  END IF;
  IF NOT v_hold AND v_table.reservation_id IS NOT NULL AND v_table.status <> 'reserved' THEN
    RETURN jsonb_build_object('success', false, 'error', 'G_WALKIN_TABLE_RESERVED');
  END IF;

  v_sched_date := COALESCE(p_scheduled_date::date, CURRENT_DATE);
  v_sched_time := COALESCE(p_scheduled_time::time, CURRENT_TIME);

  IF v_hold THEN
    -- reservation-hold: no order yet, table sits reserved until seat_guests
    INSERT INTO public.reservations (name, phone, guests, date, time, status,
                                     table_ids, order_type, notes,
                                     kitchen_scheduled_for,
                                     location_id, organization_id, created_at, updated_at)
    VALUES (p_name, p_phone, p_guests, v_sched_date, v_sched_time, 'confirmed',
            ARRAY[p_table_number], p_order_type, p_notes,
            (v_sched_date + v_sched_time) - interval '20 minutes',
            v_table.location_id, v_table.organization_id, now(), now())
    RETURNING id INTO v_reservation_id;

    UPDATE public.table_floors SET
      status = 'reserved',
      reservation_id = v_reservation_id,
      reservation_name = p_name,
      reservation_phone = p_phone,
      guest_count = p_guests,
      current_order_id = NULL,
      updated_at = now()
    WHERE table_number = p_table_number;

    INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
    VALUES (v_reservation_id, p_table_number, now())
    ON CONFLICT (reservation_id, table_number) DO NOTHING;

    v_result := jsonb_build_object('success', true, 'reservation_id', v_reservation_id,
      'table_number', p_table_number, 'mode', 'reservation_hold');
    RETURN v_result;
  END IF;

  INSERT INTO public.reservations (name, phone, guests, date, time, status,
                                   table_ids, order_type, notes,
                                   location_id, organization_id, created_at, updated_at)
  VALUES (p_name, p_phone, p_guests, CURRENT_DATE, CURRENT_TIME, 'confirmed',
          ARRAY[p_table_number], p_order_type, p_notes,
          v_table.location_id, v_table.organization_id, NOW(), NOW())
  RETURNING id INTO v_reservation_id;

  INSERT INTO public.reservation_tables (reservation_id, table_number, created_at)
  VALUES (v_reservation_id, p_table_number, NOW())
  ON CONFLICT (reservation_id, table_number) DO NOTHING;

  INSERT INTO public.orders (table_number, status, guest_count, order_type,
                             location_id, organization_id, total_amount, returned_amount,
                             created_at, updated_at)
  VALUES (p_table_number, 'new', p_guests, p_order_type,
          v_table.location_id, v_table.organization_id, 0, 0, NOW(), NOW())
  RETURNING id INTO v_order_id;

  UPDATE public.table_floors SET
    status = 'occupied',
    guest_count = p_guests,
    current_order_id = v_order_id,
    updated_at = NOW()
  WHERE table_number = p_table_number;

  PERFORM public.log_reservation_operation(
    v_reservation_id,
    'walkin',
    jsonb_build_object('table_number', p_table_number, 'guests', p_guests),
    jsonb_build_object('table_number', p_table_number, 'guests', p_guests, 'order_id', v_order_id),
    p_user_id
  );

  INSERT INTO outbox_events (aggregate_type, aggregate_id, event_type, payload, status)
  VALUES ('table', v_table.id, 'table.order_opened',
    jsonb_build_object('table_number', p_table_number,
      'order_id', v_order_id,
      'reservation_id', v_reservation_id,
      'order_type', p_order_type,
      'location_id', v_table.location_id),
    'pending');

  v_result := jsonb_build_object(
    'success', true,
    'reservation_id', v_reservation_id,
    'order_id', v_order_id,
    'table_number', p_table_number
  );
  RETURN v_result;
EXCEPTION
  WHEN OTHERS THEN
    RETURN jsonb_build_object('success', false, 'error', SQLERRM);
END;
$$;


--
-- Name: waste_order_item_atomic(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.waste_order_item_atomic(p_order_item_id uuid, p_reason text DEFAULT 'waste'::text, p_performed_by uuid DEFAULT NULL::uuid, p_performed_by_terminal_id text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public'
    AS $$
DECLARE
  v_item RECORD;
  v_order RECORD;
  v_new_total NUMERIC := 0;
  v_inv jsonb;
BEGIN
  PERFORM public.validate_actor(p_performed_by);
  SELECT * INTO v_item FROM public.order_items WHERE id = p_order_item_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order item not found');
  END IF;

  SELECT * INTO v_order FROM public.orders WHERE id = v_item.order_id FOR UPDATE;
  IF NOT FOUND THEN
    RETURN jsonb_build_object('success', false, 'error', 'Order not found');
  END IF;

  IF v_item.kitchen_status = 'wasted' THEN
    RETURN jsonb_build_object('success', false, 'error', 'Item already wasted');
  END IF;

  v_inv := public._inventory_reverse_item(p_order_item_id, COALESCE(p_reason, 'waste'), p_performed_by);

  UPDATE public.order_items SET
    kitchen_status = 'wasted',
    updated_at = NOW()
  WHERE id = p_order_item_id;

  SELECT COALESCE(SUM(total_price), 0) INTO v_new_total FROM public.order_items
  WHERE order_id = v_order.id AND kitchen_status NOT IN ('cancelled', 'voided', 'wasted');

  UPDATE public.orders SET
    total_amount = v_new_total,
    version = COALESCE(version, 0) + 1,
    updated_by_terminal_id = p_performed_by_terminal_id,
    updated_at = NOW()
  WHERE id = v_order.id;

  INSERT INTO public.operation_logs (
    table_number, order_id, action, old_values, new_values, performed_by
  ) VALUES (
    v_order.table_number, v_order.id, 'waste_order_item',
    jsonb_build_object('item_id', p_order_item_id, 'kitchen_status', v_item.kitchen_status, 'order_total', v_order.total_amount),
    jsonb_build_object('item_id', p_order_item_id, 'kitchen_status', 'wasted', 'reason', p_reason, 'order_total', v_new_total),
    p_performed_by
  );

  RETURN jsonb_build_object('success', true, 'new_order_total', v_new_total,
    'inventory', (v_inv->>'result'), 'inventory_reversed', (v_inv->>'reversed')::int);
END;
$$;


