--
-- Name: labor_summaries; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.labor_summaries AS
 SELECT COALESCE(sh.report_date, date(sh.opened_at)) AS period,
    sh.staff_id,
    COALESCE(s.hourly_rate, (0)::numeric) AS hourly_rate,
    GREATEST((EXTRACT(epoch FROM (COALESCE(sh.closed_at, now()) - sh.opened_at)) / (3600)::numeric), (0)::numeric) AS hours_worked,
    (GREATEST((EXTRACT(epoch FROM (COALESCE(sh.closed_at, now()) - sh.opened_at)) / (3600)::numeric), (0)::numeric) * COALESCE(s.hourly_rate, (0)::numeric)) AS total_labor_cost
   FROM (public.shifts sh
     JOIN public.staff s ON ((s.id = sh.staff_id)));


