COMMENT ON CONSTRAINT orders_status_check ON public.orders IS '0.4-A canonical order status vocabulary (legacy text labels, enforced)';


--
-- Name: order_hourly_stats; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.order_hourly_stats WITH (security_invoker='on') AS
 SELECT EXTRACT(hour FROM (created_at AT TIME ZONE 'Asia/Baku'::text)) AS hour,
    count(*) AS order_count
   FROM public.orders
  WHERE (created_at >= (now() - '30 days'::interval))
  GROUP BY (EXTRACT(hour FROM (created_at AT TIME ZONE 'Asia/Baku'::text)))
  ORDER BY (count(*)) DESC;


