--
-- Name: table_order_contract; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.table_order_contract AS
 SELECT tf.id,
    tf.table_number,
    tf.status AS table_status,
    tf.kitchen_status AS table_kitchen_status,
    tf.current_order_id,
    o.status AS current_order_status,
    o.kitchen_status AS current_order_kitchen_status,
    o.total_amount AS current_order_total,
    ( SELECT count(*) AS count
           FROM public.orders x
          WHERE ((x.table_number = tf.table_number) AND (x.location_id = tf.location_id) AND (x.status <> ALL (ARRAY['paid'::text, 'cancelled'::text, 'closed'::text, 'refunded'::text, 'partially_refunded'::text, 'voided'::text])))) AS open_orders,
    tf.location_id,
    tf.organization_id
   FROM (public.table_floors tf
     LEFT JOIN public.orders o ON ((o.id = tf.current_order_id)));


