--
-- Name: v_closed_orders; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_closed_orders AS
 SELECT id AS order_id,
    table_number,
    total_amount,
    paid_amount,
    payment_method,
    discount_type,
    discount_value,
    cogs,
    profit,
    (COALESCE(paid_amount, (0)::numeric) - COALESCE(cogs, (0)::numeric)) AS gross_profit,
        CASE
            WHEN (COALESCE(paid_amount, (0)::numeric) > (0)::numeric) THEN round((((COALESCE(paid_amount, (0)::numeric) - COALESCE(cogs, (0)::numeric)) / COALESCE(paid_amount, (0)::numeric)) * (100)::numeric), 1)
            ELSE (0)::numeric
        END AS profit_margin_pct,
    tip_amount,
    guest_count,
    created_at AS order_created_at,
    paid_at,
    updated_at,
    reservation_id,
    jsonb_array_length(items) AS item_count
   FROM public.orders o
  WHERE (status = 'paid'::text);


--
-- Name: v_daily_revenue; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_daily_revenue AS
 SELECT date((paid_at AT TIME ZONE 'Asia/Baku'::text)) AS sale_date,
    count(DISTINCT id) AS order_count,
    COALESCE(sum(paid_amount), (0)::numeric) AS total_revenue,
    COALESCE(sum(cogs), (0)::numeric) AS total_cogs,
    COALESCE(sum(profit), (0)::numeric) AS total_profit,
    COALESCE(avg(guest_count), (0)::numeric) AS avg_guest_count,
    COALESCE(sum(tip_amount), (0)::numeric) AS total_tips,
    count(DISTINCT table_number) FILTER (WHERE (table_number IS NOT NULL)) AS unique_tables
   FROM public.orders
  WHERE ((status = 'paid'::text) AND (paid_at IS NOT NULL))
  GROUP BY (date((paid_at AT TIME ZONE 'Asia/Baku'::text)))
  ORDER BY (date((paid_at AT TIME ZONE 'Asia/Baku'::text))) DESC;


--
-- Name: v_daily_staff_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_daily_staff_performance AS
 WITH order_attribution AS (
         SELECT
                CASE
                    WHEN (o.assigned_to IS NOT NULL) THEN o.assigned_to
                    ELSE o.created_by
                END AS staff_id,
            o.id AS order_id,
            o.total_amount,
            o.tip_amount,
            o.created_at
           FROM public.orders o
          WHERE ((o.status = ANY (ARRAY['paid'::text, 'closed'::text])) AND (o.created_at >= (now() - '30 days'::interval)))
        )
 SELECT date(oa.created_at) AS report_date,
    s.id AS staff_id,
    s.name AS staff_name,
    r.name AS role,
    count(DISTINCT oa.order_id) AS order_count,
    COALESCE(sum(oa.total_amount), (0)::numeric) AS revenue,
    COALESCE(sum(oa.tip_amount), (0)::numeric) AS tips,
    COALESCE(avg(oa.total_amount), (0)::numeric) AS avg_order_value
   FROM ((public.staff s
     LEFT JOIN public.roles r ON ((r.id = s.role_id)))
     LEFT JOIN order_attribution oa ON ((oa.staff_id = s.id)))
  WHERE (s.is_active = true)
  GROUP BY (date(oa.created_at)), s.id, s.name, r.name
  ORDER BY (date(oa.created_at)) DESC, COALESCE(sum(oa.total_amount), (0)::numeric) DESC;


--
-- Name: v_staff_performance; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_staff_performance AS
 WITH order_attribution AS (
         SELECT
                CASE
                    WHEN (o.assigned_to IS NOT NULL) THEN o.assigned_to
                    ELSE o.created_by
                END AS staff_id,
            o.id AS order_id,
            o.total_amount,
            o.tip_amount,
            o.created_at
           FROM public.orders o
          WHERE (o.status = ANY (ARRAY['paid'::text, 'closed'::text]))
        )
 SELECT s.id AS staff_id,
    s.name AS staff_name,
    r.name AS role,
    count(DISTINCT oa.order_id) AS total_orders,
    COALESCE(sum(oa.total_amount), (0)::numeric) AS total_revenue,
    COALESCE(sum(oa.tip_amount), (0)::numeric) AS total_tips,
    COALESCE(avg(oa.total_amount), (0)::numeric) AS avg_order_value,
    min(oa.created_at) AS first_order_at,
    max(oa.created_at) AS last_order_at
   FROM ((public.staff s
     LEFT JOIN public.roles r ON ((r.id = s.role_id)))
     LEFT JOIN order_attribution oa ON ((oa.staff_id = s.id)))
  WHERE (s.is_active = true)
  GROUP BY s.id, s.name, r.name
  ORDER BY COALESCE(sum(oa.total_amount), (0)::numeric) DESC;


--
-- Name: v_stock_health; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_stock_health AS
 SELECT count(*) FILTER (WHERE ((current_stock <= (0)::numeric) OR (current_stock IS NULL))) AS out_of_stock_count,
    count(*) FILTER (WHERE ((current_stock > (0)::numeric) AND (current_stock <= critical_limit))) AS critical_count,
    count(*) FILTER (WHERE ((current_stock > critical_limit) OR (critical_limit IS NULL) OR (critical_limit = (0)::numeric))) AS normal_count,
    count(*) AS total_ingredients,
    round((((count(*) FILTER (WHERE ((current_stock <= (0)::numeric) OR (current_stock IS NULL))))::numeric / (GREATEST(count(*), (1)::bigint))::numeric) * (100)::numeric), 1) AS out_of_stock_pct
   FROM public.ingredients;


--
-- Name: v_top_products; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.v_top_products AS
 SELECT p.id AS product_id,
    p.name_az AS product_name,
    p.category_id,
    c.name_az AS category_name,
    count(DISTINCT o.id) AS order_count,
    sum(oi.quantity) AS total_quantity_sold,
    sum(oi.total_price) AS total_revenue,
    p.cost_price,
    (sum(oi.total_price) - (COALESCE(p.cost_price, (0)::numeric) * (sum(oi.quantity))::numeric)) AS estimated_profit
   FROM (((public.order_items oi
     JOIN public.orders o ON (((o.id = oi.order_id) AND (o.status = 'paid'::text))))
     JOIN public.products p ON ((p.id = oi.product_id)))
     LEFT JOIN public.categories c ON ((c.id = p.category_id)))
  GROUP BY p.id, p.name_az, p.category_id, c.name_az, p.cost_price
  ORDER BY (sum(oi.quantity)) DESC;


--
-- Name: waste_standards; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.waste_standards (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    keyword text NOT NULL,
    waste_percentage numeric NOT NULL,
    category text,
    created_at timestamp with time zone DEFAULT now()
);


--
-- Name: webhook_events; Type: TABLE; Schema: public; Owner: -
--

CREATE TABLE public.webhook_events (
    id uuid DEFAULT gen_random_uuid() NOT NULL,
    correlation_id uuid,
    event_type character varying(100) NOT NULL,
    source character varying(50) DEFAULT 'saito'::character varying NOT NULL,
    payload jsonb DEFAULT '{}'::jsonb NOT NULL,
    status character varying(20) DEFAULT 'pending'::character varying NOT NULL,
    target_url text,
    response_status integer,
    retry_count integer DEFAULT 0 NOT NULL,
    max_retries integer DEFAULT 3 NOT NULL,
    next_retry_at timestamp with time zone,
    created_at timestamp with time zone DEFAULT now() NOT NULL,
    sent_at timestamp with time zone,
    CONSTRAINT webhook_events_status_check CHECK (((status)::text = ANY ((ARRAY['pending'::character varying, 'sent'::character varying, 'failed'::character varying, 'dead'::character varying])::text[])))
);


